window.__D("text/zohar-hebrew-translation/c021",{"p":[[9522011836,"<p>וּבַסֵּפֶר שֶׁל רַב יֵיבָא סָבָא, בְּמִנְחָה בְּשַׁבָּת הֲרֵי הִתְעוֹרְרוּת שֶׁל שְׂמֹאל, וְהַנְּקֻדָּה הַתַּחְתּוֹנָה בְּאוֹתוֹ צַד הַשְּׂמֹאל מְקַבֶּלֶת סוֹד הַתּוֹרָה. אָז בְּאוֹתָהּ שָׁעָה נוֹסַעַת מִצַּד שְׂמֹאל, וּמִשֶּׁלָּהּ אָנוּ קוֹרְאִים.</p>\n<p>שֶׁהֲרֵי הִיא עוֹמֶדֶת בַּסּוֹד שֶׁל תֵּשַׁע (ספירות), וְקוֹרְאִים תִּשְׁעָה, וְהֵם שִׁשָּׁה שֶׁל חֹל וּשְׁלֹשָׁה בְּשָׁעָה שֶׁהַשְּׂמֹאל מִתְעוֹרֵר בְּשַׁבָּת, וּלְהַכְלִיל הַכֹּל כְּאֶחָד. וְהִיא מִתְעַטֶּרֶת בָּהֶם בִּשְׁלֹשָׁה צְדָדִים, כְּמוֹ שְׁלֹשֶׁת הַצְּדָדִים הָעֶלְיוֹנִים שֶׁהֵם כְּלָל שֶׁל פָּרָשַׁת הַשַּׁבָּת. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכה לִכְבוֹד הַשַּׁבָּת. אַשְׁרָיו בִּשְׁנֵי הָעוֹלָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>כָּתוּב (שמות טז) אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מַה זֶּה מִמְּקֹמוֹ? שָׁנִינוּ, מִמְּקֹמוֹ - מֵאוֹתוֹ מָקוֹם שֶׁרָאוּי לָלֶכֶת. וְסוֹד הַדָּבָר - שֶׁכָּתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְזֶה הַמָּקוֹם. וְזֶהוּ סוֹד הַכָּתוּב (שמות ג) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו. מָקוֹם יָדוּעַ הוּא לְמַעְלָה, וְקוֹרְאִים לוֹ מָקוֹם, שֶׁנּוֹדָע בּוֹ הַכָּבוֹד הָעֶלְיוֹן שֶׁלְּמַעְלָה. וּמִשּׁוּם כָּךְ אַזְהָרָה לָאָדָם, שֶׁהֲרֵי מִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה שֶׁל מַעְלָה, שֶׁלֹּא יֵצֵא מִמֶּנּוּ. שֶׁאִם (יצא מפיו דבור של חל) יֵצֵא מִמֶּנּוּ, הוּא מְחַלֵּל שַׁבָּת. בְּיָדוֹ - בְּמַעֲשֶׂה, כְּמוֹ שֶׁבֵּאַרְנוּ. בְּרַגְלוֹ - לָלֶכֶת מִחוּץ לְאַלְפַּיִם אַמָּה. כָּל אֵלֶּה הֵם חִלּוּל שַׁבָּת.</p>\n<p>אַל יֵצֵא אִישׁ מִמְּקֹמוֹ, זֶהוּ מְקוֹם כְּבוֹד הַקְּדֻשָּׁה הַזּוֹ, שֶׁהֲרֵי מִמֶּנּוּ לַחוּץ הוּא מָקוֹם שֶׁל אֱלֹהִים אֲחֵרִים. בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. כְּבוֹד ה' שֶׁלְּמַעְלָה. מִמְּקוֹמוֹ - זֶה כָּבוֹד שֶׁלְּמַטָּה, וְזֶהוּ סוֹד שֶׁל עֲטֶרֶת שַׁבָּת. וּמִשּׁוּם כָּךְ, אַל יֵצֵא אִישׁ מִמְּקֹמוֹ. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>כָּתוּב, (שמות לג) הִנֵּה מָקוֹם אִתִּי. מָקוֹם אִתִּי, וַדַּאי זֶהוּ מָקוֹם טָמִיר וְגָנוּז שֶׁלֹּא נוֹדָע כְּלָל. מִמַּשְׁמָע שֶׁכָּתוּב אִתִּי - מָקוֹם שֶׁלֹּא הִתְגַּלָּה וְעוֹמֵד טָמִיר, וְזֶהוּ מָקוֹם עֶלְיוֹן לְמַעְלָה לְמַעְלָה, הֵיכָל עֶלְיוֹן טָמִיר וְגָנוּז. אֲבָל זֶהוּ מָקוֹם לְמַטָּה, כְּפִי שֶׁאָמַרְנוּ. וְזֶהוּ מָקוֹם שֶׁנִּפְרָד לְמַעְלָה וְנִפְרָד לְמַטָּה, וּמִשּׁוּם כָּךְ אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי.</p>\n<p>וּמַדֹּתֶם מִחוּץ לָעִיר אֶת פְּאַת קֵדְמָה אַלְפַּיִם בָּאַמָּה וְגוֹ' (במדבר לה), הֲרֵי פֵּרְשׁוּהָ בְּאוֹתָם סוֹדוֹת עֶלְיוֹנִים. אֲבָל אַלְפַּיִם בָּאַמָּה - שֶׁיָּרְשָׁה שְׁנֵי צְדָדִים לְכָל צַד, וְהִיא מִתְעַטֶּרֶת תָּמִיד בִּשְׁנֵי צְדָדִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה. וְסִימָנְךְ - שְׁכִינָה לֹא שׁוֹרָה מִחוּץ לַתְּחוּם הָרָאוּי לָהּ.</p>\n<p>כְּשֶׁיּוֹצֵאת שַׁבָּת, צְרִיכִים יִשְׂרָאֵל שֶׁלְּמַטָּה לְהִתְעַכֵּב, שֶׁהֲרֵי הוּא יוֹם גָּדוֹל עֶלְיוֹן, (צריךלהתעכבעליו) וּבַיּוֹם הַזֶּה שׁוֹרֶה עָלָיו אוֹרֵחַ גָּדוֹל וְנִכְבָּד, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִתְעַכֵּב, לְהַרְאוֹת שֶׁלֹּא דוֹחֲקִים בָּאוֹרֵחַ הַקָּדוֹשׁ. אָז פּוֹתְחִים יִשְׂרָאֵל וְאוֹמְרִים, (תהלים עח) וְהוּא רַחוּם יְכַפֵּר עָון וְגוֹ'. שֶׁתִּקּוּן יָפֶה הוּא בַּלַּיְלָה הַזֶּה, כֵּיוָן שֶׁהַדִּין חוֹזֵר לִמְקוֹמוֹ - מַה שֶּׁלֹּא רָאוּי כְּשֶׁנִּכְנֶסֶת שַׁבָּת, כְּשֶׁהַדִּין מִסְתַּלֵּק וְלֹא נִמְצָא.</p>\n<p>בְּשָׁעָה שֶׁפּוֹתְחִים יִשְׂרָאֵל \"וִיהִי נֹעַם\" וְסֵדֶר הַקְּדֻשָּׁה, כָּל אוֹתָם רִשְׁעֵי הַגֵּיהִנֹּם פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ. אַשְׁרֵיכֶם הַצַּדִּיקִים הַשּׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה. אוֹי לָרְשָׁעִים שֶׁלֹּא זָכוּ לִשְׁמֹר תּוֹרָה. אָז דּוּמָ\"ה מַקְדִּים, וּמִתְעוֹרֵר כָּרוֹז וְאוֹמֵר: (שם ט) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה כָּל גּוֹיִם שְׁכֵחֵי אֱלֹהִים. וְכָל קְבוּצוֹת הָרוּחוֹת הַלָּלוּ טוֹרְדוֹת אוֹתָם בַּגֵּיהִנֹּם, וְאֵין מִי שֶׁמְּרַחֵם עֲלֵיהֶם. אַשְׁרֵיהֶם כָּל שׁוֹמְרֵי הַשַּׁבָּת בָּעוֹלָם הַזֶּה, וּמְעַנְּגִים אֶת אוֹתוֹ הָעֹנֶג שֶׁשּׁוֹרֶה מִלְמַעְלָה, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>זְהִ מִי שֶׁשּׁוֹרֶה בְתַעֲנִית בְּשַׁבָּת, שְׁנַיִם מִתְעוֹרְרִים עָלָיו לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אֶחָד, אוֹתָהּ רוּחַ עֶלְיוֹנָה קְדוֹשָׁה שֶׁהִצְטָרֵךְ לְהִתְעַנֵּג וְלֹא הִתְעַנֵּג. וְאֶחָד, אוֹתוֹ מְמֻנֶּה שֶׁעוֹמֵד עַל מִי שֶׁשָּׁרוּי בְּתַעֲנִית, וּשְׁמוֹ סַנְגַּרְיָ\"ה. וְעוֹלִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ וּמִתְעוֹרְרִים עָלָיו.</p>\n<p>וְאוֹתָהּ רוּחַ מִסְתַּלֶּקֶת חֲסֵרָה מֵאוֹתָהּ הֲנָאָה שֶׁלְּמַטָּה. וּכְשֶׁהָרוּחַ הַזּוֹ לֹא נִשְׁלְמָה לְמַטָּה, רוּחַ אַחֶרֶת שֶׁלְּמַעְלָה לֹא נִשְׁלְמָה. כֵּיוָן שֶׁלֹּא נִשְׁלְמוּ לְמַטָּה וּלְמַעְלָה, אָז רָאוּי אוֹתוֹ אָדָם לְהִתְקַלֵּל וּלְהֵעָנֵשׁ. אֶלָּא כֵּיוָן שֶׁנִּשְׁלַם בִּזְמַן אַחֵר, וְאוֹתוֹ מְמֻנֶּה שֶׁהִתְמַנָּה עַל עִנּוּי וְתַעֲנִית נִשְׁלָם בְּתוֹךְ אוֹתָם מְמֻנִּים אֲחֵרִים בָּעֹנֶג שֶׁלְּמַעְלָה, קוֹרְעִים לוֹ כָּל גְּזַר דִּינוֹ שֶׁנִּגְזַר מֵאוֹתָם שִׁבְעִים שָׁנִים עֶלְיוֹנִים.</p>\n<p>לְמֶלֶךָ שֶׁשָּׂמַח בַּהִלּוּלָא שֶׁלּוֹ, וְכָל בְּנֵי הָאָדָם שְׂמֵחִים עִמּוֹ. רָאָה אִישׁ אֶחָד נָתוּן בְּקוֹלָר, צִוָּה עָלָיו וְהִתִּירוּהוּ, כְּדֵי שֶׁכֻּלָּם יִמָּצְאוּ בְשִׂמְחָה.</p>\n<p>וְאַחַר כָּךְ חוֹזְרִים הַמְמֻנִּים הַלָּלוּ שֶׁמַּעֲנִישִׁים בְּנֵי אָדָם, וְנִפְרָעִים מִן הָאָדָם עַל שֶׁנִּמְצָא בִּגְלָלוֹ חִסָּרוֹן לְמַעְלָה וּמַטָּה. מַה תַּקָּנָתוֹ? לֵישֵׁב תַּעֲנִית עַל תַּעֲנִית. מָה הַטַּעַם? זֶה בִּטֵּל עֹנֶג שַׁבָּת - יְבַטֵּל עֹנֶג שֶׁל חֹל.</p>\n<p>וְאִם הוּא מְבַטֵּל עֹנֶג שַׁבָּת וּמִתְעַנֵּג בַּחֹל, דּוֹמֶה כְּמוֹ שֶׁמַּחֲשִׁיב עַל דָּבָר אַחֵר יוֹתֵר מִמַּה שֶּׁמַּחֲשִׁיב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. הָרוּחַ הָעֶלְיוֹנָה, קֹדֶשׁ הַקְּדָשִׁים שֶׁשּׁוֹרָה עָלָיו לֹא עִנֵּג, וּבִטְּלָהּ מִמֶּנּוּ. רוּחַ אַחֶרֶת שֶׁל חֹל שֶׁשּׁוֹרָה אַחַר כָּךְ עַל הָעוֹלָם מַחֲשִׁיב וּמְעַנֵּג אוֹתוֹ, אָז חוֹזְרִים וְנִפְרָעִים מִמֶּנּוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ תַּעֲנִית אַחֶרֶת בְּיוֹם רִאשׁוֹן שֶׁל חֹל, בִּזְמַן שֶׁשּׁוֹרָה עַל הָעוֹלָם אוֹתָהּ רוּחַ שֶׁל חֹל, וּבָזֶה יֵשׁ לוֹ רְפוּאָה, כֵּיוָן שֶׁלֹּא הֶחֱשִׁיב אֶת רוּחַ הַחֹל. וְסִימָנְךְ - (ויקרא ה) וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל וְגוֹ'. גַּזְלָן אֵינוֹ מַחֲשִׁיב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ מַחֲשִׁיב בְּנֵי אָדָם, לָכֵן אֵין לֹא עֹנֶשׁ כְּגַנָּב. גַּנָּב שֶׁמַּחֲשִׁיב בְּנֵי אָדָם יוֹתֵר מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, יאשׁ לוֹ עֹנֶשׁ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי מִי שֶׁמַּשְׁלִים לְמַטָּה אֶת אוֹתוֹ עֹנֶג עֶלְיוֹן כָּרָאוּי.</p>\n<p>הַיּוֹם הַזֶּה מִתְעַטֵּר בְּשִׁבְעִים עֲטָרוֹת, וְהַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ נִשְׁתַּלֵּם בְּכָל הַצְּדָדִים, וְכָל הַדְּרָגוֹת מוּאָרוֹת, וְהַכֹּל בְּשִׂמְחַת הַבְּרָכוֹת וּבִקְדֻשָּׁה עַל קְדֻשָּׁה וְתוֹסֶפֶת שֶׁל קְדֻשָּׁה.</p>\n<p>קְדֻשָּׁה שֶׁל עֶרֶב שַׁבָּת זוֹהִי קְדֻשָּׁה שֶׁל שַׁבַּת בְּרֵאשִׁית. שֶׁהֲרֵי מִתְקַדֵּשׁ מִשְּׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים, וְשָׁלֹשׁ דְּרָגוֹת שֶׁל תַּפּוּחִים הַקְּדוֹשִׁים. וּצְרִיכִים לְהַזְכִּיר עַל הַקְּדֻשָּׁה הַזּוֹ אֶת כְּלַל מַעֲשֵׂה בְרֵאשִׁית, וּמְנוּחָה בְּסוֹד שֶׁל שְׁלֹשִׁים וּשְׁנַיִם הַשְּׁבִילִים וּשְׁלֹשׁ הַדְּרָגוֹת שֶׁנִּכְלָלוֹת בָּהֶם, סוֹד הָעֵדוּת שֶׁל מַעֲשֵׂה בְרֵאשִׁית, דְּהַיְנוּ (בראשית ב) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם וְגוֹ'. וַיְכַל אֱלֹהִים, שֶׁיֵּשׁ בָּעֵדוּת הַזּוֹ שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת, שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים עִם שְׁלֹשׁ הַדְּרָגוֹת שֶׁל הַתַּפּוּחִים הַקְּדוֹשִׁים.</p>\n<p>שָׁלש דְּרָגוֹת, שֶׁהֵן: שְׁבִיעִי. שְׁבִיעִי. שְׁבִיעִי. וְיֵשׁ בּוֹ סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְסוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְסוֹד כָּל הָאֱמוּנָה. שָׁלֹשׁ פְּעָמִים אֱלֹהִים: אֶחָד הָעוֹלָם הַתַּחְתּוֹן. אֶחָד פַּחַד יִצְחָק. וְאֶחָד הָעוֹלָם הָעֶלְיוֹן הַקָּדוֹשׁ, קֹדֶשׁ קָדָשִׁים. צָרִיךְ אָדָם לְהָעִיר אֶת הָעֵדוּת הַזּוֹ בְּשִׂמְחָה וּרְצוֹן הַלֵּב, לְהָעִיד לִפְנֵי בַעְלָהּ שֶׁל הָאֱמוּנָה. וְכָל מִי שֶׁמֵּעִיד אֶת זֶה וְיָשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, מְכַפֵּר עַל כָּל חֲטָאָיו.</p>\n<p>בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְמִצְותָיו וְרָצָה בָנוּ וְכוּ', קִדּוּשׁ זֶה הוּא בְּמִשְׁקָל אֶחָד כְּנֶגֶד עֵדוּת הָאֱמוּנָה, וְהֵם שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת אֲחֵרוֹת, כְּמוֹ שֶׁיֵּשׁ בְּוַיְכֻלּוֹ. הַכֹּל עוֹלֶה לְשִׁבְעִים תֵּבוֹת לְהִתְעַטֵּר בָּהֶם שַׁבָּת שֶׁל עֶרֶב שַׁבָּת. אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁיְּכַוֵּן רְצוֹנוֹ לַדְּבָרִים הַלָּלוּ לִכְבוֹד רִבּוֹנוֹ.</p>\n<p>קִדּוּשׁ הַיּוֹם, הֲרֵי פֵּרְשׁוּהוּ בּוֹרֵא פְּרִי הַגֶּפֶן, וְלֹא יוֹתֵר. שֶׁהֲרֵי הַיּוֹם עוֹמֵד לְקַדֵּשׁ אוֹתוֹ. מַה שֶּׁאֵין כֵּן בַּלַּיְלָה, שֶׁאָנוּ צְרִיכִים לְקַדֵּשׁ אוֹתוֹ בַּדְּבָרִים הַלָּלוּ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְלֹא מִתְקַדֵּשׁ הַלַּיְלָה הַזֶּה, אֶלָּא רַק בָּעָם הַקָּדוֹשׁ לְמַטָּה, כְּשֶׁשּׁוֹרָה עֲלֵיהֶם אוֹתָהּ רוּחַ עֶלְיוֹנָה. וְאָנוּ צְרִיכִים לְקַדְּשׁוֹ בִּרְצוֹן הַלֵּב, וּלְכַוֵּן הַדַּעַת לָזֶה.</p>\n<p>וְהַיּוֹם מְקַדֵּשׁ אוֹתוֹ, וְיִשְׂרָאֵל מְקַדְּשִׁים בִּתְפִלּוֹת וּבַקָּשׁוֹת וּמִתְקַדְּשִׁים בִּקְדֻשָּׁתוֹ בַּיּוֹם הַזֶּה. אַשְׁרֵי יִשְׂרָאֵל הָעָם הַקָּדוֹשׁ שֶׁיָּרְשׁוּ יוֹם הַזֶּה נַחֲלַת יְרֻשָּׁה לְעוֹלָמִים.</p>"],[9522011837,"<p>אַחַר שֶׁיּוֹצֵאת שַׁבָּת, צָרִיךְ אָדָם לְהַבְדִּיל בֵּין קֹדֶשׁ לְחֹל. לָמָּה? שֶׁהֲרֵי נִתְּנָה רְשׁוּת לַמְמֻנִּים שֶׁלְּמַטָּה לִשְׁלֹט עַל הָעוֹלָם, וּבְכָל מַעֲשֵׂי הָעוֹלָם לְהַרְאוֹת יִחוּד בְּמָקוֹם קָדוֹשׁ, בִּקְדֻשָּׁה עֶלְיוֹנָה, וּלְהַפְרִיד לְמַטָּה מִיִּחוּד הָעֶלְיוֹן, וּלְבָרֵךְ עַל מְאוֹרֵי הָאֵשׁ.</p>\n<p>מִשּׁוּם שֶׁכָּל הָאִשִּׁים הָאֲחֵרִים נִטְמְנוּ וְנִגְנְזוּ בְּיוֹם הַשַּׁבָּת, פְּרָט לְאֵשׁ אַחַת שֶׁל קְדֻשָּׁה עֶלְיוֹנָה שֶׁנִּגְלְתָה וְנִכְלְלָה בִּקְדֻשַּׁת הַשַּׁבָּת. וּכְשֶׁהָאֵשׁ הַזּוֹ מִתְגַּלָּה, כָּל יֶתֶר הָאִשּׁוֹת נִטְמָנוֹת וְנִגְנָזוֹת לְפָנֶיהָ. וְהָאֵשׁ הַזּוֹ הִיא שֶׁל עֲקֵדַת יִצְחָק, שֶׁלּוֹהֶטֶת עַל גַּבֵּי הַמִּזְבֵּחַ. מִשּׁוּם כָּךְ צָרִיךְ לְבָרֵךְ עַל מְאוֹרֵי הָאֵשׁ. וְהָאֵשׁ הַזּוֹ לֹא צְרִיכָה אֵשׁ שֶׁל חֹל, אֶלָּא אֵשׁ שֶׁל שַׁבָּת, וְהָאֵשׁ הַזּוֹ הִיא אֵשׁ שֶׁיּוֹצֵאת מֵאוֹתָהּ הָאֵשׁ שֶׁלְּמַעְלָה.</p>\n<p>וְזוֹהִי אֵשׁ שֶׁסּוֹבֶלֶת אֵשׁ. וְכֵיוָן שֶׁהָאֵשׁ הַזּוֹ שֶׁיּוֹצֵאת מֵהָאֵשׁ שֶׁלְּמַעְלָה מִתְבָּרֶכֶת בְּבִרְכַּת הָאוֹר, אָז כָּל שְׁאָר הָאִשּׁוֹת הָאֲחֵרוֹת יוֹצְאוֹת וְנִתְמַנּוֹת בִּמְקוֹמָן, וְנִתֶּנֶת לָהֶן רְשׁוּת לְהָאִיר.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁמְּבָרְכִים עַל הָאֵשׁ, מִזְדַּמְּנוֹת אַרְבַּע מֶרְכָּבוֹת, אַרְבַּע מַחֲנוֹת לְמַטָּה, לְהָאִיר מֵאוֹתָהּ אֵשׁ מְבֹרֶכֶת, וְהֵם נִקְרָאִים מְאוֹרֵי הָאֵשׁ. מִשּׁוּם כָּךְ צָרִיךְ לִכְפֹּף אַרְבַּע אֶצְבָּעוֹת שֶׁל יַד יָמִין, וּלְהָאִיר לָהֶם מִתּוֹךְ אוֹתוֹ אוֹר הַנֵּר שֶׁמִּתְבָּרֵךְ.</p>\n<p>וְאוֹתָן אֶצְבָּעוֹת רֶמֶז לְאוֹתָם מְאוֹרֵי הָאֵשׁ שֶׁמְּאִירִים וְשׁוֹלְטִים מֵאוֹתוֹ הָאוֹר שֶׁל הַנֵּר שֶׁמִּתְבָּרֵךְ. וּמִשּׁוּם שֶׁהֵן דְּרָגוֹת שֶׁלְּמַטָּה, כְּשֶׁמַּרְאֶה אָדָם הָאֶצְבָּעוֹת לִפְנֵי אוֹתוֹ אוֹר הַנֵּר, צָרִיךְ לְכָפְפָם לְפָנָיו, מִשּׁוּם שֶׁאוֹתוֹ אוֹר שׁוֹלֵט עֲלֵיהֶם, וְהֵם מְאִירִים מִמֶּנּוּ.</p>\n<p>בִּשְׁאָר הַבְּרָכוֹת צָרִיךְ לִזְקֹף אֶת הָאֶצְבָּעוֹת כְּדֵי לְהַרְאוֹת קְדֻשָּׁה עֶלְיוֹנָה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁשּׁוֹלְטוֹת עַל הַכֹּל, שֶׁהַשֵּׁם הַקָּדוֹשׁ הִתְעַטֵּר בָּהֶן וְהִתְקַדֵּשׁ בָּהֶן, וְכָל הַדְּרָגוֹת מִתְבָּרְכוֹת כְּאֶחָד, וּמְאִירִים מִתּוֹךְ הַמְּנוֹרָה הָעֶלְיוֹנָה שֶׁל הַכֹּל, וּמִשּׁוּם כָּךְ צְרִיכִים לְזָקְפָם לְמַעְלָה. וְכָאן צָרִיךְ לְכוֹפֵף אֶת הָאֶצְבָּעוֹת לִפְנֵי הַנֵּר כְּדֵי לְהַרְאוֹת אֶת הַדְּרָגוֹת שֶׁלְּמַטָּה שֶׁמְּאִירִים מִתּוֹךְ הַמָּאוֹר הָעֶלְיוֹן, וּמִכָּאן שׁוֹלְטִים וּמְאִירִים מִמֶּנָּה, וְהֵם מְאוֹרֵי הָאֵשׁ.</p>\n<p>בְּכָל יוֹם אָנוּ מְבָרְכִים מְאוֹרֵי אוֹר, שֶׁהֵם אוֹרוֹת עֶלְיוֹנִים שֶׁעוֹמְדִים בְּאוֹתוֹ אוֹר רִאשׁוֹן, וְכָל הַדְּרָגוֹת מִתְבָּרְכוֹת וּמְאִירוֹת כֻּלָּן כְּאַחַת מִתּוֹךְ הַמָּאוֹר הָעֶלְיוֹן, וְאֵלֶּה נִקְרָאִים מְאוֹרֵי הָאֵשׁ. וּמִשּׁוּם הַסּוֹד הַזֶּה מְבָרְכִים בּוֹרֵא מְאוֹרֵי הָאֵשׁ.</p>\n<p>וְאִם תֹּאמַר, לָמָּה בּוֹרֵא, וְלֹא אוֹמְרִים מֵאִיר מְאוֹרֵי הָאֵשׁ, הוֹאִיל וּמְאִירִים מֵאוֹתָהּ הָאֵשׁ, מֵאוֹתָהּ מְנוֹרָה מְברֶכֶת? אֶלָּא, כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת, כָּל אוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה וְכָל אוֹתָם שֶׁמְּאִירִים וְשׁוֹלְטִים, כֻּלָּם נִכְנָסִים וְנִכְלָלִים בַּנֵּר הַזֶּה, וְנִטְמָנִים וְנִגְנָזִים וְנִשְׁמָרִים בּוֹ וְלֹא נִרְאִים בּוֹ, אֶלָּא רַק אוֹתָהּ נְקֻדָּה לְבַדָּהּ, וְכֻלָּם נִטְמְנוּ בְתוֹכָהּ בְּכָל יוֹם הַשַּׁבָּת.</p>\n<p>כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, הוּא מוֹצִיא אוֹתָם כָּל אֶחָד וְאֶחָד כְּאִלּוּ נִבְרְאוּ בְּאוֹתָהּ שָׁעָה, וְכֻלָּם יָצְאוּ וְנִבְרְאוּ כְּמִקֹּדֶם וְהִתְמַנּוּ עַל מְקוֹמָם לִשְׁלֹט, וְאָז הַנֵּר הַזֶּה מִתְבָּרֵךְ, וְנִכְנָעִים לְפָנָיו לְהָאִיר. כֵּיוָן שֶׁמְּאִירִים, אָז הֵם מִתְמַנִּים כָּל אֶחָד וְאֶחָד עַל מְקוֹמוֹ.</p>\n<p>כְּמוֹ זֶה אוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת שֶׁנִּקְרָאוֹת מְאוֹרֵי אוֹר, שׁוֹלְטוֹת בַּיּוֹם וּמְאִירוֹת מִתוֹךְ הַמָּאוֹר הָעֶלְיוֹן. בְּשָׁעָה שֶׁיּוֹרֵד הַלַּיְלָה, אוֹתוֹ מָאוֹר עֶלְיוֹן כּוֹנֵס אוֹתָם וּמַכְנִיס אוֹתָם לְתוֹכוֹ עַד שֶׁמֵּאִיר הַיּוֹם. כֵּיוָן שֶׁיִּשְׂרָאֵל מְבָרְכִים עַל הָאוֹר בַּיּוֹם, אָז מוֹצִיא אוֹתָם בִּשְׁלֵמוּת הָאוֹר, וְלָכֵן מְבָרְכִים יוֹצֵר הַמְּאוֹרוֹת וְלֹא אוֹמְרִים בּוֹרֵא (אלאיוצר). וְכָאן בּוֹרֵא מְאוֹרֵי הָאֵשׁ, מִשּׁוּם אוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה.</p>\n<p>וְהַסֹל הוּא סוֹד הָאֶצְבָּעוֹת, בָּהֶן רְמוּזוֹת הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַדְּרָגוֹת הַתַּחְתּוֹנוֹת. הַדְּרָגוֹת הָעֶלְיוֹנוֹת נוֹדָעוֹת בִּזְקִיפַת הָאֶצְבָּעוֹת לְמַעְלָה, וּבִזְקִיפַת הָאֶצְבָּעוֹת מִתְבָּרְכוֹת הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַדְּרָגוֹת הַתַּחְתּוֹנוֹת כְּאֶחָד, וּבְהַנְמָכַת הָאֶצְבָּעוֹת מִתְבָּרְכִים לְהָאִיר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת לְבַדָּן.</p>"],[9522011838,"<p>וְהַסּוֹד הַזֶּה, הַצִּפָּרְנַיִם שֶׁל אֲחוֹרֵי הָאֶצְבָּעוֹת. וְהָאֶצְבָּעוֹת לְבַדָּן לִפְנִים. הַצִּפָּרְנַיִם שֶׁל אֲחוֹרֵי הָאֶצְבָּעוֹת הֵם פָּנִים אֲחֵרוֹת שֶׁצְּרִיכוֹת לְהָאִיר מִתּוֹךְ אוֹתוֹ נֵר, וְאוֹתָם פָּנִים שֶׁנִּקְרָאִים אֲחוֹרַיִם. הָאֶצְבָּעוֹת לִפְנִים בְּלִי צִפָּרְנַיִם, אֵלּוּ הֵן הַפָּנִים הַפְּנִימִיִּים הַמְכֻסִּים. וְסוֹד זֶה - (שמות לג) וְרָאִיתָ אֶת אֲחֹרָי. אֵלֶּה אֲחוֹרֵי הָאֶצְבָּעוֹת לְאָחוֹר בְּצִפָּרְנֵיהֶן. וּפָנַי לֹא יֵרָאוּ, אֵלֶּה הָאֶצְבָּעוֹת לִפְנִים בְּלִי צִפָּרְנַיִם, שֶׁהֵן הַפָּנִים הַפְּנִימִיִּים.</p>\n<p>וּכְשֶׁמְּבָרְכִים עַל הַנֵּר, צָרִיךְ לְהַרְאוֹת אֶת אֲחוֹרֵי הָאֶצְבָּעוֹת בַּצִּפָּרְנַיִם, לְקַבֵּל אוֹר מִתּוֹךְ אוֹתוֹ הַנֵּר, וְאֶת פְּנִים הָאֶצְבָּעוֹת לֹא צָרִיךְ לִכְפּוֹת (להראות) אוֹתָן שֶׁיָּאִירוּ מִתּוֹךְ אוֹתוֹ נֵר, שֶׁהֲרֵי אֵינָן מְאִירוֹת אֶלָּא מִתּוֹךְ הַנֵּר הָעֶלְיוֹן שֶׁלְּמַעְלָה לְמַעְלָה, שֶׁהוּא טָמִיר וְגָנוּז וְשֶׁלֹּא נִגְלֶה כְּלָל. וְאֵינָן מְאִירוֹת מִתּוֹךְ נֵר שֶׁגָּלוּי כְּלָל. מִשּׁוּם כָּךְ צָרִיךְ לְהַרְאוֹת אֶת אֲחוֹרֵי הָאֶצְבָּעוֹת בַּצִּפָּרְנַיִם, וְאֶת פְּנִים הָאֶצְבָּעוֹת לֹא צָרִיךְ לְהַרְאוֹת לִפְנֵי הַנֵּר הַזֶּה. טְמִירוֹת הֵן, וּבַסֵּתֶר הֵן מְאִירוֹת. פְּנִימִיּוֹת הֵן, וּמִפְּנִימִיִּים מְאִירוֹת. עֶלְיוֹנוֹת הֵן, וּמֵעֶלְיוֹנִים הֵן מְאִירוֹת. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְצָרִיךָ לְהָרִיחַ בִּבְשָׂמִים כְּשֶׁיּוֹצֵאת שַׁבָּת עַל שֶׁהִסְתַּלְּקָה אוֹתָהּ רוּחַ, וְנֶפֶשׁ הָאָדָם נִשְׁאֶרֶת עֲרֻמָּה (משתגית בבקעים) מִשּׁוּם אוֹתוֹ סִלּוּק שֶׁהִסְתַּלְּקָה הָרוּחַ מִמֶּנּוּ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>כָּתוּב (בראשית כז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר. אֲבָל בּא וּרְאֵה, הָרֵיחַ הוּא קִיּוּם הַנֶּפֶשׁ, מִשּׁוּם שֶׁהוּא דָּבָר שֶׁנִּכְנָס לַנֶּפֶשׁ וְלֹא לַגּוּף. בֹּא וּרְאֵה, כָּתוּב וַיָּרַח אֶת רֵיחַ בְּגָדָיו, הֲרֵי פֵּרְשׁוּהוּ שֶׁאֵלּוּ הָיוּ אוֹתָם לְבוּשֵׁי אָדָם הָרִאשׁוֹן שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְלָבְשָׁם.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי כְּשֶׁחָטָא אָדָם, הָעֳבַר מִמֶּנּוּ אוֹתוֹ לְבוּשׁ נִכְבָּד שֶׁהִתְלַבֵּשׁ בּוֹ בָּרִאשׁוֹנָה כְּשֶׁהִכְנִיסוֹ לְגַן עֵדֶן, וְאַחַר שֶׁחָטָא הִלְבִּישׁ אוֹתוֹ בִּלְבוּשׁ אַחֵר. הַלְּבוּשׁ הָרִאשׁוֹן שֶׁהִתְלַבֵּשׁ בּוֹ אָדָם בְּגַן עֵדֶן, הוּא הָיָה (מאותם מלבושים) מֵאוֹתָן מֶרְכָּבוֹת שֶׁנִּקְרְאוּ אֲחוֹרַיִם, וְאוֹתָם לְבוּשִׁים שֶׁנִּקְרְאוּ לְבוּשֵׁי צִפֹּרֶן.</p>\n<p>וּכְשֶׁהָיָה בְּגַן עֵדֶן, כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם מַחֲנוֹת קְדוֹשִׁים, כֻּלָּם הִקִּיפוּ אֶת אָדָם, וְנִשְׁמַר מֵהַכֹּל, וְלֹא הָיָה יָכוֹל דָּבָר רַע לִקְרַב אֵלָיו. וְכֵיוָן שֶׁחָטָא וְהָעָבְרוּ מִמֶּנּוּ אוֹתָם לְבוּשִׁים, (והתלבש בלבושי חל מדברים) פָּחַד מִדְּבָרִים רָעִים וְרוּחוֹת רָעוֹת, וְהִסְתַּלְּקוּ מִמֶּנּוּ אוֹתָם מַחֲנוֹת קְדוֹשִׁים. וְלֹא נִשְׁאֲרוּ בוֹ אֶלָּא אוֹתָם רָאשֵׁי צִפָּרְנֵי הָאֶצְבָּעוֹת שֶׁסּוֹבְבִים אֶת הַצִּפָּרְנַיִם סְבִיב זֻהֲמָה אַחֶרֶת.</p>\n<p>וּמִשּׁוּם כָּךְ לֹא צָרִיךְ לְאָדָם לְגַדֵּל אוֹתָן צִפָּרְנַיִם שֶׁל זֻהֲמָה, שֶׁהֲרֵי כַּמָּה שֶׁמִּתְרַבּוֹת, כָּךְ גַּם מַרְבֶּה עָלָיו זֻהֲמָה, וְיִדְאַג בְּכָל יוֹם וְצָרִיךְ לִגְזר אוֹתָן, וְלֹא יִזְרֹק אוֹתָן, שֶׁלֹּא יַעֲשֶׂה קָלוֹן בְּאוֹתוֹ מָקוֹם, שֶׁיָּכוֹל אוֹתוֹ אָדָם לְהִנָּזֵק. וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. שֶׁהֲרֵי לְכָל אֲחוֹרַיִם מַקִּיף הַצַּד הָאַחֵר, וְלֹא צְרִיכִים אוֹתוֹ בַּמָּקוֹם שֶׁל הָעוֹלָם.</p>\n<p>אַחַר כָּךְ עָשָׂה לְאָדָם לְבוּשִׁים אֲחֵרִים מֵהֶעָלִים שֶׁל עֲצֵי גַּן הָעֵדֶן שֶׁבָּאָרֶץ. שֶׁהֲרֵי בָּרִאשׁוֹנָה הָיוּ אוֹתָם לְבוּשִׁים מֵאוֹתָם אֲחוֹרַיִם שֶׁל הַגָּן שֶׁלְּמַעְלָה, וְעַכְשָׁו מֵהַגָּן שֶׁל הָאָרֶץ, וְיָצְאוּ מֵהַגָּן. וְאוֹתָם לְבוּשִׁים הָיוּ מַעֲלִים רֵיחוֹת וּבְשָׂמִים שֶׁל הַגָּן שֶׁהַנֶּפֶשׁ מִתְיַשֶּׁבֶת בָּהֶם וּשְׂמֵחָה בָהֶם. זֶהוּ שֶׁכָּתוּב וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ, שֶׁהֲרֵי הִתְיַשְּׁבָה נַפְשׁוֹ וְרוּחוֹ שֶׁל יִצְחָק בְּאוֹתוֹ רֵיחַ.</p>"],[9522011839,"<p>מִשּׁוּם כָּךְ, כְּשֶׁיּוֹצֵאת שַׁבָּת, צָרִיךְ לְהָרִיחַ בַּבְּשָׂמִים לְיַשֵּׁב אֶת נַפְשׁוֹ בְּאוֹתוֹ רֵיחַ עַל אוֹתוֹ רֵיחַ עֶלְיוֹן קָדוֹשׁ שֶׁהִסְתַּלֵּק מִמֶּנּוּ, וְאוֹתוֹ רֵיחַ הַמְעֻלֶּה שֶׁבַּבְּשָׂמִים הוּא הֲדַס, שֶׁהֲרֵי קִיּוּם הַמָּקוֹם הַקָּדוֹשׁ שֶׁמִּמֶּנּוּ יוֹצְאוֹת הַנְּשָׁמוֹת הוּא הֲדַס. וְזֶהוּ קִיּוּם הַנֶּפֶשׁ כְּמוֹ שֶׁלְּמַעְלָה, כְּדֵי לְהִתְקַיֵּם מֵאוֹתָהּ הִתְעַרְטְלוּת שֶׁנִּשְׁאֲרָה.</p>\n<p>כְּשֶׁיּוֹצֵאת הַשַּׁבָּת, הִתְלַבֵּשׁ אָדָם בְּאוֹתָם לְבוּשֵׁי גַּן עֵדֶן שֶׁל הָאָרֶץ שֶׁמַּעֲלִים רֵיחַ וּבְשָׂמִים, לְקַיֵּם אֶת הַנֶּפֶשׁ עַל אוֹתָהּ רוּחַ קְדוֹשָׁה עֶלְיוֹנָה נִכְבָּדָה שֶׁהִסְתַּלְּקָה מִמֶּנּוּ. וַהֲדַס הוּא וַדַּאי קִיּוּם הַנֶּפֶשׁ, כְּדֻגְמָא עֶלְיוֹנָה, שֶׁהִתְקַיְּמָה קִיּוּם הַנֶּפֶשׁ.</p>"],[9522011840,"<p>אוֹתָהּ רוּחַ עֶלְיוֹנָה שֶׁיּוֹרֶדֶת עַל אָדָם בְּשִׂמְחָה וּמְשַׂמַּחַת אֶת נַפְשׁוֹ, אָז עוֹמֶדֶת נֶפֶשׁ הָאָדָם כְּמוֹ הָעוֹלָם הַבָּא, שֶׁעָתִיד לֵהָנוֹת מִמֶּנּוּ. כְּמוֹ שֶׁאָדָם מְהַנֶּה אֶת הָרוּחַ הַזּוֹ בָּעוֹלָם הַזֶּה, כָּךְ אוֹתָהּ רוּחַ מְהַנָּה אוֹתוֹ לָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה' וְגוֹ'. וְכָתוּב וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. כְּמוֹ שֶׁאָדָם מַרְוֶה אֶת אוֹתוֹ עֹנֶג וּמְהַנֶּה אוֹתוֹ, כָּךְ גַּם הוּא מַרְוֶה אוֹתוֹ לָעוֹלָם הַבָּא. אָז כְּשֶׁהָאָדָם זוֹכֶה וּמַשְׁלִים אֶת שְׁלֵמוּת כְּבוֹד שַׁבָּת כְּפִי שֶׁאָמַרְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו וְאוֹמֵר, (שם מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>קָם רַבִּי אַבָּא וּשְׁאָר הַחֲבֵרִים וְנָשְׁקוּ רֹאשׁוֹ. בָּכוּ וְאָמְרוּ, אַשְׁרֵי חֶלְקֵנוּ שֶׁהַדֶּרֶךְ הַזּוֹ זִמֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לְפָנֵינוּ. אָמַר רַבִּי אַבָּא, לִי זִמֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא הַדֶּרֶךְ הַזּוֹ כְּדֵי לְהִתְחַבֵּר עִמָּכֶם. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לַדֶּרֶךְ הַ את.</p>\n<p>אָמַר לָהֶם, אֹמַר לָכֶם מַה שֶּׁרָאִיתִי, הַיּוֹם הַזֶּה יָצָאתִי לַדֶּרֶךְ, וְרָאִיתִי אוֹר אֶחָד שֶׁנֶּחֱלָק לִשְׁלֹשָׁה אוֹרוֹת, וְהָלְכוּ לְפָנַי וְנִטְמְנוּ. וְאָמַרְתִּי, וַדַּאי שְׁכִינָה רָאִיתִי, אַשְׁרֵי חֶלְקִי. וְעַכְשָׁו אוֹתָם שְׁלֹשֶׁת הָאוֹרוֹת שֶׁרָאִיתִי, אַתֶּם הֵם, וַדַּאי שֶׁאַתֶּם אוֹרוֹת וּמְנוֹרוֹת עֶלְיוֹנוֹת לְהָאִיר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי אַבָּא, עַד כָּאן לֹא יָדַעְתִּי שֶׁכָּל הַמַּרְגָּלִיּוֹת הַנִּסְתָּרוֹת הַלָּלוּ הָיוּ תַחַת יְדֵיכֶם, כֵּיוָן שֶׁרָאִיתִי שֶׁהֲרֵי בִּרְצוֹן מִצְוַת רִבּוֹנְכֶם נֶאֶמְרוּ הַדְּבָרִים הַלָּלוּ, יָדַעְתִּי שֶׁכָּל הַדְּבָרִים עוֹלִים בְּיוֹם זֶה לְתוֹךְ הַכִּסֵּא הָעֶלְיוֹן וְלוֹקֵחַ אוֹתָם אוֹתוֹ בַּעַל הַפָּנִים וְעוֹשֶׂה מֵהֶם עֲטָרוֹת לַאֲדוֹנוֹ. וְהַיּוֹם הַזֶּה מִתְעַטְּרִים (שבעים) שִׁשִּׁים מֶרְכָּבוֹת קְדוֹשׁוֹת לִכְבוֹד הַכִּסֵּא בְּאוֹתָם דְּבָרִים שֶׁנֶּאֶמְרוּ כָּאן בַּיּוֹם הַזֶּה.</p>\n<p>בֵּין כָּךְ זָקַף אֶת עֵינָיו וְרָאָה שֶׁהֶעֱרִיב הַשֶּׁמֶשׁ. אָמַר רַבִּי אַבָּא, נֵלֵךְ לַכְּפָר הַזֶּה שֶׁהוּא קָרוֹב לָנוּ בַּמִּדְבָּר. הָלְכוּ וְלָנוּ שָׁם. בַּחֲצוֹת הַלַּיְלָה קָם רַבִּי אַבָּא וּשְׁאָר הַחֲבֵרִים לְהִשְׁתַּדֵּל בַּתּוֹרָה. אָמַר רַבִּי אַבָּא, מִכָּאן וָהָלְאָה נֹאמַר דְּבָרִים לְעַטֵּר בָּהֶם אֶת הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, שֶׁעַכְשָׁו הוּא הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁל עֵדֶן מַקְשִׁיבִים לְקוֹלוֹת הַצַּדִּיקִים שֶׁבָּאָרֶץ.</p>"],[9522011841,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, כָּתוּב (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה' וְהָאָרֶץ נָתַן לִבְנֵי אָדָם. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, וְכָךְ צָרִיךְ לוֹמַר: הַשָּׁמַיִם לַה', וְהָאָרֶץ נָתַן לִבְנֵי אָדָם. מַה זֶּה הַשָּׁמַיִם שָׁמַיִם? אֶלָּא כָּאן יֵשׁ לְהִתְבּוֹנֵן, מִשּׁוּם שֶׁיֵּשׁ שָׁמַיִם וְיֵשׁ שָׁמַיִם. שָׁמַיִם לְמַטָּה, וְאֶרֶץ לְמַטָּה מֵהֶם. שָׁמַיִם לְמַעְלָה, וְאֶרֶץ לְמַטָּה מֵהֶם. וְכָל הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת כֻּלָּן כְּמוֹ זֶה, אֵלֶּה בְּאֵלֶּה.</p>\n<p>שָׁמַיִם לְמַטָּה, הֵם עֶשֶׂר יְרִיעוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם קד) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָם וְאֶת הַמַּחֲנוֹת שֶׁבְּתוֹכָם לְהַנְהִיג אֶת הָאָרֶץ הַתַּחְתּוֹנָה. הַתְּשִׁיעִי מַנְהִיג אֶת הַתַּחְתּוֹנִים, שֶׁסּוֹבְבִים כַּעֲבוֹתוֹת הָעֲגָלָה. הָעֲשִׂירִי הוּא הָעִקָּר.</p>\n<p>וּבְכָל הַמַּחֲנוֹת מְמֻנִּים יֵשׁ עַד לַשְּׁבִיעִי. וּמֵהַשְּׁבִיעִי וָהָלְאָה יֵשׁ אוֹר שֶׁהִתְפַּשֵּׁט לְמַטָּה מִתּוֹךְ הַכִּסֵּא הָעֶלְיוֹן, וּמֵאִיר לָעֲשִׂירִי, וְהָעֲשִׂירִי, מֵאוֹתוֹ הָאוֹר שֶׁהוּא לוֹקֵחַ, נוֹתֵן לַתְּשִׁיעִי, וְהוּא לַשְּׁמִינִי וָמַטָּה.</p>\n<p>הַשְּׁמִינִי הַזֶּה, כְּשֶׁנִּפְקָדִים כֹּחוֹת הַכּוֹכָבִים וּמוֹצִיא אוֹתָם, אוֹתוֹ הָאוֹר עוֹמֵד וְנוֹתֵן כֹּחוֹ לְכָל אֶחָד וְאֶחָד לְהִתְמַנּוֹת בְּאוֹתוֹ מָקוֹם שֶׁצָּרִיךְ, שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ'. מֵרֹב אוֹנִים - זֶהוּ הַ הַר שֶׁלְּמַעְלָה שֶׁנִּקְרָא רֹב אוֹנִים.</p>\n<p>וּבְכָל רָקִיעַ וְרָקִיעַ יֵשׁ מְמֻנֶּה, וְנִפְקָד עַל הָעוֹלָם וְעַל הָאָרֶץ לְהַנְהִיג אֶת הַכֹּל. פְּרָט לְאֶרֶץ יִשְׂרָאֵל, שֶׁלֹּא מַנְהִיג אוֹתָהּ לֹא רָקִיעַ וְלֹא כֹּחַ אַחֵר, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וְאִם תֹּאמַר, אֵיךְ שָׁרוּי לְחִנָּם רָקִיעַ עַל אֶרֶץ יִשְׂרָאֵל, וַהֲרֵי טַל וּמָטָר יוֹרֵד עָלֶיהָ מֵהָרָקִיעַ כִּשְׁאָר כָּל אֶרֶץ אַחֶרֶת?</p>\n<p>אֶלָּא בְּכָל רָקִיעַ וְרָקִיעַ יֵשׁ מְמֻנִּים שֶׁשּׁוֹלְטִים עַל הָעוֹלָם, וְאוֹתוֹ מְמֻנֶּה שֶׁשּׁוֹלֵט עַל אוֹתוֹ רָקִיעַ נוֹתֵן מִן הַכֹּחַ שֶׁיֵּשׁ לוֹ לְאוֹתוֹ רָקִיעַ, (כדי לתת למטה) וְאוֹתוֹ רָקִיעַ לוֹקֵחַ מֵאוֹתוֹ מְמֻנֶּה, וְנוֹתֵן לְמַטָּה לָאָרֶץ. וְאוֹתוֹ הַמְמֻנֶּה אֵינוֹ לוֹקֵחַ אֶלָּא מֵהַתַּמְצִית שֶׁלְּמַעְלָה. אֲבָל הָאָרֶץ הַקְּדוֹשָׁה אֵין שׁוֹלֵט עַל אוֹתוֹ הָרָקִיעַ שֶׁעָלֶיהָ מְמֻנֶּה אַחֵר, וְלֹא כֹּחַ אַחֵר, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, וְהוּא פּוֹקֵד אֶת הָאָרֶץ הַקְּדוֹשָׁה בְּאוֹתוֹ רָקִיעַ.</p>\n<p>בְּכָל רָקִיעַ וְרָקִיעַ יֵשׁ פְּתָחִים יְדוּעִים וְשִׁלְטוֹן כָּל הַמְמֻנִּים מִפֶּתַח לְפֶתַח רָשׁוּם, וּמֵאוֹתוֹ פֶּתַח וָהָלְאָה לֹא שׁוֹלֵט אֲפִלּוּ כִּמְלֹא נִימָה, וְלֹא נִכְנָס זֶה (אפלו) לִתְחוּם פֶּתַח חֲבֵרוֹ פְּרָט לִכְשֶׁנִּתֶּנֶת לוֹ רְשׁוּת לִשְׁלֹט אֶחָד עַל חֲבֵרוֹ, וְאָז שׁוֹלְטִים הַמְּלָכִים שֶׁבָּאָרֶץ אֶחָד עַל חֲבֵרוֹ.</p>\n<p>בְּאֶמְצַע כָּל הָרְקִיעִים יֵשׁ פֶּתַח אֶחָד שֶׁנִּקְרָא גְּבִילוֹ\"ן, וְתַחַת הַפֶּתַח הַזֶּה יֵשׁ שִׁבְעִים פְּתָחִים אֲחֵרִים לְמַטָּה, וְשִׁבְעִים מְמֻנִּים שׁוֹמְרִים מֵרָחוֹק שֶׁל אַלְפַּיִם אַמָּה שֶׁלֹּא קְרֵבִים אֵלָיו. וּמֵאוֹתוֹ פֶּתַח עוֹלָה דֶּרֶךְ לְמַעְלָה לְמַעְלָה, עַד שֶׁמַּגִּיעָה לַכִּסֵּא הָעֶלְיוֹן, וּמֵאוֹתוֹ הַפֶּתַח לְכָל הַצְּדָדִים שֶׁבָּרָקִיעַ, עַד שַׁעַר הַפֶּתַח שֶׁנִּקְרָא מַגְדוֹ\"ן (מנדו\"ן), שֶׁשָּׁם הוּא סִיּוּם הָרָקִיעַ שֶׁל תְּחוּמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל.</p>\n<p>וְכָל אוֹתָם שִׁבְעִים פְּתָחִים שֶׁרְשׁוּמִים בְּתוֹךְ אוֹתוֹ פֶּתַח שֶׁנִּקְרָא גְּבִילוֹ\"ן, כֻּלָּם רְשׁוּמִים בַּכִּסֵּא הַקָּדוֹשׁ, וּלְכֻלָּם קוֹרְאִים שַׁעֲרֵי צֶדֶק, שֶׁלֹּא שׁוֹלֵט אַחֵר עֲלֵיהֶם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקֵד אֶת הָאָרֶץ הַקְּדוֹשָׁה בְּאוֹתוֹ רָקִיעַ, מִפֶּתַח לְפֶתַח בִּפְקִידָה כְּמוֹ שֶׁצָּרִיךְ. וּמִתַּמְצִית אוֹתָהּ פְּקִידָה מְקַבְּלִים אוֹתָם שִׁבְעִים מְמֻנִּים, וְנוֹתְנִים לְכָל הַמְמֻנִּים הָאֲחֵרִים.</p>"],[9522011842,"<p>בְּגַן עֵדֶן שֶׁלְּמַטָּה, בָּרָקִיעַ שֶׁעוֹמֵד עָלָיו, יֵשׁ בּוֹ סוֹד עֶלְיוֹנִים. כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָרָקִיעַ, הֵבִיא אֵשׁ וּמַיִם מִתּוֹךְ כִּסֵּא כְבוֹדוֹ וְשִׁתְּפָם כְּאֶחָד, וְעָשָׂה מֵהֶם רָקִיעַ לְמַטָּה, וְהִתְפַּשְּׁטוּ עַד שֶׁהִגִּיעוּ לְאוֹתוֹ מָקוֹם שֶׁל גַּן עֵדֶן וְיָשְׁבוּ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? לָקַח מֵהַשָּׁמַיִם הָעֶלְיוֹנִים הַקְּדוֹשִׁים אֵשׁ וּמַיִם אֲחֵרִים שֶׁנִּמְצָאִים וְלֹא נִמְצָאִים, שֶׁנִּגְלִים וְלֹא נִגְלִים, וּמֵאוֹתָם אֵשׁ וּמַים שֶׁנִּטְּלוּ מֵהַשָּׁמַיִם הָעֶלְיוֹנִים, עָשָׂה מֵהֶם מְתִיחַת הָרָקִיעַ, וּמָתַח אוֹתוֹ עַל הַגָּן הַזֶּה שֶׁלְּמַטָּה, וּמִתְחַבֵּר לְתוֹךְ רָקִיעַ אַחֵר.</p>\n<p>אַרְבָּעָה גְוָנִים בְּאוֹתָהּ מְתִיחַת הָרָקִיעַ שֶׁעַל הַגָּן - לָבָן אָדם יָרֹק וְשָׁחֹר. לַגְּוָנִים הַלָּלוּ יֵשׁ אַרְבָּעָה פְתָחִים מִתַּחַת לְאוֹתָהּ מְתִיחַת הָרָקִיעַ, וְאוֹתָם הַפְּתָחִים לְאַרְבַּעַת צִדְדֵי הָרָקִיעַ שֶׁעַל גַּבֵּי הַגָּן. וּמֵאוֹתָם אֵשׁ מַיִם שֶׁנַּעֲשָׂה מֵהֶם אוֹתוֹ רָקִיעַ, נִפְתָּחִים בְּאַרְבָּעָה פְתָחִים אַרְבָּעָה אוֹרוֹת.</p>\n<p>לְצַד יָמִין בְּאוֹתוֹ פֶּתַח מִתּוֹךְ מְתִיחַת צַד (המים) הַיָּמִין מְאִירִים שְׁנֵי אוֹרוֹת בְּאוֹתָם שְׁנֵי פְּתָחִים, בְּפֶתַח הַיָּמִין, וּבַפֶּתַח שֶׁהוּא (בפניםיוצאאור, והוא פנים) כְּנֶגֶד הַפָּנִים.</p>\n<p>בְּתוֹךָ הָאוֹר הַמֵּאִיר לְצַד יָמִין רְשׁוּמָה אוֹת אַחַת מְאִירָה וּבוֹלֶטֶת (ולוהטת) וְנוֹצֶצֶת בְּהִתְנוֹצְצוּת מִתּוֹךְ אוֹתוֹ הָאוֹר, וְהִיא הָאוֹת מ', וְעוֹמֶדֶת בְּאֶמְצַע אוֹתוֹ הָאוֹר שֶׁל הַפֶּתַח. הָאוֹת הַזּוֹ עוֹלָה וְיוֹרֶדֶת, וְלֹא עוֹמֶדֶת בְּמָקוֹם אֶחָד. אוֹתוֹ הָאוֹר לוֹקֵחַ אוֹתָהּ אוֹת וּמוֹצִיא אוֹתָהּ, וּמִשּׁוּם כָּךְ אֵינָהּ עוֹמֶדֶת בְּמָקוֹם אֶחָד.</p>\n<p>בְּתוֹךָ הָאוֹר הַמֵּאִיר בַּצַּד שֶׁהוּא כְּנֶגֶד הַפָּנִים, רְשׁוּמָה אוֹת אַחַת שֶׁמְּאִירָה וּבוֹלֶטֶת וְנוֹצֶצֶת בְּהִתְנוֹצְצוּת בְּתוֹךְ אוֹתוֹ הָאוֹר, וְהִיא הָאוֹת ר', וְלִפְעָמִים נִרְאֵית ב' (ד'), וְעוֹמֶדֶת בְּאֶמְצַע אוֹתוֹ הָאוֹר שֶׁבַּפֶּתַח, וְעוֹלָה וְיוֹרֶדֶת, לִפְעָמִים גְּלוּיָה וְלִפְעָמִים לֹא גְלוּיָה, וְלֹא עוֹמֶדֶת בְּמָקוֹם אֶחָד. שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ עוֹמְדוֹת, וּכְשֶׁנִּשְׁמוֹת הַצַּדִּיקִים נִכְנָסוֹת לְגַן עֵדֶן, שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ יוֹצְאוֹת מִתּוֹךְ אוֹתוֹ הָאוֹר, וְעוֹמְדוֹת עַל אוֹתָהּ נְשָׁמָה, וְעוֹלִים וְיוֹרְדִים.</p>\n<p>וְאָז, מֵאוֹתָם שְׁנֵי הַפְּתָחִים, מַקְדִּימִים וְיוֹרְדִים מִלְמַעְלָה שְׁתֵּי מֶרְכָּבוֹת. מֶרְכָּבָה עֶלְיוֹנָה אַחַת, שֶׁהִיא מֶרְכַּבְתּוֹ שֶׁל מִיכָאֵל, גְּדוֹל הַסְּגָנִים. הַמֶּרְכָּבָה הַשְּׁנִיָּה, שֶׁהִיא מֶרְכַּבְתּוֹ שֶׁל אוֹתוֹ מְמֻנֶּה גָדוֹל שֶׁנִּקְרָא בּוֹאֵ\"ל. וְזֶה שַׁמָּשׁ נִכְבָּד שֶׁנִּקְרָא רְפָאֵ\"ל. וְהֵם יוֹרְדִים וְעוֹמְדִים עַל הַנְּשָׁמָה, אוֹמְרִים לָהּ: שָׁלוֹם בּוֹאֵךְ, יָבֹא שָׁלוֹם יָבֹא שָׁלוֹם. וְאָז אוֹתָן שְׁתֵּי הָאוֹתִיּוֹת עוֹלוֹת וְעוֹמְדוֹת בִּמְקוֹמָן, וְנִגְנָזוֹת לְתוֹךְ אוֹתוֹ הָאוֹר שֶׁל אוֹתָם פְּתָחִים.</p>\n<p>שְׁנֵי פְּתָחִים אֲחֵרִים, שְׁנֵי אוֹרוֹת אֲחֵרִים לוֹהֲטִים מֵאוֹר הָאֵשׁ בְּאוֹתָם פְּתָחִים, אֶחָד לְצַד שְׂמֹאל וְאֶחָד לְאָחוֹר. שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת לוֹהֲטוֹת בְּאוֹתָם אוֹרוֹת וְנוֹצְצִים בְּתוֹכָם. אוֹת אַחַת ג' וְאוֹת אַחַת נ'. וּכְשֶׁהָאוֹתִיּוֹת הָרִאשׁוֹנוֹת חוֹזְרוֹת לִמְקוֹמָן, שְׁתֵּי הָאֲחֵרוֹת הַלָּלוּ נוֹצְצוֹת, עוֹלוֹת וְיוֹרְדוֹת, יוֹצְאוֹת מֵאוֹתָם אוֹרוֹת וְעוֹמְדוֹת עַל הַנְּשָׁמָה.</p>\n<p>אָז יוֹרְדוֹת שְׁתֵּי מֶרְכָּבוֹת מֵאוֹתָם שְׁנֵי פְתָחִים. מֶרְכָּבָה אַחַת הִיא מֶרְכַּבְתּוֹ שֶׁל גַּבְרִיאֵל, מְמֻנֶּה גָדוֹל וְנִכְבָּד. הַמֶּרְכָּבָה הַשְּׁנִיָּה הִיא מֶרְכָּבָה אַחֶרֶת קְדוֹשָׁה שֶׁל נוּרִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, וְיוֹרְדוֹת מֵאוֹתָם פְּתָחִים וְעוֹמְדוֹת עַל הַנְּשָׁמָה, וְהָאוֹתִיּוֹת חוֹזְרוֹת לִמְקוֹמָן.</p>\n<p>אָז, שְׁתֵּי הַמֶּרְכָּבוֹת הַלָּלוּ נִכְנָסוֹת לְתוֹךְ הֵיכָל אֶחָד טָמִיר שֶׁבַּגָּן שֶׁנִּקְרָא אֲהָלוֹ\"ת, וְשָׁם שְׁנֵים עָשָׂר מִינֵי בְשָׂמִים גְּנוּזִים, שֶׁכָּתוּב (שיר ד) נֵרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן וְגוֹ'. וְאוֹתָם שְׁנֵים עָשָׂר מִינֵי בְשָׂמִים שֶׁלְּמַטָּה.</p>\n<p>וְשָׁם כָּל אוֹתָם לְבוּשֵׁי הַנְּשָׁמוֹת שֶׁרְאוּיִים לְהִתְלַבֵּשׁ בָּהֶם כָּל אֶחָד וְאֶחָד כָּרָאוּי. בְּאוֹתוֹ לְבוּשׁ נִרְשְׁמוּ כָּל אוֹתָם מַעֲשִׂים טוֹבִים שֶׁעָשָׂה בָּעוֹלָם הַזֶּה, וְכֻלָּם רְשׁוּמִים בּוֹ וּמַכְרִיזִים: זֶהוּ לְבוּשׁוֹ שֶׁל פְּלוֹנִי. וְנוֹטְלִים אֶת אוֹתוֹ לְבוּשׁ, וּמִתְלַבֶּשֶׁת בּוֹ אוֹתָהּ נִשְׁמַת הַצַּדִּיק שֶׁבַּגָּן כְּמוֹ בַּדְּיוֹקָן שֶׁבָּעוֹלָם הַזֶּה.</p>\n<p>וְהַדְּבָרִים הַלָּלוּ מִשְּׁלֹשִׁים יוֹם וְאֵילָךְ, שֶׁהֲרֵי כָּל שְׁלֹשִׁים הַיָּמִים אֵין לְךְ נְשָׁמָה שֶׁלֹּא תְקַבֵּל עֹנֶשׁ טֶרֶם שֶׁתִּכָּנֵס לְגַן עֵדֶן. כֵּיוָן שֶׁקִּבְּלָה עֹנֶשׁ, נִכְנֶסֶת לְגַן עֵדֶן, כְּמוֹ שֶׁבֵּאֲרוּהָ. אַחַר שֶׁהִתְלַבְּנָה, מִתְלַבֶּשֶׁת. כֵּיוָן שֶׁהִתְלַבְּשָׁה בַּלְּבוּשׁ הַזֶּה, נוֹתְנִים לָהּ מָקוֹם כָּרָאוּי לָהּ. אָז כָּל אוֹתָן הָאוֹתִיּוֹת יוֹרְדוֹת, וְעוֹלוֹת אוֹתָן מֶרְכָּבוֹת.</p>\n<p>אוֹתוֹ רָקִיעַ חוֹזֵר פַּעֲמַיִם בְּכָל יוֹם בְּאוֹתָהּ נְטִילַת הָרָקִיעַ הָאַחֵר הַזֶּה שֶׁנִּדְבָּק בּוֹ. וְהָרָקִיעַ הַזֶּה אֵינוֹ יוֹצֵא מִחוּץ לַגָּן. הָרָקִיעַ הַזֶּה רָקוּם בְּכָל מִינֵי גְוָנִים.</p>\n<p>עָשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת רְשׁוּמוֹת חֲקוּקוֹת בְּאוֹתוֹ רָקִיעַ, כָּל אוֹת וָאוֹת נוֹטֶפֶת מֵהַמָּן (מהטל), מֵהַטַּל שֶׁלְּמַעְלָה עַל הַגָּן, וּמֵאוֹתוֹ הַטַּל שֶׁל הָאוֹתִיּוֹת רוֹחֲצוֹת אוֹתָן נְשָׁמוֹת וְנִרְפָּאוֹת, אַחַר שֶׁטָּבְלוּ בִּנְהַר דִּינוּר לְהִטָּהֵר. וְהַטַּל אֵינוֹ יוֹרֵד אֶלָּא מִתּוֹךְ אוֹתִיּוֹת שֶׁרְשׁוּמוֹת וַחֲקוּקוֹת בְּאוֹתוֹ רָקִיעַ, מִשּׁוּם שֶׁאוֹתָן אוֹתִיּוֹת הֵן כְּלַל הַתּוֹרָה, וְאוֹתוֹ הָרָקִיעַ הַסּוֹד שֶׁל הַתּוֹרָה, שֶׁהֲרֵי מֵאֵשׁ וּמַיִם שֶׁל הַתּוֹרָה נַעֲשָׂה.</p>\n<p>וְעַל כֵּן הֵם שׁוֹפְעִים טַל עַל כָּל אוֹתָם שֶׁהִשְׁתַּדְּלוּ בַתּוֹרָה לִשְׁמָהּ בָּעוֹלָם הַזֶּה. וְהַדְּבָרִים הַלָּלוּ רְשׁוּמִים בְּגַן עֵדֶן וְעוֹלִים עַד אוֹתוֹ רָקִיעַ, וְנוֹטְלִים מֵאוֹתָן אוֹתִיּוֹת אוֹתוֹ הַטַּל לְהָזִין אֶת הַנְּשָׁמָה הַזּוֹ. זֶהוּ שֶׁכָּתוּב (דברים לב) יַעֲרֹף כַּמָּטָר לִקְחִי תִּזַּל כַּטַּל אִמְרָתִי.</p>\n<p>בְּאֶמְצַע הָרָקִיעַ הַזֶּה עוֹמֵד פֶּתַח אֶחָד כְּנֶגֶד הַפֶּתַח שֶׁאָמַרְנוּ שֶׁל הַהֵיכָל שֶׁלְּמַעְלָה, שֶׁבְּאוֹתוֹ פֶּתַח הַנְּשָׁמוֹת פּוֹרְחוֹת מֵהַגָּן שֶׁלְּמַטָּה לְמַעְלָה בְּעַמּוּד אֶחָד הַנָּעוּץ בַּגָּן עַד לְאוֹתוֹ פֶּתַח.</p>\n<p>בְּתוֹךָ אוֹתוֹ רָקִיעַ (עמוד) בְּאוֹתוֹ פֶּתַח, שֶׁהוּא בְּאֶמְצַע הָרָקִיעַ שֶׁבַּגָּן, נִכְנָסִים לְתוֹכָהּ שְׁלֹשָׁה גְוָנִים שֶׁל אוֹר כְּלוּלִים כְּאֶחָד, וּמְאִירִים לְצוּרוֹת אוֹתוֹ הָעַמּוּד. וְאָז הָרָקִיעַ (העמוד) הַזֶּה נוֹצֵץ וּמִתְלַהֵט בְּכַמָּה גְוָנִים (אורות) שֶׁמִּתְלַהֲטִים. בְּכָל שָׁעָה מְאִירִים הַצַּדִּיקִים מֵאוֹתוֹ זִיו עֶלְיוֹן. אֲבָל בְּכָל שַׁבָּת וְשַׁבָּת וּבְכָל רֹאשׁ חֹדֶשׁ מִתְגַּלָּה הַשְּׁכִינָה יוֹתֵר מִשְּׁאָר הַזְּמַנִּים בְּאוֹתוֹ רָקִיעַ, וְכָל הַצַּדִּיקִים בָּאִים וּמִשְׁתַּחֲוִים לָהּ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לַלְּבוּשִׁים הַלָּלוּ שֶׁאָמַרְנוּ, שֶׁמִּתְלַבְּשִׁים בָּהֶם הַצַּדִּיקִים בְּגַן עֵדֶן (שלמטה). אֵלֶּה מִמַּעֲשִׂים טוֹבִים שֶׁעָשָׂה אָדָם בָּעוֹלָם הַזֶּה בְּמִצְווֹת הַתּוֹרָה, וּבָהֶם עוֹמֶדֶת הַנְּשָׁמָה בְּגַן עֵדֶן שֶׁלְּמַטָּה, וּמִתְלַבֶּשֶׁת בַּלְּבוּשִׁים הַנִּכְבָּדִים הַלָּלוּ.</p>\n<p>כְּשֶׁעוֹלָה הַנְּשָׁמָה בְּאוֹתוֹ פֶּתַח הָרָקִיעַ לְמַעְלָה, מִזְדַּמְּנִים לָהּ לְבוּשִׁים אֲחֵרִים נִכְבָּדִים עֶלְיוֹנִים, שֶׁהֵם מֵרָצוֹן וְכַוָּנַת הַלֵּב בַּתּוֹרָה וּבִתְפִלָּה, שֶׁכְּשֶׁעוֹלֶה אוֹתוֹ רָצוֹן לְמַעְלָה, מִתְעַטֵּר בָּהּ מִי שֶׁמִּתְעַטֵּר, וְנִשְׁאָר חֵלֶק לְאוֹתוֹ אָדָם, וְנַעֲשֶׂה מִמֶּנּוּ לְבוּשִׁים שֶׁל אוֹר לְהַלְבִּישׁ בָּהֶם הַנְּשָׁמָה לַעֲלוֹת לְמַעְלָה. וְאַף עַל גַּב שֶׁבֵּאֲרוּהָ שֶׁאוֹתָם לְבוּשִׁים תְּלוּיִים בַּמַּעֲשִׂים - אֵלֶּה לֹא תְלוּיִים אֶלָּא בִּרְצוֹן הָרוּחַ, כְּמוֹ שֶׁנִּתְבָּאֵר, לַעֲמֹד בְּתוֹךְ מַלְאָכִים וְרוּחוֹת קְדוֹשׁוֹת, וְזֶהוּ בֵּרוּר הַדָּבָר. וְהַמְּנוֹרָה הַקְּדוֹשָׁה לָמַד כָּךְ מֵאֵלִיָּהוּ: הַלְּבוּשִׁים שֶׁלְּמַטָּה בַּגָּן שֶׁבָּאָרֶץ בְּמַעֲשִׂים, וְהַלְּבוּשִׁים שֶׁלְּמַעְלָה, (ברוח ורצון וכונת הלב) בְּרָצוֹן וְכַוָּנַת הָרוּחַ בַּלֵּב.</p>\n<p>וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ' (בראשית ב), הֲרֵי פֵּרְשׁוּהָ, אֲבָל בַּגָּן הַזֶּה שֶׁלְּמַטָּה, נָהָר יֹצֵא מֵעֵדֶן וַדַּאי. וְצָרִיךְ לָדַעַת, הַנָּהָר הַזֶּה שֶׁיּוֹצֵא בַּגָּן שֶׁלְּמַטָּה, בְּאֵיזֶה מָקוֹם הוּא עִקָּרוֹ וְשָׁרְשׁוֹ. בְּאֵיזֶה מָקוֹם? בְּעֵדֶן. הָעֵדֶן הַזֶּה הוּא סוֹד עֶלְיוֹן, וְלֹא נִתְּנָה רְשׁוּת לְעֵין הַשֵּׂכֶל לִשְׁלֹט בּוֹ. וְסוֹד הַדָּבָר - אִלְמָלֵא הַמָּקוֹם הַזֶה נִמְסָר לְמַטָּה לְהִתְגַּלּוֹת, הַמָּקוֹם שֶׁל הָעֵדֶן הָעֶלְיוֹן הַקָּדוֹשׁ נִמְסָר גַּם כֵּן לָדַעַת. אֶלָּא (אבל) מִשּׁוּם הַהַסְתָּרָה שֶׁל כְּבוֹד הָעֵדֶן הָעֶלְיוֹן הַקָּדוֹשׁ, נִטְמָן וְנִגְנָז הָעֵדֶן הַתַּחְתּוֹן שֶׁאוֹתוֹ נָהָר שׁוֹפֵעַ וְיוֹצֵא מִמֶּנּוּ, וְלָכֵן לֹא נִמְסָר לְהִתְגַּלּוֹת אֲפִלּוּ לְאוֹתָן הַנְּשָׁמוֹת שֶׁבְּגַן עֵדֶן.</p>\n<p>כְּמוֹ שֶׁהַנָּהָר הַזֶּה נִפְרָד וְיוֹצֵא מִתּוֹךְ עֵדֶן לְהַשְׁקוֹת אֶת הַגָּן שֶׁלְּמַעְלָה, כָּךְ גַּם מִתּוֹךְ אוֹתוֹ הַפֶּתַח שֶׁל הָאֶמְצַע יוֹצֵא אוֹר אֶחָד שֶׁנִּפְרָד לְאַרְבָּעָה צְדָדִים, בְּאַרְבָּעָה פְתָחִים שֶׁאָמַרְנוּ. הַמָּקוֹם שֶׁעוֹמְדוֹת אוֹתָן הָאוֹתִיּוֹת הָרְשׁוּמוֹת. וְאוֹתוֹ הָאוֹר שֶׁנִּפְרָד לְאַרְבָּעָה אוֹרוֹת, בְּאַרְבַּע אוֹתִיּוֹת שֶׁנּוֹצְצוֹת (ויוצאות) יוֹצֵא מֵעֵדֶן, מָקוֹם שֶׁזּוֹהֶרֶת הַנְּקֻדָּה שֶׁלְּמַעְלָה.</p>\n<p>וְאוֹתָהּ נְקֻדָּה מְאִירָה, וְנַעֲשֶׂה עֵדֶן לְהָאִיר, וְאֵין מִי שֶׁשּׁוֹלֵט לִרְאוֹת וְלָדַעַת אֶת הַנְּקֻדָּה הַזּוֹ פְּרָט לְאוֹתוֹ אוֹר שֶׁמִּתְפַּשֵּׁט מִמֶּנָּה, שֶׁמִּשְׁתַּחֲוִים לְפָנָיו אוֹתָם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כְּמוֹ שֶׁנִּתְבָּאֵר. וְהַנְּקֻדָּה הַתַּחְתּוֹנָה הַזּוֹ הִיא גַּן אֶל הָעֵדֶן הָעֶלְיוֹן, הַמָּקוֹם שֶׁלֹּא נִתָּן לָדַעַת וּלְהִתְבּוֹנֵן.</p>\n<p>עַל כָּל זֶה כָּתוּב, (ישעיה סה) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. הַשֵּׁם הַזֶּה הִתְפָּרֵשׁ. אֱלֹהִים זוּלָתְךְ - זוֹ הַנְּקֻדָּה הַתַּחְתּוֹנָה הַקְּדוֹשָׁה, שֶׁהוּא יוֹדֵעַ אֶת הָעֵדֶן הַזֶּה שֶׁלְּמַטָּה שֶׁטָּמוּן בַּגָּן, וְאֵין אַחֵר שֶׁמַּכִּיר אוֹתוֹ. אֱלֹהִים זוּלָתְךְ - זֶהוּ הָעֵדֶן הָעֶלְיוֹן עַל הַכֹּל, שֶׁהוּא סוֹד הָעוֹלָם הַבָּא, שֶׁהוּא מַכִּיר אֶת הַנְּקֻדָּה הַתַּחְתּוֹנָה בְּצַדִּיק אֶחָד שֶׁיּוֹצֵא מִמֶּנּוּ, נָהָר שֶׁמַּרְוֶה אוֹתָהּ, וְאֵין מִי שֶׁמַּכִּיר אוֹתָהּ פְּרָט לוֹ, שֶׁכָּתוּב אֱלֹהִים זוּלָתְךְ, שֶׁהוּא אָחוּז לְמַעְלָה לְמַעְלָה עַד אֵין סוֹף.</p>\n<p>וְהַנָּהָר הַזֶּה שֶׁיּוֹצֵא מֵעֵדֶן לְמַטָּה הוּא סוֹד לַחֲכָמִים בְּסוֹד הַכָּתוּב, וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. וְהַדָּבָר הַזֶּה הִתְפָּרֵשׁ לְמַעְלָה וָמַטָּה. הַנְּשָׁמָה שֶׁיּוֹצֵאת מֵעוֹלַם הַחֹשֶׁךְ הַזֶּה, הִיא תְאֵבָה לִרְאוֹת בְּאוֹר הָעוֹלָם הָעֶלְיוֹן כְּאָדָם הַזֶּה שֶׁתָּאֵב לִשְׁתּוֹת מַיִם בְּתַאֲוָה. כָּךְ כָּל אֶחָד וְאֶחָד הוּא צַחְצָחוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ה) צִחֵה צָמָא. צָמָא, מֵאוֹתָם צָחוֹת שֶׁל אוֹרוֹת שֶׁל הַגָּן וְהָרָקִיעַ וְהַהֵיכָלוֹת שֶׁל הַגָּן.</p>\n<p>וְאוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, כָּל אוֹתָן נְשָׁמוֹת בִּלְבוּשֵׁי כָבוֹד יוֹשְׁבוֹת עַל אוֹתוֹ נָהָר, וְאִלְמָלֵא אוֹתוֹ לְבוּשׁ, לֹא יְכוֹלִים לִסְבֹּל, וְאָז מִתְיַשְּׁבוֹת וְרָווֹת בְּאוֹתָם צָחוֹת וִיכוֹלוֹת לִסְבֹּל. וְאוֹתוֹ נָהָר הוּא תִּקּוּן הַנְּשָׁמוֹת לְהִתְיַשֵּׁב וּלְהִזּוֹן וְלֵהָנוֹת מֵאוֹתָן צָחוֹת, וְהַנְּשָׁמוֹת נֶהֱנוֹת (מתתקנות) עַל אוֹתוֹ נָהָר וּמִתְיַשְּׁבוֹת בּוֹ.</p>\n<p>אוֹתוֹ נָהָר עֶלְיוֹן שֶׁלְּמַעְלָה מוֹצִיא נְשָׁמוֹת, וְהֵן פּוֹרְחוֹת מִמֶּנּוּ לְתוֹךְ הַגָּן, שֶׁהַנָּהָר הַזֶּה שֶׁלְּמַטָּה בַּגָּן שֶׁבָּאָרֶץ מַתְקִין נְשָׁמוֹת לְהִתְתַּקֵּן וּלְהִתְיַשֵּׁב בְּאוֹתָן צָחוֹת. כְּמוֹ כֵן בָּעוֹלָם הַזֶּה בַּחוּץ, בְּרֵיחַ הַמַּיִם מִתְיַשֶּׁבֶת הַנֶּפֶשׁ לְהָאִיר, שֶׁהֲרֵי מֵהָעִקָּר כְּמוֹ זֶה יוֹצֵא. וּמִשּׁוּם שֶׁהַנְּשָׁמוֹת מִתְתַּקְּנוֹת עַל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, יְכוֹלוֹת לְהִתְיַשֵּׁב בְּאוֹתָן צָחוֹת עֶלְיוֹנוֹת וְלַעֲלוֹת לְמַעְלָה בְּאוֹתוֹ פֶּתַח שֶׁבְּאֶמְצַע הָרָקִיעַ, וְעַמּוּד אֶחָד שֶׁעוֹמֵד בְּאֶמְצַע הַגָּן, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>בְּאוֹתוֹ עַמּוּד עוֹלִים לְמַעְלָה בְּתוֹךְ אוֹתוֹ פֶּתַח שֶׁל הָרָקִיעַ, וּבוֹ סְבִיבוֹ יֵשׁ בּוֹ (ישעיה ד) עָנָן (יומם) וְעָשָׁן נֹגַהּ. וְאַף עַל גַּב שֶׁבֵּאֲרוּהוּ לְזֶה הַפָּסוּק, אֲבָל עָנָן וְעָשָׁן אֵלּוּ מִבַּחוּץ, וְנֹגַהּ מִבִּפְנִים. וְזֶה הוּא לְחַפּוֹת עַל אֵלּוּ שֶׁעוֹלִים לְמַעְלָה, שֶׁלֹּא יֵרָאוּ מִלִּפְנֵי אֵלּוּ שֶׁיּוֹשְׁבִים לְמַטָּה.</p>\n<p>וַהֲרֵי כָּאן סוֹד הַסּוֹדוֹת. כַּאֲשֶׁר (רוצה הקדוש ברוך הוא לתקן הגקדה הזו) הַנְּקֻדָּה הַזּוֹ רוֹצָה לְהִתְתַּקֵּן בְּתִקּוּנֶיהָ וּלְהִתְקַשֵּׁט בְּשַׁבָּתוֹת וּזְמַנִּים וּבְחַגִּים, שׁוֹלַחַת אַרְבַּע פְּנֵי נֶשֶׁר, וְעוֹמְדִים עַל הַהֵיכָל שֶׁנִּקְרָא דְּרוֹר, וְהַיְנוּ מָר דְּרוֹר. וּבִגְלַל כָּךְ בִּשְׁנַת הַיּוֹבֵל צְרִיכִים לְהַכְרִיז דְּרוֹר, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וּקְרָאתֶם דְּרוֹר. וְאוֹתָם אַרְבַּע פָּנִים נוֹתְנִים קוֹל, וְאֵין מִי שֶׁיִּשְׁמַע אוֹתוֹ פְּרָט לְאוֹתָן הַנְּשָׁמוֹת הָרְאוּיוֹת לַעֲלוֹת, וְהֵן מִתְכַּנְּסוֹת שָׁם, וְלוֹקְחִים אוֹתָם אַרְבַּע הַפָּנִים הַלָּלוּ, וּמַכְנִיסִים אוֹתָם פְּנִימָה בְּאוֹתוֹ עַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע.</p>\n<p>וּבְאוֹתָהּ שָׁעָה עוֹלֶה אוֹתוֹ עַמּוּד, עָנָן וְאֵשׁ וְעָשָׁן, וְנֹגַהּ מִבִּפְנִים. וּשְׁנֵי אֵלֶּה נִקְרָאִים מְכוֹן הַר צִיּוֹן וּמִקְרָאֶיהָ. מְכוֹן הַר צִיּוֹן - זֶהוּ הַתִּקּוּן שֶׁלְּמַעְלָה, כְּשֶׁהַנְּקֻדָּה הַתַּחְתּוֹנָה מִתְקַשֶּׁטֶת, וְהֵם מִקְרָאֶיהָ שֶׁל אוֹתָהּ נְקֻדָּה לְהִתְקַשֵּׁט.</p>\n<p>כֵּיוָן שֶׁעוֹלוֹת הַנְּשָׁמוֹת הַלָּלוּ עַד לְאוֹתוֹ פֶּתַח הָרָקִיעַ, אֲזַי אוֹתוֹ רָקִיעַ סוֹבֵב סְבִיב הַגָּן שָׁלֹשׁ פְּעָמִים, וּמִקּוֹל נְעִימוּת שֶׁל סִבּוּב אוֹתוֹ רָקִיעַ יוֹצְאוֹת כָּל אוֹתָן נְשָׁמוֹת וְשׁוֹמְעוֹת אוֹתוֹ נֹעַם שֶׁל אוֹתוֹ רָקִיעַ, וְרוֹאִים אוֹתוֹ הָעַמּוּד שֶׁמַּעֲלֶה אֵשׁ וְעָנָן וְעָשָׂן וְנֹגַהּ שֶׁלּוֹהֵט, וְכֻלָּם מִשְׁתַּחֲוִים. וְאָז הַנְּשָׁמוֹת עוֹלוֹת בְּאוֹתוֹ הַפֶּתַח, עַד שֶׁעוֹלִים לְתוֹךְ הָעִגּוּל שֶׁסּוֹבֵב בְּאוֹתָהּ נְקֻדָּה, וְאָז רוֹאִים מַה שֶּׁרוֹאִים. וּמִתּוֹךְ הָאוֹר וְהַשִּׂמְחָה מִמַּה שֶּׁרָאוּ, עוֹלִים וְיוֹרְדִים, מִתְקָרְבִים וּמִתְרַחֲקִים.</p>\n<p>וְהִיא מִשְׁתּוֹקֶקֶת אֲלֵיהֶם וּמִתְקַשֶּׁטֶת בְּאוֹר. וְאָז לוֹבֵשׁ קִנְאָה (מאור) צַדִּיק עֶלְיוֹן אֶחָד, וּמִסְתַּכֵּל בָּאוֹר וְיֹפִי שֶׁל הַנְּקֻדָּה הַזּוֹ וּבְתִקּוּנֶיהָ, וְאוֹחֵז בָּהּ וּמַעֲלֶה אוֹתָהּ אֵלָיו, וּמֵאִיר אוֹר בְּאוֹר וְנִהְיִים אֶחָד. וְכָל חֵילוֹת הַשָּׁמַיִם פּוֹתְחִים בְּאוֹתָהּ שָׁעָה וְאוֹמְרִים: אַשְׁרֵיכֶם הַצַּדִּיקִים שׁוֹמְרֵי הַתּוֹרָה, אַשְׁרֵיהֶם הַמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֲרֵי שִׂמְחַת אֲדוֹנְכֶם הִיא בָכֶם, שֶׁהֲרֵי עֲטֶרֶת רִבּוֹנְכֶם מִתְעַטֶּרֶת בָּכֶם.</p>\n<p>וְאָז, כֵּיוָן שֶׁמְּאִירִים אוֹר בְּאוֹר, שְׁנֵי אוֹרוֹת מִתְחַבְּרִים כְּאֶחָד וּמְאִירִים. אַחַר כָּךְ יוֹרְדִים אוֹתָם גְּוָנִים וּמִתְבּוֹנְנִים לְהִשְׁתַּעֲשֵׁעַ בְּאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, וּמְתַקְּנִים אוֹתָם לְעַטֵּר לְמַעְלָה. וְעַל זֶה נֶאֱמַר עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כָּתוּב (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְמָעְלָה. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל יֵשׁ רָקִיעַ וְיֵשׁ רָקִיעַ. הָרָקִיעַ שֶׁלְּמַטָּה הוּא עוֹמֵד עַל גַּבֵּי אַרְבַּע חַיּוֹת, וּמִשָּׁם מִתְפַּשֵּׁט וּמַתְחִיל דְּיוֹקָן שֶׁל נְקֵבָה אַחַת שֶׁאֲחוֹרֵי הַזָּכָר, וְזֶהוּ סוֹד הַכָּתוּב (שמות לג) וְרָאִיתָ אֶת אֲחֹרָי, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אָחוֹר וָקֶדֶם צַרְתָּנִי. וְכָתוּב (בראשיתב) וַיִּקַּח אַחַת מִצַּלְעֹתָיו.</p>\n<p>הָרָקִיעַ שֶׁלְּמַעְלָה הוּא עוֹמֵד עַל גַּבֵּי הַחַיּוֹת הָעֶלְינוֹת, וּמִשָּׁם מִתְפַּשֵּׁט וּמַתְחִיל הַדְּיוֹקָן שֶׁל זָכָר אֶחָד, שֶׁהוּא סוֹד עֶלְיוֹן. וּשְׁנֵי הָרְקִיעִים הַלָּלוּ, אֶחָד נִקְרָא קְצֵה הַשָּׁמַיִם, וְאֶחָד נִקְרָא מִקְצֵה הַשָּׁמַיִם, שֶׁכָּתוּב (דברים ד) וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. רָאשֵׁי הַחַיָּה שֶׁלְּמַטָּה הֵם אַרְבַּע חַיּוֹת, שֶׁהֵן רְשׁוּמוֹת (אורות) עֶלְיוֹנוֹת עַל אוֹתָן אַרְבַּע אוֹתִיּוֹת רְשׁוּמוֹת שֶׁבְּתוֹךְ אוֹתָם אַרְבָּעָה פְתָחִים שֶׁבְּגַן עֵדֶן.</p>\n<p>וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁעֵדֶן שֶׁלְּמַטָּה הוּא בָּאָרֶץ - כָּךְ זֶה וַדַּאי. אֲבָל הַכֹּל הוּא סוֹד עֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁהַנְּקֻדָּה הַזּוֹ שֶׁאָמַרְנוּ, כְּמוֹ שֶׁיֵּשׁ לָהּ חֵלֶק לְמַעְלָה - כָּךְ גַּם יֵשׁ לָהּ חֵלֶק לְמַטָּה בָּאָרֶץ. וְהַגָּן הַזֶּה לְמַטָּה הוּא חֶלְקָהּ שֶׁל אוֹתָהּ נְקֻדָּה לְהִשְׁתַּעֲשֵׁעַ בְּרוּחוֹת הַצַּדִּיקִים בָּאָרֶץ, וְנֶהֱנֵית בְּכָל הַצְּדָדִים, לְמַעְלָה וָמַטָּה. לְמַעְלָה בְּצַדִּיק, וּלְמַטָּה בְּאוֹתוֹ פְּרִי הַצַּדִּיק. וְלֹא נִמְצָא שַׁעֲשׁוּעַ מַעְלָה וָמַטָּה אֶלָּא בְּצַדִּיק. וְהַגָּן הַזֶּה הוּא מֵאוֹתָהּ נְקֻדָּה שֶׁנִּקְרֵאת עֵדֶן. (נקדה שגוטלת מאמא עליונה הטמונה בגן עדן של הארץ).</p>\n<p>אוֹתָם רָאשֵׁי הַחַיָּה אֵלּוּ אַרְבָּעָה רָאשֵׁי פָנִים. אֶחָד אַרְיֵה, שֶׁכָּתוּב (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין. וְאֶחָד שׁוֹר, שֶׁכָּתוּב וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול. וְאֶחָד נֶשֶׁר, שֶׁכָּתוּב וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וְאָדָם כְּלָל שֶׁל הַכֹּל, שֶׁכָּתוּב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וְאַרְבָּעָה רָאשֵׁי הָאוֹרוֹת הַלָּלוּ שֶׁמַּשָּׂאָם (חיות שגוטלות) אֶת הַכִּסֵּא הַקָּדוֹשׁ, וּמִתּוֹךְ הַמַּשָּׂא שֶׁלָּהֶם הֵם מַזִּיעִים. וּמֵאוֹתָהּ זֵעָה שֶׁל מַשָּׂאָם, נַעֲשֶׂה אוֹתוֹ נְהַר דִּינוּר, שֶׁכָּתוּב (דניאלז) נְהַר דִּינוּר שׁוֹפֵעַ וְיוֹצֵא מִלְּפָנָיו אֶלֶף אֲלָפִים יְשַׁמְּשׁוּהוּ.</p>\n<p>וּכְשֶׁעוֹלוֹת הַנְּשָׁמוֹת, הֵן רוֹחֲצוֹת בְּאוֹתוֹ נְהַר דִּינוּר, וְעוֹלוֹת לְקָרְבָּן וְאֵינָן נִשְׂרָפוֹת, אֶלָּא רוֹחֲצוֹת. בֹּא וּרְאֵה מִסַּלָּמַנְדְּרָא, שֶׁעוֹשִׂים מִמֶּנָּה לְבוּשׁ, וּמִתּוֹךְ שֶׁהִיא מֵאֵשׁ, אֵין רוֹחֲצִים אוֹתוֹ לְבוּשׁ אֶלָּא בְּאֵשׁ. הָאֵשׁ אוֹכֶלֶת הַזֻּהֲמָה שֶׁבּוֹ, וְנִרְחָץ אוֹתוֹ לְבוּשׁ. כָּךְ גַּם הַנְּשָׁמָה מֵאֵשׁ שֶׁנִּלְקְחָה מִתּוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, שֶׁכָּתוּב בָּהּ (שם) כִּסְאוֹ שְׁבִיבֵי אֵשׁ, בִּזְמַן שֶׁרוֹצָה לִרְחֹץ מֵאוֹתָהּ זֻהֲמָה שֶׁבָּהּ, עוֹבֶרֶת בָּאֵשׁ וְנִרְחֶצֶת, וְהָאֵשׁ אוֹכֶלֶת כָּל אוֹתָהּ הַזֻּהֲמָה שֶׁבַּנְּשָׁמָה, וְהַנְּשָׁמָה רוֹחֶצֶת וּמִתְלַבֶּנֶת.</p>\n<p>וְאם תֹּאמַר, אִם כָּךְ, אֵין לַנְּשָׁמָה עֹנֶשׁ כָּזֶה - בּא וּרְאֵה, אוֹי לַנְּשָׁמָה שֶׁסּוֹבֶלֶת אֵשׁ זָרָה, וְאַף עַל גַּב שֶׁמִּתְלַבֶּנֶת. אֲבָל כְּשֶׁהַזֻּהֲמָה רַבָּה עָלֶיהָ, אוֹי לַנְּשָׁמָה שֶׁסּוֹבֶלֶת אוֹתוֹ עֹנֶשׁ, מִשּׁוּם שֶׁאוֹתָהּ זֻהֲמָה בְּפַעֲמַיִם מִתְלַבֶּנֶת בָּאֵשׁ.</p>\n<p>בַּפַּעַם הָרִאשׁוֹנָה, כֵּיוָן שֶׁקִּבְּלָה עֹנֶשׁ בַּגּוּף, הוֹלֶכֶת הַנְּשָׁמָה, וְנוֹטְלִים אוֹתָהּ וּמַכְנִיסִים אוֹתָהּ לְתוֹךְ מָקוֹם אֶחָד שֶׁנִּקְרָא בֶּן הִנֹּם. וְלָמָּה נִקְרָא בֶּן הִנֹּם? אֶלָּא מָקוֹם אֶחָד הוּא בַּגֵּיהִנֹּם שֶׁשָּׁם נִצְרָפוֹת הַנְּשָׁמוֹת בְּצֵרוּף לְהִתְלַבֵּן טֶרֶם שֶׁנִּכְנָסוֹת לְגַן עֵדֶן. (ואם זכאיות אותן נשמות, כאשר מכניסים אותן באותו מקום) שְׁנֵי מַלְאָכִים שְׁלוּחִים מְזֻמָּנִים בְּגַן עֵדֶן, וְעוֹמְדִים בַּשַּׁעַר, וְצוֹוְחִים לְאוֹתָם הַמְמֻנִּים שֶׁבְּאוֹתוֹ מָקוֹם שֶׁבַּגֵּיהִנֹּם כְּדֵי לְקַבֵּל אוֹתָהּ הַנְּשָׁמָה.</p>\n<p>וְאוֹתָהּ הַנְּשָׁמָה, בְּטֶרֶם תִּתְלַבֵּן בָּאֵשׁ, אוֹתָם שְׁלוּחִים צוֹוְחִים אֲלֵיהֶם וְאוֹמְרִים: הִנֹּם. וּבִזְמַן שֶׁמִּתְלַבֶּנֶת, אוֹתָם מְמֻנִּים יוֹצְאִים עִמָּהּ מֵאוֹתוֹ מָקוֹם, וּמַזְמִינִים אוֹתָהּ לְפִתְחוֹ שֶׁל גַּן עֵדֶן שֶׁשָּׁם אוֹתָם שְׁלִיחִים, וְאוֹמְרִים לָהֶם: הִנֹּם. אֵלֶּה הֵם הַנְּשָׁמוֹת שֶׁהִתְלַבְּנוּ. וְאָז מַכְנִיסִים אוֹתָהּ נְשָׁמָה בְּגַן עֵדֶן.</p>\n<p>וְכַמָּה הִיא שְׁבוּרָה מִתּוֹךְ אוֹתוֹ שֶׁבֶר שֶׁל הַהִתְלַבְּנוּת שֶׁל הַגֵּיהִנֹּם (של אותו) שֶׁל אוֹתוֹ שֶׁבֶר שֶׁל הָאֵשׁ הַתַּחְתּוֹנָה. וְאַף עַל גַּב שֶׁיּוֹרֶדֶת מִלְמַעְלָה, (אבל) כֵּיוָן שֶׁמַּגִּיעָה לָאָרֶץ לְמַטָּה, הִיא אֵשׁ שֶׁאֵינֶנָּה דַקִּיקָה, וְהַנְּשָׁמָה נֶעֱנֶשֶׁת בָּהּ וְנִשְׁבֶּרֶת. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא שֶׁמֶשׁ שֶׁמְּאִירָה מֵאוֹתָם אַרְבָּעָה פְתָחִים שֶׁמְּאִירִים בָּרָקִיעַ שֶׁמֵּעַל הַגָּן, וּמַגִּיעַ לְאוֹתָהּ נְשָׁמָה וְנִרְפֵּאת. זֶהוּ שֶׁכָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>בַּפַּעִם הַשְּׁנִיָּה, אַחַר שֶׁיָּשְׁבָה בְּגַן עֵדֶן שֶׁלְּמַטָּה, כָּל אוֹתוֹ זְמַן שֶׁיָּשְׁבָה וְעַד עַכְשָׁו אֵינָהּ נִפְרֶדֶת מֵאוֹתָם דְּבָרִים שֶׁל מַרְאֵה הָעוֹלָם הַזֶּה מִכֹּל וָכֹל. וּכְשֶׁמַּעֲלִים אוֹתָהּ לְמַעְלָה, צְרִיכָה לְהִפָּרֵד מִכָּל מַרְאֶה וּמִכָּל הַדְּבָרִים שֶׁלְּמַטָּה. וּמַעֲבִירִים אוֹתָהּ בְּאוֹתוֹ נְהַר דִּינוּר, וְאָז הַנְּשָׁמָה מִתְלַבֶּנֶת בּוֹ מִכֹּל וָכֹל, וְיוֹצֵאת וְנִרְאֵית לִפְנֵי רִבּוֹן הָעוֹלָם בְּרוּכָה (ברורה) מִכָּל הַצְּדָדִים. כֵּיוָן שֶׁמִּסְתַּכֶּלֶת בְּאוֹתוֹ אוֹר, נִרְפֵּאת וְנִשְׁלֶמֶת מֵהַכֹּל. וְאָז עוֹמְדוֹת אוֹתָן נְשָׁמוֹת בִּלְבוּשִׁים, מִתְעַטְּרִים לִפְנֵי רִבּוֹנָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְאוֹתָן נְשָׁמוֹת שֶׁבְּגַן עֵדֶן שֶׁלְּמַטָּה מְשׁוֹטְטוֹת בְּכָל רָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת, וְעוֹלוֹת עַד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא חוֹמוֹת יְרוּשָׁלַיִם, שֶׁשָּׁם כַּמָּה מְמֻנִּים וּמֶרְכָּבוֹת שֶׁשּׁוֹמְרִים אוֹתָם הַחוֹמוֹת, שֶׁכָּתוּב (ישעיה סב) עַל חוֹמֹתַיִךְ הִפְקַדְתִּי שּמְרִים. וְעוֹלִים עַד אוֹתוֹ מָקוֹם, וְלֹא נִכְנָסוֹת פְּנִימָה עַד שֶׁמִּתְלַבְּנוֹת, וְשָׁם מִשְׁתַּחֲווֹת וּשְׂמֵחוֹת מֵאוֹתוֹ אוֹר, וְשָׁבוֹת לְתוֹךְ הַגָּן.</p>\n<p>יוֹצְאוֹת מִשָּׁם וּמְשׁוֹטְטוֹת בָּעוֹלָם, וְרוֹאוֹת בְּאוֹתָם הַגּוּפוֹת שֶׁל הָרְשָׁעִים וּבְאוֹתוֹ עֹנֶשׁ שֶׁלָּהֶם, שֶׁכָּתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי כִּי תוֹלַעְתָּם לֹא תָמוּת וְאִשָּׁם לֹא תִכְבֶּה וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַה זֶּה לְכָל בָּשָׂר? לְאוֹתָם שְׁאָר הַגּוּפִים שֶׁסְּבִיבָם, וַהֲרֵי פֵּרְשׁוּהָ. וְאַחַר מְשׁוֹטְטִים וּמִסְתַּכְּלִים בְּאוֹתָם בַּעֲלֵי מַכְאוֹבִים וּבְנֵי מַחֲלוֹת, וְאוֹתָם שֶׁסּוֹבְלִים עַל הַיִּחוּד שֶׁל רִבּוֹנָם, וְשָׁבִים וְאוֹמְרִים לַמָּשִׁיחַ.</p>\n<p>בְּשָׁעָה שֶׁאוֹמְרִים לוֹ לַמָּשִׁיחַ אֶת צַעַר יִשְׂרָאֵל בְּגָלוּתָם, וְאוֹתָם הָרְשָׁעִים שֶׁבָּהֶם שֶׁאֵינָם מִתְבּוֹנְנִים לָדַעַת אֶת רִבּוֹנָם, הוּא מֵרִים קוֹל וּבוֹכֶה עַל אוֹתָם הָרְשָׁעִים שֶׁבָּהֶם. זֶהוּ שֶׁכָּתוּב (שם נג) וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ מְדֻכָּא מֵעֲונֹתֵינוּ. שָׁבוֹת אוֹתָן נְשָׁמוֹת וְעוֹמְדוֹת בִּמְקוֹמָן.</p>\n<p>בְּגַן עֵדֶן יֵשׁ הֵיכָל אֶחָד שֶׁנִּקְרָא הֵיכַל בְּנֵי הַמַּחֲלוֹת. אָז הַמָּשִׁיחַ נִכְנָס לְאוֹתוֹ הֵיכָל, וְקוֹרֵא לְכָל הַמַּחֲלוֹת וְהַמַּכְאוֹבִים וְכָל יִסּוּרֵי יִשְׂרָאֵל שֶׁיָּבֹאוּ עָלָיו, וְכֻלָּם בָּאִים עָלָיו. וְאִלְמָלֵא שֶׁהוּא מֵקֵל מֵעַל יִשְׂרָאֵל וְנוֹטֵל עָלָיו, לֹא הָיָה אָדָם שֶׁיָּכוֹל לִסְבֹּל אֶת יִסּוּרֵי יִשְׂרָאֵל עַל עָנְשֵׁי הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שם) אָכֵן חֳלָיֵנוּ הוּא נָשָׂא וְגוֹ'. כְּמוֹ כֵן רַבִּי אֶלְעָזָר בָּאָרֶץ.</p>\n<p>מִשּׁוּם שֶׁאֵין חֶשְׁבּוֹן לְאוֹתָם יִסּוּרִים שֶׁעוֹמְדִים עַל אָדָם בְּכָל יוֹם עַל עָנְשֵׁי הַתּוֹרָה, וְכֻלָּם יָרְדוּ לָעוֹלָם בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה. וּכְשֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ הַקְּדוֹשָׁה בְּאוֹתָן עֲבוֹדוֹת וְקָרְבָּנוֹת שֶׁהָיוּ עוֹשִׂים, הָיוּ מְסַלְּקִים אֶת כָּל אוֹתָן מַחֲלוֹת וְיִסּוּרִים מִן הָעוֹלָם, וְעַכְשָׁו הַמָּשִׁיחַ מְסַלֵּק אוֹתָם מִבְּנֵי הָעוֹלָם טֶרֶם שֶׁיּוֹצֵא מֵהָעוֹלָם הַזֶּה, וּמְקַבֵּל עָנְשׁוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּשֶׁאוֹתָם חֲטָאִים יְתֵרִים שֶׁמַּכְנִיסִים אוֹתָם לְתוֹךְ בִּפְנִים הַגֵּיהִנֹּם בְּאוֹתָם מָדוֹרִים תַּחְתּוֹנִים אֲחֵרִים, וּמְקַבְּלִים עֹנֶשׁ רַב מֵרֹב הַזֻּהֲמָה שֶׁבַּנְּשָׁמָה, אָז מַדְלִיקִים אֵשׁ יוֹתֵר, לֶאֱכֹל אוֹתָהּ זֻהֲמָה. (אוי לאותה נשמה שסובלת אותו הענש. ועל זה אותם מלאכי חבלה שבגיהגם מטרידים אותו במקלות של אש לנער את אותה הזהמה. אוי לגשמה שסובלת אותו ענש).</p>\n<p>אַשְׁרֵיהֶם שֶׁשּׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה. אוֹתָהּ נְקֻדָּה קְדוֹשָׁה שֶׁרוֹצָה לְהִשְׁתַּעֲשֵׁעַ לְמַעְלָה וּלְמַטָּה בְּרוּחוֹת הַצַּדִּיקִים, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּשֶׁאוֹתָהּ נְקֻדָּה רוֹצָה לְהִשְׁתַּעֲשֵׁעַ לְמַטָּה בְּרוּחוֹת הַצַּדִּיקִים כְּאֵם שֶׁשְּׂמֵחָה עִם בָּנֶיהָ וּמִשְׁתַּעֲשַׁעַת בָּהֶם, כָּךְ גַּם בַּחֲצוֹת הַלַּיְלָה הִיא יוֹרֶדֶת וּמִשְׁתַּעֲשַׁעַת בָּהֶם.</p>"],[9522011843,"<p>הָרָקִיעַ שֶׁאָמַרְנוּ שֶׁעוֹמֵד עַל הַגָּן, הִיא עוֹמֶדֶת עַל אַרְבָּעָה רָאשֵׁי הַחַיּוֹת, וְאוֹתָן אַרְבַּע אוֹתִיּוֹת שֶׁאָמַרְנוּ הֵם סוֹד שֶׁל אַרְבַּע הַחַיּוֹת. וְהָרָקִיע הַזֶּה עוֹמֵד לְמַטָּה (עליהן), כְּמוֹ שֶׁנִּתְבָּאֵר. הָרָקִיעַ שֶׁל אוֹתָהּ נְקֻדָּה עוֹמֵד לְמַעְלָה עַל אוֹתָן אַרְבַּע חַיּוֹת עֶלְיוֹנוֹת שֶׁאָמַרְנוּ, וְאוֹתוֹ רָקִיעַ (כדגמתזה מזה) נִרְקָם בִּגְוָנִים קְדוֹשִׁים.</p>\n<p>בָּרָקִיעַ הַזֶּה מִסְתַּכְּלוֹת אַרְבַּע הַחַיּוֹת, וְכָל אוֹתָם חֲיָלוֹת לְמַטָּה. כְּשֶׁהָרָקִיעַ הַזֶּה מֵאִיר בִּגְוָנָיו וְנוֹצֵץ, אָז יוֹדְעוֹת כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁהֲרֵי טַרְפָּם הִזְדַּמֵּן. הָרָקִיעַ הַזֶּה רָקוּם בְּכָל הַגְּוָנִים הַקְּדוֹשִׁים, וּבוֹ עוֹמְדִים אַרְבַּע פְּתָחִים רְשׁוּמִים בְּאַרְבַּע אוֹתִיּוֹת נוֹצְצוֹת.</p>\n<p>פֶּתַח אֶחָד רָשׁוּם לְצַד מִזְרָח, וּבוֹ עוֹמֶדֶת בְּאוֹתוֹ פֶּתַח אוֹת אַחַת, וְאוֹתָהּ אוֹת הִיא א'. וְזֶה נוֹצֵץ וְעוֹלֶה וְיוֹרֵד בַּפֶּתַח הַזֶּה. הַפֶּתַח הַזֶּה מֵאִיר וְנוֹצֵץ מֵהִתְנוֹצְצוּת עֶלְיוֹנָה, וְהָאוֹת הַזּוֹ נוֹצֶצֶת וּבוֹלֶטֶת (ולוהטת) בְּתוֹכָהּ, וְהִיא יוֹרֶדֶת וְעוֹלָה וְנִרְשֶׁמֶת בְּאוֹתוֹ פֶּתַח.</p>\n<p>פֶּתַח שֵׁנִי רָשׁוּם לְצַד צָפוֹן, וּבוֹ עוֹמֶדֶת אוֹת אַחַת, וְהִיא הָאוֹת ד'. וְזוֹ עוֹמֶדֶת וְנוֹצֶצֶת, עוֹלָה וְיוֹרֶדֶת, וְלוֹהֶטֶת בְּאוֹתוֹ פֶּתַח. לִפְעָמִים נוֹצֶצֶת בְּהִתְנוֹצְצוּת, וְלִפְעָמִים נִטְמָן אוֹתוֹ אוֹר וְלֹא מֵאִיר. וְלָכֵן הָאוֹת הַזּוֹ אֵינָהּ עוֹמֶדֶת בְּקִיּוּם מַתְמִיד, וְהָאוֹת הַזּוֹ נִרְשֶׁמֶת בְּאוֹתוֹ פֶּתַח.</p>\n<p>הַפֶּתַח הַשְּׁלִישִׁי הוּא פֶּתַח שֶׁעוֹמֵד לְצַד מַעֲרָב, וּבוֹ עוֹמֶדֶת אוֹת אַחַת שֶׁרְשׁוּמָה וּנְאוֹרָה בְּאוֹתוֹ פֶּתַח, וְזוֹהִי הָאוֹת נ', וְהָאוֹת הַזּוֹ נוֹצֶצֶת בְּהִתְנוֹצְצוּת בְּאוֹתוֹ הַפֶּתַח.</p>\n<p>הַפֶּתַח הָרְבִיעִי זֶהוּ הַפֶּתַח שֶׁעוֹמֵד לְצַד דָרוֹם, וּבוֹ עוֹמֵד רֹשֶׁם שֶׁל נְקֻדָּה תַחְתּוֹנָה קְטַנָּה שֶׁנִּרְאֵית וְלֹא נִרְאֵית, וְזוֹהִי הָאוֹת י', וְאַרְבַּע הָאוֹתִיּוֹת הַלָּלוּ לְאַרְבָּעָה צְדָדִים, (נוצצים) בְּאוֹתוֹ רָקִיעַ בְּאוֹתָם פְּתָחִים.</p>\n<p>בָּרָקִיעַ הַזֶּה רְשׁוּמוֹת אוֹתִיּוֹת אֲחֵרוֹת (לד' צדדים) בִּכְתָרִים עַל רָאשֵׁיהֶם, וְאוֹתָן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת מִתְעַטְּרוֹת בִּכְתָרִים. הָרָקִיעַ הַזֶּה נוֹסֵעַ וְסוֹבֵב עַל גַּבֵּי הַחַיּוֹת בָּרֹשֶׁם שֶׁל הָאוֹתִיּוֹת, הַסּוֹד שֶׁל חֶשְׁבּוֹן הַיִּחוּד בְּסוֹד שֶׁל צֵרוּף אֶחָד, וְהֵם: א\"ט ב\"ח ג\"ז ד\"ו.</p>\n<p>הָאוֹתִיּוֹת הַלָּלוּ סוֹבְבוֹת בְּאוֹתוֹ רָקִיעַ בְּסוֹד שֶׁל אוֹתִיּוֹת אֲחֵרוֹת (של מרכבות) עֶלְיוֹנוֹת קְדוֹשׁוֹת נִסְתָּרוֹת, וְאוֹתָן אוֹתִיּוֹת אֲחֵרוֹת (עליונות) שֶׁנִּסְתָּרוֹת סוֹבְבוֹת אֶת אוֹתוֹ רָקִיעַ, וְאָז נִרְאוֹת הָאוֹתִיּוֹת הַלָּלוּ בְּגִלְגּוּל (של הרקיע הזה), שֶׁהֵם א\"ט ב\"ח, וּרְשׁוּמוֹת בָּרָקִיעַ הַזֶּה.</p>\n<p>בְּשָׁעָה שֶׁמֵּאִיר הָרָקִיעַ הַזֶּה, מְאִירִים בּוֹ אַרְבָּעָה סוֹדוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, וְהֵם צֵרוּף בַּצֵּרוּפִים שֶׁל שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים. אָז יוֹרֵד טַל מֵהָרָקִיעַ הַזֶּה בְּאוֹתָן הָאוֹתִיּוֹת שֶׁל סוֹד הַשֵּׁם הַקָּדוֹשׁ, וְכָל אוֹתָן מֶרְכָּבוֹת נִזּוֹנוֹת, וְכָל אוֹתָם הַחֲיָלוֹת וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, וְכֻלָּם מְקַבְּלִים בְּשִׂמְחָה.</p>\n<p>בְּשָׁעָה שֶׁהַדִּין תָּלוּי, הָאוֹתִיּוֹת הַלָּלוּ נִטְמָנוֹת וְנִגְנָזִים אַרְבַּע בְּתוֹךְ אַרְבַּע, וְהֵם ט\"ח ז\"ו. בְּשָׁעָה שֶׁאֵלֶּה נִגְנְזוּ וְנִטְמְנוּ, אָז הַקּוֹל שֶׁל צַד צָפוֹן מִתְעוֹרֵר, וְיוֹדְעִים שֶׁהַדִּין שָׁרוּי עַל הָעוֹלָם. וּבָרָקִיעַ הַזֶּה נִרְשָׁם גָּוֶן אֶחָד שֶׁכּוֹלֵל אֶת כָּל הַגְּוָנִים.</p>\n<p>כְּשֶׁנּוֹסֵעַ הָרָקִיעַ הַזֶּה מִצַּד הַמִּזְרָח, אוֹתָם אַרְבָּעָה הָרָאשִׁים שֶׁאָמַרְנוּ בְּאַרְבַּע (פנים) אוֹתִיּוֹת, נוֹסְעִים כֻּלָּם בְּמַסָּעוֹת, וְעוֹלִים בָּעֲלִיָּה לְמַעְלָה. וּכְשֶׁנּוֹסְעִים וְעוֹלִים לְמַעְלָה, מִסְתַּלֶּקֶת מִי שֶׁמִּסְתַּלֶּקֶת, וְחוֹזְרוֹת הָאוֹתִיּוֹת וְנִרְאוֹת בִּשְׁלֵמוּת בַּסּוֹד הָרִאשׁוֹן, א\"ט ב\"ח ג\"ז ד\"ו, וְנִרְקָם אוֹתוֹ רָקִיעַ, וְאָז מֵאִיר בְּאוֹר.</p>\n<p>וּכְשֶׁהָרָקִיעַ הַזֶּה מֵאִיר כְּמִקֹּדֶם בָּאוֹתִיּוֹת הַלָּלוּ, כֻּלָּם שָׁבִים וְשׁוֹאֲגִים לִטְרֹף טֶרֶף וּמָזוֹן. כֵּיוָן שֶׁהֵם שׁוֹאֲגִים וּמַעֲלִים קוֹלוֹת, אוֹתוֹ קוֹל נִשְׁמָע לְמַעְלָה לְמַעְלָה, וְאָז נוֹטֵל בְּרָכוֹת וּקְדֻשּׁוֹת מִי שֶׁנּוֹטֵל.</p>\n<p>סוֹבְבוֹת הָאוֹתִיּוֹת וּמִתְגַּלְגְּלוֹת, וְסוֹבְבוֹת אֶת אוֹתוֹ רָקִיעַ, וְעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת לְצַד דָּרוֹם. כֵּיוָן שֶׁעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת לְצַד דָּרוֹם, עוֹלוֹת וְנוֹצְצוֹת בְּהִתְנוֹצְצוּת וְלוֹהֲטוֹת, וְאָז בְּאֶמְצַע אוֹתוֹ רָקִיעַ רֹשֶׁם אֶחָד נִרְשָׁם, וְאוֹתוֹ הָרֹשֶׁם הוּא אוֹת אַחַת, וְהִיא י'. כֵּיוָן שֶׁהָאוֹת הַזּוֹ נִרְשְׁמָה וְנִרְאֵית, אָז לוֹהֲטוֹת אַחֲרֶיהָ שָׁלֹשׁ אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן הו\"ה.</p>\n<p>אֵלּוּ הָאוֹתִיּוֹת מְנַצְנְצוֹת בְּאֶמְצַע הָרָקִיעַ הַזֶּה, עוֹלוֹת וְיוֹרְדוֹת, לוֹהֲטוֹת בִּשְׁלֹשָׁה עָשָׂר (בשנים עשר) לְהָטִים. אָז אַחַר שֶׁאֵלּוּ הַשְּׁלֹשׁ עֶשְׂרֵה פְּעָמִים לוֹהֲטוֹת, יוֹרֵד מִי שֶׁיּוֹרֵד, וְנִכְלֶלֶת בְּאוֹתָן אוֹתִיּוֹת וּמִתְעַטֶּרֶת בָּהֶן וְלֹא נוֹדַעַת. אָז כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת בְּשִׂמְחָה, וִעוֹלִים שִׁירִים וְתִשְׁבָּחוֹת.</p>\n<p>הָרָקִֹיעַ הַזֶּה נוֹסֵעַ שֵׁנִית וְסוֹבֵב וּמִתְגַּלְגֵּל, וְאוֹתָן הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת שֶׁאָמַרְנוּ, שֶׁהֵן א\"ט ב\"ח, כֻּלָּן נִכְלָלוֹת בְּאוֹתָן אוֹתִיּוֹת עֶלְיוֹנוֹת, סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁאָמַרְנוּ, וְסוֹבְבוֹת לְאוֹתוֹ הָרָקִיעַ, וְעוֹמְדוֹת אוֹתָן אוֹתִיּוֹת שֶׁהָיוּ בְּאֶמְצַע סוֹד הַשֵּׁם הַקָּדוֹשׁ, כֻּלָּן נִרְשָׁמוֹת לְצַד צָפוֹן, וְנִרְשָׁמוֹת וְאֵינָן נִרְשָׁמוֹת. אֵין מִי שֶׁיִּסְתַּכֵּל בְּאוֹתוֹ הַצַּד. כֻּלָּן מְכֻסּוֹת, וְאוֹמֵר בְּקוֹל נֹעַם: בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וּמִתְכַּסּוֹת מִצַּד צָפוֹן (של הפנים) וְאוֹמְרוֹת אֶת זֶה, מִתְכַּסּוֹת מִכָּל הַצְּדָדִים וְאוֹמְרוֹת אֶת זֶה.</p>\n<p>הָרָקִיעַ הַזֶּה סוֹבֵב כְּמִקֹּדֶם וּמִתְגַּלְגֵּל מִצַּד לְצַד, וְאָז קוֹל נְעִימַת הַמַּחֲנוֹת הָרַבִּים בְּצַד זֶה, וְקוֹל נְעִימַת מַחֲנוֹת רַבִּים בְּצַד זֶה, וְכֵן לְאַרְבָּעָה צְדָדִים. בְּאוֹתָהּ שָׁעָה אוֹתוֹ הָרָקִיעַ מֵאִיר בְּאוֹר אַחֵר, יוֹתֵר מִכְּמוֹ שֶׁהָיָה, וְעוֹמֵד בְּאוֹר בְּגָוֶן אַחֵר כָּלוּל מִכָּל הַגְּוָנִים.</p>\n<p>וְאֵלּוּ הָאוֹתִיּוֹת שֶׁאָמַרְנוּ עוֹלוֹת לְמַעְלָה בְּאוֹתוֹ רָקִיעַ, וּמְקַבְּלִים אוֹת אַחַת שֶׁהִיא עֶלְיוֹנָה, שֶׁמִּתְחַבֶּרֶת בְּשֵׁם זֶה שֶׁל אֵלּוּ הָאוֹתִיּוֹת. מִשּׁוּם שֶׁאַף עַל גַּב שֶׁהָאוֹתִיּוֹת הַלָּלוּ הֵן שֶׁל הַשֵּׁם הַקָּדוֹשׁ, זֶהוּ שֵׁם שֶׁנִּכְלָל לְמַטָּה, מִשּׁוּם שֶׁסּוֹד זֶה נִכְלָל לְמַעְלָה וְנִכְלָל לְמַטָּה, וּכְשֶׁנִּכְלָל לְמַטָּה, אֵלּוּ הָאוֹתִיּוֹת עוֹלוֹת לְקַבֵּל אוֹת אַחַת (יו\"ד), שֶׁהֲרֵי מֵאוֹתָהּ הָאוֹת נִזּוֹנוּ אֵלּוּ הָאוֹתִיּוֹת לְמַטָּה, וְאוֹתָהּ הָאוֹת הִיא ו'. וְיוֹרְדוֹת וּמִתְחַבְּרוֹת הָאוֹתִיּוֹת הַלָּלוּ בְּאוֹתָהּ הָאוֹת, וְאָז כֻּלָּן בְּעִטּוּר אֶחָד, וְנַעֲשֶׂה שֵׁם שָׁלֵם.</p>\n<p>לְמַטָה, שֵׁם שָׁלֵם וְלֹא שָׁלֵם. שֵׁם שָׁלֵם בְּחָמֵשׁ אוֹתִיּוֹת (ולא שלם של תשע אותיות, שם שלם בחמש אותיות) הוּא - וַיהֹוָ\"ה. סוֹד שֶׁל זָכָר וּנְקֵבָה בְּרֶמֶז. הַשֵּׁם שָׁלֵם הוּא בְּתֵשַׁע אוֹתִיּוֹת, וְהֵם יְהֹוָ\"ה אֱלֹהִים. זֶהוּ שֵׁם שָׁלֵם מֵהַכֹּל. שֵׁם אַחֵר הוּא בְּרֶמֶז, וְהוּא בְּחָמֵשׁ כְּפִי שֶׁאָמַרְנוּ. אֲבָל זֶהוּ שָׁלֵם בַּכֹּל.</p>\n<p>כֵּיוָן שֶׁמִּתְחַבְּרוֹת הָאוֹתִיּוֹת הַלָּלוּ, אוֹתוֹ רָקִיעַ מֵאִיר בִּשְׁלֹשִׁים וּשְׁנַיִם אוֹרוֹת, וְאָז הַכֹּל הוּא בְּשִׂמְחָה, הַכֹּל עוֹמֵד בְּסוֹד אֶחָד מַעְלָה וָמַטָּה. כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָן מַחֲנוֹת, כֻּלָּם עוֹמְדִים בְּסוֹד שֶׁל שְׁלֵמוּת, וְכָל הַדְּרָגוֹת מְתֻקָּנוֹת עַל מְקוֹמָן, כָּל אַחַת וְאַחַת כָּרָאוּי.</p>\n<p>בָּרָקִיעַ הַזֶּה עוֹמֶדֶת לְצַד צָפוֹן שַׁלְהֶבֶת אַחַת מְאִירָה שֶׁאֵינָהּ שׁוֹכֶכֶת תָּמִיד, וְהִיא רְשׁוּמָה בְּאוֹתִיּוֹת אֲחֵרוֹת לְיָמִין, וְהֵם עֲשָׂרָה שֵׁמוֹת, וְעוֹלוֹת לְשִׁבְעִים שֵׁמוֹת, וְכֻלָּן רְשׁוּמוֹת בָּרָקִיעַ הַזֶּה, וּמְאִירוֹת כֻּלָּן כְּאֶחָד.</p>\n<p>מֵהָרָקִיעַ הַזֶּה נוֹסְעִים כָּל אוֹתָם הָרְקִיעִים שֶׁלְּמַטָּה שֶׁלְּצַד הַקְּדֻשָּׁה, עַד שֶׁמַּגִּיעִים לְאוֹתָם הָרְקִיעִים הָאֲחֵרִים שֶׁלְּצַד אַחֵר, וְאֵלֶּה נִקְרָאִים יְרִיעוֹת עִזִּים, כְּמוֹ שֶׁנֶּאֱמַר וַיַּעַשׂ יְרִיעֹת עִזִים לְאֹהֶל עַל הַמִּשְׁכָּן.</p>\n<p>מִשּׁוּם שֶׁיֵּשׁ יְרִיעוֹת וְיֵשׁ יְרִיעוֹת. יְרִיעוֹת הַמִּשְׁכָּן הֵן יְרִיעוֹת שֶׁנִּקְרָאוֹת רְקִיעֵי הַחַיּוֹת שֶׁל הַמִּשְׁכָּן הַקָּדוֹשׁ. יְרִיעוֹת עִזִּים הֵם רְקִיעִים (יריעות) אֲחֵרִים שֶׁל הַצַּד הָאַחֵר. אֵלֶּה רְקִיעִים בְּסוֹד הַמֶּרְכָּבוֹת שֶׁל רוּחוֹת קְדוֹשׁוֹת, וְאֵלֶּה רְקִיעִים שֶׁבַּחוּץ שֶׁעוֹמְדִים בְּדִבְרֵי הָעוֹלָם, וְהֵם צְדָדִים שֶׁל תְּשׁוּבָה וּמַעֲשִׂים שֶׁל הַגּוּף. וְאֵלֶּה מְכַסִּים עַל אוֹתָם רְקִיעִים שֶׁלִּפְנִים, כְּמוֹ קְלִפָּה עַל הַמֹּחַ. הָרְקִיעִים שֶׁלִּפְנִים הֵם אוֹתוֹ קָלוּשׁ שֶׁעוֹמֵד עַל הַמֹּחַ, וְאֵלּוּ נִקְרָאִים שָׁמַיִם לַה'. לַשֵּׁם אֶחָד זֶה שֶׁלְּמַטָּה.</p>\n<p>רְקִיעִים אֲחֵרִים לְמַעְלָה, וְהֵם רְקִיעִים פְּנִימִיִּים שֶׁנִּקְרָאִים רְקִיעֵי הַחַיּוֹת, שֶׁהֵם סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד הַחַיּוֹת הַגְּדוֹלוֹת הָעֶלְיוֹנוֹת, וְאֵלֶּה הֵם הַסּוֹדוֹת שֶׁל הָאוֹתִיּוֹת (סודות עליונים) הָעֶלְיוֹנוֹת בְּסוֹדוֹת הַתּוֹרָה, כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת רְשׁוּמוֹת שֶׁיּוֹצְאוֹת מִתּוֹךְ הָרָקִיעַ הָעֶלְיוֹן הַשְּׁמִינִי, שֶׁהוּא רָקִיעַ עַל גַּבֵּי הַחַיּוֹת הָעֶלְיוֹנוֹת, וְזֶהוּ שֶׁאֵין לוֹ מַרְאֶה. זֶהוּ טָמִיר וְגָנוּז, וְאֵין בּוֹ גָּוֶן.</p>\n<p>כָּל הַגְּוָנִים יוֹצְאִים מִמֶּנּוּ. אֵין בּוֹ גָּוֶן, וְלֹא נִרְאָה וְלֹא הִתְגַּלָּה. זֶהוּ שֶׁמּוֹצִיא אֶת כָּל הָאוֹרוֹת. בּוֹ לֹא נִרְאֶה לֹא אוֹר וְלֹא חֹשֶׁךְ וְלֹא גָוֶן כְּלָל, פְּרָט לְנִשְׁמוֹת הַצַּדִּיקִים שֶׁרוֹאוֹת מִתּוֹךְ הָרָקִיעַ הַתַּחְתּוֹן כְּמֵאַחַר הַכֹּתֶל, אוֹר שֶׁמּוֹצִיא וּמֵאִיר הָרָקִיעַ הָעֶלְיוֹן הַזֶּה, וְאוֹתוֹ אוֹר שֶׁלֹּא פוֹסֵק, אֵין מִי שֶׁמַּכִּיר אוֹתוֹ וְאֵין מִי שֶׁעוֹמֵד בּוֹ.</p>\n<p>מִתַּחַת לָזֶה, כָּל אוֹתָם הָרְקִיעִים נִכְלְלוּ בַשֵּׁם הַזֶּה נִקְרָא שָׁמַיִם, וְאֵלּוּ (השם הקדוש) נִקְרָאִים הַשָּׁמַיִם אוֹתָם שֶׁהַשֵּׁם הָעֶלְיוֹן נִקְרָא בָהֶם, אוֹתָם שֶׁהַשֵּׁם הַקָּדוֹשׁ הִתְעַטֵּר בָּהֶם. וְעַל זֶה כָּתוּב, (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה', לְאוֹתָהּ גְּנִיזַת הָרָקִיעַ הָעֶלְיוֹן שֶׁעוֹמֵד עֲלֵיהֶם.</p>\n<p>עַד כָּאן רֶמֶז לַשֵּׁם הַקָּדוֹשׁ, (סוד של השמים הקדושים) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בְשֵׁמוֹת. מִכָּאן וָהָלְאָה אֵין חָכָם בְּהַשְׂכֵּל שֶׁיָּכוֹל לָדַעַת וּלְהִדָּבֵק כְּלָל, פְּרָט לְאוֹר אֶחָד קָטָן בְּלִי קִיּוּם (קיום הכל) לְהִתְיַשֵּׁב בּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּכְנָס וְיוֹצֵא, וְיוֹדֵעַ לְהִסְתַּכֵּל בְּסוֹדוֹת אֲדוֹנוֹ וְלִדְבֹּק בּוֹ.</p>\n<p>בַּסּוֹדוֹת הַלָּלוּ יָכוֹל אָדָם לִדְבֹּק בַּאֲדוֹנוֹ, לָדַעַת אֶת שְׁלֵמוּת הַחָכְמָה בְּסוֹד עֶלְיוֹן כְּשֶׁעוֹבֵד לַאֲדוֹנוֹ בִּתְפִלָּה, בְּרָצוֹן וּבְכַוָּנַת הַלֵּב, מַדְבִּיק רְצוֹנוֹ כְּאֵשׁ בְּגַחֶלֶת לְיַחֵד אוֹתָם רְקִיעִים תַּחְתּוֹנִים שֶׁל צַד הַקְּדֻשָּׁה לְעַטְּרָם בְּשֵּׁם אֶחָד תַּחְתּוֹן. וּמִשָּׁם וָהָלְאָה לְיַחֵד אוֹתָם רְקִיעִים עֶלְיוֹנִים פְּנִימִיִּים לִהְיוֹת כֻּלָּם אֶחָד בְּאוֹתוֹ רָקִיעַ עֶלְיוֹן שֶׁעוֹמֵד עֲלֵיהֶם.</p>\n<p>וּבְעוֹד שֶׁפִּיו וְשִׂפְתוֹתָיו מְרַחֲשׁוֹת, לִבּוֹ יְכַוֵּן, וּרְצוֹנוֹ יִתְעַלֶּה לְמַעְלָה לְמַעְלָה, לְיַחֵד אֶת הַכֹּל בְּסוֹד הַסּוֹדוֹת, שֶׁשָּׁם תְּקוּעִים כָּל הָרְצוֹנוֹת וְהַמַּחֲשָׁבוֹת בְּסוֹד שֶׁעוֹמֵד בְּאֵין סוֹף, וּלְכַוֵּן בָּזֶה בְּכָל תְּפִלָּה וּתְפִלָּה, בְּכָל יוֹם וָיוֹם, לְעַטֵּר אֶת כָּל יָמָיו בְּסוֹד הַיָּמִים הָעֶלְיוֹנִים בַּעֲבוֹדָתוֹ.</p>\n<p>בַּלַּיְלָה יָשִׂים רְצוֹנוֹ, שֶׁהֲרֵי נִפְטָר מֵהָעוֹלָם, וְנִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ, וְיַחֲזִירֶנָּה לְרִבּוֹן הַכֹּל. מִשּׁוּם שֶׁכָּל לַיְלָה וְלַיְלָה (אותה נקדה עומדת לכלל בתוכה אותן נשמות הצדיקים).</p>\n<p>סוֹד הַסּוֹדוֹת לָדַעַת לְאוֹתָם חַכְמֵי לֵב. הָרָקִיעַ הַזֶּה הַתַּחְתּוֹן, בְּסוֹד אוֹתָהּ הַנְּקֻדָּה הוּא עוֹמֵד, כְּמוֹ שֶׁאָמַרְנוּ. אוֹתוֹ הָרָקִיעַ הוּא כָּלוּל מִמַּעְלָה וּמִמַּטָּה, וִיסוֹדוֹ לְמַטָּה כַּנֵּר הַזֶּה שֶׁמַּעֲלֶה אוֹר שָׁחֹר, לְהֵאָחֵז בָּאוֹר הַלָּבָן, וְהַיְסוֹד שֶׁלָּהּ הוּא לְמַטָּה בְּאוֹתָהּ פְּתִילָה בְּשֶׁמֶן. אַף כָּךְ לְמַטָּה אוֹתָהּ נְקֻדָּה - בַּיּוֹם נִכְלֶלֶת מִלְמַעְלָה, וּבַלַּיְלָה נִכְלֶלֶת מִמַּטָּה בְּאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>וְכָל דִּבְרֵי הָעוֹלָם, כֻּלָּם חוֹזְרִים לָעִקָּר וְהַיְסוֹד וְהַשֹּׁרֶשׁ שֶׁמִּמֶּנּוּ יָצְאוּ. וְכַמָּה לֵילוֹת עֲתִידִים לִטֹּל כָּל אֶחָד וְאֶחָד מַה שֶּׁרָאוּי לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהליםטז) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. הַנֶּפֶשׁ הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְשָׁבָה אֶל אוֹתוֹ עִקָּר שֶׁרָאוּי לָהּ. הַגּוּף עוֹמֵד שָׁקֵט כְּאֶבֶן, וְחוֹזֵר לְאוֹתוֹ מָקוֹם שֶׁרָאוּי לוֹ לִשְׁרוֹת עָלָיו, וּמִשּׁוּם כָּךְ שָׁב הַגּוּף לַצַּד שֶׁלּוֹ, וְהַנֶּפֶשׁ לַצַּד שֶׁלָּהּ.</p>\n<p>עֵל הַגּוּף שׁוֹרֶה סוֹד הַצַּד הָאַחֵר, וְלָכֵן נִטְמָאִים יָדָיו, וְצָרִיךְ לִרְחֹץ אוֹתָם. כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהֲרֵי בַּלַּיְלָה הַכֹּל שָׁב לִמְקוֹמוֹ, וְנִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת וְחוֹזְרוֹת לִמְקוֹמָן, וּמִתְעַטֶּרֶת (בהם) מַה שֶּׁמִּתְעַטֶּרֶת, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים, וְאָז עוֹלֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר מֵהַכֹּל.</p>\n<p>בַּלַּיְלָה שׁוֹלְטִים הַמְמֻנִּים שֶׁנִּפְקְדוּ עַל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים לְהַעֲלוֹתָן לְמַעְלָה וּלְהַקְרִיבָן קָרְבַּן מְנַחֵם לַאֲדוֹנָם. אוֹתוֹ מְמֻנֶּה שֶׁנִּפְקָד עַל כָּל אוֹתָם מַחֲנוֹת, שְׁמוֹ סוֹרִיּ\"א מְמֻנֶּה גָּדוֹל. כֵּיוָן שֶׁעוֹלָה הַנְּשָׁמָה לְכָל אוֹתָם רְקִיעִים, אָז מַקְרִיבִים אוֹתָהּ אֵלָיו וּמֵרִיחַ בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יא) וַהֲרִיחוֹ בְּיִרְאַת ה'. כְּמוֹ שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לַעֲשׂוֹת בָּעוֹלָם, וְעַל יָדוֹ עוֹבְרִים כֻּלָּם בְּפִקָּדוֹן עַל יָדוֹ לְהִתְקָרֵב הָלְאָה.</p>\n<p>וְכָל הַנְּשָׁמוֹת, כְּשֶׁנִּקְרָבוֹת לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָבוֹת וְנִרְאוֹת שָׁם, זֶהוּ סוֹד, כָּל הַנְּשָׁמוֹת נִכְלָלוֹת בְּאוֹתָהּ נְקֻדָּה, וְלוֹקַחַת אוֹתָם פַּעַם אַחַת, כְּמוֹ מִי שֶׁבּוֹלֵעַ בְּלִיעַת דָּבָר, וּמִתְעַבֶּרֶת כְּמוֹ אִשָּׁה שֶׁמִּתְעַבֶּרֶת. הַסּוֹד הַזֶּה לְבַעֲלֵי מִדּוֹת. כְּשֶׁנְּקֻדָּה זוֹ מִתְעַבֶּרֶת כְּאִשָּׁה שֶׁמִּתְעַבֶּרֶת, נֶהֱנֵית מֵאוֹתָהּ הֲנָאָה שֶׁמַּכְלִילָה נְשָׁמָה מֵהָעוֹלָם הַזֶּה בְּאוֹתָם מַעֲשִׂים וּבְאוֹתָהּ תּוֹרָה שֶׁהִשְׁתַּדְּלָה בָּהּ בַּיּוֹם, וְנוֹטֶלֶת אוֹתוֹ רָצוֹן שֶׁל הָעוֹלָם הַזֶּה, וּבוֹ נֶהֱנֵית בְּשִׂמְחָה, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים.</p>\n<p>אַחַר כָּךְ הִיא מוֹצִיאָה אוֹתָם הַחוּצָה וּמוֹלִידָה אוֹתָם כְּמִקֹּדֶם, וְהַנְּשָׁמָה הִיא חֲדָשָׁה כָּעֵת כְּמִקֹּדֶם, וְסוֹד זֶה - (איכה ג) חֲדָשִׁים לַבְּקָרִים. חֲדָשִׁים וַדַּאי, כְּמוֹ שֶׁנִּתְבָּאֵר. מָה הַטַּעַם הֵם חֲדָשִׁים? מִשּׁוּם סוֹד הַכָּתוּב רַבָּה אֱמוּנָתֶךְ. רַבָּה וַדַּאי, שֶׁיָּכְלָה לְהַכְלִילָם וּלְהַכְנִיסָם לְתוֹכָהּ, וּמוֹצִיאָה אוֹתָם וְהֵם חֲדָשִׁים, וְלָכֵן לוֹקַחַת אֲחֵרִים מִלְמַעְלָה בַּיּוֹם. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֵּין כָּךְ הֵאִיר הַיּוֹם. אָמַר רַבִּי אַבָּא, נָקוּם וְנֵלֵךְ וְנוֹדֶה לְרִבּוֹן הָעוֹלָם. קָמוּ וְהָלְכוּ וְהִתְפַּלְלוּ, וְאַחַר כָּךְ חָזְרוּ אֵלָיו הַחֲבֵרִים. אָמְרוּ לוֹ, מִי שֶׁהִתְחִיל - שֶׁיְּסַיֵּם אֶת הַשֶּׁבַח. אַשְׁרֵי חֶלְקֵנוּ בַּדֶּרֶךְ הַזּוֹ, שֶׁכָּל זֶה זָכִינוּ לְעַטֵּר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹדוֹת הַחָכְמָה.</p>"],[9522011844,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרוֹן עֲצֵי שִׁטִּים וְגוֹ'. כָּאן, אַף עַל גַּב שֶׁכָּל סוֹדוֹת הַמִּשְׁכָּן הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים בַּחֶדֶר הַקָּדוֹשׁ, כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי סוֹד זֶה מִתְעַטֵּר בְּכַמָּה סוֹדוֹת לִלְמֹד חָכְמָה. אָרוֹן זֶה הוּא סוֹד לְהַכְנִיס תּוֹרָה שֶׁבִּכְתָב, וְנִגְנְזָה בּוֹ בְּשִׁשָּׁה לוּחוֹת (ונגנזו בו ששה לוחות, והם ששה מסובבים) מְסוֹבָבִים, וְזֶה נִקְרָא אָרוֹן. כְּשֶׁסּוֹבְבִים אוֹתָם שִׁשָּׁה לִהְיוֹת כְּאֶחָד, אָז הוּא גוּף אֶחָד לְהַכְנִיס בּוֹ סוֹד הַתּוֹרָה בְּשִׁשָּׁה צְדָדִים וַאָרון.</p>\n<p>וְהַלּוּחוֹת הֵם חֲמִשָּׁה, וּמַכְנִיסִים בּוֹ חֲמִשָּׁה סְפָרִים, וְאוֹתָם חֲמִשָּׁה הֵם שִׁשָּׁה בְּדַרְגָּה אַחַת שֶׁנִּכְנֶסֶת בָּהּ בְּנִסְתָּר, שֶׁנִּקְרֵאת סוֹד הַכֹּל, וְזֶהוּ סוֹד הַבְּרִית. כְּשֶׁזֶּה נִכְנָס לְתוֹךְ אוֹתָם חֲמִשָּׁה לוּחוֹת, אָז עוֹמֵד הָאָרוֹן וְהַתּוֹרָה בְּסוֹד שֶׁל תֵּשַׁע דְּרָגוֹת, שֶׁהֵן שְׁנֵי שֵׁמוֹת, יְהֹוָ\"ה אֱלֹהִי\"ם. וְאַחַר כָּךְ עוֹמֵד לוּחַ אֶחָד, סוֹד עֶלְיוֹן שֶׁמְּכַסֶּה עַל הַכֹּל, וְהוּא אוֹתוֹ הַסּוֹד שֶׁל אוֹתוֹ רָקִיעַ שֶׁמְּסוֹבֵב וּמְכַסֶּה עַל הַכֹּל, וְכֻלָּם עוֹמְדִים בַּסֵּתֶר.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל וְלָדַעַת אֶת סוֹדוֹת הָאָרוֹן. יֵשׁ אָרוֹן וְיֵשׁ אָרוֹן, זֶה כְּנֶגֶד זֶה. פָּתַח וְאָמַר, (שמואל ב כב) הַכֹּל נָתַן אֲרַוְנָה הַמֶּלֶךְ לַמֶּלֶךְ וְגוֹ'. וְכִי אֲרַוְנָה הָיָה מֶלֶךְ? וְאַף עַל גַּב שֶׁבֵּאֲרוּהָ הַחֲבֵרִים, אֶלָּא דָּוִד, שֶׁכָּתוּב בּוֹ (שם ה) כָּל מַכֵּה יְבֻסִי וְיִגַּע בַּצִּנּוֹר וְגוֹ', וְהוּא נָטַל וְתָפַס אֶת יְרוּשָׁלַיִם וּמִשֶּׁלּוֹ הָיָה, וְלָמָּה קָנָה בְּכֶסֶף? וְאִם תֹּאמַר, שֶׁאַף עַל גַּב שֶׁיְּרוּשָׁלַיִם הָיְתָה שֶׁל דָּוִד - אוֹתוֹ מָקוֹם הָיָה נַחֲלָתוֹ שֶׁל אֲרַוְנָה, כְּמוֹ שֶׁהָיָה בְּנָבוֹת הַיִּזְרְעֵאלִי (מלכים א כא), שֶׁאַף עַל גַּב שֶׁשָּׁלַט אַחְאָב וְהָיָה מֶלֶךְ, הִצְטָרֵךְ לְבַקֵּשׁ אוֹתוֹ כֶּרֶם מִנָּבוֹת, אַף כָּךְ דָּוִד?</p>\n<p>אֶלָּא וַדַּאי אֲרַוְנָה הָיָה מֶלֶךְ, וְאוֹתוֹ מָקוֹם הָיָה בִּרְשׁוּתוֹ וְהָיָה שׁוֹלֵט עָלָיו, וּכְשֶׁהִגִּיעַ זְמַן לָצֵאת מִתַּחַת יָדוֹ, לֹא יָצָא אֶלָּא בְּהַרְבֵּה דָם וְהָרַג בְּיִשְׂרָאֵל, וְאַחַר כָּךְ עָמַד הַמַּלְאָךְ הַמַּשְׁחִית עַל אוֹתוֹ מָקוֹם, וְשָׁם, כְּשֶׁהָיָה הוֹרֵג וְעוֹמֵד בְּאוֹתוֹ מָקוֹם, לֹא הָיָה יָכוֹל, וְתָשַׁשׁ כֹּחוֹ.</p>\n<p>וְאוֹתוֹ מָקוֹם, הַמָּקוֹם שֶׁנֶּעֱקַד בּוֹ יִצְחָק הָיָה, שֶׁשָּׁם בָּנָה אַבְרָהָם מִזְבֵּחַ וְעָקַד אֶת יִצְחָק בְּנוֹ. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ מָקוֹם, הִתְמַלֵּא רַחֲמִים. זֶהוּ שֶׁכָּתוּב רָאָה ה' וַיִּנָּחֶם וְגוֹ'. מַה זֶּה רָאָה ה'? רָאָה עֲקֵדַת יִצְחָק בְּאוֹתוֹ מָקוֹם, וְשָׁב וְרִחֵם עֲלֵיהֶם מִיָּד.</p>\n<p>וַיֹּאמֶר לַמַּלְאָךְ הַמַּשְׁחִית רַב עַתָּה וְגוֹ'. מַה זֶּה רַב? הֲרֵי פֵּרְשׁוּהָ, קַח אֶת הָרַב. אֶלָּא כָּךְ הוּא, כָּתוּב כָּאן רַב, וְכָתוּב שָׁם רַב לָכֶם שֶׁבֶת בָּהָר הַזֶּה. אַף כָּךְ גַּם רַב - רַב לְךְ שֶׁיִּהְיֶה מָקוֹם זֶה תַּחַת יָדְךְ. שָׁנִים רַבּוֹת הָיָה תַחַת יָדְךְ, מִכָּאן וָהָלְאָה רַב, הַחֲזֵר אֶת הַמָּקוֹם לִבְעָלָיו. וְעִם כָּל זֶה, (בדם) בְּמָוֶת וּבְמָמוֹן יָצָא מִתַּחַת יָדוֹ.</p>\n<p>וְלָמָּה נִקְרָא אֲרַוְנָה? אֶלָּא כָּתוּב אֲרַוְנָה, וְכָתוּב אָרְנָן. בְּעוֹד שֶׁאוֹתוֹ מָקוֹם הָיָה תַחַת יָדוֹ, נִקְרָא אֲרַוְנָה, אָרוֹן שֶׁל הַצַּד הָאַחֵר. וְעַל שֶׁנּוֹסְפוּ בוֹ אוֹתִיּוֹת יְתֵרוֹת, כָּךְ צָרִיךְ לְהוֹסִיף לְאוֹתוֹ רַע עַיִן, סוֹד שֶׁל הַצַּד הָאַחֵר, וְאוֹתָהּ תּוֹסֶפֶת הִיא חִסָּרוֹן לוֹ.</p>\n<p>בְּצַד הַקְּדֻשָּׁה גּוֹרְעִים לוֹ אוֹתִיּוֹת, וְנוֹסֶפֶת קְדֻשָּׁתוֹ. וְזֶהוּ סוֹד הַכָּתוּב, (מלכים א ז) עַל שְׁנֵי עָשָׂר בָּקָר. גָּרַע מֵ\"ם, שֶׁלֹּא כָתוּב שְׁנֵים, אֶלָּא שְׁנֵי. וְלַצַּד הָאַחֵר נוֹתְנִים תּוֹסֶפֶת אוֹתִיּוֹת, שֶׁכָּתוּב וַיַּעַשׂ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן עַשְׁתֵּי עֶשְׂרֵה יְרִיעֹת. תּוֹסֶפֶת אוֹתִיּוֹת, וְהוּא חִסָּרוֹן. וּבְצַד הַקְּדֻשָּׁה שְׁנֵי עָשָׂר וְלֹא יוֹתֵר. וְכָאן עַשְׁתֵּי עֶשְׂרֵה, וְהַכֹּל הוּא חִסָּרוֹן אֵלָיו. וְכָךְ צָרִיךְ לְאוֹתוֹ רַע עַיִן לְהַשְׁלִים אֶת הָעַיִן שֶׁלּוֹ, וְהוּא בְּחִסָּרוֹן. (כדגמא זו ארונה, תוספת אותיות, ולא כתוב ארון).</p>\n<p>בֹּא וּרְאֵה, צַד הַקְּדֻשָּׁה נִקְרָא אֲרוֹן הַבְּרִית, וְאוֹתוֹ אֲרוֹן הַבְּרִית רָאוּי לַגּוּף לְהַכְנִיס בּוֹ דְּיוֹקַן אָדָם. וְעַל סוֹד זֶה, אוֹתָם חֲסִידִים קְדוֹשִׁים, כְּשֶׁהָיוּ נִפְטָרִים מֵהָעוֹלָם הַזֶּה, הָיוּ מַכְנִיסִים אוֹתָם בְּאָרוֹן, שֶׁהֲרֵי הַצַּד הָאַחֵר אֵינוֹ מְתֻקָּן בְּגוּף וְאֵינוֹ בִּכְלָל שֶׁל גּוּף הָאָדָם. וְלָכֵן לֹא נִבְרְאוּ גוּפִים לְאוֹתוֹ צַד הָאַחֵר, מִשּׁוּם שֶׁאֵינָם בִּכְלָל שֶׁל גּוּף אָדָם.</p>"],[9522011845,"<p>מַה כָּתוּב בְּיוֹסֵף? וַיִּישֶׂם בָּאָרוֹן. לָמָּה שְׁתֵּי יוֹדִי\"ם? אֶלָּא שֶׁהִתְחַבְּרָה בְּרִית בִּבְרִית, סוֹד שֶׁלְּמַטָּה בַּסּוֹד שֶׁלְּמַעְלָה, וְנִכְנַס בְּאָרוֹן. (בא וראה, צד הקדשה נקרא ארון הברית, ואותו ארון הברית נתקן להכניס בו סוד התורה, שהיא סוד של הצורה של הגוף הקדוש. כמו כן למטה נתקן ארון להכניס בתוכו צורת הגוף, סודהאדם. ומי הואשגמצאבסוד אדם, 'מי ששומר אות ברית הקדוש, ועל סוד זה אותם חסידים קדושים, כאשר היו נפטרים מעולם הזה, היו מכניסים אותם בארון, משום שלא ראוי להכנסבארוןאלאמיששמרלבריתזו, אותקיום הקדוש. ביוסף מה כתוב, ' ויישם בארון) מָה הַטַּעַם? מִשּׁוּם שֶׁשָּׁמַר הַבְּרִית הַקָּדוֹשׁ וְהִתְקַיֵּם בּוֹ. לָכֵן רָאוּי לְהִכָּנֵס בְּאָרוֹן, וְהַכֹּל כָּרָאוּי.</p>\n<p>בָּכָה רַבִּי אַבָּא וְאָמַר, אוֹי לִבְנֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים אוֹתָהּ בּוּשָׁה! אוֹי לְאוֹתוֹ עֹנֶשׁ שֶׁל כָּל מִי שֶׁרוֹצֶה לְהִכָּנֵס לְאָרוֹן, כִּי לֹא צָרִיךְ לְהַכְנִיס לְאָרוֹן, פְּרָט לְצַדִּיק שֶׁיּוֹדֵעַ בְּנַפְשׁוֹ וְנוֹדָע בְּעַצְמוֹ שֶׁלֹּא חָטָא בְּאוֹתָהּ בְּרִית, אוֹת הַבְּרִית הַקָּדוֹשׁ, מֵעֲלוּמָיו, וְשָׁמַר אוֹתוֹ כָּרָאוּי. וְאִם לֹא, לֹא צָרִיךְ לְהִכָּנֵס לְאָרוֹן וְלִפְגֹּם אֶת הָאָרוֹן.</p>\n<p>הַסּוֹד שֶׁצָּרִיךְ לְהִתְחַבֵּר בְּאוֹת בְּרִית קֹדֶשׁ הוּא הַסּוֹד הָרָאוּי לוֹ, וְלֹא לְאַחֵר. שֶׁהֲרֵי אָרוֹן אֵינוֹ מִתְחַבֵּר אֶלָּא בְּצַדִּיק שֶׁשּׁוֹמֵר בְּרִית קֹדֶשׁ. וּמִי שֶׁפּוֹגֵם אֶת הַבְּרִית וְנִכְנָס בְּאָרוֹן - אוֹי לוֹ שֶׁפָּגַם אוֹתוֹ בְּחַיָּיו, וְאוֹי לוֹ שֶׁפָּגַם אוֹתוֹ בְּמִיתָתוֹ. אוֹי לוֹ מֵאוֹתוֹ עֹנֶשׁ. אוֹי לוֹ שֶׁפָּגַם הָאוֹת וַאֲרוֹן הַבְּרִית הַקָּדוֹשׁ, אוֹי לוֹ מֵאוֹתָהּ בּוּשָׁה, שֶׁנּוֹקְמִים מִמֶּנּוּ נִקְמַת עוֹלָמִים - נְקָמָה שֶׁל הָעוֹלָם הַזֶּה, וּנְקָמָה שֶׁל אוֹתוֹ פְּגָם. וְסוֹד זֶה כָּתוּב, (תהלים קכה) כִּי לֹא יָנוּחַ שֵׁבֶט הָרֵשַׁע עַל גּוֹרַל הַצַּדִּיקִים.</p>\n<p>בְּשָׁעָֹה שֶׁדָּנִים אוֹתוֹ בְּאוֹתוֹ עוֹלָם, מִסְתַּכְּלִים בְּמַעֲשָׂיו. אִם הָיָה פּוֹגֵם אֶת סוֹד בְּרִית הַקֹּדֶשׁ שֶׁחָתוּם בִּבְשָׂרוֹ, וְעַכְשָׁו פּוֹגֵם אֶת הָאָרוֹן (הברית) שֶׁלּוֹ בָּזֶה - לָזֶה אֵין חֵלֶק בַּצַּדִּיקִים. מִסְתַּכְּלִים בּוֹ וְדָנִים אוֹתוֹ, וּמוֹצִיאִים אוֹתוֹ מִכְּלָל שֶׁל אָדָם. כֵּיוָן שֶׁהוֹצִיאוּ אוֹתוֹ מִכְּלָל שֶׁל אָדָם, מוֹצִיאִים אוֹתוֹ מִכְּלָל שֶׁל כָּל הָאֲחֵרִים שֶׁנּוֹעֲדוּ לְחַיֵּי עוֹלָם, וְנוֹתְנִים אוֹתוֹ לְאוֹתוֹ (ארון) צַד שֶׁאֵינוֹ נִכְלָל בַּסּוֹד שֶׁל גּוּף הָאָדָם. כֵּיוָן שֶׁנִּמְסָר לְאוֹתוֹ צַד - אוֹי לוֹ שֶׁמַּכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם, וְלֹא יוֹצֵא מִשָּׁם לְעוֹלָמִים. עַל זֶה כָּתוּב, (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי וְגוֹ'. אוֹתָם שֶׁנִּשְׁאֲרוּ מִכְּלָל שֶׁל אָדָם.</p>\n<p>וְהַדְּבָרִים הַלָּלוּ, כְּשֶׁלֹּא עָשָׂה תְשׁוּבָה שְׁלֵמָה, תְּשׁוּבָה שֶׁרְאוּיָה לְכַסּוֹת עַל כָּל מַעֲשָׂיו. וְעִם כָּל זֶה, טוֹב לוֹ שֶׁלֹּא יִכָּנֵס לְאָרוֹן, שֶׁהֲרֵי כָּל זְמַן שֶׁהַגּוּף עוֹמֵד, הַנְּשָׁמָה נִדּוֹנֵית וְלֹא נִכְנֶסֶת לִמְקוֹמָהּ, פְּרָט לְאוֹתָם חֲסִידִים עֶלְיוֹנִים קְדוֹשִׁים שֶׁרְאוּיִים לַעֲלוֹת עִם גּוּפָם. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מִשּׁוּם שֶׁאֵין חֵטְא קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ זֶה שֶׁמְּשַׁקֵּר וּפוֹגֵם אֶת אוֹת בְּרִית הַקֹּדֶשׁ, וְזֶה אֵינוֹ רוֹאֶה פְּנֵי שְׁכִינָה, וְעַל חֵטְא זֶה כָּתוּב, (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'. וְכָתוּב, (תהלים ה) לֹא יְגֻרְךְ רָע.</p>\n<p>מַה כָּתוּב כָּאן? וַיַּעַשׂ בְּצַלְאֵל אֶת הָאָרֹן. וְכִי לָמָּה לֹא עָשׂוּ אוֹתָם הַחֲכָמִים שֶׁעָשׂוּ אֶת הַמִּשְׁכָּן אֶת הָאָרוֹן? אֶלָּא בְּצַלְאֵל סִיּוּם הַגּוּף, שֶׁהוּא סוֹד הַבְּרִית הַקָּדוֹשׁ, וְשָׁמַר אוֹתוֹ, וְהוּא עוֹמֵד בְּנַחֲלַת חֶלְקוֹ. הוּא הִשְׁתַּדֵּל בַּמַּעֲשֶׂה שֶׁלּוֹ וְלֹא אַחֵר. בָּאוּ כָּל הַחֲבֵרִים וְנָשְׁקוּ אוֹתוֹ.</p>"],[9522011846,"<p>כְּשֶׁהִגִּיעוּ לְרַבִּי שִׁמְעוֹן וְסִדְּרוּ הַדְּבָרִים הַלָּלוּ לְפָנָיו, כָּל מַה שֶּׁנֶּאֱמַר בְּאוֹתָהּ דֶּרֶךְ, פָּתַח וְאָמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. הַפָּסוּק הַזֶּה נִתְבָּאֵר. אֲבָל בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, וְאֹרַח צַדִּיקִים, אוֹתָהּ דֶּרֶךְ שֶׁהַצַּדִּיקִים הָלְכוּ בָהּ, הִיא דֶּרֶךְ אֲמִתִּית, דֶּרֶךְ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּהּ, הַדֶּרֶךְ שֶׁהוּא הוֹלֵךְ לִפְנֵיהֶם, וְכָל אוֹתָן מֶרְכָּבוֹת בָּאוֹת לִשְׁמֹעַ דְּבָרִים שֶׁהֵם מְדַבְּרִים וְאוֹמְרִים בְּפִיהֶם. כְּאוֹר נֹגַהּ, שֶׁמֵּאִיר וְהוֹלֵךְ, וְלֹא נֶחְשָׁךְ (כלל), כְּדֶרֶךְ אוֹתָם הָרְשָׁעִים שֶׁדַּרְכָּם תָּמִיד חֲשׁוּכָה, כְּמוֹ שֶׁנֶּאֱמַר, דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה וְגוֹ'.</p>\n<p>דָּבָר אַחֵר וְאֹרַח צַדִּיקִים - מַה בֵּין אֹרַח לְדֶרֶךְ? הֲרֵי פֵּרְשׁוּהָ. אֲבָל דֶּרֶךְ הִיא שֶׁעַכְשָׁו נִפְתְּחָה וְנִגְלְתָה, וְנַעֲשֶׂה בְּאוֹתוֹ מָקוֹם דֶּרֶךְ שֶׁלֹּא כָתְשׁוּ בָהּ רַגְלַיִם מִקֹּדֶם לָכֵן. דֶּרֶךְ - כְּמוֹ שֶׁנֶּאֱמַר, (ישעיה סג) כְּדֹרֵךְ בְּגַת, שֶׁכּוֹתְשִׁים בּוֹ רַגְלַיִם כָּל מִי שֶׁרוֹצֶה.</p>\n<p>וְעַל זֶה לַצַּדִּיקִים קוֹרֵא אֹרַח, שֶׁהֵם הָיוּ רִאשׁוֹנִים לִפְתֹּחַ אוֹתוֹ מָקוֹם, וְלֹא כָּל הַמָּקוֹם הַהוּא. אֶלָּא אַף עַל גַּב שֶׁאֲחֵרִים בְּנֵי הָעוֹלָם הוֹלְכִים בְּאוֹתוֹ מָקוֹם - עַכְשָׁו שֶׁהוֹלְכִים בָּהּ צַדִּיקִים, הוּא מָקוֹם חָדָשׁ, שֶׁעַכְשָׁו אוֹתוֹ מָקוֹם הוּא חָדָשׁ כְּמוֹ מִי שֶׁלֹּא הָלַךְ בּוֹ אָדָם אַחֵר לְעוֹלָמִים, מִשּׁוּם שֶׁצַּדִּיקִים עוֹשִׂים חִדּוּשׁ לְכָל אוֹתוֹ מָקוֹם בְּכַמָּה דְבָרִים עֶלְיוֹנִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם.</p>\n<p>וְעוֹד, שֶׁשְּׁכִינָה הוֹלֶכֶת בְּאוֹתוֹ מָקוֹם מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן. וּמִשּׁוּם כָּךְ נִקְרָא אֹרַח צַדִּיקִים, מִשּׁוּם שֶׁהִתְאָרַח בּוֹ אוֹרֵחַ עֶלְיוֹן קָדוֹשׁ. דֶּרֶךְ הִיא פְּתוּחָה לַכֹּל, וְכוֹתְשִׁים בָּהּ כָּל מִי שֶׁרוֹצֶה, אֲפִלּוּ אוֹתָם הָרְשָׁעִים. דֶּרֶךְ, סוֹד זֶה - (שם מג) הַנֹּתֵן בַּיָּם דָּרֶךְ. מִשּׁוּם שֶׁדּוֹרֵךְ בּוֹ הַצַּד הָאַחֵר שֶׁלֹּא צָרִיךְ, וְשׁוֹלֵט לְטַמֵּא אֶת הַמִּשְׁכָּן. וְעַל זֶה צַדִּיקִים לְבַדָּם עוֹמְדִים וְשׁוֹלְטִים בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֹרַח. כְּמוֹ שֶׁבֵּאַרְנוּ, דֶּרֶךְ פְּתוּחָה לַכֹּל, לְצַד זֶה וּלְצַד זֶה.</p>\n<p>וְאַתֶּם, קְדוֹשִׁים עֶלְיוֹנִים, דֶּרֶךְ קְדוֹשָׁה עֶלְיוֹנָה הִזְדַּמְּנָה לָכֶם וְהִתְאָרַחְתֶּם בָּהּ, וּדְבָרִים מְעֻלִּים עֶלְיוֹנִים (אלו) הִסְתַּדְּרוּ לִפְנֵי עַתִּיק הַיָּמִים. אַשְׁרֵי חֶלְקְכֶם.</p>"],[9522011847,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דברים לד) וִיהוֹשֻׁעַ בִּן נוּן מָלֵא רוּחַ חָכְמָה כִּי סָמַךְ מֹשֶׁה וְגוֹ'. בְּכַמָּה מְקוֹמוֹת מָצָאנוּ שֶׁפְּנֵי מֹשֶׁה כִּפְנֵי הַשֶּׁמֶשׁ, וִיהוֹשֻׁעַ כִּפְנֵי הַלְּבָנָה. שֶׁאֵין אוֹר לַלְּבָנָה אֶלָּא אוֹר הַשֶּׁמֶשׁ כְּשֶׁמֵּאִיר לַלְּבָנָה, וְהַלְּבָנָה מִתְמַלֵּאת מִתּוֹךְ הַשֶּׁמֶשׁ. וּכְשֶׁמִּתְמַלֵּאת, אָז עוֹמֶדֶת בִּשְׁלֵמוּתָהּ.</p>\n<p>הִשְׁתַּלְּמוּת הַלְּבָנָה מִי הוּא? סוֹד שֶׁל הַכֹּל שֶׁנִּקְרָא דְמוּת בְּסוֹד הַשֶּׁמֶשׁ הָעֶלְיוֹן יְיָ. שֶׁהֲרֵי בַּשֵּׁם הַזֶּה אֵינוֹ עוֹמֵד, רַק בִּזְמַן שֶׁעוֹמֶדֶת בִּשְׁלֵמוּת. שֶׁהֲרֵי כַּמָּה שֵׁמוֹת הֵם שֶׁיָּרְשָׁה, וְנִקְרֵאת בָּהֶם כְּפִי הַשָּׁעָה שֶׁעוֹמֶדֶת בָּהּ, (וכפי השעה עומדת בה) כָּךְ נִקְרֵאת בְּאוֹתוֹ שֵׁם מַמָּשׁ. וּכְשֶׁעוֹמֶדֶת בְּסוֹד הַשְּׁלֵמוּת וְנִשְׁלֶמֶת מִכָּל הַצְּדָדִים, אָז נִקְרָא יְדוָ\"ד. הַשְׁלָמָתָהּ כַּהַשְׁלָמָה שֶׁלְּמַעְלָה, שֶׁיָּרְשָׁה הַבַּת אֶת אִמָּהּ.</p>\n<p>וְהַיְנוּ (הארה) בַּחֲמִשָּׁה עָשָׂר יָמִים, שֶׁכָּתוּב (ויקראכג) בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה. וְכָתוּב (שם) אַךְ בֶּעָשׂוֹר (יום) לַחֹדֶשׁ הַשְּׁבִיעִי. וְהַכֹּל סוֹד אֶחָד. כְּשֶׁעוֹמֵד הָעוֹלָם הַבָּא בַּסּוֹד שֶׁל כָּל עֶשֶׂר הָאֲמִירוֹת עַל הַחֹדֶשׁ הַזֶּה, נִקְרָא בֶּעָשׂוֹר. וּכְשֶׁנִּרְשֶׁמֶת הַלְּבָנָה בִּשְׁלֵמוּת אַחַת בֵּינֵיהֶן, נִקְרָא בַּחֲמִשָּׁה עָשָׂר, שֶׁהֲרֵי ה' הִתְחַבְּרָה וְנֶחְקְקָה בֵינֵיהֶם.</p>\n<p>וְסוֹד זֶה י\"ה, וּכְשֶׁעוֹמֶדֶת בְּשֵׁם זֶה, אָז מִתְחַבֶּרֶת בְּה', וְהִיא נוֹסֶפֶת (אל התחתונים לזון אותם ולתת להם טרפם, ומתוספת) הִיא בְּסוֹד הָאוֹת ה' כְּמִקֹּדֶם. אֶחָד, לְהֵחָקֵק וּלְהִתְחַבֵּר בַּסּוֹד שֶׁלְּמַעְלָה, וְאֶחָד, כְּדֵי לָתֵת מָזוֹן לְמַטָּה, וְאָז עוֹמֶדֶת הַלְּבָנָה בִּשְׁלֵמוּת לְכָל הַצְּדָדִים, מַעְלָה וָמַטָּה, בְּסוֹד הַשֵּׁם הַזֶּה, לִהְיוֹת הַכֹּל סוֹד אֶחָד וּשְׁלֵמוּת אַחַת.</p>\n<p>יְהוֹשֻׁעַ זֶהוּ סוֹד שֶׁל הַשְׁלָמַת הַלְּבָנָה בָּאוֹתִיּוֹת הַלָּלוּ בִּן נוּ\"ן. נוּ\"ן וַדַּאי, שֶׁהֲרֵי נוּן הִיא סוֹד הַלְּבָנָה, מָלֵא בְּסוֹד הַהַשְׁלָמָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְאָז הוּא מָלֵא רוּחַ חָכְמָה וַדַּאי.</p>\n<p>מִשּׁוּם שֶׁהַנְּקֻדָּה הָעֶלְיוֹנָה, שֶׁהִיא י', מִתְפַּשֶּׁטֶת וּמוֹצִיאָה רוּחַ, וְאוֹתָהּ רוּחַ עוֹשָׂה הֵיכָל. וְאוֹתָהּ רוּחַ מִתְפַּשֶּׁטֶת וְנַעֲשֵׂית לְשִׁשָּׁה צְדָדִים. אוֹתָהּ רוּחַ מִתְפַּשֶּׁטֶת בַּסּוֹד שֶׁל כָּל אֵלֶּה. וּמְמַלֵּא וְעוֹשֶׂה הֵיכָל לְמַטָּה, וְהַכֹּל מִתְמַלֵּא, וְנַעֲשֶׂה סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּהַשְׁלָמָה אַחַת.</p>\n<p>וּמִשּׁוּם כָּךְ יְהוֹשֻׁעַ מָלֵא רוּחַ חָכְמָה, מִשּׁוּם - כִּי סָמַךְ מֹשֶׁה אֶת יָדָיו עָלָיו, שֶׁהוּא הֵרִיק עָלָיו בְּרָכוֹת וְנִתְמַלְּאָה הַבְּאֵר מִמֶּנּוּ. וְאַתֶּם, קְדוֹשִׁים עֶלְיוֹנִים, כָּל אֶחָד מִכֶּם הִתְמַלֵּא רוּחַ חָכְמָה, וְעוֹמֵד בִּשְׁלֵמוּת בְּסוֹדוֹת הַחָכְמָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָכֶם וְסָמַךְ יָדוֹ עֲלֵיכֶם. אַשְׁרֵי חֶלְקִי שֶׁעֵינַי רָאוּ אֶת זֶה וְרָאוּ אֶת שְׁלֵמוּת רוּחַ הַחָכְמָה בָּכֶם.</p>"],[9522011848,"<p>פָּתַח וְאָמַר, כָּתוּב (ויקרא יט) לֹא תֹאכְלוּ עַל הַדָּם לֹא תְנַחֲשׁוּ וְלֹא תְעוֹנֵנוּ. פָּסוּק זֶה פֵּרְשׁוּהוּ, וְסוֹד הַדָּבָר - זֶה מִי שֶׁאוֹכֵל בְּלִי תְפִלָּה, שֶׁיִּתְפַּלֵּל (קדםשאוכל) עַל דָּמוֹ, שָׁקוּל הוּא כִּמְנַחֵשׁ וּמְעוֹנֵן.</p>\n<p>מִשּׁוּם שֶׁבַּלַּיְלָה הַנְּשָׁמָה עוֹלָה (ומשתטחת) לִרְאוֹת בְּסוֹד הַכָּבוֹד הָעֶלְיוֹן, כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי לוֹ, וְנִשְׁאָר הָאָדָם בְּאוֹתוֹ כֹּחַ שֶׁהִשְׁתַּתֵּף (שהתפשט) בְּתוֹךְ הַדָּם לְקַיֵּם הַגּוּף, וְלָכֵן (ועם כל זה) טוֹעֵם טַעַם שֶׁל מָוֶת. וְאוֹתוֹ כֹּחַ לֹא נוֹעָד לְהִתְעוֹרֵר לְתוֹךְ אוֹתוֹ כֹּחַ שֶׁל הַנְּשָׁמָה וּלְקַבֵּל אוֹתוֹ. וּכְשֶׁמִּתְעוֹרֵר הָאָדָם, אֵינוֹ טָהוֹר, וַהֲרֵי בֵּאַרְנוּ שֶׁצַּד הָאַחֵר שׁוֹלֵט עַל מָקוֹם שֶׁעוֹמֵד בְּלִי נְשָׁמָה.</p>\n<p>כֵּיוָן שֶׁנִּטְהַר בְּמַיִם, וְאַף עַל גַּב שֶׁהִשְׁתַּדֵּל אָדָם בַּתּוֹרָה, (טוֹעֵם טַעַם מִיתָה, שֶׁהַצַּד הָאַחֵר שׁוֹלֵט בְּמָקוֹם שֶׁנִּמְצָא בְּלֹא נְשָׁמָה, וּכְשֶׁמִּתְעוֹרֵר בֶּן אָדָם, אַף עַל גַּב שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה) אוֹתָהּ נְשָׁמָה לֹא חוֹזֶרֶת לִמְקוֹמָהּ וְלֹא שׁוֹלֶטֶת בָּאָדָם, פְּרָט לְכֹחַ הַדָּם לְבַדּוֹ שֶׁנִּקְרָא נֶפֶשׁ, אוֹתָהּ שֶׁמִּתְפַּשֶּׁטֶת בְּדָם תָּמִיד, וַהֲרֵי בֵּאַרְנוּ. וּכְשֶׁיִּתְפַּלֵּל אָדָם תְּפִלָּה שֶׁל עֲבוֹדַת אֲדוֹנוֹ, אָז מִתְיַשֵּׁב כֹּחַ הַדָּם בִּמְקוֹמוֹ, וּמִתְגַּבֵּר כֹּחַ הַנְּשָׁמָה וּמִתְיַשֶּׁבֶת עַל אוֹתוֹ מָקוֹם. וְאָז אָדָם מֻשְׁלָם לִפְנֵי אֲדוֹנוֹ, כְּמוֹ שֶׁצָּרִיךְ נֶפֶשׁ לְמַטָּה, וְסוֹד הַדָּבָר שֶׁהַנְּשָׁמָה לְמַעְלָה.</p>\n<p>וְעַל כָּךְ, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּה טֶרֶם שֶׁיֹּאכַל, מַעֲמִיד עַצְמוֹ כְּמוֹ שֶׁצָּרִיךְ, וְעוֹלָה הַנְּשָׁמָה עַל מְקוֹם מוֹשָׁבָהּ כְּמוֹ שֶׁצָּרִיךְ. וְאִם אָכַל טֶרֶם שֶׁיִּתְפַּלֵּל תְּפִלָּתוֹ, שֶׁיִּתְיַשֵּׁב הַדָּם עַל מְקוֹמוֹ, זֶהוּ כִּמְנַחֵשׁ וּמְעוֹנֵן. מִשּׁוּם שֶׁזּוֹ דַּרְכּוֹ שֶׁל מְנַחֵשׁ לַעֲלוֹת לַצַּד הָאַחֵר, וּלְהַנְמִיךְ אֶת הַצַּד שֶׁל הַקְּדֻשָּׁה.</p>\n<p>לָמָּה נִקְרָא אוֹתוֹ אָדָם שֶׁמִּשְׁתַּדֵּל בְּאוֹתוֹ צַד מְנַחֵשׁ? עַל שֶׁהִשְׁתַּדֵּל עִם אוֹתוֹ נָחָשׁ לְחַזֵּק כֹּחוֹ וּלְהַגְבִּירוֹ. וְזֶהוּ כְּמִי שֶׁעוֹבֵד אֱלֹהִים אֲחֵרִים. וְכֵן זֶה עוֹבֵד לְאוֹתוֹ כֹּחַ שֶׁל הַדָּם, וְלֹא עוֹבֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַזֵּק אֶת צַד הַנְּשָׁמָה, הַצַּד שֶׁל הַקְּדֻשָּׁה.</p>\n<p>מְעוֹנֵן, שֶׁמִּשְׁתַּדֵּל בְּחֵטְא וְלֹא מִשְׁתַּדֵּל בִּזְכֻיּוֹת. וְאִם תֹּאמַר, הֲרֵי עוֹמֶדֶת נ' בָּאֶמְצַע - כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי לֹא יְכוֹלִים לִשְׁלֹט בְּאוֹתוֹ הַצַּד הָאַחֵר, עַד שֶׁמְּעָרְבִים בָּהּ עֵרוּב שֶׁל צַד הַקְּדֻשָּׁה כְּחוּט אֶחָד דַּקִּיק. מִי שֶׁרוֹצֶה לְהַעֲמִיד שֶׁקֶר, יְעָרֵב בּוֹ דְּבַר אֱמֶת כְּדֵי שֶׁיִּתְקַיֵּם אוֹתוֹ שֶׁקֶר. וְעַל זֶה עֲוֹן דְּבַר שֶׁקֶר הוּא, וּכְדֵי לְהַעֲמִידוֹ, מַכְנִיסִים בּוֹ דְּבַר אֱמֶת, וְזוֹהִי נ'. בָּזֶה מַעֲמִידִים אֶת אוֹתוֹ שֶׁקֶר. וּמִי שֶׁלֹּא מִתְפַּלֵּל תְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא טֶרֶם שֶׁיֹּאכַל עַל דָּמוֹ, כִּמְנַחֵשׁ וּמְעוֹנֵן.</p>"],[9522011849,"<p>תְּפִלַּת אָדָם, כְּפִי שֶׁאֲמַרְתֶּם אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, אַשְׁרֵי חֶלְקְכֶם, שֶׁהֲרֵי בִּתְפִלָּה מִתְתַּקְּנִים גּוּפוֹ וְנַפְשׁוֹ שֶׁל אָדָם וְנַעֲשֶׂה שָׁלֵם. תְּפִלָּה הִיא תִּקּוּנִים מְתֻקָּנִים שֶׁמִּתְתַּקְּנִים כְּאֶחָד, וְהֵם אַרְבָּעָה. תִּקּוּן רִאשׁוֹן - תִּקּוּן שֶׁל עַצְמוֹ לְהִשְׁתַּלֵּם. תִּקּוּן שֵׁנִי - תִּקּוּן שֶׁל הָעוֹלָם הַזֶּה. תִּקּוּן שְׁלִישִׁי - תִּקּוּן שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה בְּכָל אוֹתָם חֵילוֹת הַשָּׁמַיִם. תִּקּוּן רְבִיעִי - תִּקּוּן שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד הַמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת, וּבְסוֹד כָּל הָעוֹלָמוֹת, מַעְלָה וָמַטָּה בִּתִקּוּן (של סודות השם הקדוש) כָּרָאוּי.</p>\n<p>תִּקֹּוּן רִאשׁוֹן, תִּקּוּן שֶׁל עַצְמוֹ - מִשּׁוּם שֶׁצָּרִיךְ לְתַקֵּן אֶת עַצְמוֹ בְּמִצְוָה וּקְדֻשָּׁה, וּלְהִתְתַּקֵּן בְּקָרְבָּנוֹת וְעוֹלוֹת לְהִטָּהֵר. תִּקּוּן שֵׁנִי, בַּתִּקּוּן שֶׁל הַקִּיּוּם שֶׁל הָעוֹלָם הַזֶּה, בְּמַעֲשֵׂה בְרֵאשִׁית לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל מַעֲשֶׂה וּמַעֲשֶׂה בְּאוֹתָם הַלְלוּיָהּ, (תהלים קמח) הַלְלוּהוּ כָּל כּוֹכְבֵי אוֹר הַלְלוּהוּ שְׁמֵי הַשָּׁמַיִם וְגוֹ', לְהַעֲמִיד אֶת קִיּוּם הָעוֹלָם הַזֶּה. וְעַל זֶה בְּבָרוּךְ שֶׁאָמַר, בָּרוּךְ - בָּרוּךְ עַל הַכֹּל.</p>\n<p>תִּקּוּן שְׁלִישִׁי, שֶׁהוּא תִּקּוּן שֶׁל הָעוֹלָם לְמַעְלָה בְּכָל אוֹתָם חֲיָלוֹת חַיָּלִים וּמַחֲנוֹת - יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְגוֹ', וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ. תִּקּוּן רְבִיעִי, תִּקּוּן הַתְּפִלָּה בַּתִּקּוּן שֶׁל סוֹד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁאֲמַרְתֶּם, אַשְׁרֵי חֶלְקְכֶם. וְכָאן סוֹד הַתִּקּוּן שֶׁל הַשֵּׁם הַשָּׁלֵם. אַשְׁרֵי חֶלְקִי עִמָּכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011850,"<p>מִצְווֹת הַתּוֹרָה שֶׁאֲמַרְתֶּם בַּתְּפִלָּה וַדַּאי כָּךְ הוּא. פָּתַח וְאָמַר, כָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא אֹתוֹ תַעֲבֹד. וְכָתוּב, (ויקרא יט) וְיָרֵאתָ מֵּאֱלֹהֶיךְ. בְּפָסוּק זֶה יֵשׁ לוֹמַר כָּךְ: וְיָרֵאתָ מֵּאֱלֹהֶיךְ, מִשּׁוּם שֶׁהֲרֵי כָּתוּב אֶת ה' אֱלֹהֶיךְ תִּירָא. מַה זֶּה מֵאֱלֹהֶיךְ? אֶלָּא סוֹד הוּא, מֵאֱלֹהֶיךְ וַדַּאי, מֵאוֹתוֹ מָקוֹם שֶׁהִתְחַבֵּר וְסוֹבֵב אֶת הַמֹּחַ שֶׁלִּפְנִים, וְזֶהוּ מֵאֱלֹהֶיךְ. יִרְאָה זוֹ לִפְחֹד מִמֶּנּוּ, שֶׁהֲרֵי שָׁם שׁוֹרֶה הַדִּין, וְהוּא דִּין שֶׁנִּשְׁאָב מִתּוֹךְ הַדִּין שֶׁלְּמַעְלָה בַּמָּקוֹם הַזֶּה.</p>\n<p>(יש אש ויש אש) שְׁלֹשָׁה גּוֹנֵי אֵשׁ כָּאן. אֵשׁ רִאשׁוֹנָה הִיא אֵשׁ שֶׁקִּבְּלָה אֵשׁ בְּשִׂמְחָה, וּשְׂמֵחִים זֶה עִם בְּאַהֲבָה. הָאֵשׁ הַשְּׁנִיָּה הִיא הָאֵשׁ שֶׁכָּתוּב בָּהּ (יחזקאל א) וְנֹגַהּ לָאֵשׁ, שֶׁנִּרְאֶה בָּהּ נֹגַהּ, וְזוֹהִי אֵשׁ שֶׁעוֹמֶדֶת בְּתוֹךְ הָאֵשׁ הַפְּנִימִית בְּשִׂמְחָה, כְּמוֹ שֶׁנִּתְבָּאֵר. הָאֵשׁ הַשְּׁלִישִׁית הִיא אֵשׁ (שבחוץ) שֶׁסּוֹבֶבֶת אוֹתוֹ נֹגַהּ, וּבְזוֹ הָאֵשׁ הִתְחִילָה יִרְאַת הַדִּין לְהַלְקוֹת הָרְשָׁעִים.</p>\n<p>וְאַף עַל גַּב שֶׁשָּׁנִינוּ שֶׁאַרְבָּעָה צְבָעִים שֶׁל אֵשׁ הֵם, וְאֵלּוּ אַרְבָּעָה שֶׁהֵם אֶחָד. אֲבָל כָּאן בָּאֵשׁ הַהִיא שֶׁאָנוּ אוֹמְרִים, מַתְחִיל פַּחַד הַדִּין, וְעַל זֶה כָּתוּב וְיָרֵאתָ מֵּאֱלֹהֶיךְ, מֵאוֹתוֹ הָעֹנֶשׁ שֶׁלּוֹ.</p>\n<p>וּבְאוֹתָהּ יִרְאָה צָרִיךְ לָשִׂים רְצוֹנוֹ בְּיִרְאָה וְאַהֲבָה כְּאֶחָד, לְפַחֵד בְּצַד זֶה - וְלֶאֱהֹב בְּצַד זֶה, וּבְאוֹתָם גְּוָנִים שֶׁאָמַרְנוּ, וְאוֹתוֹ הַפַּחַד לִהְיוֹת פּוֹחֵד מֵעֹנֶשׁ. שֶׁמִּי שֶׁעוֹבֵר עַל מִצְווֹת הַתּוֹרָה נֶעֱנָשׁ בְּאוֹתוֹ צַד. שֶׁכְּשֶׁמַּתְחִיל אוֹתוֹ צַד לְהַלְקוֹת, לֹא שׁוֹקֵט עַד שֶׁמְּכַלֶּה אוֹתוֹ מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ צָרִיךְ לִפְחֹד מֵהָאֵשׁ הַ את שֶׁשָּׁרוּי בָּהּ הַפַּחַד.</p>\n<p>וּמִמֶּנָּה מִתְפַּשֶּׁטֶת אֵשׁ לַחוּץ שֶׁל יִרְאָה אַחֶרֶת, וְעַל זֶה כָּתוּב (שופטים ו) לֹא תִירְאוּ אֶת אֱלֹהֵי הָאֱמֹרִי, שֶׁאָסוּר לִפְחֹד מִמֶּנּוּ. וְהָאֵשׁ הַזּוֹ שֶׁל יִרְאָה שֶׁאָמַרְנוּ הִיא קֹדֶשׁ וּמִשְׁתַּתֶּפֶת בִּקְדֻשָּׁה, וְזוֹהִי שֶׁסּוֹבֶבֶת אוֹתוֹ נֹגַהּ שֶׁאָמַרְנוּ. וְאוֹתָהּ אֵשׁ אַחֶרֶת שֶׁבַּחוּץ, מִתְחַבֶּרֶת בָּזוֹ לִפְעָמִים, וְלִפְעָמִים מָעֳבֶרֶת מִמֶּנָּה וְלֹא מִתְחַבֶּרֶת עִמָּהּ. וּכְשֶׁגּוֹרֵם שֶׁתִּתְחַבֵּר בָּזוֹ, אֲזַי הוּא אֵשׁ שֶׁל חֹשֶׁךְ, וּמַחֲשִׁיכָה וּמְכַסָּה אֶת הָאוֹר שֶׁל הָאֲחֵרוֹת הַלָּלוּ, וְסִימָנְךְ - וְאֵשׁ מִתְלַקַּחַת, וְלֹא שֶׁתָּמִיד עוֹמֶדֶת, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>אַחַר כָּךְ הִיא אַהֲבָה, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁאַהֲבָה שׁוֹרָה לְאַחַר יִרְאָה. וְסוֹד הַדָּבָר - כֵּיוָן שֶׁהִתְחִילָה יִרְאָה עַל רֹאשׁוֹ שֶׁל הָאָדָם, מִתְעוֹרֶרֶת אַחַר כָּךְ אַהֲבָה, שֶׁהִיא יָמִין, שֶׁמִּי שֶׁעוֹבֵד מִתּוֹךְ אַהֲבָה, נִדְבָּק בְּמָקוֹם עֶלְיוֹן לְמַעְלָה וְנִדְבָּק בִּקְדֻשַּׁת הָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהֲרֵי עוֹלָה לְהִתְעַטֵּר וּלְהִדָּבֵק בְּצַד הַיָּמִין.</p>\n<p>וְאִם תֹּאמַר שֶׁעֲבוֹדָה שֶׁהִיא מִצַּד הַיִּרְאָה אֵינָהּ עֲבוֹדָה - עֲבוֹדָה נִכְבָּדָה הִיא, אֲבָל לֹא עוֹלָה לְהִדָּבֵק לְמַעְלָה. וּכְשֶׁעוֹבֵד מֵאַהֲבָה, עוֹלֶה וּמִתְעַטֵּר לְמַעְלָה וְנִדְבָּק בָּעוֹלָם הַבָּא, וְזֶהוּ אָדָם שֶׁמְּזֻמָּן לָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקוֹ, שֶׁהוּא שׁוֹלֵט עַל מְקוֹם הַיִּרְאָה, שֶׁהֲרֵי אֵין מִי שֶׁשּׁוֹלֵט עַל דַּרְגַּת הַיִּרְאָה, אֶלָּא רַק אַהֲבָה, סוֹד הַיָּמִין.</p>\n<p>סוֹד הַיִּחוּד שֶׁצָּרִיךְ לְאוֹתוֹ שֶׁרָאוּי לָעוֹלָם הַבָּא, לְיַחֵד אֶת שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְיַחֵד הָאֵיבָרִים וְהַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת, לְהַכְלִיל אֶת כֻּלָּם וּלְהַכְנִיסָם לְמָקוֹם שֶׁצָּרִיךְ לִקְשֹׁר קֶשֶׁר. וְזֶהוּ סוֹד הַכָּתוּב, (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד.</p>"],[9522011851,"<p>וְסוֹד שֶׁל שְׁמַע - שֵׁם שֶׁעוֹלֶה לְשִׁבְעִים שֵׁמוֹת, וְזֶה כְּלָל אֶחָד. יִשְׂרָאֵל - יִשְׂרָאֵל סָבָא, מִשּׁוּם שֶׁיֵּשׁ קָטָן, שֶׁכָּתוּב (הושע יא) נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וְזֶהוּ יִשְׂרָאֵל סָבָא, סוֹד אֶחָד בִּכְלָל אֶחָד. שְׁמַע יִשְׂרָאֵל - כָּאן נִכְלֶלֶת אִשָּׁה בְּבַעְלָהּ.</p>\n<p>וְאַחַר שֶׁנִּכְלְלוּ זֶה בָּזוֹ בִּכְלָל אֶחָד, אֲזַי צְרִיכִים לְיַחֵד אֶת הָאֵיבָרִים וּלְחַבֵּר שְׁנֵי מִשְׁכָּנוֹת כְּאֶחָד בְּכָל הָאֵיבָרִים בִּרְצוֹן הַלֵּב, לַעֲלוֹת בַּדְּבֵקוּת שֶׁל אֵין סוֹף, לְהִתְדַּבֵּק הַכֹּל שָׁם, לִהְיוֹת רָצוֹן אֶחָד שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְסוֹד זֶה יִהְיֶה, כְּמוֹ שֶׁנֶּאֱמַר יִהְיֶה ה' אֶחָד, בְּסוֹד שֶׁל יִהְיֶה. י', לְיַחֵד וּלְהִדָּבֵק בְּה', שֶׁהוּא הֵיכָל הַפְּנִימִי, לִמְקוֹם (מקום) גְּנִיזַת הַנְּקֻדָּה הָעֶלְיוֹנָה הַזּוֹ שֶׁהִיא י'. וְזֶהוּ סוֹד יְהֹוָ\"ה אֱלֹהֵינוּ. אֵלּוּ שְׁתֵּי אוֹתִיּוֹת (שמות) שֶׁהֵם יָ\"הּ.</p>\n<p>וְלִכְלל כָּל הָאֵיבָרִים בְּאוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ, שֶׁהוּא הֵיכָל הַפְּנִימִי, לְהַחֲזִיר דְּבָרִים לִמְקוֹמָם לָעִקָּר וִיסוֹד וְשֹׁרֶשׁ שֶׁלָּהֶם, עַד הַמָּקוֹם הַהוּא שֶׁל שֹׁרֶשׁ הַבְּרִית.</p>\n<p>וּלְבַסּוֹף אֵלּוּ שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת לְיַחֵד וּלְהַדְבִּיק י' בְּה'. אוֹת י' הִיא סוֹד הַבְּרִית הַקָּדוֹשׁ. וְאוֹת ה' הַזּוֹ הִיא הֵיכָל, מְקוֹם גְּנִיזָה שֶׁל סוֹד הַבְּרִית הַקָּדוֹשׁ הַזֶּה, שֶׁהוּא י'. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ שֶׁהִיא ו' הַשְּׁנִיָּה. אֲבָל י', הַסּוֹד שֶׁלּוֹ לְיַחֲדָם כְּאֶחָד.</p>\n<p>אֶחָד - לְיַחֵד מִשָּׁם וָמַעְלָה הַכֹּל כְּאֶחָד, וּלְהַעֲלוֹת רָצוֹן לְהִתְקַשֵּׁר הַכֹּל (ממטה למעלה) בְּקֶשֶׁר אֶחָד. לְהַעֲלוֹת רְצוֹנוֹ בְּיִרְאָה וְאַהֲבָה לְמַעְלָה לְמַעְלָה עַד אֵין סוֹף, וְלֹא יַשְׁאִיר רָצוֹן מִכָּל אוֹתָן דְּרָגוֹת וְאֵיבָרִים, אֶלָּא בְּכֻלָּם יַעֲלֶה רְצוֹנוֹ לְהַשִּׂיגָם, וְשֶׁיִּהְיוּ כֻלָּם קֶשֶׁר אֶחָד בָּאֵין סוֹף.</p>\n<p>וְזְהִוּ הַיִּחוּד שֶׁל רַב הַמְנוּנָא סָבָא שֶׁלָּמַד מֵאָבִיו, וְאָבִיו מֵרַבּוֹ, עַד פִּיו שֶׁל אֵלִיָּהוּ, וְיָפֶה הוּא, וְהוּא יִחוּד בְּתִקּוּן. וְאַף עַל גַּב שֶׁאָנוּ בֵּאַרְנוּ אֶת זֶה בְּכַמָּה סוֹדוֹת, כָּל הַסּוֹדוֹת עוֹלִים לְאֶחָד. אֲבָל הַסּוֹד הַזֶּה מָצָאנוּ בְּסִפְרוֹ, וְיָפֶה הוּא, וְהוּא יִחוּד בְּתִקּוּן. וַהֲרֵי אָנוּ בְּיִחוּד שֶׁל סוֹד אַחֵר הֵעַרְנוּ דְבָרִים, וְהוּא יָפֶה, וְהַיִּחוּד כָּרָאוּי וְכָךְ הוּא. אֲבָל הַיִּחוּד הַזֶּה יִחוּד בְּתִקּוּן, וְזֶהוּ יִחוּדוֹ שֶׁל רַב הַמְנוּנָא סָבָא.</p>\n<p>וְעוֹד הָיָה אוֹמֵר, מִי שֶׁרְצוֹנוֹ לְהַכְלִיל אֶת כָּל סוֹדוֹת הַיִּחוּד בְּדָבָר אֶחָד יוֹתֵר יָפֶה. וְלָכֵן אָנוּ מַאֲרִיכִים בְּאֶחָד, לַעֲלוֹת רְצוֹנוֹ מִמַּעְלָה לְמַטָּה, וּמִמַּטָּה לְמַעְלָה, לִהְיוֹת הַכֹּל אֶחָד. אֲבָל בְּסוֹד זֶה יִהְיֶ\"ה, סִימָן (בעלמא) הוּא לָזֶה.</p>\n<p>וְזְהִ שֶׁשָּׁנִינוּ, אֶחָד (להיות ד') - סוֹד מַעְלָה וּמַטָּה וְאַרְבַּעַת צִדְדֵי הָעוֹלָם, כָּךְ הוּא, לְיַחֵד מַעְלָה וּמַטָּה כְּמוֹ שֶׁנִּתְבָּאֵר, (ולארבעה) וְאַרְבַּעַת צִדְדֵי הָעוֹלָם אֵלּוּ הֵם סוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה לְהַכְלִיל הַכֹּל כְּאֶחָד, בְּקֶשֶׁר אֶחָד, בְּיִחוּד אֶחָד עַד אֵין סוֹף, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>"],[9522011852,"<p>הַסּוֹד שֶׁל לְהַזְכִּיר אֶת יְצִיאַת מִצְרַיִם אַחַר כָּךְ, מִשּׁוּם שֶׁשְּׁכִינָה הָיְתָה בַּגָּלוּת, וּבִזְמַן שֶׁהִיא בַּגָּלוּת, אֵינוֹ חִבּוּר לְחַבֵּר זֶה בָּזֶה, הָעוֹלָם הַתַּחְתּוֹן בָּעוֹלָם הָעֶלְיוֹן, וּלְהַרְאוֹת חֵרוּת שֶׁל אוֹתָהּ גְּאֻלָּה שֶׁהָיְתָה בְּכַמָּה אוֹתוֹת, בְּכַמָּה נִסִּים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ לְהַזְכִּיר אוֹתָהּ גְּאֻלָּה, וּלְהַרְאוֹת שֶׁאַף עַל גַּב שֶׁהָיְתָה בַּגָּלוּת - עַכְשָׁו יֵשׁ לָהּ חֵרוּת. מִיּוֹם שֶׁהֻתְּרוּ אוֹתָם הַקְּשָׁרִים בְּמִצְרַיִם, אוֹתָם אוֹתוֹת וְנִסִּים נַעֲשׂוּ.</p>\n<p>וְצָרִיךָ לְהַרְאוֹת אֶת חֵרוּתָהּ, מִשּׁוּם שֶׁהִתְחַבְּרָה עִם בַּעְלָהּ, וּכְדֵי לְהַסְמִיךְ גְּאֻלָּה לִתְפִלָּה, שֶׁיִּהְיֶה הַכֹּל אֶחָד לְלֹא פֵרוּד, וְלֹא לְהַרְאוֹת גֵּרוּשִׁים. וְסִימָנְךְ - וְאִשָּׁה גְּרוּשָׁה מֵאִישָׁהּ לֹא יִקָּחוּ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי הִיא בַּגָּלוּת, וַהֲרֵי גֹּרְשָׁה - לֹא כָּךְ. אֶלָּא וַדַּאי שֶׁהִיא בַּגָּלוּת לָדוּר עִם יִשְׂרָאֵל וּלְהָגֵן עֲלֵיהֶם, אֲבָל לֹא גֹרְשָׁה. וַהֲרֵי שְׁכִינָה לֹא נִרְאֲתָה בְּבַיִת רִאשׁוֹן וּבְבַיִת שֵׁנִי. טֶרֶם שֶׁגָּלוּ יִשְׂרָאֵל עָלְתָה לְמַעְלָה, וְאַחַר כָּךְ שָׂמָה אֶת מְדוֹרָהּ עִמָּם, אֲבָל גֵּרוּשִׁים לֹא הָיוּ לְעוֹלָמִים.</p>\n<p>וּמִשּׁוּם כָּךְ צָרִיךְ לְהַרְאוֹת גְּאֻלָּה שֶׁיֵּשׁ בָּהּ אַרְבַּע גְּאֻלּוֹת. וְסוֹד כָּאן - בְּשָׁעָה שֶׁיָּצְאָה שְׁכִינָה מִגָּלוּת מִצְרַיִם, בִּקְשָׁה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּפְדֶּה אוֹתָהּ עַכְשָׁו אַרְבַּע פְּעָמים, שֶׁהֵן אַרְבַּע גְּאֻלּוֹת כְּנֶגֶד אַרְבַּע גָּלֻיּוֹת, כְּדֵי שֶׁתִּהְיֶה בַּת חוֹרִין וְלֹא תִהְיֶה מְגֹרֶשֶׁת. וּבְאוֹתָהּ שָׁעָה עָמְדָה וְנִגְאֲלָה אַרְבַּע גְּאֻלּוֹת, בְּאוֹתָהּ יְצִיאַת מִצְרַיִם. וְעַכְשָׁו שֶׁהִצְטָרְכָה בְּתִקּוּנֶיהָ לְהִתְחַבֵּר עִם בַּעְלָהּ, צָרִיךְ לְהַרְאוֹת אוֹתָהּ גְּאֻלַּת מִצְרַיִם שֶׁיֵּשׁ בָּהּ אַרְבַּע גְּאֻלּוֹת.</p>\n<p>וְעַל זֶה יֵשׁ לְהַזְכִּיר בְּאוֹתָהּ גְּאֻלָּה אַרְבַּע פְּעָמִים אֱמֶת, אֱמֶת, אֱמֶת, אֱמֶת, עַד עֶזְרַת אֲבוֹתֵינוּ, שֶׁזּוֹהִי עֶזְרָה וְסֶמֶךְ לְיִשְׂרָאֵל כֻּלָּם. וּמִשָּׁם וָהָלְאָה אַרְבַּע פְּעָמִים אֲחֵרוֹת אֱמֶת, אֱמֶת, אֱמֶת, אֱמֶת, לִהְיוֹת אַרְבַּע הַגְּאֻלּוֹת הַלָּלוּ בְּקִיּוּם חָזָק בְּחוֹתָם חָזָק שֶׁל טַבַּעַת הַמֶּלֶךְ, אַרְבַּע גְּאֻלּוֹת כְּפוּלוֹת בְּקִיּוּם.</p>\n<p>וְכֻלָּן בְּאוֹתָהּ יְצִיאַת מִצְרַיִם, שֶׁאִלּוּ לֹא נִמְצְאוּ אוֹתָן אַרְבַּע גְּאֻלּוֹת בְּאוֹתָהּ יְצִיאַת מִצְרַיִם, כָּל פַּעַם שֶׁתִּהְיֶה גָלוּת, לֹא מִתְחַבֶּרֶת בְּתִקּוּנֶיהָ לְהִתְיַחֵד בַּשֵּׁם הַקָּדוֹשׁ, וְלָכֵן צָרִיךְ תָּמִיד לְהַזְכִּיר אֶת גְּאֻלַּת מִצְרַיִם בְּכָל הַקְּדֻשּׁוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>סוֹד הַקְּדֻשָּׁה (של שמו) הֲרֵי בֵּאַרְנוּ, שֶׁהֲרֵי בִּקְדֻשָּׁה הַכֹּל מִתְקַדְּשִׁים - מַעְלָה וּמַטָּה, וְכָל הַדְּרָגוֹת, וְכָל הַמֶּרְכָּבוֹת עֶלְיוֹנוֹת וְתַחְתּוֹנוֹת, כֻּלָּם מִתְקַדְּשִׁים בַּקְּדֻשָּׁה הַזּוֹ. וּבַקְּדֻשָּׁה הַזּוֹ בֵּאַרְנוּ סוֹדוֹת עֶלְיוֹנִים לְאוֹתָם בַּעֲלֵי סוֹדוֹת שֶׁמִּתְבּוֹנְנִים בִּקְדֻשַּׁת רִבּוֹנָם, אַשְׁרֵי חֶלְקָם.</p>\n<p>הַסּוֹד לִמְסֹר הַנֶּפֶשׁ לַאֲדוֹנוֹ הוּא יָפֶה שֶׁאֲמַרְתֶּם הַחֲבֵרִים. אַשְׁרֵי חֶלְקְכֶם, וְאַשְׁרֵי עֵינַי שֶׁרָאוּ כָּךְ, שֶׁרָאִיתִי בְּחַיַּי שֶׁמְּעוֹרְרִים דְּבָרִים קְדוֹשִׁים אֵלּוּ בָּעוֹלָם הַזֶּה, (משום שכלם) וְכֻלָּם כְתוּבִים לְמַעְלָה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>"],[9522011853,"<p>פָּתַח וְאָמַר, (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחֹשְׁבֵי שְׁמוֹ. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, אָז נִדְבְּרוּ?! אָז דִּבְּרוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה נִדְבְּרוּ? אֶלָּא נִדְבְּרוּ לְמַעְלָה מִכָּל אוֹתָן מֶרְכָּבוֹת קְדוֹשׁוֹת וְכָל אוֹתָם חֲיָלוֹת קְדוֹשִׁים.</p>\n<p>מִשּׁוּם שֶׁאוֹתָם דְּבָרִים קְדוֹשִׁים עוֹלִים לְמַעְלָה, וְכַמָּה הֵם שֶׁמַּקְדִּימִים וְנוֹטְלִים אוֹתָם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִתְעַטְּרִים בְּכַמָּה עֲטָרוֹת בְּאוֹתָם אוֹרוֹת עֶלְיוֹנִים, וְכֻלָּם נִדְבְּרוּ מִלִּפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. מִי רָאָה אֶת הַשְּׂמָחוֹת? מִי רָאָה אֶת הַתִּשְׁבָּחוֹת שֶׁעוֹלוֹת בְּכָל אוֹתָם רְקִיעִים, כְּשֶׁהַדְּבָרִים הַלָּלוּ עוֹלִים (לפני המלך הקדוש), וְהַמֶּלֶךְ הַקָּדוֹשׁ מִסְתַּכֵּל בָּהֶם וּמִתְעַטֵּר בָּהֶם, וְהֵם עוֹלִים (על ראשו, והיו עטרה ויורדים ויושבים) וְיוֹשְׁבִים עַל חֵיקוֹ וּמִשְׁתַּעֲשֵׁעַ בָּהֶם, וּמִשָּׁם עוֹלִים עַל רֹאשׁוֹ וְנִהְיִים עֲטָרָה. וְעַל זֶה אָמְרָה תוֹרָה, (משלי ח) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. לֹא כָתוּב וְהָיִיתִי, אֶלָּא וָאֶהְיֶה, בְּכָל זְמַן וּבְכָל עֵת שֶׁדְּבָרִים עֶלְיוֹנִים עוֹלִים לְפָנָיו.</p>\n<p>פַּעָמַיִם כָּתוּב יִרְאֵי ה', יִרְאֵי ה'. אֶלָּא יִרְאֵי ה' לְמַעְלָה, יִרְאֵי ה' לְמַטָּה. יִרְאֵי ה' עוֹמְדִים לְמַטָּה, וְאוֹתָם דְּבָרִים עוֹמְדִים בִּדְיוֹקְנֵיהֶם לְמַעְלָה. וְסוֹד זֶה מָצָאנוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ, שֶׁכָּל דִּבְרֵי הַצַּדִּיקִים שֶׁבָּאָרֶץ הֵם מִתְעַטְּרִים וְעוֹמְדִים לִפְנֵי הַמֶּלֶךְ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בָּהֶם. וְאַחַר כָּךְ הֵם יוֹרְדִים וְעוֹמְדִים לְפָנָיו בִּדְיוֹקַן אוֹתוֹ הַצַּדִּיק שֶׁאָמַר אוֹתָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּאוֹתוֹ דְיוֹקָן, וְאַחַר כָּךְ נִכְתָּבִים בְּסֵפֶר זִכָּרוֹן לְפָנָיו, לַעֲמֹד לְפָנָיו בְּקִיּוּם תְּמִידִי.</p>\n<p>וּלְחֹשְׁבֵי שְׁמוֹ, מַה זֶּה וּלְחֹשְׁבֵי שְׁמוֹ? הֲרֵי פֵּרְשׁוּהָ, (אבל) כָּל אוֹתָם שֶׁמְּחַשְּׁבִים דִּבְרֵי תוֹרָה לְהַשִּׂיג אֶת אֲדוֹנָם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ כְּדֵי לְהַכִּיר אוֹתוֹ וּלְהַתְקִין אֶת חָכְמַת שְׁמוֹ בְּלִבָּם, שֶׁכָּתוּב וּלְחֹשְׁבֵי שְׁמוֹ, שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ.</p>"],[9522011854,"<p>כָּתוּב (יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. פָּסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ. אֲבָל וּמִמַּעַל לָרָקִיעַ, בְּאוֹתוֹ רָקִיעַ לְמַטָּה, כְּמוֹ שֶׁאֲמַרְתֶּם הַחֲבֵרִים. אַשְׁרֵי חֶלְקִי וְאַשְׁרֵי חֶלְקְכֶם (באותו רקיע למעלה). שֶׁהֲרֵי בָּרָקִיעַ שֶׁלְּמַעְלָה אֵין מִי שֶׁמִּתְבּוֹנֵן בּוֹ, וּמִלְמַעְלָה מִמֶּנּוּ עוֹמֵד אוֹתוֹ אֶבֶן סַפִּיר, שֶׁהֲרֵי הִתְעוֹרַרְנוּ בוֹ בְּסוֹד שֶׁל אוֹתָהּ מַרְגָּלִית טוֹבָה נִכְבָּדָה, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>דְּמוּת כִּסֵּא, וְלֹא כָתוּב דְּמוּת הַכִּסֵּא, מִשּׁוּם שֶׁיֵּשׁ כִּסֵּא וְיֵשׁ כִּסֵּא. הַכִּסֵּא - הָעֶלְיוֹן הַטָּמִיר וְהַגָּנוּז שֶׁלֹּא הִתְגַּלָּה וְאֵין מִי שֶׁעוֹמֵד בּוֹ לָדַעַת וּלְהִתְבּוֹנֵן. וְלָכֵן כָּתוּב כִּסֵּא סְתָם, זֶהוּ הַכִּסֵּא שֶׁלְּמַטָּה.</p>\n<p>דְּמוּת כְּמַרְאֵה אָדָם. כֵּיוָן שֶׁאָמַר דְּמוּת, אָז לָמָּה כְּמַרְאֵה, שֶׁהֲרֵי דַּי לוֹ דְּמוּת אָדָם? אֶלָּא דְּמוּת אָדָם זֶהוּ סוֹד עֶלְיוֹן בְּאוֹתוֹ כָּבוֹד עֶלְיוֹן, דְּיוֹקָן שֶׁל אָדָם. אֲבָל זֶה שֶׁנּוֹסָף כְּמַרְאֵה - לְהַכְלִיל אוֹתָם דְּיוֹקְנָאוֹת שֶׁל דִּבְרֵי חָכְמָה וְאוֹתָם סוֹדוֹת שֶׁל חָכְמָה שֶׁעוֹלוֹת וּמִתְעַטְּרוֹת לְמַעְלָה, וְאַחַר כָּךְ עוֹמְדוֹת בִּדְיוֹקָן שֶׁל אָדָם בְּאוֹתוֹ הַדְּיוֹקָן שֶׁל הַצַּדִּיקִים שֶׁמְּעַטְּרִים אוֹתָם, וּבְכֻלָּם מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַטְרוֹתָיו.</p>\n<p>וְאַתֶּם הַחֲבֵרִים, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ כָּעֵת בְּאוֹתָם דְּבָרִים שֶׁאֲמַרְתֶּם, מִתְעַטְּרִים בְּאוֹתָהּ דֶּרֶךְ. וַהֲרֵי עֲמַדְתֶּם לִפְנֵי רִבּוֹנְכֶם בִּדְיוֹקְנֵיכֶם הַקְדוֹשִׁים, שֶׁהֲרֵי אֲנִי, בְּשָׁעָה שֶׁרָאִיתִי אֶתְכֶם וְהִסְתַּכַּלְתִּי בִּדְיוֹקְנֵיכֶם, רָאִיתִי בָכֶם שֶׁאַתֶּם רְשׁוּמִים בְּסוֹד שֶׁל אָדָם, וְיָדַעְתִּי שֶׁהֲרֵי דְּיוֹקְנֵיכֶם נוֹעָד לְמַעְלָה. וְכָךְ מְזֻמָּנִים הַצַּדִּיקִים לֶעָתִיד לָבֹא, שֶׁיִּהְיוּ נוֹדָעִים לְעֵין הַכֹּל, וּלְהַרְאוֹת פַּרְצוּף קָדוֹשׁ לִפְנֵי כָּל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה סא) כָּל רֹאֵיהֶם יַכִּירוּם כִּי הֵם זֶרַע בֵּרַךְ ה'.</p>\n<p>בֵּין כָּךְ רָאָה אֶת רַבִּי יוֹסֵי שֶׁהָיָה מְהַרְהֵר בְּדִבְרֵי הָעוֹלָם. אָמַר לוֹ, יוֹסֵי, קוּם וְהַשְׁלֵם דְּיוֹקְנְךְ, שֶׁאוֹת אַחַת חֲסֵרָה בְּךְ. קָם רַבִּי יוֹסֵי וְשָׂמַח בְּדִבְרֵי תוֹרָה וְקָם לְפָנָיו. הִסְתַּכֵּל בּוֹ רַבִּי שִׁמְעוֹן. אָמַר לוֹ, רַבִּי יוֹסֵי, עַכְשָׁו אַתָּה שָׁלֵם לִפְנֵי עַתִּיק הַיָּמִים וּדְיוֹקְנְךְ שָׁלֵם.</p>"],[9522011855,"<p>פָּתַח וְאָמַר, וַיַּעֲשׂוּ אֶת צִיץ נֵזֶר הַקֹּדֶשׁ זָהָב טָהוֹר וְגוֹ'. לָמָּה נִקְרָא צִיץ? הִסְתַּכְּלוּת לְהִסְתַּכֵּל בּוֹ. וּמִשּׁוּם שֶׁהָיָה עוֹמֵד עַל הִסְתַּכְּלוּת שֶׁל אָדָם, נִקְרָא צִיץ. וְכָל מִי שֶׁהִסְתַּכֵּל בּוֹ בְּאוֹתוֹ צִיץ, הָיָה נוֹדָע בּוֹ וּמֻכָּר.</p>\n<p>בַּצִיץ הָיוּ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ חֲקוּקוֹת בַּחֲקִיקָה וַחֲקוּקוֹת בּוֹ. וְאִם צַדִּיק הָיָה אוֹתוֹ שֶׁעוֹמֵד לְפָנָיו, אוֹתָן אוֹתִיּוֹת שֶׁחֲקוּקוֹת בְּתוֹךְ הַזָּהָב הָיוּ בּוֹלְטוֹת מִמַּטָּה לְמַעְלָה וְעוֹלוֹת מֵאוֹתָהּ חֲקִיקָה בְּאוֹר, וְהָיוּ מְאִירוֹת בִּפְנֵי אוֹתוֹ הָאָדָם.</p>\n<p>נוֹצֶצֶת בּוֹ הִתְנוֹצְצוּת, וְלֹא נוֹצְצִים. בַּשָּׁעָה הָרִאשׁוֹנָה שֶׁהִסְתַּכֵּל בּוֹ הַכֹּהֵן, הָיָה רוֹאֶה אֶת אוֹר הָאוֹתִיּוֹת כֻּלָּם בַּפָּנִים, וּכְשֶׁהָיָה מִסְתַּכֵּל לְעַיֵּן בּוֹ, לֹא הָיָה רוֹאֶה דָבָר, אֶלָּא אֶת אוֹר פָּנָיו שֶׁמֵּאִיר כְּאִלּוּ נִיצוֹץ שֶׁל זָהָב הָיָה נוֹצֵץ בּוֹ. רַק שֶׁהַכֹּהֵן הָיָה יוֹדֵעַ אֶת מַרְאֵה הַהִסְתַּכְּלוּת הָרִאשׁוֹנָה שֶׁהָיָה רוֹאֶה לְפִי שָׁעָה, שֶׁהֲרֵי רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בְּאוֹתוֹ אָדָם, וְיוֹדֵעַ שֶׁהוּא מְזֻמָּן לָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהַמַּרְאֶה הַזֶּה מְאִירִים עָלָיו מִלְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מְרֻצֶּה בּוֹ. וּכְשֶׁמִּסְתַּכְּלִים בּוֹ לֹא רוֹאִים דָּבָר, מִשּׁוּם שֶׁהַמַּרְאֶה שֶׁלְּמַעְלָה אֵינוֹ מִתְגַּלֶּה אֶלָּא לְפִי שָׁעָה.</p>\n<p>וְאִם עוֹמֵד אָדָם לִפְנֵי אוֹתוֹ צִיץ וּפָנָיו אֵינָם מַרְאִים לְפִי שָׁעָה מַרְאֶה קָדוֹשׁ, הָיָה הַכֹּהֵן יוֹדֵעַ שֶׁהֲרֵי הוּא עַז מֵצַח, וְצָרִיךְ לְכַפֵּר עָלָיו וּלְבַקֵּשׁ עָלָיו רַחֲמִים.</p>"],[9522011856,"<p>וַיַּעַשׂ אֶת צִיץ נֶזֶר הַקֹּדֶשׁ. רַבִּי יְהוּדָה פָּתַח הַפָּסוּק בְּרוּת (רות ב), עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, לָמָּה צָרִיךְ כָּאן לִכְתֹּב? אָמַר לוֹ רַבִּי יִצְחָק, אִם כָּךְ, כַּמָּה פְסוּקִים הֵם בַּתּוֹרָה שֶׁנִּרְאֶה שֶׁלֹּא הִצְטָרְכוּ לְהִכָּתֵב, וְרָאִינוּ שֶׁכֻּלָּם סוֹדוֹת עֶלְיוֹנִים. אָמַר רַבִּי יְהוּדָה, בְּפָסוּק זֶה מִי שֶׁרוֹאֶה וְלֹא מִתְבּוֹנֵן בּוֹ, כְּמִי שֶׁלֹּא טָעַם תַּבְשִׁיל הוּא דּוֹמֶה.</p>\n<p>אֶלָּא סוֹד כָּאן, וּבְרוּחַ הַקֹּדֶשׁ נֶאֱמַר. מִשּׁוּם שֶׁרָאָה בֹּעַז, הַדַּיָּן שֶׁל יִשְׂרָאֵל, אֶת עַנְוְתָנוּתָהּ שֶׁל אוֹתָהּ צַדֶּקֶת, שֶׁלֹּא מְרִימָה עֵינֶיהָ לִרְאוֹת בְּמָקוֹם אַחֵר אֶלָּא לְפָנֶיהָ, וְרָאֲתָה כָּל מַה שֶּׁרָאֲתָה בְּעַיִן טוֹבָה, וְעַזּוּת הַמֵּצַח לֹא הָיְתָה בָּהּ - שִׁבַּח אֶת עֵינֶיהָ.</p>\n<p>מִשּׁוּם שֶׁיֵּשׁ עֵינַיִם שֶׁבִּשְׁבִילָן אֵין שׁוֹלֶטֶת בְּרָכָה בְּאוֹתוֹ מָקוֹם, וְהוּא רָאָה בָּהּ עַיִן טוֹבָה, שֶׁעַל כָּל מַה שֶּׁהִסְתַּכְּלָה הָיָה בְּעַיִן טוֹבָה. וְעוֹד, שֶׁרָאָה שֶׁהָיָה מַצְלִיחַ בְּיָדָהּ כָּל מַה שֶּׁהָיְתָה לוֹקַחַת נוֹסָף בַּשָּׂדֶה. וּבעַז הִתְבּוֹנֵן שֶׁרוּחַ הַקֹּדֶשׁ שׁוֹרָה עָלֶיהָ, וְאָז פָּתַח וְאָמַר, עֵינַיִךְ בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן וְגוֹ'. אִם תֹּאמַר, בִּשְׁבִיל אוֹתָם הַלּוֹקְטִים כָּל אוֹתָם הָאֲחֵרִים, אֵיךְ אָמַר שֶׁתֵּלֵךְ אַחֲרֵיהֶם? לֹא הָיָה צָרִיךְ לִכְתֹּב אֶלָּא וְלָקַטְתְּ אַחֲרֵיהֶן. מַה זֶּה וְהָלַכְתְּ אַחֲרֵיהֶן? אֶלָּא בִּשְׁבִיל עֵינֶיהָ הוּא אָמַר, עֵינֶיהָ שֶׁהָיוּ גוֹרְמוֹת (ברכות רבות, ועל כן) בְּרָכוֹת לְלוֹקְטִים רַבִּים, וְעַל כֵּן וְהָלַכְתְּ אַחֲרֵיהֶן, אַחַר עֵינַיִךְ. כָּל שְׁאָר בְּנֵי הָעוֹלָם אֵין לָהֶם רְשׁוּת לָלֶכֶת אַחַר עֵינֵיהֶם, וְאַתְּ אַחַר עֵינַיִךְ, שֶׁעֵינַיִךְ גּוֹרְמוֹת לִבְרָכוֹת רַבּוֹת.</p>\n<p>דָּבָר אַחֵר בַּשָּׂדֶה אֲשֶׁר יִקְצֹרוּן - בּעַז רָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה מְלָכִים עֶלְיוֹנִים שַׁלִּיטִים, שֶׁהֵם הָעֵינַיִם שֶׁל הַכֹּל, כְּמוֹ שֶׁהָיְתָה תָּמָר, שֶׁכָּתוּב בָּהּ (בראשית לח) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. הִתְיַשְּׁבָה בַּפֶּתַח שֶׁיּוֹצֵא מִמֶּנּוּ מְלָכִים שַׁלִּיטִים עֶלְיוֹנִים שֶׁנִּקְרָאִים עֵינַיִם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר טו) אִם מֵעֵינֵי הָעֵדָה. כְּמוֹ שֶׁכָּל אֶבְרֵי הַגּוּף לֹא הוֹלְכִים אֶלָּא אַחַר הָעֵינַיִם, וְהָעֵינַיִם מַנְהִיגוֹת אֶת כָּל הַגּוּף - אַף כָּךְ מְלָכִים וְסַנְהֶדְרִין וְכָל אוֹתָם שַׁלִּיטִים, הַכֹּל הוֹלְכִים אַחֲרֵיהֶם (שהולכים האיברים אחר העינים), וּמִשּׁוּם כָּךְ אָמַר לָהּ עֵינַיִךְ. אֵלּוּ הַמְּלָכִים וְהַשַּׁלִּיטִים שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה.</p>\n<p>בַּשָּׂדֶה, אֵיזֶה שָׂדֶה? זֶה צִיּוֹן וִירוּשָׁלַיִם, שֶׁכָּתוּב (מיכה ג) צִיּוֹן שָׂדֶה תֵחָרֵשׁ. וְכָתוּב (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', זוֹ יְרוּשָׁלַיִם. וְעַל כֵּן כָּתוּב עֵינַיִךְ בַּשָּׂדֶה, שֶׁהֵם הָעֵינַיִם שֶׁלָּהּ, שֶׁעֲתִידִים לָצֵאת מִמֶּנָּה, לֹא יִהְיוּ שַׁלִּיטִים אֶלָּא בַּשָּׂדֶה. אֲשֶׁר יִקְצֹרוּן, שֶׁהֲרֵי מֵאוֹתוֹ שָׂדֶה הָיוּ לוֹקְחִים כָּל בְּנֵי הָעוֹלָם תּוֹרָה וְאוֹר שֶׁמֵּאִיר, שֶׁכָּתוּב (ישעיה ב) כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה.</p>\n<p>וְהָלַכְתְּ אַחֲרֵיהֶן, בַּמַּעֲשִׂים הַכְּשֵׁרִים הַלָּלוּ שֶׁאֲנִי רָאִיתִי בָךְ. הֲלוֹא צִוִּיתִי אֶת הַנְּעָרִים וְגוֹ', כְּמַשְׁמָעוֹ שֶׁלּוֹ, מִשּׁוּם שֶׁאִשָּׁה דַּעְתָּהּ קַלָּה. וְצָמִת, לְשׁוֹן נְקִיּוּת נָקַט. וְצָמִת, שֶׁאִם תְּשׁוּקָתֵךְ לִדְבּק בְּאָדָם לְקַיֵּם זֶרַע בָּעוֹלָם - וְהָלַכְתְּ אֶל הַכֵּלִים, אֵלֶּה הֵם הַצַּדִּיקִים שֶׁנִּקְרָאִים כְּלֵי ה', שֶׁכָּתוּב (שם נב) הִבָּרוּ נֹשְׂאֵי כְּלֵי ה'. שֶׁעֲתִידִים הַצַּדִּיקִים לְהָבִיא לָהֶם אֶת כָּל הָעוֹלָם דּוֹרוֹן לְמֶלֶךְ הַמָּשִׁיחַ. וְאוֹתָם כְּלֵי ה', כֵּלִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נֶהֱנֶה בָהֶם, אֵלֶּה הֵם כֵּלִים שְׁבוּרִים, שְׁבוּרִים הֵם בָּעוֹלָם הַזֶּה כְּדֵי לְקַיֵּם אֶת הַתּוֹרָה. וְהַשִּׁמּוּשׁ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּמֵּשׁ בָּהֶם לֹא מִשְׁתַּמֵּשׁ אֶלָּא מִתּוֹךְ הַכֵּלִים הַלָּלוּ. וּכְשֶׁתִּתְדַּבֵּק בָּהֶם, וְשָׁתִית וְגוֹ'.</p>"],[9522011857,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (רות ג) וַיֹּאכַל בּעַז וַיֵּשְׁתְּ וַיִּיטַב לִבּוֹ. מַה זֶּה וַיִּיטַב לִבּוֹ? שֶׁבֵּרַךְ עַל מְזוֹנוֹ, וּפֵרְשׁוּהָ. וְזֶהוּ סוֹד, שֶׁמִּי שֶׁמְּבָרֵךְ עַל מְזוֹנוֹ זֶה מֵיטִיב לְלִבּוֹ, וּמִי מוֹלִיךְ? (ומי הוא, ') כְּמוֹ שֶׁכָּתוּב (תהלים כז) לְךְ אָמַר לִבִּי. וְכָתוּב (שם עג) צוּר לְבָבִי וְגוֹ'.</p>\n<p>וּמִשּׁוּם שֶׁבִּרְכַּת הַמָּזוֹן חֲבִיבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא - כָּל מִי שֶׁמְּבָרֵךְ עַל הַשּׂבַע, מֵיטִיב וּמְשַׂמֵּחַ לְמָקוֹם אַחֵר, וְסִימָנְךְ - סְעוּדַת הַשַּׁבָּת, שֶׁמָּקוֹם אַחֵר נֶהֱנֶה מֵאוֹתָהּ בְּרָכָה שֶׁל שּבַע וְשִׂמְחָה. וְכָאן נֶהֱנֶה מֵאוֹתָהּ בְּרָכָה שֶׁל שּׁבַע שֶׁל אוֹתוֹ צַדִּיק בּעַז, וְזֶהוּ וַיִּיטַב לִבּוֹ.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁהַמָּזוֹן הוּא קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אוֹתוֹ מָקוֹם, וְכֵיוָן שֶׁאָדָם אוֹכֵל וְשׁוֹתֶה וּמְבָרֵךְ, אוֹתָהּ בְּרָכָה עוֹלָה, וְנֶהֱנֶה מֵאוֹתָם דְּבָרִים שֶׁל שּׁבַע שֶׁעוֹלִים, וְנִמְצָא שֶׁנֶּהֱנִים מִן הַמָּזוֹן מִמַּטָּה וּמִלְמַעְלָה.</p>\n<p>וְזְהִוּ הַסּוֹד שֶׁבֵּין הַחֲבֵרִים. הַסּוֹד שֶׁבַּחֹל לֹא נֶהֱנֶה אוֹתוֹ מָקוֹם, אֶלָּא מֵאוֹתָם דְּבָרִים שֶׁעוֹלִים מִתּוֹךְ שּׁבַע, וְכָל הַדְּבָרִים מִתְעַטְּרִים וְרוֹוִים וּשְׂבֵעִים בְּשִׂמְחָה, וְאוֹתוֹ מָקוֹם נֶהֱנֶה מֵהֶם. בְּשַׁבָּת הוּא סוֹד אַחֵר בַּמָּזוֹן מַמָּשׁ, וּבְאוֹתָהּ שִׂמְחָה שֶׁל הַמָּזוֹן שֶׁל מִצְוָה שֶׁל שַׁבָּת, וּבַכֹּל נִמְצָא כָּלוּל - מִמַּעְלָה וָמַטָּה. וְסוֹד זֶה - כִּי מִמְּךְ הַכֹּל וּמִיָּדְךְ נָתַנּוּ לָךְ. וַדַּאי מֵהֲנָאָתָהּ הַזּוֹ, וּבְאוֹתָהּ שִׂמְחָה שֶׁל מָזוֹן שֶׁל מִצְוַת הַשַּׁבָּת, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>מִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ שּׁבַע, צָרִיךְ לְכַוֵּן לִבּוֹ וְלָשִׂים רְצוֹנוֹ בְּשִׂמְחָה, וְלֹא יִמָּצֵא עָצוּב, אֶלָּא שֶׁיְּבָרֵךְ בְּשִׂמְחָה בְּסוֹד זֶה וְלָשִׂים רְצוֹנוֹ שֶׁהֲרֵי הוּא נוֹתֵן עַכְשָׁו לְאַחֵר בְּשִׂמְחָה, בְּעַיִן טוֹבָה. וּכְמוֹ שֶׁהוּא מְבָרֵךְ בְּשִׂמְחָה וּבְעַיִן טוֹבָה, כָּךְ נוֹתְנִים לוֹ בְּשִׂמְחָה וּבְעַיִן טוֹבָה. וּמִשּׁוּם כָּךְ לֹא יִמָּצֵא עָצוּב כְּלָל, אֶלָּא בְּשִׂמְחָה וּבְדִבְרֵי תוֹרָה, וְיָשִׂים לִבּוֹ וּרְצוֹנוֹ לָתֵת בְּרָכָה זוֹ בַּסּוֹד שֶׁצָּרִיךְ.</p>\n<p>סוֹד כָּאן, אַרְבַּע מֶרְכָּבוֹת שׁוֹלְטוֹת בְּאַרְבָּעָה צְדָדִים וּמַחֲנוֹת, נִזּוֹנוּ מֵאוֹתָהּ בִּרְכַּת הַשּׂבַע, וּבְאוֹתָם דְּבָרִים שֶׁל בָּרוּךְ אַתָּה, נֶהֱנֶה וּמִתְרַבֶּה וּמִתְעַטֵּר בּוֹ. וּמִי שֶׁמְּבָרֵךְ, צָרִיךְ רָצוֹן בְּשִׂמְחָה וּבְעַיִן טוֹבָה, וְעַל כֵּן כָּתוּב (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ.</p>\n<p>וְכָאן רֵד לְסוֹף הַפָּסוּק, שֶׁכָּתוּב כִּי נָתַן מִלַּחְמוֹ לַדָּל. שֶׁאִם לֹא תֹאמַר כָּךְ - הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ. אֶלָּא טוֹב עַיִן, כְּמוֹ שֶׁבֵּאַרְנוּ, הוּא יְבָרֵךְ וַדַּאי, בְּעַיִן טוֹבָה וּבְשִׂמְחָה. וְאֵינוֹ לְחִנָּם לְבָרֵךְ בְּשִׂמְחָה, שֶׁהֲרֵי מֵאוֹתָהּ בְּרָכָה וּמֵאוֹתָהּ שִׂמְחָה נָתַן מִלַּחְמוֹ לַדַּל, מָקוֹם שֶׁצָּרִיךְ לְהִזּוֹן מִכָּל הַצְּדָדִים. מָקוֹם שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם. מָקוֹם שֶׁנֶּהֱנֶה מִכָּל הַצְּדָדִים וְנִכְלָל מִכָּל הַצְּדָדִים. הַדְּבָרִים הַלָּלוּ לֹא נִמְסְרוּ אֶלָּא לַחֲכָמִים שֶׁיּוֹדְעִים סוֹדוֹת עֶלְיוֹנִים וְדַרְכֵי הַתּוֹרָה.</p>\n<p>בֹּא וּרְאֵה, בֹּעַז הָיָה טוֹב עַיִן, וְעַזּוּת מֵצַח מֵעוֹלָם לֹא הָיְתָה בּוֹ. מַה כָּתוּב? (רות ג) וַיָּבא לִשְׁכַּב בִּקְצֵה הָעֲרֵמָה. סוֹד הַכָּתוּב - (שיר ז) בִּטְנֵךְ עֲרֵמַת חִטִּים. מִכָּאן לָמַדְנוּ, שֶׁכָּל מִי שֶׁמְּבָרֵךְ בִּרְכַּת הַמָּזוֹן כָּרָאוּי בְּשִׂמְחָה וּבִרְצוֹן הַלֵּב, כְּשֶׁמִּסְתַּלֵּק מִן הָעוֹלָם הַזֶּה מְתֻקָּן לוֹ מָקוֹם בְּתוֹךְ סוֹדוֹת עֶלְיוֹנִים בְּהֵיכָלוֹת קְדוֹשִׁים. אַשְׁרֵי הָאִישׁ שֶׁשּׁוֹמֵר אֶת מִצְווֹת אֲדוֹנוֹ וְיוֹדֵעַ אֶת סוֹדָן, שֶׁאֵין לְךְ מִצְוָה וּמִצְוָה בַּתּוֹרָה שֶׁאֵין תְּלוּיִים בָּהּ סוֹדוֹת עֶלְיוֹנִים וְאוֹרוֹת וְזִיוִים עֶלְיוֹנִים, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה שֶׁהֲרֵי אָמְרוּ, שֶׁכָּל אוֹתָם עַזֵּי הַמֵּצַח שֶׁאֵין לָהֶם בּוּשָׁה, אֵין לָהֶם חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. כָּל עַזֵּי הַמֵּצַח שֶׁהָיוּ בְּיִשְׂרָאֵל, כְּשֶׁהָיוּ מִסְתַּכְּלִים בְּאוֹתוֹ הַצִּיץ, הָיוּ מְשַׁבְּרִים אֶת לִבָּם וּמִסְתַּכְּלִים בְּמַעֲשֵׂיהֶם, מִשּׁוּם שֶׁצִּיץ הָיָה עוֹמֵד עַל אוֹת, וְכָל מִי שֶׁמִּסְתַּכֵּל בּוֹ הָיָה מִתְבַּיֵּשׁ בְּמַעֲשָׂיו. וְלָכֵן הַצִּיץ מְכַפֵּר עַל אוֹתָם עַזֵּי פָנִים, עַזֵּי מֵצַח.</p>\n<p>אוֹתִיּוֹת שֶׁל הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁהָיוּ חֲקוּקוֹת עַל הַצִּיץ, הָיוּ מְאִירוֹת וּבוֹלְטוֹת וְנוֹצְצוֹת. כָּל מִי שֶׁהָיָה מִסְתַּכֵּל בְּאוֹתָהּ הִתְנוֹצְצוּת שֶׁל הָאוֹתִיּוֹת, נוֹפְלוֹת פָּנָיו מֵאֵימָה וְהָיָה נִשְׁבָּר לִבּוֹ, וְאָז הַצִּיץ מְכַפֵּר עֲלֵיהֶם. כְּמוֹ זֶה, כֵּיוָן שֶׁהוּא גּוֹרֵם לִשְׁבֹּר לִבּוֹ וּלְהִכָּנַע מִלִּפְנֵי רִבּוֹנוֹ.</p>"],[9522011858,"<p>כְּמוֹ כֵן הַקְּטֹרֶת, כָּל מִי שֶׁהֵרִיחַ בְּאוֹתוֹ עָשָׁן, כְּשֶׁעָלָה אוֹתוֹ עַמּוּד מֵאוֹתוֹ מַעֲלֶה עָשָׁן, הָיָה מְבָרֵר אֶת לִבּוֹ בְּבֵרוּר (באורהבשמחה) לַעֲבֹד אֶת רִבּוֹנוֹ וּמַעֲבִיר מִמֶּנּוּ זֻהֲמַת הַיֵּצֶר הָרָע, וְלֹא הָיָה לוֹ אֶלָּא לֵב אֶחָד כְּנֶגֶד אָבִיו שֶׁבַּשָּׁמַיִם, מִשּׁוּם שֶׁקְּטֹרֶת הִיא שֶׁבֶר לַיֵּצֶר הָרָע וַדַּאי בְּכָל הַצְּדָדִים. כְּמוֹ שֶׁצִּיץ הָיָה עוֹמֵד עַל נֵס - אַף קְטֹרֶת. שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם לִשְׁבֹּר אֶת הַצַּד הָאַחֵר, פְּרָט לַקְּטֹרֶת.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (במדבר יז) קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. מָה הַטַּעַם? כִּי יָצָא הַקֶּצֶף מִלִּפְנֵי ה' הֵחֵל הַנָּגֶף. שֶׁהֲרֵי אֵין שֶׁבֶר לְאוֹתוֹ הַצַּד פְּרָט לַקְּטֹרֶת, שֶׁאֵין לְךְ דָּבָר חָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ קְטֹרֶת, וְעוֹמֶדֶת לְבַטֵּל כְּשָׁפִים וּדְבָרִים רָעִים מֵהַבַּיִת. רֵיחַ וַעֲשַׁן הַקְּטֹרֶת שֶׁעוֹשִׂים בְּנֵי אָדָם, בְּאוֹתוֹ מַעֲשֶׂה הוּא מְבַטֵּל, כָּל שֶׁכֵּן הַקְּטֹרֶת.</p>\n<p>דָּבָר זֶה גְּזֵרָה עוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל וְקוֹרֵא בְּכָל יוֹם אֶת מַעֲשֵׂה (פרשת) הַקְּטֹרֶת, יִנָּצֵל מִכָּל הַדְּבָרִים הָרָעִים וְכִשְׁפֵי הָעוֹלָם, וּמִכָּל הַפְּגָעִים הָרָעִים, וּמֵהִרְהוּר רַע וּמִדִּין רַע וּמִמָּוֶת, וְלֹא יִנָּזֵק כָּל אוֹתוֹ יוֹם, שֶׁלֹּא יָכוֹל הַצַּד הָאַחֵר לִשְׁלֹט עָלָיו, וְצָרִיךְ שֶׁיְּכַוֵּן בּוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אִם בְּנֵי אָדָם הָיוּ יוֹדִים כַּמָּה הוּא עֶלְיוֹן מַעֲשֵׂה הַקְּטֹרֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיוּ נוֹטְלִים כָּל דִּבּוּר וְדִבּוּר מִמֶּנּוּ וְהָיוּ מַעֲלִים אוֹתוֹ עֲטָרָה עַל רָאשֵׁיהֶם כְּמוֹ כֶּתֶר שֶׁל זָהָב. וּמִי שֶׁמִּשְׁתַּדֵּל בּוֹ, צָרִיךְ לְהִסְתַּכֵּל בְּמַעֲשֵׂה הַקְּטֹרֶת, וְאִם יְכַוֵּן בּוֹ בְּכָל יוֹם, יֵשׁ לוֹ חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְיִסְתַּלֵּק הַמָּוֶת מִמֶּנּוּ וּמֵהָעוֹלָם, וְיִנָּצֵל מִכָּל הַדִּינִים שֶׁל הָעוֹלָם הַזֶּה, וּמִצְּדָדִים רָעִים, וּמִדִּין הַגֵּיהִנֹּם וּמִדִּין הַמַּלְכוּת הָאַחֶרֶת.</p>\n<p>בְּאוֹתָהּ קְטֹרֶת, כְּשֶׁהָיָה עוֹלֶה עָשָׁן בָּעַמּוּד, הַכֹּהֵן הָיָה רוֹאֶה הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ פְּרוּשׂוֹת (פורחות) בָּאֲוִיר וְעוֹלוֹת לְמַעְלָה בְּאוֹתוֹ עַמּוּד. אַחַר כָּךְ כַּמָּה מֶרְכָּבוֹת קְדוֹשׁוֹת סוֹבְבוֹת אוֹתוֹ מִכָּל הַצְּדָדִים עַד שֶׁעוֹלֶה בְּאוֹר וְשִׂמְחָה, וּמְשַׂמֵּחַ אֶת מִי שֶׁמְּשַׂמֵּחַ, וְקוֹשֵׁר קְשָׁרִים לְמַעְלָה וּלְמַטָּה כְּדֵי לְיַחֵד הַכֹּל, וַהֲרֵי בֵּאַרְנוּ. וְזֶה מְכַפֵּר עַל יֵצֶר הָרָע וְעַל עֲבוֹדָה זָרָה, שֶׁהוּא הצַּד הָאַחֵר, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011859,"<p>פָּתַח וְאָמַר, (שמות ל) וַיַּעַשׂ מִזְבֵּחַ מִקְטַר קְטֹרֶת וְגוֹ'. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, מִשּׁוּם שֶׁהָיוּ שְׁנֵי מִזְבְּחוֹת - מִזְבַּח הָעוֹלוֹת וּמִזְבַּח קְטֹרֶת הַסַּמִּים, זֶה בַּחוּץ וְזֶה בִּפְנִים, מִזְבַּח הַקְּטֹרֶת הַזֶּה שֶׁהוּא פְּנִימִי, לָמָּה נִקְרָא מִזְבֵּחַ, וַהֲרֵי אֵין זוֹבְחִים בּוֹ זְבָחִים, וּמִזְבֵּחַ עַל כֵּן נִקְרָא?</p>\n<p>אֶלָּא מִשּׁוּם שֶׁמְּבַטֵּל וְכוֹפֵת כַּמָּה צְדָדִים רָעִים, וּמִשּׁוּם שֶׁאוֹתוֹ הַצַּד הָרָע כָּפוּת, לֹא יָכוֹל לִשְׁלֹט וְלֹא לִהְיוֹת קָטֵגוֹר, וְעַל כֵּן נִקְרָא מִזְבֵּחַ. כְּשֶׁאוֹתוֹ הַצַּד הָרָע הָיָה רוֹאֶה (עמוד העשן) עֲשַׁן הַקְּטֹרֶת שֶׁעוֹלֶה - נִכְנָע וּבוֹרֵחַ, וְלֹא יָכוֹל לִקְרַב כְּלָל לַמִּשְׁכָּן. וּמִשּׁוּם זֶה נִטְהָר וְלֹא מִתְעָרֵב בְּאוֹתָהּ שִׂמְחָה שֶׁלְּמַעְלָה, פְּרָט לַקָּדוֹשׁ-בָּרוּךְ- הוּא לְבַדּוֹ, וּמִשּׁוּם שֶׁכָּל כָּךְ חֲבִיבָה, לֹא עוֹמֵד אוֹתוֹ מִזְבֵּחַ אֶלָּא (פנימי) לִפְנִים, שֶׁזֶּהוּ הַמִּזְבֵּחַ שֶׁנִּמְצָאוֹת בּוֹ בְּרָכוֹת, וְעַל כֵּן נִסְתָּר מִן הָעַיִן.</p>\n<p>מַה כָּתוּב בְּאַהֲרֹן? (במדבריז) וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה, שֶׁכָּפַת אֶת מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט כְּלָל וְלֹא לַעֲשׂוֹת דִּין. סִימָן זֶה נִמְסַר בְּיָדֵינוּ, שֶׁבְּכָל מָקוֹם שֶׁאוֹמְרִים בְּכַוָּנָה וּרְצוֹן הַלֵּב אֶת מַעֲשֵׂה הַקְּטֹרֶת, שֶׁאֵין שׁוֹלֵט הַמָּוֶת בְּאוֹתוֹ מָקוֹם וְלֹא יֻזַּק, וְלֹא יְכוֹלִים שְׁאָר הָעַמִּים לִשְׁלֹט עַל אוֹתוֹ הַמָּקוֹם.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, מִזְבֵּחַ מִקְטַר קְטֹרֶת. כֵּיוָן שֶׁכָּתוּב מִזְבֵּחַ, לָמָּה נִקְרָא מִקְטַר קְטֹרֶת? אֶלָא מִשּׁוּם שֶׁנּוֹטְלִים מֵהַמָּקוֹם הַזֶּה לְהַקְטִיר כְּמוֹ שֶׁעָשָׂה אַהֲרֹן. עוֹד, הַמִּזְבֵּחַ צָרִיךְ לְהַקְטִיר לְקַדְּשׁוֹ בְּאוֹתָהּ קְטֹרֶת, וְעַל כֵּן מִקְטַר קְטֹרֶת. עוֹד, מִקְטַר קְטֹרֶת כְּתַרְגּוּמוֹ, לְהַקְטִיר קְטֹרֶת. שֶׁהֲרֵי אָסוּר לְהַקְטִיר בְּמָקוֹם אַחֵר קְטֹרֶת, רַק מִמַּחְתָּה. (ממחתה של יום הכפורים).</p>\n<p>בֹּא וּרְאֵה, זֶה מִי שֶׁדִּין רוֹדֵף אַחֲרָיו, צָרִיךְ אֶת הַקְּטֹרֶת הַזּוֹ וְלָשׁוּב לִפְנֵי רִבּוֹנוֹ, שֶׁהֲרֵי הוּא סִיּוּעַ לְסַלֵּק דִּינִים מִמֶּנּוּ, וּבָזֶה וַדַּאי הֵם מִסְתַּלְּקִים מִמֶּנּוּ, אִם הוּא רָגִיל בְּכָךְ לְהַזְכִּיר פַּעֲמִים בַּיּוֹם - בַּבֹּקֶר וּבָעֶרֶב, שֶׁכָּתוּב קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר, וְכָתוּב בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. וְזֶהוּ קִיּוּמוֹ שֶׁל הָעוֹלָם תָּמִיד, שֶׁכָּתוּב (שמות ל) קְטֹרֶת תָּמִיד לִפְנֵי ה' לְדֹרֹתֵיכֶם. וַדַּאי שֶׁהוּא קִיּוּם הָעוֹלָם לְמַטָּה וְקִיּוּם הָעוֹלָם לְמַעְלָה.</p>\n<p>בְּאוֹתוֹ מָקוֹם שֶׁלֹּא נִזְכָּר בְּכָל יוֹם מַעֲשֵׂה הַקְּטֹרֶת, הַדִּינִים שֶׁלְּמַעְלָה שְׁרוּיִים בּוֹ וּמַגֵּפוֹת רַבּוֹת בּוֹ, וְעַמִּים אֲחֵרִים שׁוֹלְטִים עָלָיו, מִשּׁוּם שֶׁכָּתוּב קְטֹרֶת תָּמִיד לִפְנֵי ה'. תָּמִיד הִיא עוֹמֶדֶת לִפְנֵי ה' יוֹתֵר מִכָּל הָעֲבוֹדוֹת הָאֲחֵרוֹת. חָבִיב הוּא מַעֲשֵׂה הַקְּטֹרֶת, שֶׁהוּא נִכְבָּד וְחָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִכָּל הָעֲבוֹדוֹת וְהָרְצוֹנוֹת (והמעשים) שֶׁל הָעוֹלָם. וְאַף עַל גַּב שֶׁהַתְּפִלָּה מְעֻלָּה מֵהַכֹּל - מַעֲשֵׂה הַקְּטֹרֶת הוּא נִכְבָּד וְחָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא וּרְאֵה מַה בֵּין תְּפִלָּה לְמַעֲשֵׂה הַקְּטֹרֶת. אֶת הַתְּפִלָּה תִּקְּנוּ בִּמְקוֹם קָרְבָּנוֹת שֶׁהָיוּ יִשְׂרָאֵל עוֹשִׂים, וְכָל אוֹתָם קָרְבָּנוֹת שֶׁהָיוּ עוֹשִׂים יִשְׂרָאֵל אֵינָם חֲשׁוּבִים כְּמוֹ הַקְּטֹרֶת. וְעוֹד, מַה בֵּין זֶה לָזֶה? אֶלָּא תְּפִלָּה הִיא תִּקּוּן לְתַקֵּן מַה שֶּׁצָּרִיךְ. קְטֹרֶת עוֹשָׂה יוֹתֵר, מְתַקֶּנֶת וְקוֹשֶׁרֶת קְשָׁרִים וְעוֹשָׂה אוֹר יוֹתֵר מֵהַכֹּל. וּמִי הוּא שֶׁמַּעֲבִיר זֻהֲמָה וּמְטַהֵר אֶת הַמִּשְׁכָּן, וְהַכֹּל מֵאִיר וְנִתְקָן וְנִקְשָׁר כְּאֶחָד.</p>\n<p>וְלָכֵן צְרִיכִים לְהַקְדִּים מַעֲשֵׂה הַקְּטֹרֶת לַתְּפִלָּה בְּכָל יוֹם וָיוֹם, לְהַעֲבִיר הַזֻּהֲמָה מֵהָעוֹלָם, שֶׁהִיא תִּקּוּן שֶׁל הַכֹּל בְּכָל יוֹם וָיוֹם, כְּמוֹ שֶׁאוֹתוֹ קָרְבָּן חָבִיב שֶׁמְּרֻצֶּה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מַה כָּתוּב בְּמֹשֶׁה? (שם) וַיֹּאמֶר ה' אֶל מֹשֶׁה קַח לְךְ סַמִּים נָטָף וְגוֹ'. אַף עַל גַּב שֶׁבֵּאֲרוּהָ, אֲבָל מַה שּׁוֹנֶה בְּמַעֲשֶׂה זֶה יוֹתֵר מִכָּל מַה שֶּׁאָמַר לוֹ? אֶלָּא קַח לְךְ - לַהֲנָאָתְךְ וּלְתוֹעַלְתְּךְ. מִשּׁוּם שֶׁכְּשֶׁאִשָּׁה נִטְהֶרֶת, זוֹ הֲנָאָה לְבַעְלָהּ. וְסוֹד זֶה - קַח לְךְ סַמִּים, לְהַעֲבִיר הַזֻּהֲמָה, לְקַדֵּשׁ אִשָּׁה עִם בַּעְלָהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה.</p>\n<p>כְּמוֹ כֵן קַח לְךְ עֵגֶל בֶּן בָּקָר שֶׁנֶּאֱמַר לְאַהֲרֹן, לְכַפֵּר עַל חֶטְאוֹ עַל אוֹתוֹ עֵגֶל שֶׁהוּא גָּרַם לָהֶם לְיִשְׂרָאֵל. וְעַל זֶה כָּתוּב בְּמֹשֶׁה קַח לְךְ, לַהֲנָאָתְךְ וּלְתוֹעַלְתְּךְ. (לכךבארוה בפסל לך, מאותה פסלת של לוח אבן נתעשר משה. אף כאן לך להנאתך ולטובתך).</p>\n<p>הַקְּטֹרֶת קוֹשֶׁרֶת קְשָׁרִים, מְאִירָה אוֹר וּמַעֲבִירָה זֻהֲמָה, וְד' מִתְחַבֶּרֶת בְּה' (ד' נעשית ה'), ה' מִתְחַבֶּרֶת בְּו', ו' עוֹלָה וּמִתְעַטֶּרֶת בְּה', ה' מְאִירָה בְּי', וְהַכֹּל מַעֲלֶה רָצוֹן לָאֵין סוֹף. וְנִהְיָה הַכֹּל קֶשֶׁר אֶחָד, וְנַעֲשֶׂה קֶשֶׁר אֶחָד בְּסוֹד אֶחָד, שֶׁהוּא קֶשֶׁר עֶלְיוֹן שֶׁל הַכֹּל.</p>\n<p>מִכָּאן וָהָלְאָה, כֵּיוָן שֶׁהַכֹּל נִקְשָׁר בַּקֶּשֶׁר הַזֶּה, אָז הַכֹּל מִתְעַטֵּר בְּסוֹד הָאֵין סוֹף, וְסוֹד הַשֵּׁם הַקָּדוֹשׁ נָאוֹר, וּמִתְעַטֵּר בְּכָל הַצְּדָדִים, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, וּמְאִירִים הַמְּאוֹרוֹת, וּמְזוֹנוֹת וּבְרָכוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת, וְהַכֹּל בְּסוֹד הַקְּטֹרֶת. וְאִם הַזֻּהֲמָה אֵינָהּ עוֹבֶרֶת, הַכֹּל לֹא נַעֲשֶׂה, שֶׁהַכֹּל תָּלוּי בָּזֶה.</p>\n<p>בֹּא וּרְאֵה, הַקְּטֹרֶת הִיא רִאשׁוֹנָה תָּמִיד לִפְנֵי הַכֹּל. וּמִשּׁוּם כָּךְ מַעֲשֵׂה הַקְּטֹרֶת צָרִיךְ לְהַקְדִּים לַתְּפִלָּה, לַשִּׁירוֹת וְתִשְׁבָּחוֹת, מִשּׁוּם שֶׁכָּל זֶה לֹא עוֹלֶה וְלֹא נִתְקָן וְלֹא נִקְשָׁר עַד שֶׁעוֹבֶרֶת הַזֻּהֲמָה. מָה כָּתוּב? (ויקרא טז) וְכִפֶּר עַל הַקֹּדֶשׁ וְגוֹ' - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וּמִפִּשְׁעֵיהֶם לְכָל חַ אתָם. וְעַל כֵּן צְרִיכִים לְכַפֵּר עַל הַקֹּדֶשׁ וּלְהַעֲבִיר הַזֻּהֲמָה וּלְטַהֵר הַקֹּדֶשׁ, וְאַחַר כָּךְ שִׁירוֹת וְתִשְׁבָּחוֹת וּתְפִלּוֹת, הַכֹּל כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי הֵם יוֹדְעִים לְתַקֵּן תִּקּוּן שֶׁלְּמַעְלָה וָמַטָּה, כְּמוֹ שֶׁצְּרִיכִים לְתַקֵּן תִּקּוּן מִמַּטָּה לְמַעְלָה עַד שֶׁהַכֹּל נִקְשָׁר כְּאֶחָד בְּקֶשֶׁר אֶחָד בְּאוֹתוֹ קֶשֶׁר (קשור) עֶלְיוֹן כְּמוֹ שֶׁצְּרִיכִים לְתַקֵּן (תקונים שלמטה צריכים לתקן) בְּתִקּוּן שֶׁל הָאוֹתִיּוֹת הָרְשׁוּמוֹת שֶׁנִּקְרָא בָּהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011860,"<p>רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, הֲרֵי כָּתוּב (בראשית ב) וְאֶל הָאִשָּׁה אָמַר הַרְבָּה אַרְבֶּה עִצְּבוֹנֵךְ וְהֵרֹנֵךְ בְּעֶצֶב תֵּלְדִי בָנִים וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ וְגוֹ'. וְלָמַדְנוּ שֶׁזֶּהוּ סוֹד עֶלְיוֹן. מֵילָא לְמַטָּה, אֲבָל הוּא כְּמוֹ שֶׁלְּמַעְלָה, מַה יֵּשׁ לוֹמַר?</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל חַיָּה אַחַת יֵשׁ בָּעוֹלָם, וְהִיא שׁוֹלֶטֶת בְּשִׁלְטוֹן עַל אֶלֶף מַפְתְּחוֹת בְּכָל יוֹם. וְהִיא נְקֵבָה, וּתְשׁוּקָתָהּ תָּמִיד עַל אֲפִיקֵי מַיִם לִשְׁתּוֹת וּלְהִתְרַוּוֹת מִצִּמְאוֹנָהּ, שֶׁכָּתוּב כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם.</p>\n<p>כָּאן יֵשׁ לְהִתְבּוֹנֵן. בָּרִאשׁוֹנָה כָּתוּב כְּאַיָּל, וְלֹא כָתוּב כְּאַיֶּלֶת, וְאַחַר תַּעֲרֹג, וְלֹא כָתוּב יַעֲרֹג. אֲבָל סוֹד זֶה, זָכָר וּנְקֵבָה שְׁנֵיהֶם כְּאֶחָד שֶׁאֵין לְהַפְרִידָם, וְאֶחָד הוּא, שֶׁלֹּא צָרִיךְ לְהַעֲלוֹת אוֹתָם זֶה מִזֶּה, אֶלָּא שְׁנֵיהֶם כְּאֶחָד. וְהַנְּקֵבָה הַזּוֹ תַּעֲרֹג עַל אֲפִיקֵי מַיִם, וְהִיא מִתְעַבֶּרֶת מִן הַזָּכָר, וְקָשֶׁה עָלֶיהָ, שֶׁהֲרֵי עַל דִּין עוֹמֶדֶת.</p>\n<p>וּכְשֶׁמּוֹלִידָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לָהּ נָחָשׁ אֶחָד עֶלְיוֹן גָּדוֹל, וּבָא וְנוֹשֵׁךְ בְּאוֹתוֹ מָקוֹם וּמוֹלִידָה. וְסוֹד זֶה - הַרְבָּה אַרְבֶּה עִצְּבוֹנֵךְ וְהֵרֹנֵךְ, מִשּׁוּם שֶׁהִיא מִתְחַלְחֶלֶת בְּכָל יוֹם וּבְעֶצֶב עַל מַעֲשֵׂי הָעוֹלָם. בְּעֶצֶב תֵּלְדִי בָנִים. בְּעֶצֶב - זֶה סוֹד הַנָּחָשׁ, שֶׁמַּעֲצִיב פְּנֵיהֶם שֶׁל הָעוֹלָם.</p>\n<p>וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ, כְּמוֹ שֶׁנֶּאֱמַר תַּעֲרֹג עַל אֲפִיקֵי מָיִם. וְהוּא יִמְשָׁל בָּךְ, הֲרֵי בֵּאַרְנוּ הַסּוֹד, שֶׁהוּא שׁוֹלֵט עָלֶיהָ. וְכָל זֶה לָמָּה? מִשּׁוּם שֶׁאָמְרָה הַלְּבָנָה, כְּמוֹ שֶׁשָּׁנִינוּ. וּמִשּׁוּם כָּךְ הִקְטִינָה אוֹרָהּ וְהִקְטִינָה שִׁלְטוֹנָהּ, וְאֵין לָהּ רְשׁוּת מֵעַצְמָהּ, פְּרָט לְכַאֲשֶׁר נוֹתְנִים לָהּ כֹּחַ.</p>\n<p>בְּעָצֶב תֵּלְדִי בָנִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם תֹּאמַר, לָמָּה צָרִיךְ נָחָשׁ לָזֶה? אֶלָּא זֶה פָּתַח דֶּרֶךְ לְהוֹרִיד כָּל (בכל) אוֹתָן נְשָׁמוֹת שֶׁל הָעוֹלָם. שֶׁאִלְמָלֵא לֹא פָּתַח דְּרָכִים לְמַטָּה, לֹא יִשְׁרֶה בְּגוּף הָאָדָם. מַה כָּתוּב? לַפֶּתַח חַטָּאת רֹבֵץ. מַה זֶּה לַפֶּתַח? לְאוֹתוֹ פֶּתַח שֶׁנּוֹעָד לְהוֹלִיד וּלְהוֹצִיא נְשָׁמוֹת לָעוֹלָם, הוּא עוֹמֵד לְאוֹתוֹ פֶּתַח.</p>\n<p>וְכָל אוֹתָן נְשָׁמוֹת שֶׁהִצְטָרְכוּ לָרֶדֶת בְּגוּפִים קְדוֹשִׁים, הוּא אֵינוֹ עוֹמֵד לְאוֹתוֹ פֶּתַח, וְאֵין לוֹ רְשׁוּת בַּנְּשָׁמָה הַהִיא. וְאִם לֹא, הֲרֵי הַנָּחָשׁ נוֹשֵׁךְ, וְנִטְמָא אוֹתוֹ נָהָר (מקום), וְאֵינָהּ נְשָׁמָה שֶׁנִּטְהֳרָה, וְכָאן הוּא סוֹד עֶלְיוֹן. בְּעֶצֶב תֵּלְדִי בָנִים - סוֹד זֶה, זֶה נָחָשׁ, שֶׁהֲרֵי עִמּוֹ מוֹלִידָה נְשָׁמוֹת, מִשּׁוּם שֶׁזֶּה הוּא עַל הַגּוּף, וְזֶה עַל הַנְּשָׁמָה, וּשְׁנֵיהֶם זֶה בָּזֶה. זֶה לוֹקֵחַ נְשָׁמָה, וְזֶה לוֹקֵחַ הַגּוּף.</p>\n<p>וְעָתִיד הַנָּחָשׁ הַזֶּה לְהוֹלִיד כָּל אוֹתָם גּוּפִים טֶרֶם שֶׁיָּבֹא זְמַנּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה סו) בְּטֶרֶם תָּחִיל יָלָדָה. הַזְּמַן שֶׁל הַנָּחָשׁ לְהוֹלִיד הוּא בְּשֶׁבַע שָׁנִים, וְכָאן בְּשֵׁשׁ, מַה שֶּׁאֵינוֹ זְמַנּוֹ. וּבְאוֹתוֹ זְמַן שֶׁיּוֹלִיד אוֹתָם, יָמוּת מֵאוֹתָהּ לֵדָה, שֶׁכָּתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח. וְכָתוּב (שם כו) יִחְיוּ מֵתֶיךְ נְבֵלָתִי יְקוּמוּן.</p>"],[9522011861,"<p>אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתוֹ זְמַן שֶׁיֵּעוֹרוּ הַמֵּתִים שֶׁל הָעוֹלָם וְיִזְדַּמְּנוּ בָּאָרֶץ הַקְּדוֹשָׁה, יָקוּמוּ חֲיָלוֹת חֲיָלוֹת כֻּלָּם עַל אֶרֶץ הַגָּלִיל, מִשּׁוּם שֶׁשָּׁם עָתִיד מֶלֶךְ הַמָּשִׁיחַ לְהִתְגַּלּוֹת, מִשּׁוּם שֶׁהוּא חֶלְקוֹ שֶׁל יוֹסֵף וְשָׁם נִשְׁבְּרוּ (נחרב) בָּרִאשׁוֹנָה. וּמִשָּׁם הִתְחִילוּ לִגְלוֹת מִכָּל מְקוֹמוֹתֵיהֶם וּלְהִתְפַּזֵּר בֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ו) וְלֹא נֶחְלוּ עַל שֶׁבֶר יוֹסֵף.</p>\n<p>וְלָמָּה יָקוּמוּ שָׁם? מִשּׁוּם שֶׁהוּא חֶלְקוֹ שֶׁל אוֹתוֹ שֶׁהוּשַׂם בְּאָרוֹן, שֶׁכָּתוּב (בראשית נ) וַיִּישֶׂם בָּאָרוֹן בְּמִצְרָיִם. וְאַחַר כָּךְ נִקְבַּר בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁכָּתוּב (יהושע כד) וְאֶת עַצְמוֹת יוֹסֵף אֲשֶׁר הֶעֱלוּ בְנֵי יִשְׂרָאֵל מִמִּצְרַיִם קָבְרוּ בִשְׁכֶם. וְזֶהוּ שֶׁעָמַד בְּקִיּוּם הַבְּרִית יוֹתֵר מֵהַכֹּל.</p>\n<p>וּבְאוֹתוֹ זְמַן שֶׁיִּתְעוֹרְרוּ כֻלָּם חֲיָלוֹת חֲיָלוֹת, כֻּלָּם יֵלְכוּ, זֶה לְחֵלֶק אֲבוֹתָם וְזֶה לְחֵלֶק אֲבוֹתָם, שֶׁכָּתוּב (ויקרא כה) וְשַׁבְתֶּם אִישׁ אֶל אֲחֻזָּתוֹ, וְיַכִּירוּ זֶה אֶת זֶה. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישָׁם כָּל אֶחָד וְאֶחָד לְבוּשִׁים רְקוּמִים, וְיָבאוּ כֻלָּם וִישַׁבְּחוּ אֶת רִבּוֹנָם בִּירוּשָׁלַיִם, וְיִתְחַבְּרוּ שָׁם הֲמוֹנִים הֲמוֹנִים, וִירוּשָׁלַיִם תִּמָּשֵׁךְ לְכָל הַצְּדָדִים יוֹתֵר מִמַּה שֶּׁנִּמְשְׁכָה כְּשֶׁהִתְחַבְּרוּ שָׁם מִן הַגָּלוּת.</p>\n<p>כֵּיוָן שֶׁיִּתְחַבְּרוּ וִישַׁבְּחוּ אֶת רִבּוֹנָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂמַח עִמָּהֶם. זֶהוּ שֶׁכָּתוּב (ירמיה לא) וּבָאוּ וְרִנְּנוּ בִמְרוֹם צִיּוֹן, וְאַחַר כָּךְ - וְנָהֲרוּ אֶל טוּב ה' וְגוֹ'. כָּל אֶחָד וְאֶחָד לְחֶלְקוֹ וְחֵלֶק אֲבוֹתָיו. וְנַחֲלַת יִשְׂרָאֵל תִּהְיֶה עַד (הרמה של רומא) עִיר הָרוֹמָאִים, וְשָׁם יִלְמְדוּ תוֹרָה, וַהֲרֵי פֵּרְשׁוּהָ, וְכָתוּב (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011862,"<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל כָּל הַנְּחָלִים - אֵלּוּ סוֹדוֹת הַנְּחָלִים וְהַמַּעְיָנוֹת הַקְּדוֹשִׁים שֶׁמִתְמַלְּאִים וְיוֹצְאִים (מבועים קדושים) לְהָאִיר וּלְמַלֵּא אֶת הַיָּם הַגָּדוֹל. וְכֵיוָן שֶׁהַיָּם הַגָּדוֹל הַזֶּה הִתְמַלֵּא מִצַּד אוֹתָם הַנְּחָלִים, אָז הוּא מוֹצִיא מַיִם וּמַשְׁקֶה אֶת כָּל חַיּוֹת הַבָּר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי.</p>\n<p>מַה כָּתוּב לְמַעְלָה? הַמְשַׁלֵּחַ מַעְיָנִים וְגוֹ'. וְאַחַר כָּךְ - יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם. אֵלֶּה הֵן הַמֶּרְכָּבוֹת שֶׁלְּמַטָּה, שֶׁכַּאֲשֶׁר הַיָּם לוֹקֵחַ אוֹתָם, אֶת כֻּלָּם הוּא לוֹקֵחַ וְשׁוֹאֵב אוֹתָם לְתוֹכוֹ, וְאַחַר כָּךְ מוֹצִיא מַיִם לְצַד אַחֵר, שֶׁהֵן הַמֶּרְכָּבוֹת הַקְּדשׁוֹת שֶׁלְּמַטָּה, וּמַשְׁקֶה אוֹתָם, וְכֻלָּם הִתְמַנּוּ וְנִפְקְדוּ בְשֵׁם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהמ) לְכֻלָּם בְּשֵׁם יִקְרָא. וּמִשּׁוּם כָּךְ, אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת.</p>"],[9522011863,"<p>רַבִּי יוֹסֵי פָּתַח, (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. מָה רַב טוּבְךְ, כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִסְתַּכֵּל וְלָדַעַת בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם יוֹצֵא קוֹל וּמַכְרִיז וְאוֹמֵר: הִשָּׁמְרוּ בְּנֵי הָעוֹלָם, סִגְרוּ דַּלְתוֹת הַחֲטָאִים, הִסְתַּלְּקוּ מֵהָרֶשֶׁת שֶׁתּוֹפֶסֶת טֶרֶם יִתָּפְסוּ רַגְלֵיהֶם בָּרֶשֶׁת הַזּוֹ. הַגַּלְגַּל סוֹבֵב תָּמִיד, עוֹלֶה וְיוֹרֵד. אוֹי לְאוֹתָם שֶׁדּוֹחִים רַגְלֵיהֶם מִתּוֹךְ הַגַּלְגַּל, שֶׁהֲרֵי נוֹפְלִים לְתוֹךְ הָעֹמֶק שֶׁטָּמוּן לְאוֹתָם רִשְׁעֵי הָעוֹלָם.</p>\n<p>אוֹי לְאוֹתָם שֶׁנּוֹפְלִים וְלֹא יָקוּמוּ, וְלֹא יֵאוֹרוּ בָּאוֹר הַגָּנוּז לַצַּדִּיקִים לָעוֹלָם הַבָּא. אַשְׁרֵיהֶם הַצַּדִּיקִים לָעוֹלָם הַבָּא, שֶׁכַּמָּה מְאוֹרוֹת גְּנוּזִים לָהֶם, כַּמָּה עִדּוּנִים בְּאוֹתוֹ הָעוֹלָם טְמוּנִים לָהֶם, שֶׁכָּתוּב מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ. מָה רַב טוּבְךְ, הֲרֵי פֵּרְשׁוּהָ שֶׁזֶּהוּ אוֹר הַגָּנוּז לַצַּדִּיקִים לָעוֹלָם הַבָּא, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, וְכָתוּב (תהליםצז) אוֹר זָרֻעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה. וְעַל זֶה מָה רַב טוּבְךְ.</p>\n<p>כָּתוּב כָּאן מָה רַב טוּבְךְ, וְכָתוּב שָׁם וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. אֲשֶׁר צָפַנְתָּ, מִשּׁוּם שֶׁהִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הָאוֹר וְהִסְתַּכֵּל בְּאוֹתָם הָרְשָׁעִים שֶׁעֲתִידִים לַחֲטֹא בָּעוֹלָם, וְגָנַז אֶת אוֹתוֹ הָאוֹר לְזַכּוֹת בּוֹ אֶת הַצַּדִּיקִים לָעוֹלָם הַבָּא, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>פָּעַלְתָּ, בָּרִאשׁוֹנָה צָפַנְתָּ, וְאַחַר כָּךְ פָּעַלְתָּ. אֶלָּא צָפַנְתָּ, כְּמוֹ שֶׁנֶּאֱמַר. פָּעַלְתָּ, בִּשְׁבִיל אוֹתוֹ הָאוֹר הַגָּנוּז בּוֹ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אֻמָּנוּת הָעוֹלָם. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, כָּתוּב בְּאַבְרָהָם, וְאוֹתוֹ אוֹר שֶׁל אַבְרָהָם גָּנַז אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבוֹ עָשָׂה אֻמָּנוּת הָעוֹלָם, שֶׁכָּתוּב פָּעַלְתָּ לַחוֹסִים בָּךְ, לְאוֹתָם שֶׁיּוֹשְׁבִים תַּחַת צִלּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>נֶגֶד בְּנֵי אָדָם, שֶׁהֲרֵי בָּאֻמָּנוּת הַזּוֹ שֶׁנֶּעֶשְׂתָה בָּאוֹר הַזֶּה עוֹמְדִים בְּנֵי אָדָם בָּעוֹלָם וְקִיּוּמָם נִהְיָה. אַף עַל פִּי שֶׁהוּא גָּנוּז, בְּנֵי הָאָדָם עוֹמְדִים בּוֹ בָּעוֹלָם הַזֶּה. פָּעַלְתָּ, אֶת אֻמָּנוּת הָעוֹלָם הַזֶּה שֶׁבּוֹ נַעֲשָׂה הַכֹּל בְּחֶשְׁבּוֹן. אֻמָּנוּת הָעוֹלָם כְּמוֹ אֻמָּנוּת הַמִּשְׁכָּן, שֶׁהוּא אֻמָּנוּת כְּמוֹ שֶׁל הָעוֹלָם, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>כָּתוּב כָּאן אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן, וְכָתוּב שָׁם אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. מִשּׁוּם שֶׁכָּל אוֹתָן תּוֹלָדוֹת שֶׁעָשׂוּ וְהוֹצִיאוּ שָׁמַיִם וָאָרֶץ, כֻּלָּן בְּכֹחַ שֶׁל אוֹתוֹ הָאוֹר הַגָּנוּז נַעֲשׂוּ וְיָצְאוּ. פְּקוּדֵי הַמִּשְׁכָּן יָצְאוּ בְּאוֹתוֹ הַכֹּחַ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר לְמַטֵּה יְהוּדָה - זֶהוּ מִצַּד הַיָּמִין. וְאִתּוֹ אָהֳלִיהָב - זֶהוּ מִצַּד הַשְּׂמֹאל. וְהַמִּשְׁכָּן מִצַּד יָמִין וּשְׂמֹאל הוּקַם וְנַעֲשָׂה, וּמֹשֶׁה שֶׁהָיָה בֵינֵיהֶם הֵקִים אוֹתוֹ.</p>"],[9522011864,"<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (ישעיה טז) וְהוּכַן בַּחֶסֶד כִּסֵּא וְיָשַׁב עָלָיו בֶּאֱמֶת וְגוֹ'. וְהוּכַן בַּחֶסֶד כִּסֵּא, הֲרֵי בֵּאַרְנוּ, כְּשֶׁעָלְתָה מַחֲשָׁבָה בְּרָצוֹן שֶׁל שִׂמְחָה מִטְּמִיר כָּל הַטְּמִירִים שֶׁלֹּא נוֹדָע וְלֹא נִדְבָּק, הִגִּיעָה אוֹתָהּ שִׂמְחָה וְהִכְּתָה לְתוֹךְ הַמַּחֲשָׁבָה, וְאָז נִכְנַס לַמָּקוֹם שֶׁנִּכְנַס.</p>\n<p>עַד שֶׁנִּגְנַז בְּהֵיכָל עֶלְיוֹן אֶחָד, שֶׁהוּא טָמִיר לְמַעְלָה. וּמִשָּׁם שָׁפְעוּ וְנִמְשְׁכוּ כָּל הָאוֹרוֹת. שֶׁל יָמִין נָסַע בָּרִאשׁוֹנָה, וְאַחַר כָּךְ כֻּלָּם נָסְעוּ, וּמֵאוֹתוֹ צַד הַיָּמִין נִתְקַן הַכִּסֵּא לְמַטָּה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְקִין אוֹתוֹ הַכִּסֵּא בְּחֶסֶד וְיָשַׁב עָלָיו בֶּאֱמֶת, שֶׁהוּא הַתִּקּוּן שֶׁל הַחוֹתָם שֶׁל הַכֹּל. וְלֹא יוֹשֵׁב עַל אוֹתוֹ כִּסֵּא אֶלָּא בְּחוֹתָם שֶׁהוּא אֱמֶת. בְּאֹהֶל דָּוִד, שֶׁבּוֹ הוּא הַכִּסֵּא לְמַטָּה.</p>\n<p>שֹׁפֵט וְדֹרֵשׁ מִשְׁפָּט וּמְהִר צֶדֶק. שֹׁפֵט - מִצַּד הַדִּין. וְדֹרֵשׁ מִשְׁפָּט - מִצַּד הָרַחֲמִים. וּמְהִר צֶדֶק - הוּא כִּסֵּא הַדִּין שֶׁהוּא הַבֵּית דִּין לְמַטָּה. בֹּא וּרְאֵה, כְּמוֹ כֵן הַמִּשְׁכָּן לֹא הֻתְקַן אֶלָּא בַּצַּד הַזֶּה כְּמוֹ זֶה שֶׁל חֶסֶד, כְּפִי שֶׁאָמַרְנוּ לְמַעְלָה. וְעַל כֵּן נִמְנוּ הַתּוֹלָדוֹת וְהִתְתַּקְּנוּ כֻלָּם לְמַטָּה.</p>"],[9522011865,"<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה. רַבִּי שִׁמְעוֹן פָּתַח, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ וְנֶאֱמַר בְּכַמָּה צְדָדִים, אֲבָל כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא אוֹתוֹ כְּמוֹ שֶׁלְּמַעְלָה לִהְיוֹת הָעוֹלָם הַזֶּה בַּדְּיוֹקָן שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה, וְכָל אוֹתָם גְּוָנִים שֶׁל מַעְלָה הִתְקִינָם לְמַטָּה, לְהַדְבִּיק וְלִקְשֹׁר עוֹלָם בְּעוֹלָם.</p>\n<p>וּכְשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הִשְׁגִּיחַ בַּתּוֹרָה וּבָרָא אוֹתוֹ. וְהִסְתַּכֵּל בַּשֵּׁם הַקָּדוֹשׁ, הַכְּלָל שֶׁל הַתּוֹרָה, וְקִיֵּם אֶת הָעוֹלָם. בִּשְׁלֹשָׁה צְדָדִים הִתְקַיֵּם הָעוֹלָם, וְהֵם חָכְמָה וּתְבוּנָה וָדַעַת. בְּחָכְמָה - שֶׁכָּתוּב (משלי ג) ה' בְּחָכְמָה יָסַד אָרֶץ. בִּתְבוּנָה - שֶׁכָּתוּב כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בְּדַעַת - שֶׁכָּתוּב בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ. הֲרֵי כֻּלָּם בְּקִיּוּם הָעוֹלָם. וּבִשְׁלֹשֶׁת אֵלֶּה נִבְנָה הַמִּשְׁכָּן, שֶׁכָּתוּב (שמות לא) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת.</p>\n<p>וְכָל הַשְּׁלֹשָׁה רְמוּזִים בַּפָּסוּק הַזֶּה. בְּרֵאשִׁית, הַיְנוּ שֶׁכָּתוּב בְּחָכְמָה. בָּרָא אֱלֹהִים, הַיְנוּ שֶׁכָּתוּב בִּתְבוּנָה. אֵת הַשָּׁמַיִם, הַיְנוּ שֶׁכָּתוּב בְּדַעַת. וְכֻלָּם כְּתוּבִים בְּמַעֲשֵׂה הַמִּשְׁכָּן. וּבְסוֹד זֶה כָּתוּב, אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן - זֶה סוֹד הַחָכְמָה. מִשְׁכַּן הָעֵדֻת - זֶה סוֹד הַתְּבוּנָה. אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה - זֶה סוֹד הַדַּעַת. וְהַכֹּל זֶה כְּנֶגֶד זֶה, מִשּׁוּם שֶׁכָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם הַזֶּה - בָּרָא אוֹתוֹ כְּמוֹ שֶׁלְּמַעְלָה, וְהַכֹּל נִרְשַׁם בַּעֲבוֹדַת הַמִּשְׁכָּן.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה עֲשֵׂה מִשְׁכָּן, הָיָה מֹשֶׁה עוֹמֵד תּוֹהֶה, שֶׁלֹּא יָדַע מַה לַּעֲשׂוֹת, עַד שֶׁהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעַיִן, כְּמוֹ שֶׁכָּתוּב (שמות כה) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר. מַה זֶּה בְּתַבְנִיתָם? אֶלָּא לָמַדְנוּ שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה דְּיוֹקַן כָּל דָּבָר וְדָבָר כְּמוֹ אוֹתוֹ דְּיוֹקָן שֶׁהוּא לְמַעְלָה, וְכָל אֶחָד וְאֶחָד הָיָה עוֹשֶׂה דְיוֹקָן שֶׁלּוֹ כַּדְּיוֹקָן (שהואלמעלה, וכל אחד עושה דיוקן שלו כדיוקן) שֶׁהוּא נַעֲשָׂה בָּאָרֶץ.</p>\n<p>אֲשֶׁר אַתָּה מָרְאֶה בָּהָר, אֲשֶׁר אַתָּה רוֹאֶה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לָמַדְנוּ שֶׁאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה הָיָה מַרְאֶה לוֹ בְּתוֹךְ כָּל אוֹתָם הַגְּוָנִים וְהַדְּיוֹקְנָאוֹת שֶׁנַּעֲשׂוּ לְמַטָּה, כַּמַּרְאֶה הַזֶּה שֶׁהֶרְאָה בְתוֹכוֹ כָּל אוֹתָם דְּיוֹקְנָאוֹת.</p>\n<p>מִמַּשְׁמָע שֶׁכָּתוּב אֲשֶׁר אַתָּה מָרְאֶה, אַתָּה - סוֹד הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה שֶׁהֶרְאָה לוֹ בְּתוֹךְ כָּל אוֹתָם הַדְּיוֹקְנָאוֹת. וְהָיָה מֹשֶׁה רוֹאֶה אוֹתָם כָּל דָּבָר וְדָבָר עַל תִּקּוּנוֹ כְּמוֹ שֶׁרוֹאֶה בְּתוֹךְ עֲשָׁשִׁית וְתוֹךְ מַרְאָה שֶׁמַּרְאָה אֶת כָּל הַדְּיוֹקְנָאוֹת. וּכְשֶׁהִסְתַּכֵּל בָּהֶם מֹשֶׁה, הִתְקַשָּׁה לְפָנָיו. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה בְּסִימָנְךְ וַאֲנִי בְּסִימָנִי. אָז הִתְיַשֵּׁב מֹשֶׁה בְּכָל מַעֲשֶׂה.</p>\n<p>כְּשֶׁנַּעָשָׂה כָּל הַמַּעֲשֶׂה, הִצְטָרֵךְ מֹשֶׁה לִמְנוֹת הַכֹּל, כְּדֵי שֶׁלֹּא יֹאמְרוּ יִשְׂרָאֵל שֶׁנִּשְׁאָר כֶּסֶף וְזָהָב וְעָלָה לָקַחַת אוֹתָם. וְלָכֵן הִצְטָרֵךְ לִמְנוֹת אֶת הַחֶשְׁבּוֹן לִפְנֵי יִשְׂרָאֵל, מִשּׁוּם שֶׁכָּתוּב (במדבר לב) וִהְיִיתֶם נְקִיִּם מֵה' וּמִיִּשְׂרָאֵל.</p>\n<p>וְלָכֵן כָּתוּב, אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת, שֶׁהֲרֵי רוּחַ הַקֹּדֶשׁ הָיְתָה מַרְאָה לְכֻלָּם אֶת חֶשְׁבּוֹן כָּל הַזָּהָב וְהַכֶּסֶף שֶׁנָּדְבוּ יִשְׂרָאֵל, וְרוּחַ הַקֹּדֶשׁ הָיְתָה אוֹמֶרֶת: וְכֶסֶף פְּקוּדֵי הָעֵדָה מְאַת כִּכָּר וְגוֹ', כָּל הַזָּהָב הֶעָשׂוּי לַמְּלָאכָה וְגוֹ'. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם בְּאוֹתָם הָאֻמָּנִים, וְרָצָה לְהוֹצִיא אֶת נֶאֱמָנוּתָם לִפְנֵי כֻלָּם.</p>\n<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן. בּא וּרְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁנַּעֲשָׂה מַעֲשֵׂה הַמִּשְׁכָּן, הָיָה הַצַּד הָאַחֵר הוֹלֵךְ וּמְשׁוֹטֵט כְּדֵי לְהַסְטִין, וְלֹא מָצָא עִלָּה עַל נֶאֱמָנוּת הָאֻמָּנִים, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא כּוֹפֵף אוֹתוֹ לִפְנֵי מֹשֶׁה, וְהוּא עָשָׂה חֶשְׁבּוֹן שֶׁל נֶאֱמָנוּת בְּעַל כָּרְחוֹ, וְעָלְתָה נֶאֱמָנוּתָם לַכֹּל. וְסוֹד זֶה שֶׁכָּתוּב אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן. וַהֲרֵי בֵּאַרְנוּ, אֵלֶּה - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מט) גַּם אֵלֶּה תִשְׁכַּחְנָה. וְכָתוּב אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה, שֶׁשָּׁם הִתְמַנָּה וְנִפְקַד עַד שֶׁנַּעֲשָׂה הַחֶשְׁבּוֹן שֶׁל בֵּית הַמִּשְׁכָּן לִפְנֵי מֹשֶׁה וְכָל יִשְׂרָאֵל.</p>\n<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת. אֵיזוֹ עֵדוּת? אֶלָּא פְּעָמִים כָּתוּב כָּאן מִשְׁכָּן, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, וְהַמִּשְׁכָּן נִקְרָא מִשְׁכַּן הָעֵדוּת. וְאֵיזוֹ עֵדוּת? כְּמוֹ שֶׁנֶּאֱמַר שִׁבְטֵי יָ\"הּ עֵדוּת לְיִשְׂרָאֵל. שֵׁם זֶה הוּא עֵדוּת לְיִשְׂרָאֵל.</p>\n<p>כְּמוֹ כֵן (תהלים פא) עֵדוּת בִּיהוֹסֵף שָׂמוֹ. עֵדוּת שֵׁם יָהּ בִּיהוֹסֵף, הִיא עֵדוּת וַדַּאי. שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ מְעִידוֹת עֵדוּת בְּכָל מָקוֹם, וְכָאן הוּא עֵדוּת. וּמִשּׁוּם כָּךְ מִשְׁכַּן הָעֵדֻת, הַמִּשְׁכָּן שֶׁל הָעֵדוּת הַזּוֹ, וְלָכֵן נִקְרָא מִשְׁכָּן, עַל סוֹד הַשֵּׁם הַקָּדוֹשׁ הַזֶּה. וְהַיְנוּ שֶׁכָּתוּב (שםקלב) וְעֵדתִי זוֹ אֲלַמְּדֵם. מִשּׁוּם שֶׁמָּקוֹם זֶה הוּא סֵתֶר וּגְנִיזַת הַכֹּל.</p>\n<p>אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה - עַד כָּאן לֹא יָדָעְנוּ אִם הַמִּשְׁכָּן פֻּקַּד אוֹ הָעֵדוּת הַזּוֹ. אֶלָּא פֻּקַּד וַדַּאי זוֹ עֵדוּת. מִשּׁוּם שֶׁמִּיּוֹם שֶׁהִסְתַּלְּקוּ הָאָבוֹת מֵהָעוֹלָם וְכָל אוֹתָם שְׁבָטִים בְּנֵי יַעֲקֹב, וְנִשְׁאֲרוּ יִשְׂרָאֵל בַּגָּלוּת בְּאוֹתָן צָרוֹת, נִשְׁכְּחָה מֵהֶם יְדִיעַת סוֹד הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן הַזֶּה, שֶׁהוּא שֵׁם הָעֵדוּת, קִיּוּמָם שֶׁל שָׁמַיִם וָאָרֶץ, שֶׁשְּׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ בֵּאֲרוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁבָּא מֹשֶׁה, נִפְקַד וְנִזְכַּר הַשֵּׁם הַזֶּה בָּעוֹלָם. שֶׁכְּשֶׁהָיָה בַּסְּנֶה, מִיָּד שָׁאַל עַל הַשֵּׁם הַזֶּה, שֶׁכָּתוּב וְאָמְרוּ לִי מַה שְּׁמוֹ מָה אֹמַר אֲלֵהֶם. וְשָׁם נִפְקַד הַשֵּׁם הַזֶּה עַל פִּי מֹשֶׁה.</p>\n<p>עָבֹדַת הַלְוִיִּם. מַה זֶּה עֲבֹדַת הַלְוִיִּם? אֶלָּא סוֹד זֶה, שֶׁכָּתוּב (במדבר יח) וְעָבַד הַלֵּוִי הוּא. הוּא - זֶה סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא הוּא, וְלֹא נִקְרָא אַתָּה. וּמִשּׁוּם כָּךְ עֲבוֹדַת הַלְוִיִּם וַדַּאי. דָּבָר אַחֵר עֲבֹדַת הַלְוִיִּם - שֶׁהֵם נוֹטְלִים אֶת הַמִּשְׁכָּן עַל כִּתְפֵיהֶם מִמָּקוֹם לְמָקוֹם, שֶׁכָּתוּב (במדבר ז) וְלִבְנֵי קְהָת לֹא נָתָן כִּי עֲבֹדַת הַקֹּדֶשׁ עֲלֵהֶם בַּכָּתֵף יִשָּׂאוּ.</p>\n<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת וְגוֹ'. רַבִּי אַבָּא פָּתַח, (ישעיהיא) וְהָיָה בַּיּוֹם הַהוּא שֹׁרֶשׁ יִשַׁי וְגוֹ'. וְהָיָה בַּיּוֹם הַהוּא, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַרְבֶּה שָׁלוֹם בָּעוֹלָם, יִתְקַיֵּם הַשֹּׁרֶשׁ שֶׁל עֵץ הַחַיִּים. וְאוֹתוֹ שֹׁרֶשׁ, מִמֶּנּוּ יִתְקַיְּמוּ שְׁאָר הַשָּׁרָשִׁים לְמַטָּה, שֶׁכֻּלָּם נִשְׁרְשׁוּ וְהִתְקַיְּמוּ מִמֶּנּוּ.</p>\n<p>אֲשֶׁר עֹמֵד לְנֵס עַמִּים, שֶׁהֲרֵי הוּא עוֹמֵד לְנֵס וּלְאוֹת לְסוֹד הַשֵּׁם הַקָּדוֹשׁ. אֵלָיו גּוֹיִם יִדְר!שׁוּ, שֶׁשָּׁם סוֹד הַקִּיּוּם שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וּמִשּׁוּם כָּךְ אֵלָיו גּוֹיִם יִדְר!שׁוּ, כְּמוֹ שֶׁנֶּאֱמַר (שם ב) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' וְגוֹ', וְעַל זֶה - אֵלָיו גּוֹיִם יִדְר!שׁוּ. וְהָיְתָה מְנֻחָתוֹ כָּבוֹד, מְנֻחָתוֹ - זֶה בֵּית הַמִּקְדָּשׁ, שֶׁכָּתוּב (תהלים קלב) זֹאת מְנוּחָתִי עֲדֵי עַד. כָּבוֹד - שֶׁכָּךְ נִקְרָא שֵׁם ה' בְּאוֹתוֹ זְמַן, שֶׁכָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם.</p>\n<p>וּמְנוּחָתוֹ שֶׁל אוֹתוֹ שֹׁרֶשׁ יִשַׁי, שֶׁנִּקְרָא כְּבוֹד ה', לֹא יִמָּנֶה וְלֹא יַעֲמֹד בְּחֶשְׁבּוֹן לְעוֹלָם. מָה הַטַּעַם? (משום שהרי עומד בחשבון עתה, ובאותו זמן לא יעמד בחשבון. מה הטעם, ') מִשּׁוּם שֶׁכָּל מַה שֶּׁעוֹמֵד בְּחֶשְׁבּוֹן, לֹא שׁוֹרוֹת שָׁם בְּרָכוֹת בִּשְׁלֵמוּת. וְהַבְּרָכוֹת שׁוֹרוֹת בְּמַה שֶּׁלֹּא עוֹמֵד בְּחֶשְׁבּוֹן. בַּזְּמַן הָרִאשׁוֹן עָמַד בְּחֶשְׁבּוֹן, שֶׁכָּתוּב אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן.</p>\n<p>בֹּא וּרְאֵה, הַמִּשְׁכָּן הַזֶּה עוֹמֵד בְּחֶשְׁבּוֹן, וְלָכֵן הִצְטָרֵךְ לִתְפִלַּת מֹשֶׁה, שֶׁיִּשְׁרוּ עָלָיו בְּרָכוֹת, שֶׁכָּתוּב וַיְבָרֶךְ אֹתָם מֹשֶׁה. וְאֵיזוֹ בְּרָכָה בֵּרַךְ אוֹתָם? יְהִי רָצוֹן שֶׁתִּשְׁרֶה בְּרָכָה עַל מַעֲשֵׂי יְדֵיכֶם. וְהַבְּרָכוֹת לֹא שׁוֹרוֹת עַל הַחֶשְׁבּוֹן הַזֶּה, עַד שֶׁקָּשַׁר אוֹתוֹ מֹשֶׁה בַּמִּשְׁכָּן שֶׁלְּמַעְלָה, שֶׁכָּתוּב אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה. דְּאִם לֹא נַעֲשֶׂה הַחֶשְׁבּוֹן עַל יְדֵי מֹשֶׁה, אֵינָם יְכוֹלִים לַעֲשׂוֹת חֶשְׁבּוֹן, שֶׁכָּתוּב אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה.</p>\n<p>פָּתַח וְאָמַר, (מלכים א יז) וַיְהִי דְבַר ה' אֶל אֵלִיָּהוּ (אליו) לֵאמֹר קוּם לֵךְ צָרְפָתָה וְגוֹ' הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךְ. וְכִי אֵיפֹה צִוָּה אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא טֶרֶם שֶׁתָּבא לָעוֹלָם צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְזֵרָתוֹ לְמַעְלָה עַל הָעוֹרְבִים לְהָבִיא מָזוֹן לְאֵלִיָּהוּ וּלְאוֹתָהּ אִשָּׁה לָתֵת לוֹ מָזוֹן.</p>\n<p>מַה כָּתוּב? וַתֹּאמֶר חַי ה' אֱלֹהֶיךְ אִם יֶשׁ לִי מָעוֹג כִּי אִם מְלֹא כַף קֶמַח בַּכַּד וּמְעַט שֶׁמֶן בַּצַּפָּחַת וְגוֹ'. וַהֲרֵי כָּאן מִדָּה הָיְתָה בְּאוֹתוֹ קֶמַח, שֶׁהֲרֵי הָיָה בּוֹ מְלֹא כַף קֶמַח בַּכַּד. כַּף הִיא הַמִּדָּה שֶׁלּוֹ. וְנִרְאֶה שֶׁאֵין שׁוֹרוֹת בּוֹ בְּרָכוֹת הוֹאִיל וְעוֹמֵד בְּמִדָּה. מַה כָּתוּב? כִּי כֹה אָמַר ה' אֱלֹהֵי יִשְׂרָאֵל כַּד הַקֶּמַח לֹא תִכְלָה וְצַפַּחַת הַשֶּׁמֶן לֹא תֶחְסָר עַד יוֹם תֵּת ה' גֶּשֶׁם.</p>\n<p>תֵּת - כָּתוּב תִּתֵּן, מָה הַטַּעַם? מִשּׁוּם שֶׁבְּכָל דּוֹר לֹא נִמְצָא מִי שֶׁיִּזְכֶּה לִזְכוּת כְּמוֹ הָאִשָּׁה הַזֹּאת, וְעַל זֶה כָּתוּב תִּתֵּן. אַתָּה תִּתֵּן מָטָר עַל הָעוֹלָם מִשּׁוּם שֶׁזְּכוּתְךְ רַבָּה.</p>\n<p>וְכָתוּב כַּד הַקֶּמַח לֹא כָלָתָה וְצַפַּחַת הַשֶּׁמֶן לֹא חָסֵר כִּדְבַר ה' אֲשֶׁר דִּבֶּר בְּיַד אֵלִיָּהוּ. וְכִי אִם אוֹתוֹ קֶמַח שֶׁעוֹמֵד בְּמִדָּה, שֶׁהָיָה מְלֹא כַף קֶמַח, לֹא פָסְקוּ מִמֶּנּוּ בְּרָכוֹת מִשּׁוּם דְּבַר אֵלִיָּהוּ, שֶׁכָּתוּב כַּד הַקֶּמַח לֹא תִכְלָה, וְכָתוּב כַּד הַקֶּמַח לֹא כָלָתָה - מִשְׁכַּן הָעֵדוּת, אַף עַל גַּב שֶׁעוֹמֵד בְּחֶשְׁבּוֹן, הוֹאִיל וְנִפְקַד עַל יְדֵי מֹשֶׁה, כָּל שֶׁכֵּן וְכָל שֶׁכֵּן שֶׁשּׁוֹרִים בּוֹ בְּרָכוֹת. וְעַל זֶה כָּתוּב, אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה.</p>\n<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (שמות ג) אַל תִּקְרַב הֲלֹם שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ, שֶׁהִפְרִידוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִשְׁתּוֹ כְּדֵי לְהִדָּבֵק בַּשְּׁכִינָה, שֶׁכָּתוּב כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. אַדְמַת קֹדֶשׁ - זוֹ שְׁכִינָה. הִדָּבְקוּת קְדוֹשָׁה נִדְבַּק מֹשֶׁה בְּאוֹתָהּ שָׁעָה לְמַעְלָה.</p>\n<p>שֶׁאָז הַקָּדוֹשׁ בָּרוּךְ הוּא קָשַׁר אוֹתוֹ בַּחֲבִיבוּת שֶׁלְּמַעְלָה, וְנִפְקַד לִהְיוֹת מְמֻנֶּה גָּדוֹל עַל הַבַּיִת, וְהוּא גּוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה, שֶׁכָּתוּב (במדבר טז) וּפָצְתָה הָאֲדָמָה אֶת פִּיהָ וְגוֹ', וְכָתוּב וַיְהִי כְּכַלֹּתוֹ לְדַבֵּר וְגוֹ', וַתִּבָּקַע הָאֲדָמָה. וְכָתוּב (שם י) קוּמָה ה'. שׁוּבָה ה'. זֶהוּ שֶׁכָּתוּב אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה. עַל פִּי מֹשֶׁה נִתְקַן וְנִפְקַד בַּכֹּל. הַפְּקִידָה שֶׁל הַמִּשְׁכָּן הָיְתָה עַל יְדֵי מֹשֶׁה, שֶׁכָּתוּב (שמות ג) פָּקֹד פָּקַדְתִּי אֶתְכֶם. שֶׁהוּא הָיָה קוֹל שֶׁהוֹצִיא אֶת אוֹתוֹ דִּבּוּר וְעָשָׂה לוֹ פְּקִידָה לָצֵאת מִן הַגָּלוּת, וְעַכְשָׁו נִפְקָד לְהַמְשִׁיךְ קְדֻשָּׁה מִמַּעְלָה לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שם כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.</p>\n<p>וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר לְמַטֵּה יְהוּדָה וְגוֹ'. אָמַר רַבִּי יְהוּדָה, הֲרֵי נֶאֱמַר שֶׁהֲרֵי בְּצַלְאֵל הָיָה מִצַּד הַיָּמִין, וְהוּא הִתְקִין תִּקּוּן הַכֹּל. וְעוֹד, שֶׁהֲרֵי יְהוּדָה הוּא שַׁלִּיט וּמֶלֶךְ עַל כָּל שְׁאָר הַשְּׁבָטִים וּמִמֶּנּוּ יָצָא מִי שֶׁהִתְקִין אֶת כָּל הַמִּשְׁכָּן. בְּצַלְאֵל, הֱרֵי פֵּרְשׁוּהָ בְּצֵל אֵל. וּמִיהוּ בְּצֵל אֵל? זֶה יָמִין. וְעוֹד, מִצַּד זֶה הִתְקִין הַכֹּל, וְיָרַשׁ חָכְמָה לַעֲשׂוֹת כָּל מַעֲשֶׂה.</p>\n<p>וְאִתּוֹ אָהֳלִיהָב בֶּן אֲחִיסָמָךְ לְמַטֵּה דָן. זֶהוּ מִצַּד הַשְּׂמֹאל, זֶהוּ מִצַּד הַדִּין הַקָּשֶׁה (הקדוש), וַהֲרֵי פֵּרְשׁוּהָ שֶׁהֲרֵי מִשְּׁנֵי צְדָדִים אֵלּוּ נַעֲשָׂה הַמִּשְׁכָּן וְהִתְתַּקֵּן בָּהֶם לְהִתְקַשֵּׁר בָּהֶם לִהְיוֹת בֵּין יָמִין וּשְׂמֹאל, וַהֲרֵי נִתְבָּאֵר וּפֵרְשׁוּהָ.</p>"],[9522011866,"<p>פָּתַח וְאָמַר, (תהלים מח) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, זָרַק אֶבֶן אַחַת נִכְבָּדָה מִתַּחַת כִּסֵּא כְבוֹדוֹ וְשִׁקַּע אוֹתָהּ עַד הַתְּהוֹם, וְרֹאשׁ אֶחָד שֶׁל אוֹתָהּ אֶבֶן נָעוּץ בְּתוֹךְ הַתְּהוֹמוֹת, וְרֹאשׁ אַחֵר לְמַעְלָה, וְאוֹתוֹ הָרֹאשׁ הָאַחֵר הָעֶלְיוֹן הוּא נְקֻדָּה אַחַת (עליונה) שֶׁעוֹמֶדֶת בְּמֶרְכַּז הָעוֹלָם, וּמִשָּׁם הִתְפַּשֵּׁט הָעוֹלָם לְיָמִין וְלִשְׂמֹאל וּלְכָל הַצְּדָדִים, וְהִתְקַיֵּם בְּאוֹתָהּ נְקֻדַּת הַמֶּרְכָּז, וְאוֹתָהּ אֶבֶן נִקְרֵאת אֶבֶן הַשְּׁתִיָּה, שֶׁמִּמֶּנָּה נִשְׁתָּל הָעוֹלָם לְכָל הַצְּדָדִים. עוֹד שְׁתִיָּ\"ה - שָׁת יָ\"הּ. הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם אוֹתָהּ לִהְיוֹת יְסוֹד הָעוֹלָם וְהַשְׁתָּלַת הַכֹּל.</p>\n<p>בִּשְׁלשָה גְוָנִים הִתְפַּשְּׁטָה הָאָרֶץ סְבִיב אוֹתָהּ נְקֻדָּה. הִתְפַּשְּׁטוּת רִאשׁוֹנָה סְבִיב אוֹתָהּ נְקֻדָּה, כָּל צַחוּת וְזַכּוּת הָאָרֶץ שָׁם הֵם עוֹמְדִים, וְשָׁם הֵם. וְזוֹ עוֹמֶדֶת לְמַעְלָה עַל כָּל הָאָרֶץ סְבִיב אוֹתָהּ נְקֻדָּה. הִתְפַּשְּׁטוּת שְׁנִיָּה סְבִיב אוֹתָהּ הִתְפַּשְּׁטוּת רִאשׁוֹנָה, אֵין שָׁם צַחוּת וְזַכּוּת כְּאוֹתָהּ רִאשׁוֹנָה, אֲבָל הוּא דַּק וְצַח בַּצַּחוּת שֶׁל הֶעָפָר יוֹתֵר מִכָּל שְׁאָר עָפָר אַחֵר. הִתְפַּשְּׁטוּת שְׁלִישִׁית הִיא חֹשֶׁךְ וְגַסּוּת הֶעָפָר יוֹתֵר מִכֻּלָּם, וּסְבִיב זֶה עוֹמְדִים מֵי הָאוֹקְיָנוֹס שֶׁסּוֹבֵב כָּל הָעוֹלָם. נִמְצָא שֶׁאוֹתָהּ נְקֻדָּה עוֹמֶדֶת בַּמֶּרְכָּז, וְכָל הַגְּוָנִים שֶׁל הַהִתְפַּשְּׁטוּת שֶׁל הָעוֹלָם סְבִיבָהּ.</p>\n<p>הִתְפַּשְּׁטוּת רִאשׁוֹנָה הוּא בֵּית הַמִּקְדָּשׁ, וְכָל אוֹתָם הֵיכָלוֹת וַעֲזָרוֹת, וְכָל אוֹתוֹ תִּקּוּן שֶׁלּוֹ וִירוּשָׁלַיִם, וְכָל הָעִיר מֵהַחוֹמוֹת וּפְנִימָה. הִתְפַּשְּׁטוּת שְׁנִיָּה - כָּל אֶרֶץ יִשְׂרָאֵל שֶׁהִתְקַדְּשָׁה בִּקְדֻשָּׁה. הִתְפַּשְּׁטוּת שְׁלִישִׁית הוּא כָּל שְׁאָר הָאָרֶץ, מְקוֹם בֵּית מוֹשָׁב שְׁאָר הָעַמִּים, וְיָם הָאוֹקְיָנוֹס שֶׁסּוֹבֵב הַכֹּל.</p>\n<p>וַהֲרֵי פֵּרְשׁוּהָ שֶׁסּוֹד זֶה גּוֹנֵי הָעַיִן שֶׁסּוֹבְבִים אוֹתָהּ נְקֻדָּה שֶׁל מֶרְכַּז הָעַיִן, שֶׁהוּא מַרְאֶה שֶׁל כָּל הָעַיִן, כְּמוֹ שֶׁאוֹתָהּ נְקֻדַּת הַמֶּרְכָּז שֶׁאָמַרְנוּ שֶׁהִיא מַרְאֶה שֶׁל הַכֹּל, וְשָׁם עוֹמֵד בֵּית קֹדֶשׁ הַקְּדָשִׁים וְאָרוֹן וְכַפֹּרֶת שֶׁהֵם הַמַּרְאֶה שֶׁל הַכֹּל. נִמְצָא שֶׁאוֹתָהּ נְקֻדָּה הִיא הַמַּרְאֶה שֶׁל כָּל הָעוֹלָם. וְעַל זֶה כָּתוּב יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן וְגוֹ'. יְפֵה - יָפֶה אוֹתוֹ הַמַּרְאֶה וְשִׂמְחַת הַכֹּל. נוֹף - נוֹף הָאִילָן, שֶׁהוּא הַיֹּפִי שֶׁל הַכֹּל.</p>\n<p>בֹּא וּרְאֵה, הַיֹּפִי שֶׁל הָעוֹלָם וְהַמַּרְאֶה שֶׁל הָעוֹלָם לֹא נִרְאָה בָּעוֹלָם, עַד שֶׁנִּבְנָה וְהוּקַם הַמִּשְׁכָּן וְנִכְנַס הָאָרוֹן לְתוֹךְ הַקֹּדֶשׁ. מֵאוֹתָהּ שָׁעָה נִרְאָה הַמַּרְאֶה שֶׁל הַכָּל בָּעוֹלָם וְהִתְתַּקֵּן הָעוֹלָם, וְהוֹלְכִים בְּאוֹתוֹ מִשְׁכָּן וּבְאוֹתוֹ אָרוֹן, עַד שֶׁמַּגִּיעִים לְאוֹתָהּ נְקֻדָּה שֶׁהִיא יְפֵה נוֹף שִׂמְחַת הַכֹּל. כֵּיוָן שֶׁהִגִּיעוּ לְשָׁם, אָז פָּתַח הָאָרוֹן וְאָמַר, (תהלים קלב) זֹאת מְנוּחָתִי עֲדֵי עַד פֹּה אֵשֵׁב כִּי אִוִּיתִיהָ.</p>\n<p>רַבִּי יֵיסָא אָמַר, הַפָּסוּק הַזֶּה אָמְרָה אוֹתוֹ כְּנֶסֶת יִשְׂרָאֵל בְּשָׁעָה שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ וְנִכְנַס הָאָרוֹן לִמְקוֹמוֹ. רַבִּי חִזְקִיָּה אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אוֹתוֹ עַל כְּנֶסֶת יִשְׂרָאֵל כְּשֶׁיִּשְׂרָאֵל עוֹשִׂים רְצוֹנוֹ, שֶׁהֲרֵי אָז הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא כְבוֹדוֹ וְחָס עַל הָעוֹלָם, וּבְרָכָה וְשָׁלוֹם וַחֲבִיבוּת הַכֹּל נִמְצָאִים. וְאָז אָמַר, זאת מְנוּחָתִי עֲדֵי עַד.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁכָּל הָאֻמָּנִים הִתְחִילוּ לַעֲשׂוֹת הָאֻמָּנוּת, אוֹתוֹ מַעֲשֶׂה מַמָּשׁ שֶׁהִתְחִילוּ הָיָה נִשְׁלָם מֵעַצְמוֹ. הֵם מַתְחִילִים - וְהִיא מַשְׁלִימָה אֶת הַמַּעֲשֶׂה, הִיא מַמָּשׁ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וַתֵּכֶל כָּל עֲבֹדַת מִשְׁכַּן אֹהֶל מוֹעֵד.</p>\n<p>כְּמוֹ זֶה - (בראשית ב) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ. וְאִם תֹּאמַר, וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי - וַדַּאי כָּךְ הוּא! שֶׁכָּל הָעוֹלָם, אַף עַל גַּב שֶׁכָּל הַמַּעֲשִׂים נִשְׁלְמוּ כָּל אֶחָד וְאֶחָד, כָּל הָעוֹלָם לֹא הָיָה שָׁלֵם בְּקִיּוּמוֹ עַד שֶׁבָּא הַיּוֹם הַשְּׁבִיעִי. שֶׁכְּשֶׁבָּא הַיּוֹם הַשְּׁבִיעִי, אָז נִשְׁלְמוּ כָּל הַמַּעֲשִׂים, וְהִשְׁלִים בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. בָּזֶה נִשְׁלַם, בְּקִיּוּם כָּל מַעֲשֶׂה שֶׁעָשָׂה, וְעַל זֶה וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי.</p>\n<p>וּכְשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ, כָּל מַעֲשֶׂה שֶׁנַּעֲשָׂה - נַעֲשָׂה מֵעַצְמוֹ. הָאֻמָּנִים הִתְחִילוֹ - וְהַמַּעֲשֶׂה נִרְאָה לָהֶם לְהֵעָשׂוֹת וְנִרְשַׁם לִפְנֵיהֶם וְהִשְׁתַּלֵּם מֵעַצְמוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (מלכים א ו) וְהַבַּיִת בְּהִבָּנֹתוֹ. לֹא כָתוּב וְהַבַּיִת כַּאֲשֶׁר בָּנוּהוּ, אֶלָּא בְּהִבָּנֹתוֹ, שֶׁהוּא נִשְׁלַם מֵעַצְמוֹ. וְכָתוּב אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה. לֹא כָתוּב בָּנוּהוּ, אֶלָּא נִבְנָה, הוּא מֵעַצְמוֹ נִבְנָה. וְכָל בְּכָל מַעֲשֶׂה שֶׁהוּא קָדוֹשׁ, מִשְׁתַּלֵּם מֵעַצְמוֹ.</p>\n<p>וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר. פָּסוּק זֶה לָמַדְנוּ, שֶׁרוּחַ הַקֹּדֶשׁ הִכְרִיזָה עָלָיו לְעֵינֵי יִשְׂרָאל וְאָמַר: וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּרִי לְמַטֵּה יְהוּדָה עָשָׂה אֵת כָּל אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה. וְאִתּוֹ אָהֳלִיהָב בֶּן אֲחִיסָמָךְ, מַה זֶּה וְאִתּוֹ? אֶלָּא לָמַדְנוּ שֶׁאָהֳלִיהָב לֹא עָשָׂה מַעֲשֶׂה לְבַדּוֹ, אֶלָּא עִם בְּצַלְאֵל, וְעִמּוֹ עָשָׂה כָּל מַה שֶּׁעָשָׂה. זֶהוּ שֶׁכָּתוּב וְאִתּוֹ, וְאִתּוֹ וְלֹא לְבַדּוֹ. מִכָּאן שֶׁהַשְּׂמֹאל בִּכְלַל יָמִין תָּמִיד, וְעַל זֶה כָּתוּב (שמות לא) וַאֲנִי הִנֵּה נָתַתִּי אִתּוֹ אֵת אָהֳלִיהָב. זֶה יָמִין וְזֶה שְׂמֹאל.</p>"],[9522011867,"<p>אֵלֶּה פְקוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדֻת אֲשֶׁר פֻּקַּד עַל פִּי מֹשֶׁה וְגוֹ'. רַבִּי יֵיסָא אָמַר, כֵּיוָן שֶׁעָשׂוּ כָּל הַחֲכָמִים אֶת הַמִּשְׁכָּן, צָרִיךְ לְהַחֲזִיר חֶשְׁבּוֹן מִכָּל אוֹתָם הַמַּעֲשִׂים שֶׁנַּעֲשׂוּ בוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל חֶשְׁבּוֹן וְחֶשְׁבּוֹן, כְּשֶׁהָיָה נַעֲשֶׂה חֶשְׁבּוֹן, כָּךְ הִתְקַיֵּם אוֹתוֹ מַעֲשֶׂה, וְהִתְקַיֵּם בִּמְקוֹמוֹ.</p>\n<p>וְיִשְׂרָאֵל כֻּלָּם, כְּמוֹ שֶׁנִּתְרַצּוּ בְּמַה שֶּׁנָּדְבוּ בָּרִאשׁוֹנָה, גַּם כָּךְ הִתְרַצּוּ בְּאוֹתוֹ חֶשְׁבּוֹן, וְאָז הִתְקַיֵּם כָּל הַמַּעֲשֶׂה בְּאוֹתוֹ רָצוֹן. וְלָכֵן צָרִיךְ כָּאן חֶשְׁבּוֹן, מִשּׁוּם שֶׁבָּזֶה מִתְקַיֵּם הַמַּעֲשֶׂה. אֵלֶּה כָּתוּב, וְלֹא כָתוּב וְאֵלֶּה. אֶלָּא זֶהוּ חֶשְׁבּוֹן שֶׁפּוֹסֵל אֶת כָּל הַחֶשְׁבּוֹנוֹת שֶׁל הָעוֹלָם, וְזֶה הִתְקַיֵּם יוֹתֵר מִכֻּלָּם, שֶׁבָּזֶה הִתְקַיֵּם הַמִּשְׁכָּן וְלֹא בְאַחֵר.</p>"],[9522011868,"<p>פָּתַח וְאָמַר, (שם ב) וְהָיָה אֱמוּנַת עִתֶּיךְ חֹסֶן יְשׁוּעֹת חָכְמַת וָדָעַת יִרְאַת ה' הִיא אוֹצָרוֹ. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים, אֲבָל הֲרֵי שָׁנִינוּ, כָּל אָדָם שֶׁמִּתְעַסֵּק בַּתּוֹרָה בָּעוֹלָם הַזֶּה וְזוֹכֶה לִקְבּעַ לָהּ עִתִּים, צָרִיךְ בֶּאֱמוּנָה, שֶׁרְצוֹנוֹ יִתְכַּוֵּן לַקָּדוֹשׁ בָּרוּךְ הוּא, יִתְכַּוֵּן לְשֵׁם שָׁמַיִם, מִשּׁוּם שֶׁאֱמוּנָה לְכָךְ הִתְכַּוְּנָה. חֹסֶן יְשׁוּעֹת, לִכְלֹל רַחֲמִים בְּדִין. חָכְמַת וָדָעַת, שֶׁשְּׁנֵי אֵלֶּה שׁוֹרִים זֶה עַל זֶה. זֶה טָמִיר וְגָנוּז, לְהַשְׁרוֹת זֶה עַל זֶה.</p>\n<p>יִרְאַת ה' הִיא אוֹצָרוֹ - אוֹצָרוֹ שֶׁל כָּל אֵלֶּה, מִשּׁוּם שֶׁיִּרְאַת ה' הַזּוֹ לוֹקַחַת כָּל אוֹתָם נְחָלִים, וְנַעֲשֵׂית אוֹצָר לְכֻלָּם. וּכְשֶׁיּוֹצְאִים מִמֶּנָּה כָּל אוֹתָם גְּנָזִים כֻּלָּם, מוֹצִיאָה אוֹתָם בְּחֶשְׁבּוֹן. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שיר ז) עֵינַיִךְ בְּרֵכוֹת בְּחֶשְׁבּוֹן. בְּחֶשְׁבּוֹן וַדַּאי עוֹשָׂה, וּמוֹצִיאָה אוֹתָם בְּרֵכוֹת מַיִם, וּמַשְׁגִּיחָה לְהוֹצִיא הַכֹּל בְּחֶשְׁבּוֹן. (ומשקים לכלם)</p>\n<p>וְלָכֵן נִקְרֵאת אֱמוּנָה, וּבַכֹּל נִקְרֵאת אֱמוּנָה, וַהֲרֵי בֵּאַרְנוּ. וּמָה אִם כָּאן צָרִיךְ לְהַרְאוֹת אֱמוּנָה - לִשְׁאָר דִּבְרֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מוֹדִיעַ לְכָל יִשְׂרָאֵל סוֹד הַנֶּאֱמָנוּת שֶׁלָּהֶם בְּכָל מַה שֶּׁעָשׂוּ, וְהַכֹּל נִתְבָּאֵר.</p>"],[9522011869,"<p>רַבִּי יוֹסֵי וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בִּבְצַלְאֵל לַעֲבוֹדַת הַמִּשְׁכָּן יוֹתֵר מִכָּל יִשְׂרָאֵל. לָמָּה? אָמַר לוֹ, הַשֵּׁם גּוֹרֵם, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם שֵׁמוֹת בָּאָרֶץ לְהִתְעַטֵּר (לעורר) בָּהֶם וְלַעֲשׂוֹת בָּהֶם מַעֲשֶׂה בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים מו) אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ.</p>\n<p>אָמַר לוֹ, סוֹד הוּא כָּאן. יְהוּדָה הָיָה מִצַּד הַשְּׂמֹאל, וְחָזַר וְנִדְבַּק בַּיָּמִין, וְעַל זֶה בְּצַד זֶה נַעֲשָׂה הַמִּשְׁכָּן. הִתְחִיל מִצַּד שְׂמֹאל, וְנִדְבַּק בְּצַד יָמִין, וְאַחַר כָּךְ נִכְלָל זֶה בָּזֶה וְנַעֲשָׂה הַכֹּל יָמִין. כְּמוֹ כֵן הַתּוֹרָה מַתְחִילָה מִשְּׂמֹאל וְנִדְבֶּקֶת בְּיָמִין, וְנִכְלָל זֶה בָּזֶה וְנַעֲשֶׂה הַכֹּל יָמִין. רְאוּבֵן הִתְחִיל מִיָּמִין וְסָטָה לִשְׂמֹאל, וְנָסְעוּ עִמּוֹ שְׁאָר הַשְּׁבָטִים שֶׁהֵם שְׂמֹאל, מִשּׁוּם שֶׁהִתְחִיל מִיָּמִין וְסָטָה לִשְׂמֹאל.</p>\n<p>יְהוּדָה הִתְחִיל מִשְּׂמֹאל וְסָטָה לְיָמִין. הִתְחִיל מִשְּׂמֹאל, מִשּׁוּם שֶׁבָּא מִצַּד שְׂמֹאל, וְנִדְבַּק בְּיָמִין, וְהַמִּשְׁכָּן נַעֲשָׂה בַּצַּד הַזֶּה. הִתְחִיל מִצַּד שְׂמֹאל וְנִדְבַּק בְּצַד יָמִין. וְעַל זֶה בְּצַלְאֵל, שֶׁבָּא מֵהַצַּד שֶׁלּוֹ, עָשָׂה אֶת הַמִּשְׁכָּן וְהִתְתַּקֵּן אֶצְלוֹ. וַהֲרֵי פֵּרְשׁוּהָ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בּוֹ, וּבֵרֵר אוֹתוֹ מִכֻּלָּם לַמַּעֲשֶׂה הַזֶּה.</p>\n<p>וְנָתַן לוֹ חָכְמָה וּתְבוּנָה וָדַעַת, כְּמוֹ שֶׁבֵּאֲרוּהָ, מִשּׁוּם שֶׁעִמּוֹ הָיָה בָּרִאשׁוֹנָה הַשְׂכֵּל הַלֵּב, שֶׁכָּתוּב (שמות לא) וּבְלֵב כָּל חֲכַם לֵב נָתַתִּי חָכְמָה. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נוֹתֵן חָכְמָה אֶלָּא לְמִי שֶׁיֵּשׁ בּוֹ חָכְמָה, וּפֵרְשׁוּהָ הַחֲבֵרִים וְנִתְבָּאֵר, וְכֵן כְּמוֹ כֵן בְּצַלְאֵל. רַבִּי שִׁמְעוֹן אָמַר, בְּצַלְאֵל - שְׁמוֹ גָּרַם לוֹ, וְעַל חָכְמָתוֹ נִקְרָא כָּךְ, וְסוֹד הַמִּלָּה בְּצַלְאֵל - בְּצֵל אֵל.</p>\n<p>פָּתַח וְאמַר, (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי וְגוֹ'. בְּצִלּוֹ - הַיְנוּ בְּצַלְאֵל, שֶׁהוּא הִתְקִין הַמִּשְׁכָּן וְעָשָׂה אוֹתוֹ, שֶׁכָּתוּב חִמַּדְתִּי וְיָשַׁבְתִּי. שֶׁהַמִּשְׁכָּן נֶחְמָד לָשֶׁבֶת בּוֹ, שֶׁהוּא עשֶׂה חֶמְדָּה לִכְנֶסֶת יִשְׂרָאֵל, וּכְנֶסֶת יִשְׂרָאֵל יוֹשֶׁבֶת בְּצֵל הָאֵל. וְזֶהוּ בְּצַלְאֵל.</p>\n<p>וּפִרְיוֹ מָתוֹק לְחִכִּי, שֶׁזֶּהוּ שֶׁעוֹשֶׂה פֵּרוֹת טוֹבִים בָּעוֹלָם, שֶׁכָּתוּב (הושע יד) מִמֶּנִּי פֶּרְיְךְ נִמְצָא. מִי הוּא פְּרִי? אֵלֶּה הֵם נִשְׁמוֹת הַצַּדִּיקִים, שֶׁהֵם פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן מוֹצִיא וְזוֹרֵק נְשָׁמוֹת לָעוֹלָם, וְהֵם הַפֵּרוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ פִּרְיוֹ. זֶהוּ כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>בְּצִלּוֹ - זֶהוּ בְּצַלְאֵל. וְעַל זֶה תִּקּוּן הַמִּשְׁכָּן עַל יְדֵי בְּצַלְאֵל הָיָה. וּמִשּׁוּם כָּךְ, וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר. בֶּן אוּרִי - זֶה אוֹר הַשֶּׁמֶשׁ שֶׁיּוֹצֵא. בֶּן אוּרִי - זֶה יָמִין. בֶּן חוּר - זֶה שְׂמֹאל. בֶּן אוּרִי בֶן חוּר (בן חור בן חורי). וְעַל זֶה נִשְׁלַם בּוֹ דִּינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה הָעֵגֶל.</p>\n<p>כָּל הַזָּהָב הֶעָשׂוּי - מֵאוֹתָהּ שָׁעָה שֶׁנָּתְנוּ לוֹ יִשְׂרָאֵל, הָיָה עָשׂוּי וְנִתְתַּקֵּן מִקֹּדֶם לְכָךְ. בְּכֹל מְלֶאכֶת הַקֹּדֶשׁ - כָּל אוֹתוֹ זָהָב נַעֲשָׂה וְנִתְתַּקֵּן בְּכֹל מְלֶאכֶת הַקֹּדֶשׁ. מָה הַטַּעַם? מִשּׁוּם שֶׁבְּכָל דַּרְגָּה וְדַרְגָּה הָיָה מִתְתַּקֵּן בָּהּ זָהָב, שֶׁאֵין שְׁלֵמוּת אֶלָּא בְּרַחֲמִים וְדִין, וְעַל זֶה זָהָב הָיָה הוֹלֵךְ בְּכָל מְלֶאכֶת הַקֹּדֶשׁ. בְּכָל אוֹתָהּ עֲבוֹדָה שֶׁנִּקְרֵאת קֹדֶשׁ הָיָה הוֹלֵךְ בָּהּ זָהָב, זָהָב בַּכֹּל.</p>\n<p>רַבִּי אַבָּא, רַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה הָיוּ יוֹשְׁבִים וְעוֹסְקִים בַּתּוֹרָה. אָמַר לוֹ רַבִּי חִזְקִיָּה לְרַבִּי אַבָּא, הֲרֵי אָנוּ רוֹאִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בְדִין בַּכֹּל לְעָרֵב זֶה בָּזֶה, וְהוּא מַאֲרִיךְ דִּין לְרִשְׁעֵי הָעוֹלָם. אִם הוּא רוֹצֶה בְּדִין, לָמָּה מְסַלֵּק אוֹתוֹ מִן הָרְשָׁעִים? אָמַר לוֹ, כַּמָּה הָרִים נֶעֶקְרוּ בַּדָּבָר הַזֶּה, אֲבָל כַּמָּה דְבָרִים גִּלָּה הַמְּנוֹרָה הַקְּדוֹשָׁה בָּזֶה.</p>\n<p>וּבֹא רְאֵה, הַדִּין שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בּוֹ הוּא דִּין בָּרוּר, הוּא דִּין שֶׁמְּעוֹרֵר אַהֲבָה וְשִׂמְחָה. אֲבָל הָרְשָׁעִים, כְּשֶׁהֵם בָּעוֹלָם, כֻּלָּם דִּין שֶׁל זֻהֲמָה, כֻּלָּם דִּין שֶׁלֹּא רוֹצֶה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלָל. וְעַל זֶה לֹא צָרִיךְ לְעָרֵב דִּין קָדוֹשׁ בְּדִין טָמֵא שֶׁל זֻהֲמָה, עַד שֶׁמִּתְכַּלֶּה מֵעַצְמוֹ וּמְאַבְּדוֹ מֵהָעוֹלָם הַבָּא, וְאוֹתוֹ דִּין שֶׁל זֻהֲמָה שֶׁבּוֹ, הוּא מְאַבֵּד אוֹתוֹ מִן הָעוֹלָם.</p>"],[9522011870,"<p>פָּתַח וְאָמַר, (תהלים צב) בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. אֲבָל בֹּא וּרְאֵה, בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב, כָּעֵשֶׂב הַזֶּה שֶׁהוּא בְּיֹבֶשׁ בָּאָרֶץ וְהוּא יָבֵשׁ, כְּשֶׁשּׁוֹרִים בּוֹ מַיִם הוּא פּוֹרֵחַ, וְאוֹתוֹ יֹבֶשׁ פּוֹרֵחַ. וּכְאִילָן הַזֶּה קָצוּץ שֶׁצָּץ מֵחָדָשׁ, וְלֹא מַעֲלֶה אֶלָּא אוֹתָם פְּאֵרוֹת לְצַד זֶה וּלְצַד זֶה, שֶׁהֵם עֲנָפִים שֶׁעוֹלִים, וּלְעוֹלָמִים לֹא עוֹלֶה אִילָן כְּפִי שֶׁהָיָה בָּרִאשׁוֹנָה לִהְיוֹת אִילָן, וְכָל זֶה לְהִשָּׁמְדָם עֲדֵי עַד, לְעָקְרָם מֵהַשָּׁרָשִׁים וּמֵהַכֹּל.</p>\n<p>עוֹד יֵשׁ סוֹד אַחֵר בָּזֶה, עַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ רָגְזוֹ עִם הָרְשָׁעִים בָּעוֹלָם הַזֶּה, מִשּׁוּם שֶׁהָעוֹלָם הַזֶּה הוּא חֵלֶק שֶׁל הַצַּד הָאַחֵר, וְהָעוֹלָם הַבָּא הוּא צַד הַקְּדֻשָּׁה. וְהוּא חֵלֶק הַצַּדִּיקִים, שֶׁהַצַּדִּיקִים יִהְיוּ בוֹ בַּעֲטֶרֶת הַכָּבוֹד שֶׁל רִבּוֹנָם. וּשְׁנֵי הַצְּדָדִים הַלָּלוּ עוֹמְדִים זֶה כְּנֶגֶד זֶה. זֶה צַד הַקְּדֻשָּׁה, וְזֶה הַצַּד הָאַחֵר שֶׁטָּמֵא. זֶה עוֹמֵד לַצַּדִּיקִים, וְזֶה עוֹמֵד לָרְשָׁעִים. וְהַכֹּל זֶה כְּנֶגֶד זֶה. אַשְׁרֵי הַצַּדִּיקִים שֶׁאֵין לָהֶם חֵלֶק בָּעוֹלָם הַזֶּה, אֶלָּא בָּעוֹלָם הַבָּא.</p>"],[9522011871,"<p>בֹּא וּרְאֵה, הַכֹּל הִתְתַּקֵּן וְהִתְגַּלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַף עַל פִּי שֶׁבָּלָק וּבִלְעָם לֹא הִתְכַּוְּנוּ עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַכֹּל הִתְתַּקֵּן לְפָנָיו, וְלֹא גָרַע מִשְּׂכָרָם כְּלוּם בָּעוֹלָם הַזֶּה. בְּאוֹתוֹ זְמַן שָׁלְטוּ עַל יִשְׂרָאֵל, שֶׁגָּרַם אוֹתוֹ קָרְבָּן לְהִסְתַּלֵּק מִיִּשְׂרָאֵל עֶשְׂרִים וְאַרְבָּעָה אֶלֶף, פְּרָט לְכָל אֵלּוּ שֶׁנֶּהֶרְגוּ, שֶׁכָּתוּב (במדבר כה) הִרְגוּ אִישׁ וַאֲנָשָׁיו הַנִּצְמָדִים לְבַעַל פְּעוֹר, וְכָתוּב קַח אֶת כָּל רָאשֵׁי הָעָם וְהוֹקַע אוֹתָם לַה'. וְעַד כָּעֵת אוֹתוֹ קָרְבָּן הָיָה תָּלוּי לְהִפָּרַע מִיִּשְׂרָאֵל. שִׁבְעָה מִזְבְּחוֹת כְּחֶשְׁבּוֹן אַרְבָּעִים וּשְׁנַיִם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בֹּא וּרְאֵה, אוֹתָם אַרְבָּעִים וּשְׁנַיִם קָרְבָּנוֹת עָשׂוּ בָלָק וּבִלְעָם, וְנָטְלוּ אוֹתָם מֵאוֹתוֹ הַצַּד הָאַחֵר לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְעַל זֶה הָיָה תָּלוּי אוֹתוֹ קָרְבָּן, שֶׁיִּטֹּל אוֹתוֹ אוֹתוֹ הַצַּד הָאַחֵר, שֶׁנִּקְרָא קְלָלָה, מִיִּשְׂרָאֵל. וְעַד עַכְשָׁו לֹא גָבָה מֵהֶם. וְזֶהוּ סוֹד (מלכים בב) וַיִּפֶן אַחֲרָיו וַיִּרְאֵם. וַיִּפֶן אַחֲרָיו - אֲחוֹרֵי שְׁכִינָה, שֶׁעָמַד הַצַּד הָאַחֵר לְאָחוֹר. וַיִּרְאֵם - הִסְתַּכֵּל בָּהֶם אוֹתוֹ הַצַּד הָאַחֵר וְרָאָה אוֹתָם שֶׁרְאוּיִים לְהֵעָנֵשׁ, וְעַל זֶה - וַיְקַלְלֵם בְּשֵׁם ה'. בְּשֵׁם ה' - לְהוֹצִיא אוֹתוֹ שֵׁם ה' מֵחִיּוּב זֶה, מֵאוֹתוֹ חִיּוּב שֶׁל אוֹתוֹ קָרְבָּן שֶׁהִקְרִיב אוֹתוֹ צַד אֵלָיו, וְהַכֹּל מְתֻקָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נֶאֱבָד דָּבָר. כְּמוֹ כֵן הַכֹּל הִתְתַּקֵּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הֵן לְטוֹב הֵן לְרַע.</p>"],[9522011872,"<p>בֹּא וּרְאֵה, דָּוִד הוּא הָיָה שֶׁבָּרַח לִפְנֵי שָׁאוּל, וְעַל זֶה גָּרַם שֶׁנֶּאֶבְדוּ כָּל אוֹתָם כֹּהֲנֵי נוֹב, וְלֹא נִשְׁאַר מִכֻּלָּם - רַק אֶבְיָתָר לְבַדּוֹ שֶׁבָּרַח. וְזֶה גָּרַם כַּמָּה רָעוֹת בְּיִשְׂרָאֵל, וּמֵת שָׁאוּל וּבָנָיו, וְנָפְלוּ מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים וּרְבָבוֹת. וְעִם כָּל זֶה, אוֹתוֹ חֵטְא הָיָה תָּלוּי עַל דָּוִד לִגְבּוֹתוֹ מִמֶּנּוּ, עַד שֶׁכָּל בְּנֵי דָוִד נֶאֶבְדוּ בְּיוֹם אֶחָד, וְלֹא נִשְׁאַר מֵהֶם אֶלָּא יוֹאָשׁ לְבַדּוֹ, שֶׁנִּגְנַב. כְּמוֹ שֶׁלֹּא נִשְׁאַר מֵאֲחִימֶלֶךְ - רַק אֶבְיָתָר לְבַדּוֹ. וְעַד עַכְשָׁו אוֹתוֹ חֵטְא הָיָה תָּלוּי לַעֲשׂוֹת דִּין עַל נוֹב עַל אוֹתוֹ חֵטְא שֶׁל נוֹב, שֶׁכָּתוּב (ישעיה י) עוֹד הַיּוֹם בְּנֹב לַעֲמֹד, וּפֵרְשׁוּהָ.</p>\n<p>כְּמוֹ זֶה - כָּל הַזָּהָב הֶעָשׂוּי לַמְּלָאכָה. מַה זֶּה הֶעָשׂוּי? כָּאן הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנָּתְנוּ יִשְׂרָאֵל זָהָב לָעֵגֶל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּים לָהֶם זָהָב זֶה לִרְפוּאָה, שֶׁהֲרֵי זְהַב הַמִּשְׁכָּן הִקְדִּים לָהֶם לְאוֹתוֹ הַזָּהָב שֶׁנָּתְנוּ לָעֵגֶל. שֶׁכָּל הַזָּהָב שֶׁהָיָה עִמָּהֶם וְנִמְצָא עִמָּהֶם, נָתְנוּ לִתְרוּמַת הַמִּשְׁכָּן. הֶהָיָה עוֹלֶה בְדַעְתְּךְ, שֶׁכְּשֶׁעָשׂוּ אֶת הָעֵגֶל נִמְצָא עִמָּהֶם זָהָב, וְהֵם פָּרְקוּ אָזְנֵיהֶם לִטֹּל אוֹתוֹ זָהָב, שֶׁכָּתוּב (שמותלב) וַיִּתְפָּרַקוּ כָּל הָעָם אֶת נִזְמֵי הַזָּהָב אֲשֶׁר בְּאָזְנֵיהֶם?! וְעַל זֶה הִקְדִּים זְהַב הַתְּרוּמָה, לְכַפֵּר עַל הַמַּעֲשֶׂה הַזֶּה. (ומשום כך)</p>\n<p>וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר לְמַטֵּה יְהוּדָה, מִצַּד הַמַּלְכוּת עָשָׂה אֶת כָּל אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה, שֶׁהֲרֵי כָּל אֻמָּנוּת הַמִּשְׁכָּן הִתְתַּקְּנָה בָהֶם וְעַל יְדֵיהֶם. בְּצַלְאֵל עָשָׂה אֶת הָאֻמָּנוּת, וּמֹשֶׁה הִתְקִין אֶת הַכֹּל אַחַר כָּךְ. מֹשֶׁה וּבְצַלְאֵל הָיוּ כְאֶחָד. מֹשֶׁה לְמַעְלָה - בְּצַלְאֵל תַּחְתָּיו. סִיּוּם הַגּוּף כְּמוֹ הַגּוּף. בְּצַלְאֵל וְאָהֳלִיהָב, הֲרֵי פֵּרְשׁוּהָ - זֶה יָמִין וְזֶה שְׂמֹאל, וְהַכֹּל אֶחָד. וּמִשּׁוּם כָּךְ, וּבְצַלְאֵל בֶּן אוּרִי בֶן חוּר לְמַטֵּה יְהוּדָה וְגוֹ', וְאִתּוֹ אָהֳלִיהָב בֶּן אֲחִיסָמָךְ לְמַטֵּה דָן וְגוֹ'.</p>"],[9522011873,"<p>כָּל הַזָּהָב הֶעָשׂוּי לַמְּלָאכָה בְּכֹל מְלֶאכֶת הַקֹּדֶשׁ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח אֶת הַפָּסוּק בֶּאֱלִישָׁע, שֶׁכָּתוּב (מלכים בב) וַיַּעַל מִשָּׁם בֵּית אֵל וְהוּא עֹלֶה בַדֶּרֶךְ וְגוֹ'. וּנְעָרִים קְטַנִּים, הֲרֵי פֵּרְשׁוּהָ - מְנֹעָרִים הָיוּ מִכָּל דִּבְרֵי הַתּוֹרָה וּמִכָּל מִצְווֹת הַתּוֹרָה. קְטַנִּים - קְטַנֵּי אֱמוּנָה, וְהִתְחַיְּבוּ בְּדִין הָעוֹלָם הַזֶּה וּבַדִּין שֶׁל הָעוֹלָם הַבָּא. יָצְאוּ מִן הָעִיר - יָצְאוּ מִסּוֹד הָאֱמוּנָה. כָּתוּב כָּאן יָצְאוּ מִן הָעִיר, וְכָתוּב שָׁם (הושע יא) וְלֹא אָבוֹא בְּעִיר. (מסוד האמונה נקרא עיר, (תהלים מח) עיר ה' צבאות עיר אלהינו).</p>\n<p>וַיִּפֶן אַחֲרָיו וַיִּרְאֵם. וַיִּפֶן אַחֲרָיו, שֶׁהִסְתַּכֵּל לַאֲחוֹרָיו אִם יַחְזְרוּ בִתְשׁוּבָה וְאִם לֹא. וַיִּרְאֵם, מַה זֶּה וַיִּרְאֵם? הִסְתַּכֵּל בָהֶם שֶׁהֲרֵי אֵין זֶרַע מְתֻקָּן עָתִיד לָצֵאת מֵהֶם, וּפֵרְשׁוּהָ. וַיִּרְאֵם, הֲרֵי פֵּרְשׁוּהָ שֶׁנַּעֲשׂוּ בְּלֵיל יוֹם הַכִּפּוּרִים, מִיָּד - וַיְקַלְלֵם בְּשֵׁם ה'.</p>\n<p>וְסוֹד הוּא בַּפָּסוּק הַזֶּה. וַיִּפֶן אַחֲרָיו - הִסְתַּכֵּל בָּהֶם אִם יֵעָנֵשׁ עֲלֵיהֶם וְהִתְפַּנָּה מִזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וַיִּפֶן אַהֲרֹן, שֶׁהִתְפַּנָּה מִצָּרַעְתּוֹ. אַף כָּאן הִתְפַּנָּה מֵעָנְשָׁם. וַיִּרְאֵם, שֶׁהָיוּ עוֹמְדִים אַחַר כָּךְ לַעֲשׂוֹת כַּמָּה רָעוֹת לְיִשְׂרָאֵל.</p>\n<p>וַיִּפֶן אַחֲרָיו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יט) וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו. מַה זֶּה מֵאַחֲרָיו? מֵאֲחוֹרֵי הַשְּׁכִינָה. אַף כָּאן וַיִּפֶן אַחֲרָיו - הִסְתַּכֵּל מֵאֲחוֹרֵי הַשְּׁכִינָה וְרָאָה אֶת כֻּלָם. שֶׁהֲרֵי בְּאוֹתוֹ לַיְלָה שֶׁשּׁוֹלֶטֶת עַל כַּפָּרַת חֲטָאֵיהֶם שֶׁל יִשְׂרָאֵל, הִתְעַבְּרוּ מֵהֶם אִמּוֹתֵיהֶם. מִיָּד - וַיְקַלְלֵם בְּשֵׁם ה' וַתֵּצֶאנָה שְׁתַּיִם דֻּבִּים מִן הַיַּעַר. שְׁתַּיִם דֻּבִּים? שְׁנַיִם דֻּבִּים הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה שְׁתַּיִם דֻּבִּים? נְקֵבוֹת הָיוּ וּבְנֵיהֶם. וַתְּבַקַּעְנָה מֵהֶם אַרְבָּעִים וּשְׁנַיִם יְלָדִים, הֲרֵי פֵּרְשׁוּהָ - כְּנֶגֶד הַקָּרְבָּנוֹת שֶׁל בָּלָק.</p>"],[9522011874,"<p>וַיְהִי זְהַב הַתְּנוּפָה, לָמָּה נִקְרָא זְהַב הַתְּנוּפָה, וְלֹא נִקְרָא כָּךְ: כֶּסֶף הַתְּנוּפָה? אֶלָּא שְׁנֵי אֵלֶּה נִקְרְאוּ כָּךְ: זְהַב הַתְּנוּפָה, וּנְחֹשֶׁת הַתְּנוּפָה. וְלֹא נִקְרָא כָּךְ כֶּסֶף הַתְּנוּפָה, אֶלָּא אֵלּוּ נִקְרְאוּ כָּךְ מִשּׁוּם שֶׁזּוֹ הִיא הִסְתַּלְּקוּת לְמַעְלָה, שֶׁהֲרֵי יֵשׁ כָּךְ לְמַטָּה, וְאֵינוֹ זְהַב (כדגמת) הַתְּנוּפָה. וּבְכָל מָקוֹם תְּנוּפָה הִיא הֲרָמָה לְמַעְלָה וְלֹא הוֹרָדָה לְמַטָּה.</p>\n<p>וְהוּא סוֹד הַחֶשְׁבּוֹן הַזֶּה, שֶׁכָּל הַדְּרָגוֹת וְהַמֶּרְכָּבוֹת הַלָּלוּ כֻּלָּן עוֹמְדוֹת בִּתְנוּפָה (זו), וְהוּא זְהַב הַתְּנוּפָה, וְזֶהוּ זָהָב. שֶׁכָּל מַה שֶּׁמִּתְפַּשֵּׁט לְמַטָּה, מַסְתִּיר אֶת הַמַּרְאֶה וְהַטּוֹב וְהָאוֹר שֶׁלּוֹ, וּכְשֶׁהוּא בִּתְנוּפָה, אָז הוּא זָהָב טוֹב בְּסוֹד הָאוֹר שֶׁלּוֹ. וְכָל אוֹתוֹ שֶׁלְּמַטָּה - פְּסֹלֶת הַזָּהָב, וְהוּא הַהִתּוּךְ שֶׁלּוֹ.</p>\n<p>וְכֶסֶף פְּקוּדֵי הָעֵדָה, מִשּׁוּם שֶׁזֶּה הוּא כָּל מַה שֶּׁמִּתְפַּשֵּׁט לְמַטָּה כָּךְ הוּא טוֹב, וְאַף עַל גַּב שֶׁאֵינוֹ בַּתְּנוּפָה הַזּוֹ - הַכֹּל הוּא לְטוֹב. אֲבָל זָהָב, כָּל מַה שֶּׁמִּתְפַּשֵּׁט לְמַטָּה - הַכֹּל הוּא לְרַע. זֶה מִתְפַּשֵּׁט לְטוֹב, וְזֶה מִתְפַּשֵּׁט לְרַע. וּמִשּׁוּם כָּךְ צָרִיךְ לְהָנִיף תְּנוּפָה וּלְהַעֲלוֹת לְמַעְלָה. וְזֶה צָרִיךְ לְהִתְפַּשֵּׁט לְמַטָּה וּלְכָל הַצְּדָדִים, מִשּׁוּם שֶׁעוֹמְדִים כֻּלָּם לְטוֹב.</p>\n<p>פָּתַח וְאָמַר, (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' וְגוֹ'. כִּי שֶׁמֶשׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָגֵן - זֶהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁמֶשׁ - זֶהוּ סוֹד הַשֵּׁם הַקָּדוֹשׁ יְהֹוָ\"ה, שֶׁכָּאן עוֹמְדוֹת כָּל הַדְּרָגוֹת לִמְנוּחָה. וּמָגֵן - זֶהוּ סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא אֱלֹהִים. וְסוֹד זֶה שֶׁכָּתוּב (בראשית טו) אָנֹכִי מָגֵן לָךְ. וְשֶׁמֶשׁ וּמָגֵן זֶהוּ סוֹד הַשֵּׁם הַשָּׁלֵם. חֵן וְכָבוֹד יִתֵּן ה', לִהְיוֹת הַכֹּל בְּסוֹד אֶחָד.</p>\n<p>לֹא יִמְנַע טוֹב לַהֹלְכִים בְּתָמִים - סוֹד זֶה (אותו) שֶׁכָּתוּב (איובלח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם. וְזֶהוּ אוֹר רִאשׁוֹן שֶׁכָּתוּב בּוֹ (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, שֶׁגְּנָזוֹ וְהִסְתִּירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאֲרוּהוּ, וְגָנַז אוֹתוֹ מֵהָרְשָׁעִים, וּמָנַע אוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אֲבָל לַצַּדִּיקִים מַה כָּתוּב? לֹא יִמְנַע טוֹב לַהֹלְכִים בְּתָמִים. זֶהוּ אוֹר הָרִאשׁוֹן שֶׁכָּתוּב בּוֹ (שם) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב.</p>\n<p>וְעַל זֶה לֹא צָרִיךְ זֶה לְהַעֲלוֹת וּלְהָנִיף אוֹתוֹ, אֶלָּא לְהִתְפַּשֵּׁט וּלְהִתְגַּלּוֹת, וְלֹא לְהִתְעַלּוֹת כְּמוֹ אוֹתוֹ אַחֵר שֶׁהוּא שְׂמֹאל, וְלָכֵן נִקְרָא אוֹתוֹ תְּנוּפָה, וְלֹא זֶה. וּמִשּׁוּם כָּךְ - וְכֶסֶף פְּקוּדֵי הָעֵדָה מְאַת כִּכָּר וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, צַד הַיָּמִין הוּא תָּמִיד עוֹמֵד לְקַיֵּם אֶת כָּל הָעוֹלָם וּלְהָאִיר וּלְבָרֵךְ אוֹתוֹ, וּמִשּׁוּם כָּךְ הַכֹּהֵן שֶׁהוּא מִצַּד הַיָּמִין, מִזְדַּמֵּן תָּמִיד לְבָרֵךְ אֶת הָעָם, שֶׁהֲרֵי מִצַּד הַיָּמִין בָּאוֹת כָּל הַבְּרָכוֹת לָעוֹלָם, וְהַכֹּהֵן נוֹטֵל בָּרֹאשׁ, וְעַל כָּךְ הוּא הִתְמַנָּה לְבָרֵךְ לְמַעְלָה וּלְמַטָּה.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו לְבָרֵךְ אֶת הָעָם, אֲזַי הַשְּׁכִינָה בָּאָה וְשׁוֹרָה עָלָיו וּמְמַלֵּאת אֶת יָדָיו. יַד יָמִין עוֹלָה לְמַעְלָה מֵעַל יַד שְׂמֹאל, כְּדֵי לְהַעֲלוֹת הַיָּמִין וּלְהַגְבִּירוֹ עַל הַשְּׂמֹאל, וְאָז כָּל הַדְּרָגוֹת שֶׁפּוֹרֵשׂ בָּהֶן אֶת יָדָיו, כֻּלָּן מִתְבָּרְכוֹת מִמְּקוֹר הַכֹּל. מְקוֹר הַבְּאֵר מִי הוּא? זֶה צַדִּיק. מְקוֹר הַכֹּל זֶהוּ עוֹלָם הַבָּא, שֶׁהוּא מָקוֹר עֶלְיוֹן שֶׁכָּל הַפָּנִים מְאִירוֹת מִשָּׁם, שֶׁהֲרֵי הוּא הַמַּעְיָן וְהַמָּקוֹר שֶׁל הַכֹּל, וְכָל הַמְּאוֹרוֹת וְהַמְּנוֹרוֹת מִשָּׁם נִדְלָקִים.</p>\n<p>כְּמוֹ כֵן הַמָּקוֹר וְהַמַּבּוּעַ שֶׁל הַבְּאֵר, כָּל אוֹתָן מְנוֹרוֹת שֶׁלְּמַטָּה, כֻּלָּן מְאִירוֹת וּמִתְמַלְּאוֹת מִמֶּנּוּ בְּאוֹר, וְזֶה עוֹמֵד כְּנֶגֶד זֶה. וּמִשּׁוּם כָּךְ, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו וּמַתְחִיל לְבָרֵךְ אֶת הָעָם, אָז שׁוֹרוֹת בְּרָכוֹת עֶלְיוֹנוֹת מִמָּקוֹר עֶלְיוֹן לְהַדְלִיק מְנוֹרוֹת, וְכָל הַפָּנִים מְאִירוֹת, וּכְנֶסֶת יִשְׂרָאֵל מִתְעַטֶּרֶת בַּעֲטָרוֹת עֶלְיוֹנוֹת, וְכָל אוֹתָן בְּרָכוֹת שׁוֹפְעוֹת וְנִמְשָׁכוֹת מִמַּעְלָה לְמַטָּה.</p>\n<p>בֹּא וּרְאֵה, מֹשֶׁה צִוָּה - וּבְצַלְאֵל עָשָׂה, לִהְיוֹת הַכֹּל בְּסוֹד הַגּוּף, וְסִיּוּם הַגּוּ,, שֶׁהוּא אוֹת בְּרִית הַקֹּדֶשׁ, לְהַרְבּוֹת אַהֲבָה וְקֶשֶׁר שֶׁל יִחוּד בַּמִּשְׁכָּן. וְהַכֹּל נַעֲשָׂה בְּסוֹד הַיָּמִין. וְעַל זֶה, בְּכָל מָקוֹם שֶׁצַּד הַיָּמִין נִמְצָא, אֵין שׁוֹלֶטֶת בּוֹ עַיִן רָעָה. וּמִשּׁוּם כָּךְ - וְכֶסֶף פְּקוּדֵי הָעֵדָה, מִשּׁוּם שֶׁאוֹתוֹ כֶּסֶף בָּא מִצַּד יָמִין, וְלָכֵן נִמְנָה הַכֹּל בַּמִּנְיָן.</p>"],[9522011875,"<p>רַבִּי יִצְחָק שָׁאַל אֶת רַבִּי שִׁמְעוֹן. אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ שֶׁבְּרָכָה אֵינָהּ שׁוֹרָה בְּדָבָר שֶׁעוֹמֵד בְּמִדָּה וּבְדָבָר שֶׁעוֹמֵד בְּחֶשְׁבּוֹן, אָז לָמָּה הָיָה כָּאן בַּמִּשְׁכָּן הַכֹּל בְּחֶשְׁבּוֹן? אָמַר לוֹ, הֲרֵי זֶה נִתְבָּאֵר, אֲבָל בְּכָל מָקוֹם שֶׁצַּד הַקְּדֻשָּׁה שׁוֹרֶה עָלָיו - אִם אוֹתוֹ חֶשְׁבּוֹן בָּא מִצַּד הַקְּדֻשָּׁה, הַבְּרָכָה שׁוֹרָה עָלָיו תָּמִיד וְלֹא סָרָה מִמֶּנּוּ. מִנַּיִן לָנוּ? מִמַּעֲשֵׂר. מִשּׁוּם שֶׁבָּא הַחֶשְׁבּוֹן לְקַדֵּשׁ, נִמְצֵאת בּוֹ בְּרָכָה. כָּל שֶׁכֵּן הַמִּשְׁכָּן שֶׁהוּא קֹדֶשׁ וּבָא מִצַּד הַקֹּדֶשׁ.</p>\n<p>אֲבָל כָּל שְׁאָר דִּבְרֵי הָעוֹלָם שֶׁלֹּא בָאִים מִצַּד הַקְּדֻשָּׁה, אֵין הַבְּרָכָה שׁוֹרָה עֲלֵיהֶם כְּשֶׁהֵם בְּחֶשְׁבּוֹן, מִשּׁוּם שֶׁהַצַּד הָאַחֵר, שֶׁהוּא רַע עַיִן, יָכוֹל לִשְׁלֹט עָלָיו. וְכֵיוָן שֶׁיָּכוֹל לִשְׁלֹט עָלָיו, אֵין בְּרָכָה נִמְצֵאת בּוֹ, כְּדֵי שֶׁלֹּא יַגִּיעוּ בְרָכוֹת לְאוֹתוֹ רַע עַיִן. (ואינגו מצד הקדשה).</p>\n<p>וּמִדָּה שֶׁל קְדֻשָּׁה וְחֶשְׁבּוֹן שֶׁל קְדֻשָּׁה תָּמִיד נוֹסָפוֹת בּוֹ בְּרָכוֹת, וְעַל זֶה וְכֶסֶף פְּקוּדֵי הָעֵדָה. פְּקוּדֵי הָעֵדָה בֶּאֱמֶת וַדַּאי, וְאֵין פַּחַד מֵעַיִן הָרָע, וְאֵין פַּחַד מִכָּל חֶשְׁבּוֹן זֶה, שֶׁהֲרֵי בַּכֹּל שׁוֹרוֹת בְּרָכוֹת מִלְמַעְלָה.</p>\n<p>וּבֹא רְאֵה, בְּזַרְעוֹ שֶׁל יוֹסֵף לֹא שׁוֹלֶטֶת בּוֹ עַיִן רָעָה, מִשּׁוּם שֶׁבָּא מִצַּד הַיָּמִין, וְעַל זֶה נַעֲשָׂה הַמִּשְׁכָּן עַל יְדֵי בְצַלְאֵל, שֶׁהֲרֵי הוּא שָׁרוּי בְּסוֹד שֶׁל יוֹסֵף, שֶׁהוּא סוֹד בְּרִית הַקְּדוֹשָׁה. וְלָכֵן מֹשֶׁה צִוָּה וּבְצַלְאֵל עָשָׂה, לִהְיוֹת הַכֹּל בְּסוֹד הַגּוּף וְסִיּוּם הַגּוּף, שֶׁהוּא אוֹת בְּרִית הַקְּדוֹשָׁה, לְהַרְבּוֹת אַהֲבָה וְקֶשֶׁר שֶׁל יִחוּד הַמִּשְׁכָּן, וְהַכֹּל נַעֲשָׂה בְּסוֹד הַיָּמִין. וּמִשּׁוּם כָּךְ - וְכֶסֶף פְּקוּדֵי הָעֵדָה, וְאוֹתוֹ חֶשְׁבּוֹן הוּא חֶשְׁבּוֹן הַדְּרָגוֹת הַמְמֻנּוֹת הַגְּדוֹלוֹת שֶׁנֶּאֱחָזוֹת מִצַּד הַיָּמִין, וְעַל זֶה כָּתוּב מְאַת כִּכָּר וְגוֹ'.</p>\n<p>רַבִּי אַבָּא וְרַבִּי אָחָא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מִטְּבֶרְיָה לְצִפּוֹרִי. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אֶת רַבִּי אֶלְעָזָר שֶׁהָיָה בָּא וְרַבִּי חִיָּיא עִמּוֹ. אָמַר רַבִּי אַבָּא, וַדַּאי נִשְׁתַּתֵּף עִם הַשְּׁכִינָה. חִכּוּ לָהֶם עַד שֶׁהִגִּיעוּ אֲלֵיהֶם. כֵּיוָן שֶׁהִגִּיעוּ אֲלֵיהֶם, אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. פָּסוּק זֶה קָשֶׁה, מַה זֶּה עֵינֵי ה' אֶל צַדִּיקִים? אִם בִּשְׁבִיל הַשְׁגָּחַת הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם כְּדֵי לְהֵיטִיב לָהֶם בָּעוֹלָם הַזֶּה, הֲרֵי רָאִינוּ כַּמָּה צַדִּיקִים הֵם שֶׁבָּעוֹלָם הַזֶּה, וַאֲפִלּוּ מְזוֹנוֹת כְּמוֹ עוֹרְבֵי הַשָּׂדֶה, לֹא יְכוֹלִים לְהַשִּׂיג. אִם כָּךְ, מַה זֶּה עֵינֵי ה' אֶל צַדִּיקִים?</p>\n<p>אֶלָּא סוֹד כָּאן יֵשׁ. בֹּא וּרְאֵה, כָּל אוֹתָם בְּרִיּוֹת הָעוֹלָם, כֻּלָּם יְדוּעִים לְמַעְלָה, בֵּין לְצַד זֶה וּבֵין לְצַד זֶה. אוֹתָם שֶׁלְּצַד הַקְּדֻשָּׁה נוֹדָעִים לְמַעְלָה אֵלָיו, וְהַשְׁגָּחָתוֹ תָּמִיד עֲלֵיהֶם. וְאוֹתָם שֶׁלְּצַד הַטֻּמְאָה נוֹדָעִים לוֹ, וְהַשְׁגָּחָתוֹ תָּמִיד עֲלֵיהֶם. וּבְמָקוֹם שֶׁשּׁוֹלֶטֶת אוֹתָהּ הַהַשְׁגָּחָה שֶׁל צַד הַקְּדֻשָּׁה, לֹא מַשְׁגִּיחַ הַצַּד הָאַחֵר, וְלֹא יִקְרַב אֵלָיו לְעוֹלָמִים וְלֹא יָכוֹל לִדְחוֹתוֹ מִמְּקוֹמוֹ בְּכָל מַה שֶּׁהוּא עוֹשֶׂה. וְלָכֵן עֵינֵי ה' אֶל צַדִּיקִים וְגוֹ', מִשּׁוּם זֶה הַצַּד הָאַחֵר לֹא יָכוֹל לִשְׁלֹט עָלָיו. וְעַכְשָׁו יֵשׁ כָּאן סִיּוּעַ שְׁמֵימִי, וְכָל הַהַשְׁגָּחָה הַטּוֹבָה שֶׁלְּמַעְלָה הִיא כָּאן, וְכָל צַד אַחֵר וְכָל דָּבָר רַע לֹא יָכוֹל לִשְׁלֹט עֲלֵיכֶם.</p>\n<p>אָמַר רַבִּי אַבָּא, הֲרֵי לָמַדְנוּ שֶׁבְּכָל מָקוֹם שֶׁצַּד הַקְּדֻשָּׁה שׁוֹרֶה עָלָיו - אַף עַל גַּב שֶׁעוֹמֵד בְּחֶשְׁבּוֹן, הַבְּרָכָה אֵינָהּ נִמְנַעַת מִשָּׁם. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ זֶה. אָמַר לוֹ, הֲרֵי יִשְׂרָאֵל הֵם קֹדֶשׁ, וּבָאִים מִצַּד הַקֹּדֶשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה'. וְכָתוּב (ויקרא יא) וִהְיִיתֶם קְדֹשִׁים כִּי קָדוֹשׁ אָנִי. אָז לָמָּה כְּשֶׁדָּוִד עָשָׂה חֶשְׁבּוֹן בְּיִשְׂרָאֵל, הָיָה בָהֶם הַמָּוֶת, שֶׁכָּתוּב (שמואל ב כד) וַיִּתֵּן ה' דֶּבֶר בְּיִשְׂרָאֵל מִן הַבֹּקֶר וְעַד עֵת מוֹעֵד?</p>\n<p>אָמַר לוֹ, מִשּׁוּם שֶׁלֹּא נָטַל מֵהֶם שְׁקָלִים, שֶׁהוּא פִּדְיוֹן, שֶׁכָּתוּב וְנָתְנוּ אִישׁ כֹּפֶר נַפְשׁוֹ לַה' בִּפְקֹד אֹתָם וְלֹא יִהְיֶה בָהֶם נֶגֶף בִּפְקֹד אֹתָם. מִשּׁוּם שֶׁצָּרִיךְ קֹדֶשׁ (שהוא בגלוי) לָתֵת פִּדְיוֹן שֶׁל קֹדֶשׁ, וְאוֹתוֹ פִּדְיוֹן שֶׁל קֹדֶשׁ לֹא נִלְקַח מֵהֶם. בּא וּרְאֵה, יִשְׂרָאֵל הֵם קֹדֶשׁ, שֶׁעוֹמְדִים בְּלִי חֶשְׁבּוֹן (של עצמם), וְלָכֵן צָרִיךְ פִּדְיוֹן לִטֹּל מֵהֶם, וְאוֹתוֹ פִּדְיוֹן עוֹמֵד בְּחֶשְׁבּוֹן, וְהֵם לֹא עוֹמְדִים בְּחֶשְׁבּוֹן.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁקֹּדֶשׁ הוּא סוֹד עֶלְיוֹן שֶׁל כָּל הַדְּרָגוֹת. מָה אוֹתוֹ קֹדֶשׁ עוֹלֶה עַל הַכֹּל וְיֵשׁ לוֹ בַּחוּץ קֹדֶשׁ אַחֵר לְמַטָּה שֶׁעוֹמֵד תַּחְתָּיו, וְעוֹמֵד בְּחֶשְׁבּוֹן וּבְמִנְיָן - אַף כָּךְ יִשְׂרָאֵל הֵם קֹדֶשׁ, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה', וְהֵם נוֹתְנִים קֹדֶשׁ אַחֵר, כֹּפֶר שֶׁלָּהֶם, שֶׁעוֹמְדִים בְּחֶשְׁבּוֹן, וְסוֹד זֶה - יִשְׂרָאֵל הֵם אִילָן שֶׁעוֹמֵד בִּפְנִים, פִּדְיוֹן (קדש) אַחֵר עוֹמֵד בַּחוּץ וְעוֹלֶה לְחֶשְׁבּוֹן, וּמֵגֵן זֶה עַל זֶה. הָלְכוּ.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (הושע ב) וְהָיָה מִסְפַּר בְּנֵי יִשְׂרָאֵל כְּחוֹל הַיָּם אֲשֶׁר לֹא יִמַּד וְלֹא יִסָּפֵר וְגוֹ'. מַה זֶּה כְּחוֹל הַיָּם? שְׁנֵי גְוָנִים הֵם כָּאן. אֶחָד - כְּחוֹל הַיָּם, מִשּׁוּם שֶׁהַיָּם, כְּשֶׁעוֹלִים הַגַּלִּים שֶׁלּוֹ בְּזַעַף וְרֹגֶז, וְאוֹתָם הַגַּלִּים עוֹלִים לִשְׁטֹף אֶת הָעוֹלָם, כְּשֶׁמַּגִּיעִים וְרוֹאִים אֶת חוֹל הַיָּם, מִיָּד נִשְׁבָּרִים וְשָׁבִים לְאָחוֹר וְשׁוֹכְכִים, וְלֹא יְכוֹלִים לִשְׁלֹט וְלִשְׁטֹף אֶת הָעוֹלָם.</p>\n<p>כְּמוֹ כֵן יִשְׂרָאֵל הֵם חוֹל הַיָּם, וּכְשֶׁשְּׁאָר הָעַמִּים, שֶׁהֵם גַּלֵּי הַיָּם, בַּעֲלֵי הָרֹגֶז וּבַעֲלֵי דִינִים קָשִׁים, רוֹצִים לִשְׁלֹט וְלִשְׁטֹף אֶת הָעוֹלָם, רוֹאִים אֶת יִשְׂרָאֵל שֶׁהֵם מִתְקַשְּׁרִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְשָׁבִים וְנִשְׁבָּרִים לִפְנֵיהֶם וְלֹא יְכוֹלִים לִשְׁלֹט בָּעוֹלָם. דֻּגְמָא אַחֶרֶת - מִשּׁוּם שֶׁחוֹל הַיָּם אֵין לוֹ חֶשְׁבּוֹן וְלֹא עוֹמֵד בְּחֶשְׁבּוֹן וְלֹא בְמִדָה, שֶׁכָּתוּב אֲשֶׁר לֹא יִמַּד וְלֹא יִסָּפֵר, אַף כָּךְ יִשְׂרָאֵל אֵין לָהֶם חֶשְׁבּוֹן וְלֹא עוֹמְדִים בְּחֶשְׁבּוֹן.</p>\n<p>בֹּא וּרְאֵה, יֵשׁ מִדָּה טְמִירָה וּגְנוּזָה, וְיֵשׁ חֶשְׁבּוֹן שֶׁעוֹמֵד בִּגְנִיזָה טְמִירָה וְגָנוּז, וְזֶה עוֹמֵד בְּמִדָּה, וְזֶה עוֹמֵד בְּחֶשְׁבּוֹן. וְזֶהוּ סוֹד וְקִיּוּם הַכֹּל, שֶׁלְּמַעְלָה וּמַטָּה, מִשּׁוּם שֶׁאוֹתָהּ מִדָּה לֹא נוֹדַעַת לְעוֹלָמִים עַל מָה עוֹמֵד הַסּוֹד שֶׁל אוֹתָהּ מִדָּה וְעַל מָה עוֹמֵד סוֹד אוֹתוֹ הַחֶשְׁבּוֹן, וְזֶהוּ סוֹד הָאֱמוּנָה שֶׁל הַכֹּל.</p>\n<p>וְיִשְׂרָאֵל לְמַטָּה לֹא עוֹמְדִים בְּחֶשְׁבּוֹן, אֶלָּא בְּצַד שֶׁל דָּבָר אַחֵר, וְהַפִּדְיוֹן הוּא שֶׁעוֹמֵד בְּחֶשְׁבּוֹן. וּמִשּׁוּם כָּךְ, כְּשֶׁיִּשְׂרָאֵל נִכְנָסִים בְּחֶשְׁבּוֹן, נוֹטְלִים מֵהֶם פִּדְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר. וְעַל כָּךְ בִּימֵי דָוִד, כְּשֶׁעָשָׂה חֶשְׁבּוֹן בְּיִשְׂרָאֵל וְלֹא נָטַל מֵהֶם פִּדְיוֹן, הָיָה רֹגֶז, וְנֶאֶבְדוּ מִיִּשְׂרָאֵל כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב בְּמַעֲשֵׂה הַמִּשְׁכָּן, וְכֶסֶף פְּקוּדֵי הָעֵדָה וְגוֹ', לְכֹל הָעֹבֵר עַל הַפְּקֻדִים. וְהַכֹּל הִתְקַדֵּשׁ לַעֲבוֹדַת הַמִּשְׁכָּן, וַהֲרֵי פֵּרְשׁוּהָ - כִּכָּרִים חֶשְׁבּוֹן אֶחָד, שְׁקָלִים חֶשְׁבּוֹן אֶחָד. מִשּׁוּם שֶׁיֵּשׁ עֶלְיוֹנִים שֶׁעוֹלִים לְחֶשְׁבּוֹן עֶלְיוֹן, וְיֵשׁ אֲחֵרִים שֶׁעוֹלִים לְחֶשְׁבּוֹן אַחֵר. זֶה עֶלְיוֹן וְזֶה תַּחְתּוֹן. וּמִשּׁוּם כָּךְ כָּתוּב וַיְהִי מְאַת כִּכָּר הַכֶּסֶף לָצֶקֶת אֵת אַדְנֵי הַקֹּדֶשׁ וְגוֹ'. אֵלֶּה הָאֲדָנִים, הֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011876,"<p>עוֹד פָּתַח וְאָמַר, (תהלים קכז) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם ה' לֹא יִבְנֶה בַיִת וְגוֹ'. פָּסוּק זֶה שְׁלֹמֹה הַמֶּלֶךְ אָמַר אוֹתוֹ בְּשָׁעָה שֶׁהָיָה בּוֹנֶה אֶת בֵּית הַמִּקְדָּשׁ וְהִתְחִיל לִבְנוֹת, וְהָיָה רוֹאֶה שֶׁהַמַּעֲשֶׂה מִתְתַּקֵּן בִּידֵיהֶם וְהָיָה נִבְנֶה מֵעַצְמוֹ, וְאָז הִתְחִיל וְאָמַר, אִם ה' לֹא יִבְנֶה בַיִת וְגוֹ'. הַיְנוּ הַסּוֹד שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא וְהִתְקִין אֶת הָעוֹלָם הַזֶּה בְּכָל מַה שֶּׁצָּרִיךְ, שֶׁהוּא בַּיִת.</p>\n<p>שָׁוְא עָמְלוּ בוֹנָיו בּוֹ - אֵלֶּה סוֹד שֶׁל אוֹתָם נְהָרוֹת (נחלים) שֶׁיּוֹצְאִים וְנִכְנָסִים כֻּלָּם בְּתוֹךְ הַבַּיִת הַזֶּה לְהַתְקִינוֹ בְּכָל מַה שֶּׁצָּרִיךְ. וְאַף עַל גַּב שֶׁכֻּלָּם בָּאִים לְתַקֵּן וְלַעֲשׂוֹת אֶת תִּקּוּנוֹ, וַדַּאי אִם ה' - שֶׁהוּא סוֹד הָעוֹלָם הָעֶלְיוֹן, שֶׁהִתְקִין (ביתו ולא עשה) וְעָשָׂה אֶת הַבַּיִת כָּרָאוּי, אוֹתָם בּוֹנִים לְחִנָּם הֵם, אֶלָּא רַק מַה שֶּׁהוּא עוֹשֶׂה וּמַתְקִין. אִם ה' לֹא יִשְׁמָר עִיר, כְּמוֹ שֶׁכָּתוּב (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ מֵרֵשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה, וּפֵרְשׁוּהָ. וּבַהַשְׁגָּחָה הַזּוֹ הִיא שְׁמוּרָה מִכָּל הַצְּדָדִים.</p>\n<p>וְאַף עַל גַּב שֶׁכָּתוּב (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ מִגִּבֹּרֵי יִשְׂרָאֵל, וְכֻלָּם שׁוֹמְרִים אוֹתָהּ. מָה הַטַּעַם הֵם שׁוֹמְרִים אוֹתָהּ? מִשּׁוּם שֶׁכָּתוּב מִפַּחַד בַּלֵּילוֹת, זֶהוּ פַּחַד הַגֵּיהִנֹּם שֶׁעוֹמֵד כְּנֶגְדָּהּ כְּדֵי לִדְחוֹתָהּ, וּמִשּׁוּם כָּךְ כֻּלָּם מַקִּיפִים אוֹתָהּ.</p>\n<p>וְאַף עַל גַּב שֶׁכֻּלָּם עוֹמְדִים בְּאוֹר הַמַּחֲשָׁבָה שֶׁלֹּא נוֹדָע, וְאָז אוֹר הַמַּחֲשָׁבָה הַזֶּה שֶׁלֹּא נוֹדָע מַכֶּה בָּאוֹר שֶׁל הַמָּסָךְ, וּמְאִירִים כְּאֶחָד וְנַעֲשִׂים תֵּשַׁע הֵיכָלוֹת.</p>\n<p>וְהַהֵיכָלוֹת אֵינָם מְאִירִים, וְאֵינָם רוּחוֹת, וְאֵינָם נְשָׁמוֹת, וְאֵין מִי שֶׁיַּעֲמֹד בָּהֶם. רְצוֹן כָּל תִּשְׁעַת הַמְּאוֹרוֹת שֶׁכֻּלָּם עוֹמְדִים בְּמַחֲשָׁבָה, שֶׁהִיא אַחַת מֵהֶן בְּחֶשְׁבּוֹן, שֶׁכֻּלָּם לִרְדּף אַחֲרֵיהֶם בְּשָׁעָה שֶׁעוֹמְדִים בְּמַחֲשָׁבָה. וְלֹא נִדְבָּקִים וְלֹא נוֹדָעִים, אֵלֶּה לֹא עוֹמְדִים לֹא בְרָצוֹן וְלֹא בְמַחֲשָׁבָה עֶלְיוֹנָה. תּוֹפְסִים בָּהּ וְלֹא תוֹפְסִים. בְּאֵלֶּה עוֹמְדִים כָּל סוֹדוֹת הָאֱמוּנָה וְכָל אוֹתָם מְאוֹרוֹת מִסּוֹד הַמַּחֲשָׁבָה הָעֶלְיוֹנָה, שֶׁלְּמַטָּה כֻּלָּם נִקְרָאִים אֵין סוֹף. עַד כָּאן מַגִּיעִים הַמְּאוֹרוֹת וְלֹא מַגִּיעִים וְלֹא נוֹדָעִים. אֵין כָּאן מַחֲשָׁבָה וְלֹא רָצוֹן.</p>\n<p>כְּשֶׁמְּאִירָה הַמַּחֲשָׁבָה וְלֹא נוֹדָע מִמַּה מְּאִירָה, אֲזַי מִתְלַבֶּשֶׁת וְנִסְתֶּרֶת בְּתוֹךְ הַבִּינָה, וּמְאִירָה (מי) לְמַה שֶּׁמְּאִירָה, וְנִכְנָסִים זֶה בָּזֶה, עַד שֶׁכֻּלָּם נִכְלָלִים כְּאֶחָד, וַהֲרֵי פֵּרְשׁוּהָ. וּבְסוֹד הַקָּרְבָּן, כְּשֶׁהַכֹּל עוֹלֶה, נִקְשָׁר זֶה בָּזֶה וּמֵאִיר זֶה בָּזֶה, אָז עוֹמְדִים כֻּלָּם בַּעֲלִיָּה, וְהַמַּחֲשָׁבָה מִתְעַטֶּרֶת בָּאֵין סוֹף, אוֹתוֹ הָאוֹר שֶׁמְּאִירָה מִמֶּנּוּ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה נִקְרָא אֵין סוֹף.</p>\n<p>כֵּיוָן שֶׁמֵּאִיר וּמִתְפַּשְּׁטִים מִמֶּנּוּ חֲיָלוֹת, אוֹתָהּ מַחֲשָׁבָה נִגְנֶזֶת וְנִסְתֶּרֶת וְלֹא יְדוּעָה, וּמִשָּׁם מִתְפַּשֶּׁטֶת הִתְפַּשְּׁטוּת לְכָל הַצְּדָדִים, וּמִתְפַּשֶּׁטֶת מִמֶּנּוּ הִתְפַּשְּׁטוּת אַחַת, שֶׁהִיא סוֹד הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וְזְהִ עוֹמֵד בִּשְׁאֵלָה, וְהוּא מַאֲמָר עֶלְיוֹן, וּפֵרְשׁוּהָ שֶׁנִּקְרֵאת מִי, שֶׁכָּתוּב (ישעיהמ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. שְׁאֵלָה אוֹתוֹ שֶׁבָּרָא אֵלֶּה. אַחַר כָּךְ הִתְפַּשֵּׁט וְנַעֲשָׂה יָם, סוֹף כָּל הַדְּרָגוֹת, שֶׁהִיא לְמַטָּה. וּמִשָּׁם מַתְחִיל לִבְנוֹת לְמַטָּה, וְהַכֹּל עָשָׂה בְּאוֹתָהּ צוּרָה מַמָּשׁ שֶׁלְּמַעְלָה, זֶה כְּנֶגֶד זֶה וְזֶה כְּדֻגְמַת זֶה. וּמִשּׁוּם כָּךְ שְׁמִירַת הַכֹּל מִמַּעְלָה וּמַטָּה.</p>\n<p>וְהִתְפַּשְּׁטוּת זוֹ, שֶׁהִיא מַחֲשָׁבָה, שֶׁהִיא עוֹלָם הָעֶלְיוֹן. וְזֶהוּ אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר, שֶׁהוּא שׁוֹמֵר יִשְׂרָאֵל. (שואשקדשומר, זהו שכתוב בו (משלי כז) ושמר אדניו יכבד) שֶׁלֹּא עוֹמֵד בּוֹ שְׁמִירָה אֶלָּא בָּעוֹלָם הָעֶלְיוֹן.</p>\n<p>בֹּא וּרְאֵה, תְּכֵלֶת הַמִּשְׁכָּן, הַכֹּל עוֹמֵד בְּסוֹד עֶלְיוֹן, וּפֵרְשׁוּהָ. תְּכֵלֶת וְאַרְגָּמָן, אֶחָד לְהִתְקַשֵּׁר בְּאֶחָד. וַהֲרֵי נֶאֱמַר בְּסוֹד הַכָּתוּב, (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא. וַהֲרֵי נֶאֱמַר שֶׁיֵּשׁ אוֹכֶלֶת אֵשׁ, וְאוֹכֶלֶת אוֹתָהּ וּמַשְׁמִידָה אוֹתָהּ, מִשּׁוּם שֶׁיֵּשׁ אֵשׁ חֲזָקָה מֵאֵשׁ, וְנִתְבָּאֵר.</p>"],[9522011877,"<p>וְאֶת הָאֶלֶף וּשְׁבַע הַמֵּאוֹת וַחֲמִשָּׁה וְשִׁבְעִים עָשָׂה וָוִים לָעַמּוּדִים וְצִפָּה רָאשֵׁיהֶם וְגוֹ'. בֹּא וּרְאֵה, לָמַדְנוּ שֶׁאוֹתָם שְׁקָלִים שָׁכַח אוֹתָם מֹשֶׁה וְלֹא יָדַע מַה נַּעֲשָׂה מֵהֶם, עַד שֶׁיָּצָא קוֹל וְאָמַר: וְאֶת הָאֶלֶף וּשְׁבַע הַמֵּאוֹת וַחֲמִשָּׁה וְשִׁבְעִים עָשָׂה וָוִים לָעַמּוּדִים.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. הַפָּסוּק הַזֶּה נִתְבָּאֵר. אֲבָל עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁנָּתַן תּוֹרָה לְיִשְׂרָאֵל וּבָא לְסִינַי, וְכַמָּה מֶרְכָּבוֹת הָיוּ עִמּוֹ, כֻּלָּם מֶרְכָּבוֹת קְדוֹשׁוֹת, וְכָל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת שֶׁל קְדֻשַּׁת הַתּוֹרָה כֻּלָּם הָיוּ שָׁם, וְתוֹרָה נִתְּנָה בְּלִהוּטִים שֶׁל אֵשׁ, וְהַכֹּל בְּצַד הָאֵשׁ, וּכְתוּבָה בְּאֵשׁ לְבָנָה עַל גַּבֵּי אֵשׁ שְׁחֹרָה, וְהָאוֹתִיּוֹת הָיוּ פוֹרְחוֹת וְעוֹלוֹת בָּאֲוִיר.</p>\n<p>וְהָאוֹת הָרִאשׁוֹנָה שֶׁל הַתּוֹרָה נֶחְלְקָה לִשְׁבַע מֵאוֹת וְשִׁבְעִים וַחֲמִשָּׁה לְכָל צַד, וְכֻלָּם נִרְאוּ בַּאֲוִיר הָרָקִיעַ בָּאוֹת ו', ו' לְצַד זֶה, ו' לְצַד זֶה. וְכֵן לְכָל הַצְּדָדִים.</p>\n<p>וְאֵלּוּ הַוָּוִין הָיוּ עוֹמְדִים עַל עַמּוּדִים, וְאוֹתָם הָעַמּוּדִים הָיוּ עוֹמְדִים עַל נֵס, וְכָל הַוָּוִים עֲלֵיהֶם. מִשּׁוּם שֶׁסּוֹד הַתּוֹרָה עוֹמֵד עַל וָ\"ו. וְאוֹתָן וָוִי\"ם שֶׁהֵם סוֹד הָאֱמוּנָה שֶׁל הַתּוֹרָה, כֻּלָּם עוֹמְדִים עַל עַמּוּדִים, שֶׁהֵם סוֹדוֹת שֶׁיּוֹצְאִים בָּהֶם נְבִיאִים, הַסּוֹד שֶׁלָּהֶם בְּכָל צַד. וְעַל אוֹתָם עַמּוּדִים עוֹמְדִים אוֹתָם הַוָּוִי\"ם.</p>\n<p>ו' עֶלְיוֹנָה הִיא סוֹד הַקּוֹל שֶׁנִּשְׁמַע, וְהוּא הַסּוֹד שֶׁעוֹמֶדֶת בּוֹ הַתּוֹרָה, מִשּׁוּם שֶׁתּוֹרָה יוֹצֵאת מֵאוֹתוֹ קוֹל פְּנִימִי, שֶׁנִּקְרָא קוֹל גָּדוֹל. וְהַקּוֹל הַגָּדוֹל הַזֶּה הוּא סוֹד הַתּוֹרָה, וְעַל זֶה כָּתוּב, (דברים ה) קוֹל גָּדוֹל וְלֹא יָסָף.</p>\n<p>בֹּא וּרְאֵה, הַקּוֹל הַגָּדוֹל הַזֶּה הוּא עִקַּר הַכֹּל וְסוֹד הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, וְעַל זֶה פֵּרְשׁוּהָ שֶׁאָסוּר לְאָדָם לְהַקְדִּים שָׁלוֹם לַחֲבֵרוֹ טֶרֶם שֶׁיִּתְפַּלֵּל תְּפִלָּתוֹ, וְסוֹד זֶה פֵּרְשׁוּהוּ, שֶׁכָּתוּב (משלי כז) מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּם קְלָלָה תֵּחָשֶׁב לוֹ. וְאֵינוֹ אָסוּר, עַד שֶׁמְּבָרֵךְ אוֹתוֹ בְּקוֹל גָּדוֹל, שֶׁהוּא עִקַּר הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וְלָכֵן סוֹד הַתּוֹרָה יוֹצֵא מֵאוֹתוֹ קוֹל גָּדוֹל, וְזֶהוּ מֶלֶךְ. בִּמְסִבּוֹ - זֶה מַעֲמַד הַר סִינַי, וּפֵרְשׁוּהָ נִרְדִּי נָתַן רֵיחוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁאָמְרוּ יִשְׂרָאֵל, (שמות כד) כָּל אֲשֶׁר דִּבֶּר ה' נַעֲשֶׂה וְנִשְׁמָע. שֶׁהַמֶּלֶךְ - זֶהוּ הַמֶּלֶךְ הָעֶלְיוֹן, וּפֵרְשׁוּהָ.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁהֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא מַבּוּל עַל הָעוֹלָם כְּדֵי לְהַשְׁחִית הַכֹּל, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ: צָרִיךְ אַתָּה (להסתתר) לְהִשָּׁמֵר שֶׁלֹּא תַרְאֶה אֶת עַצְמְךְ לִפְנֵי הַמַּשְׁחִית, שֶׁלֹּא יִשְׁלֹט עָלֶיךְ, מִשּׁוּם שֶׁלֹּא הָיָה מִי שֶׁיָּגֵן עָלָיו. כֵּיוָן שֶׁנִּקְרַב הַקָּרְבָּן שֶׁהִקְרִיב נֹחַ, אָז הִתְבַּשֵּׂם הָעוֹלָם, וְלֹא הִתְבַּסֵּם כָּל כָּךְ עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי. כֵּיוָן שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, אָז הִתְבַּשֵּׂם הָעוֹלָם, וְהַמַּשְׁחִית לֹא נִמְצָא בָּעוֹלָם.</p>\n<p>וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ זְמַן לְהַעֲבִיר אֶת אוֹתוֹ מַשְׁחִית מֵהָעוֹלָם, (וכאשר) רַק שֶׁיִּשְׂרָאֵל סָרְחוּ בְּאוֹתוֹ זְמַן לְיָמִים מוּעָטִים וְעָשׂוּ אֶת הָעֵגֶל. וְאָז מַה כָּתוּב? (שם לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. וְעֶדְיָם הָיָה סוֹדוֹת הַשֵּׁם הַקָּדוֹשׁ שֶׁעִטֵּר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִטַּל מֵהֶם, וְאָז שָׁלַט הַמַּשְׁחִית עַל הָעוֹלָם וְחָזַר כְּמִקֹּדֶם, כְּמוֹ בְּאוֹתוֹ זְמַן שֶׁשָּׁלַט בָּעוֹלָם, וְעָשָׂה דִּין.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בִּימֵי הַמַּבּוּל מִי נָתַן שָׁם מַשְׁחִית? שֶׁהֲרֵי הַמַּיִם הָיוּ שֶׁנִּתְגַּבְּרוּ. בּא וּרְאֵה, אֵין לְךְ דִּין בָּעוֹלָם, אוֹ כְּשֶׁמֻּכֶּה הָעוֹלָם בְּדִין, שֶׁלֹּא נִמְצָא בֵינֵיהֶם אוֹתוֹ הַמַּשְׁחִית שֶׁהוֹלֵךְ בְּתוֹךְ אוֹתָם הַדִּינִים שֶׁנַּעֲשִׂים בָּעוֹלָם. אַף כָּאן הָיָה מַבּוּל, וְהַמַּשְׁחִית הָיָה הוֹלֵךְ בְּתוֹךְ הַמַּבּוּל, וְהוּא נִקְרָא כָּךְ. וְלָכֵן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ לִטְמֹן עַצְמוֹ וְלֹא יִתְרָאֶה בָּעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא וּרְאֵה, אָמַר רַבִּי אֶלְעָזָר, וְאֶת הָאֶלֶף וּשְׁבַע הַמֵּאוֹת וַחֲמִשָּׁה וְשִׁבְעִים עָשָׂה וָוִים לָעַמּוּדִים. לָמָּה וָוִים? אֶלָּא כְּמוֹ מִין וָ\"ו הָיוּ, וְרֹאשָׁם מְצֻפֶּה זָהָב. הֵם שֶׁל כֶּסֶף, וְרֹאשָׁם מְצֻפֶּה זָהָב, מִשּׁוּם שֶׁכָּל וָ\"ו בָּא בְּצַד הָרַחֲמִים, וְכֻלָּם הָיוּ יוֹדְעִים לְמַעְלָה בַּחֶשְׁבּוֹן. וּמִשּׁוּם שֶׁבָּאוּ מִצַּד הָרַחֲמִים הָיוּ נִקְרָאִים וָוִי\"ם, וְכָל הַשְּׁאָר תְּלוּיִים בָּהֶם. וְאֵין וָ\"ו אֶלָּא זָהָב וָכֶסֶף כְּאֶחָד. וּמִשּׁוּם כָּךְ כָּל אֵלּוּ נִקְרְאוּ וָוִים שֶׁל אוֹתָם עַמּוּדִים. אֵילוּ עַמּוּדִים? כְּמוֹ שֶׁנֶּאֱמַר וְהָעַמּוּדִים שְׁנַיִם וְגוֹ'. מִשּׁוּם שֶׁהֲרֵי אֵלֶּה הֵם מִחוּץ לַגּוּף, לְמַטָּה הָיוּ עוֹמְדִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, לֹא יָדַעְתִּי אִם זוֹ עֲבוֹדַת קֹדֶשׁ אוֹ חֹל, מִשּׁוּם שֶׁכָּתוּב וְאֶת הָאֶלֶף. שֶׁהֲרֵי כָּתוּב כָּאן הָאֶלֶף, וְכָתוּב שָׁם (שיר ח) הָאֶלֶף לְךְ שְׁלֹמֹה. מַה לְּהַלָּן הָאֶלֶף חֹל - אַף כָּאן הָאֶלֶף חֹל.</p>\n<p>אָמַר לוֹ, לֹא כָּךְ! שֶׁאִם הוּא הָיָה חֹל, לֹא הָיוּ נַעֲשִׂים מִמֶּנּוּ וָוִים. וְעוֹד, שֶׁהֲרֵי שָׁם כָּתוּב הָאֶלֶף וְלֹא יוֹתֵר, וְכָאן כָּתוּבּ הָאֶלֶף וּשְׁבַע הַמֵּאוֹת וַחֲמִשָּׁה וְשִׁבְעִים. הָאֶלֶף שֶׁשָּׁם הֵם חֹל, שֶׁכָּתוּב הָאֶלֶף לְךְ שְׁלֹמֹה, וְזֶהוּ חֹל, מִשּׁוּם שֶׁכָּל חֹל אֵינוֹ בְּצַד הַקְּדֻשָּׁה כְּלָל. חֹל הוּא מֵהַצַּד הָאַחֵר הַטָּמֵא, וְעַל זֶה הַבְדָּלָה בֵּין קֹדֶשׁ לְחֹל, מִשּׁוּם שֶׁצְּרִיכִים לְהַבְדִּיל בֵּין קֹדֶשׁ לְחֹל. וְסוֹד הַכָּתוּב כָּךְ הוּא - (ויקרא י) וּלֲהַבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין הַחֹל וּבֵין הַטָּמֵא וּבֵין הַטָּהוֹר.</p>\n<p>וְעִם כָּל זֶה, אַף עַל גַּב שֶׁהַפְרָדָה יֵשׁ לַקֹּדֶשׁ מִן הַחֹל, חֵלֶק אֶחָד יֵשׁ לוֹ בַּקְּדֻשָּׁה מִצַּד הַשְּׂמֹאל. זֶהוּ שֶׁכָּתוּב הָאֶלֶף לְךְ שְׁלֹמֹה, שֶׁהֵם אֶלֶף יְמֵי הַחֹל, וְהֵם יְמֵי הַגָּלוּת. כְּמוֹ שֶׁיֵּשׁ אֶלֶף יָמִים שֶׁל קְדֻשָּׁה, כָּךְ גַּם אֶלֶף יָמִים לַצַּד הָאַחֵר. וְעַל זֶה הֵעִירוּ הַחֲבֵרִים, שֶׁאוֹתָם יְמֵי הַגָּלוּת יִהְיוּ אֶלֶף שָׁנִים.</p>\n<p>וְעַל כֵּן, יֵשׁ אֶלֶף וְיֵשׁ אֶלֶף, וְאוֹתָן אֶלֶף שְׁנוֹת הַגָּלוּת, אַף עַל גַּב שֶׁיִּשְׂרָאֵל יִהְיוּ בַגָּלוּת וְיִתְמַשְּׁכוּ יוֹתֵר - בְּאֶלֶף הַשָּׁנִים הַלָּלוּ הֵם יִתְמַשְּׁכוּ, שֶׁל אוֹתָם אֶלֶף יָמִים שֶׁאָמַרְנוּ. וּמִשּׁוּם כָּךְ פֵּרְשׁוּהָ, כָּל שְׁלֹמֹה שֶׁיֵּשׁ בְּשִׁיר הַשִּׁירִים - קֹדֶשׁ, פְּרָט לָזֶה שֶׁהוּא חֹל. הָאֶלֶף שֶׁל כָּאן הוּא קֹדֶשׁ, וְכָל מַעֲשָׂיו קֹדֶשׁ, וְעַל זֶה עָשָׂה וָוִים לָעַמּוּדִים.</p>\n<p>בֹּא וּרְאֵה, הֲרֵי אָמַרְנוּ, כָּל ו' הוּא בְּסוֹד הָרַחֲמִים, וְכָל מָקוֹם שֶׁבָּא ו' בַּשֵּׁם הַקָּדוֹשׁ, הוּא רַחֲמִים, כְּמוֹ (בראשיתיט) וַה' הִמְטִיר עַל סְדם. (שם יג) וַה' אָמַר אֶל אַבְרָם. רַחֲמִים וְדִין כְּאֶחָד. שֶׁמַּה שּׁוֹנָה בַּמַּבּוּל שֶׁכָּתוּב אֱלֹהִים בְּכָל מָקוֹם? לָמָּה לֹא כָתוּב וַה'? אֶלָּא שָׁנִינוּ, בְּכָל מָקוֹם שֶׁכָּתוּב וַה' - הוּא וּבֵית דִּינוֹ. אֱלֹהִים סְתָם - דִּין לְבַדּוֹ.</p>\n<p>אֶלָּא בִּסְדוֹם נַעֲשָׂה דִּין, וְלֹא כְּדֵי לְהַשְׁמִיד אֶת הָעוֹלָם, וּמִשּׁוּם כָּךְ הוּא הִתְעָרֵב עִם דִּין. אֲבָל בַּמַּבּוּל כָּל הָעוֹלָם הֻשְׁמַד, וְכָל אוֹתָם שֶׁנִּמְצְאוּ בָעוֹלָם. וְאִם תֹּאמַר, שֶׁהֲרֵי נֹחַ וְכָל מַה שֶּׁעִמּוֹ נִצְּלוּ - הֲרֵי נִסְתָּר מֵהָעַיִן הָיָה, שֶׁלֹּא נִרְאָה, וְעַל כֵּן כָּל מַה שֶּׁנִּמְצָא בָּעוֹלָם הִשְׁמִיד אוֹתוֹ.</p>\n<p>וְעַל זֶה וַה' - בְּגָלוּי, וְלֹא הִשְׁמִיד הַכֹּל. אֱלֹהִים - נִסְתָּר, וְצָרִיךְ לְהִשָּׁמֵר, שֶׁהֲרֵי מַשְׁמִיד הַכֹּל. וְלָכֵן אֱלֹהִים לְבַדּוֹ הָיָה, וְסוֹד זֶה - (תהלים כט) ה' לַמַּבּוּל יָשָׁב. מַה זֶּה יָשָׁב? אִלְמָלֵא מִקְרָא כָּתוּב, לֹא יְכוֹלִים לוֹמַר. יָשָׁב - יָשַׁב לְבַדּוֹ, שֶׁלֹּא בָא עִם דִּין. כָּתוּב כָּאן יָשָׁב, וְכָתוּב שָׁם (ויקרא יג) בָּדָד יֵשֵׁב, לְבַדּוֹ.</p>\n<p>וְסוֹד לָמַדְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתָּר וְגָלוּי. גָּלוּי הוּא בֵּית דִּין שֶׁלְּמַטָּה. נִסְתָּר הוּא הַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִשָּׁם. מִשּׁוּם כָּךְ, כָּל דִּבְרֵי אָדָם שֶׁהֵם בְּנִסְתָּר, הַבְּרָכוֹת שׁוֹרוֹת עָלָיו. וְכָל אוֹתָם שֶׁבְּגָלוּי, אוֹתוֹ מָקוֹם שֶׁל בֵּית דִּין שׁוֹרֶה עָלָיו, מִשּׁוּם שֶׁהוּא מָקוֹם בְּגָלוּי. וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>עֵד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ (שירא), בְּאוֹתָהּ חֲבֵרוּת וְתַפְנוּק שֶׁל הָעֵדֶן הָעֶלְיוֹן, (הרי בארנו שזה) בְּאוֹתוֹ שְׁבִיל נִסְתָּר וְגָנוּז וְלֹא יָדוּעַ, וּמִתְמַלֵּא מִמֶּנּוּ, וְיוֹצְאִים בִּנְחָלִים יְדוּעִים. נֵרְדִּי נָתַן רֵיחוֹ - זֶה הַיָּם הָאַחֲרוֹן שֶׁבָּרָא אֶת הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ שֶׁלְּמַעְלָה, וּמַעֲלֶה רֵיחַ טוֹב עֶלְיוֹן לִשְׁלֹט וְלַעֲשׂוֹת, וְיָכוֹל וְשׁוֹלֵט וּמֵאִיר בְּאוֹר עֶלְיוֹן.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַנֵּרְדְּ הַזֶּה הֶעֱלָה רֵיחַ לְמַעְלָה, אָז הַחֲבִיבוּת נִקְשְׁרָה, וְעוֹלָה הַנֵּרְדְּ הַזֶּה לְהֵאָחֵז לְמַעְלָה, וְכָל הַמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת, כֻּלָּן מַעֲלוֹת רֵיחוֹת לְהִתְעַטֵּר לְמַעְלָה. כָּל אוֹתָן מֶרְכָּבוֹת נִקְרָאוֹת עֲלָמוֹת שִׁיר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מז) עַל עֲלָמוֹת שִׁיר, וַהֲרֵי פֵּרְשׁוּהָ. מַה זֶּה עֲלָמוֹת שִׁיר? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) וַעֲלָמוֹת אֵין מִסְפָּר. מַה זֶּה וַעֲלָמוֹת אֵין מִסְפָּר? כְּמוֹ שֶׁנֶּאֱמַר (איוב כה) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. וּמִשּׁוּם שֶׁאֵין לָהֶם חֶשְׁבּוֹן, כָּתוּב וַעֲלָמוֹת אֵין מִסְפָּר.</p>\n<p>וָוִים לָעַמּוּדִים, כֻּלָּם זְכָרִים. כָּל אוֹתָם שֶׁעוֹלִים בְּשֶׁמֶן מִשְׁחָה לְמַעְלָה, כֻּלָּם עוֹמְדִים בְּסוֹד שֶׁל זְכָרִים, וְלֹא נִקְרָא זָכָר אֶלָּא ו', סוֹד שֶׁל הַשָּׁמַיִם, שֶׁהֵם זְכָרִים. וְכָל אוֹתָם שֶׁלְּמַטָּה נִקְרָאִים נְקֵבוֹת. וּמִשּׁוּם כָּךְ, כָּל אוֹתָם שֶׁבָּאִים מִצַּד הַשְּׂמֹאל, מִצַּד הַנְּקֵבָה, הִתְמַנּוּ עַל הַשִּׁיר וְאוֹמְרִים שִׁירָה תָּמִיד. וְעַל זֶה כָּתוּב עַל עֲלָמוֹת שִׁיר. וְכֻלָּם יוֹצְאִים בְּסוֹד שֶׁל ה'. ה' מוֹצִיאָה כַּמָּה חֲיָלוֹת לְמִינֵיהֶם בְּסוֹד שֶׁל ו'. ו' - זֶה סוֹד שֶׁל זָכָר שֶׁעוֹמֵד לָתֵת מָזוֹן לַנְּקֵבָה.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל אוֹתָם הַוָּוִים עָשָׂה בְּצַלְאֵל, לָתֵת לָהֶם לִשְׁרוֹת עַל הַנְּקֵבוֹת, וְיוֹצְאִים מִסּוֹד שֶׁל אֶלֶף, שֶׁהוּא חֶשְׁבּוֹן שָׁלֵם. וּשְׁבַע מֵאוֹת, שֶׁהוּא סוֹד שָׁלֵם. וַחֲמִשָּׁה, גַּם כָּךְ. וְשִׁבְעִים, הַכֹּל סוֹד אֶחָד. וְעַל זֶה מִסּוֹד שֶׁל כָּךְ וְחֶשְׁבּוֹן זֶה עָשָׂה וָוִים. וְכֻלָּם בְּסוֹד שֶׁל ו', וּבִדְמוּת שֶׁל ו' נַעֲשׂוּ, וְהַכֹּל בְּסוֹד עֶלְיוֹן וּבְחֶשְׁבּוֹן לוֹקְחִים.'</p>"],[9522011878,"<p>וּנְחֹשֶׁת הַתְּנוּפָה שִׁבְעִים כִּכָּר. אָמַר רַבִּי יְהוּדָה, כָּל זֶה יָרַד לְמַטָּה בִּדְיוֹקָן עֶלְיוֹן שֶׁל סוֹד הָאֱמוּנָה. כְּמוֹ כֵן עָשָׂה נְבוּכַדְנֶצַּר הָרָשָׁע אוֹתוֹ הַצֶּלֶם שֶׁהִתְקִין. אָמַר רַבִּי יוֹסֵי, הוּא לֹא עָשָׂה כָּךְ, אֲבָל בַּחֲלוֹמוֹ רָאָה כָּךְ, שֶׁהֲרֵי בַּחֲלוֹמוֹ רָאָה רֹאשׁ שֶׁל זָהָב, אַחַר כָּךְ כֶּסֶף, וְאַחַר כָּךְ נְחֹשֶׁת. וְאִם תֹּאמַר, בַּרְזֶל וְחֶרֶס לָמָּה לֹא כָּךְ? מִשּׁוּם שֶׁאֵינָם כְּדָאִים לְהִכָּנֵס לַקֹּדֶשׁ, וְאֵלֶּה שְׁלֹשֶׁת הָאֲחֵרִים נִכְנְסוּ.</p>\n<p>וְסוֹדוֹ שֶׁל הַמִּשְׁכָּן בְּשָׁלֹשׁ שָׁלֹשׁ בְּאֵלֶּה הַמַּתָּכוֹת. וּבַשְּׁאָר אַרְבָּעָה, כְּמוֹ תְּכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי וְשֵׁשׁ. וּכְמוֹ אַרְבָּעָה טוּרֵי אֶבֶן.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מֵהֶם בִּשְׁלֹשָׁה, מֵהֶם בְּאַרְבָּעָה, מֵהֶם בִּשְׁנַיִם, מֵהֶם בְּאֶחָד. אֲבָל כָּל מַעֲרָכָה וּמַעֲרָכָה אֵינָהּ אֶלָּא בְּשָׁלֹשׁ. שָׁלֹשׁ מַעֲרָכוֹת הֵן שֶׁנִּפְרָדוֹת לְכָל צַד, לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְכָל מַעֲרָכָה וּמַעֲרָכָה שֶׁהִיא לְכָל צַד, שָׁלֹשׁ מַעֲרָכוֹת הֵן, וּבֵאַרְנוּ.</p>\n<p>מַעָרָכָה רִאשׁוֹנָה שֶׁלְּצַד מִזְרָח - שָׁלֹשׁ מַעֲרָכוֹת הֵן, וְהֵן תֵּשַׁע מַעֲרָכוֹת. מִשּׁוּם שֶׁכָּל מַעֲרָכָה מֵאוֹתָן שָׁלֹשׁ יֵשׁ לָהּ שָׁלֹשׁ מַעֲרָכוֹת, וְנִמְצָא שֶׁהֵן תֵּשַׁע. וְכַמָּה אֶלֶף וּרְבָבוֹת תַּחְתֵּיהֶן. וְתֵשַׁע הַמַּעֲרָכוֹת הַלָּלוּ, כֻּלָּן מִתְנַהֲגוֹת בְּאוֹתִיּוֹת רְשׁוּמוֹת. וְכָל מַעֲרָכָה מִסְתַּכֶּלֶת אֶל אוֹתָן הָאוֹתִיּוֹת הָרְשׁוּמוֹת, וַהֲרֵי פֵּרְשׁוּהָ. וְכֵן לְכָל מַעֲרָכָה וּמַעֲרָכָה, וְכֻלָּן נוֹסְעוֹת בְּאוֹתִיּוֹת רְשׁוּמוֹת. וְאֵלּוּ עֶלְיוֹנוֹת מֵאֵלּוּ, וְעוֹמְדוֹת אֵלּוּ עַל אֵלּוּ. (ומתחברות כלן ואומרות שירה).</p>\n<p>וּכְשֶׁפּוֹרְחוֹת אוֹתָן הָאוֹתִיּוֹת לְתוֹךְ אֲוִיר הָרוּחַ, אוֹתוֹ הַמְמֻנֶּה עַל הַכֹּל, אָז כֻּלָּן נוֹסְעוֹת, (והשירה מתבסמת) וַהֲרֵי פֵּרְשׁוּהָ. וְאוֹת אַחַת מַכָּה מִלְּמַטָּה, וְאוֹתָהּ הָאוֹת עוֹלָה וְיוֹרֶדֶת, וּשְׁתֵּי אוֹתִיּוֹת פּוֹרְחוֹת עֲלֵיהֶן. וְהָאוֹת הַזּוֹ מִלְּמַטָּה, עוֹלָה מִלְּמַטָּה לְמַעְלָה וּמִתְחַבֶּרֶת בָּהֶן, וְנַעֲשׂוֹת שָׁלֹשׁ אוֹתִיּוֹת, כֻּלָּן לְפִי אוֹתִיּוֹת יה\"ו, שֶׁהֵן שָׁלֹשׁ תּוֹךְ אַסְפַּקְלַרְיָה הַמְּאִירָה. מֵאֵלֶּה נִפְרְדוּ שָׁלֹשׁ מַעֲרָכוֹת. וְהֵן שְׁתֵּי אוֹתִיּוֹת, וְאוֹתָהּ הָאוֹת שֶׁעוֹלָה מִתְחַבֶּרֶת עִמָּהֶן, וְהֵן שָׁלֹשׁ.</p>\n<p>בֹּא וּרְאֵה, אוֹתָן שְׁתֵּי אוֹתִיּוֹת עֶלְיוֹנוֹת שֶׁעוֹלוֹת בָּאֲוִיר, הֵן כְּלוּלוֹת זוֹ בָּזוֹ, רַחֲמִים וְדִין, וּמִשּׁוּם כָּךְ הֵן שְׁתַּיִם, וְהֵן מֵהָעוֹלָם שֶׁלְּמַעְלָה בְּסוֹד הַזָּכָר. וְזוֹ שֶׁעוֹלָה וּמִתְחַבֶּרֶת עִמָּהֶן הִיא נְקֵבָה, וְנִכְלֶלֶת בִּשְׁתֵּיהֶן.</p>\n<p>כְּמוֹ שֶׁנְּקֵבָה נִכְלֶלֶת בִּשְׁנֵי צְדָדִים, בְּיָמִין וּשְׂמֹאל, וּמִתְחַבֶּרֶת בָּהֶן - כָּךְ גַּם הָאוֹת הַזּוֹ נְקֵבָה, וּמִתְחַבֶּרֶת בִּשְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן בִּשְׁנֵי צְדָדִים. אֵלּוּ עֶלְיוֹנִים וְאֵלּוּ תַּחְתּוֹנִים. וְהַכֹּל הוּא אֶחָד, זָכָר וּנְקֵבָה.</p>\n<p>שֶׁכְּשֶׁנִּבְרָא הָעוֹלָם, אוֹתָן הָאוֹתִיּוֹת הֵן מֵהָעוֹלָם הָעֶלְיוֹן, שֶׁהֵן הוֹלִידוּ כָּל הַמַּעֲשִׂים שֶׁלְּמַטָּה כְּמוֹ שֶׁהֵן מַמָּשׁ. מִשּׁוּם כָּךְ, מִי שֶׁיּוֹדֵעַ אוֹתָן וְנִזְהָר בָּהֶן, הוּא אָהוּב לְמַעְלָה וְאָהוּב לְמַטָּה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הָאוֹתִיּוֹת הַלָּלוּ כֻּלָּן זָכָר וּנְקֵבָה, לְהִתְכַּלֵּל כְּאֶחָד, בְּסוֹד מַיִם עֶלְיוֹנִים וּמַיִם תַּחְתּוֹנִים, וְהַכֹּל אֶחָד, וְזֶהוּ יִחוּד שָׁלֵם. וְעַל זֶה, מִי שֶׁיּוֹדֵעַ אוֹתָן וְנִזְהָר בָּהֶן, אַשְׁרָיו בָּעוֹלָם הַזֶּה וְאַשְׁרָיו בָּעוֹלָם הַבָּא. מִשּׁוּם שֶׁהוּא הָעִקָּר שֶׁל הַיִּחוּד הַשָּׁלֵם כָּרָאוּי. שָׁלֹשׁ שָׁלֹשׁ מִצַּד זֶה וּמִצַּד זֶה, בְּיִחוּד אֶחָד בִּשְׁלֵמוּת הַכֹּל. וְכֻלָּן סוֹד הַמַּעֲרָכָה הָעֶלְיוֹנָה כָּרָאוּי כְּמוֹ שֶׁל מַעְלָה, שֶׁאוֹתָהּ מַערָכָה שָׁלֹשׁ שָׁלֹשׁ בְּסוֹד אֶחָד.</p>\n<p>מַעָֹרָכָה שְׁנִיָּה שֶׁלְּצַד דָּרוֹם, (שהוא סוד הכסף) שָׁלֹשׁ מַעֲרָכוֹת הֵן לְאוֹתוֹ צַד, וְכָל מַעֲרָכָה וּמַעֲרָכָה שָׁלֹשׁ שָׁלֹשׁ, וְהֵן תֵּשַׁע, כְּמוֹ שֶׁנֶּאֱמַר. וְהָאוֹתִיּוֹת נֶחְלְקוּ כָּךְ לְכָל הַצְּדָדִים, לְהִתְחַבֵּר הַכֹּל בְּאֶחָד, מִשּׁוּם שֶׁיֵּשׁ אוֹתִיּוֹת בְּסוֹד הַנְּקֵבָה וְאוֹתִיּוֹת בְּסוֹד הַזָּכָר, וְכֻלָּן מִתְחַבְּרוֹת כְּאֶחָד, וְנִהְיִים אֶחָד בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הַשָּׁלֵם, וְלָהֶם מַעֲרָכוֹת מְמֻנּוֹת שָׁלֹשׁ שָׁלֹשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר. וְהַכֹּל יוֹצֵא מִמַּעֲרֶכֶת הָאָבוֹת שֶׁלְּמַעְלָה כַּמַּעֲרָכָה שֶׁהִתְתַּקְּנוּ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ יה\"ו, כְּמוֹ שֶׁנִּתְבָּאֵר. כָּל הַמַּעֲרָכוֹת הַלָּלוּ מִתְנַהֲגוֹת בָּאוֹתִיּוֹת הַיְדוּעוֹת הַלָּלוּ וְנוֹסְעִים בָּהֶם, וְכַמָּה חֲיָלוֹת וּגְדוֹלִים, כֻּלָּם לְמַטָּה, שֶׁנּוֹסְעִים וּמִתְנַהֲגִים בַּמַּעֲרָכָה הַזּוֹ.</p>\n<p>מַעָרָכָה שְׁלִישִׁית שֶׁלְּצַד צָפוֹן, בְּשָׁלֹשׁ מַעֲרָכוֹת הֵן לְאוֹתוֹ צַד, וְהֵן תֵּשַׁע. וּבִשְׁלֹשָׁה צְדָדִים שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד, וְהֵן תֵּשַׁע. וְאוֹתָן מַעֲרָכוֹת מִשְּׁלֹשָׁה צְדָדִים, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>שֶׁבַע וְעֶשְׂרִים בְּסוֹד הָאוֹתִיּוֹת, שֶׁהֵם שֶׁבַע וְעֶשְׂרִים. וְאַף עַל גַּב שֶׁהֵן עֶשְׂרִים וּשְׁתַּיִם - שְׁלֵמוּת הָאוֹתִיּוֹת הִיא עֶשְׂרִים וְשֶׁבַע. וְנִמְצָאִים כְּמוֹ שֶׁאוֹתִיּוֹת עֶשְׂרִים וְשֶׁבַע, כָּךְ סִדּוּר הַמַּעֲרָכוֹת הַלָּלוּ עֶשְׂרִים וְשֶׁבַע, לְשָׁלֹשׁ שָׁלֹשׁ מַעֲרָכוֹת לְכָל צַד. וְנִמְצְאוּ אֵלֶּה הַשָּׁלֹשׁ שֶׁל הַצַּד הַזֶּה שֶׁהֵן תֵּשַׁע, וְאֵלֶּה הַשָּׁלֹשׁ שֶׁל הַצַּד הַזֶּה שֶׁהֵן תֵּשַׁע, וְאֵלֶּה הַשָּׁלֹשׁ שֶׁל הַצַּד הַזֶּה שֶׁהֵן תֵּשַׁע. נִמְצָא שֶׁכֻּלָּם לְעֶשְׂרִים וְשֶׁבַע.</p>\n<p>וְסוֹד שֶׁל הָעֶשְׂרִים וְשֶׁבַע הַלָּלוּ הֵן תֵּשַׁע אוֹתִיּוֹת שֶׁהֵן בְּסוֹד הַנְּקֵבָה, לְהִתְחַבֵּר בָּהֶן נְקֵבָה עִם אוֹתָן שְׁמוֹנֶה עֶשְׂרֵה אֲחֵרוֹת בַּסּוֹד שֶׁנִּתְבָּאֵר, וְהַכֹּל הוּא כָּרָאוּי.</p>\n<p>בֹּא וּרְאֵה, כְּמוֹ שֶׁהָאוֹתִיּוֹת הָעֶלְיוֹנוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן, כָּךְ גַּם אוֹתִיּוֹת אֲחֵרוֹת לְמַטָּה. אוֹתִיּוֹת עֶלְיוֹנוֹת גְּדוֹלוֹת, וְאוֹתִיּוֹת תַּחְתּוֹנוֹת קְטַנּוֹת. וְהַכֹּל זֶה כְּמוֹ זֶה. וְכָל הַסּוֹדוֹת הַלָּלוּ בְּסוֹד שֶׁל זָכָר וּנְקֵבָה, הַכֹּל הוּא בִּשְׁלֵמוּת, וְלָכֵן הַכֹּל הוּא בְּסוֹד עֶלְיוֹן.</p>"],[9522011879,"<p>בְּאַרְבָּעִים וַחֲמִשָּׁה מִינֵי גּוֹנֵי הָאוֹרוֹת נֶחֱלָק הָעוֹלָם.</p>\n<p>שִׁבְעָה נֶחֱלָקִים לְשִׁבְעָה תְהוֹמוֹת. כָּל אֶחָד מַכֶּה בַּתְּהוֹם שֶׁלּוֹ, וְהָאֲבָנִים מִתְגַּלְגְּלוֹת בְּתוֹךְ הַתְּהוֹם, וְנִכְנָס אוֹתוֹ אוֹר בְּאוֹתָן אֲבָנִים וְנוֹקֵב אוֹתָן, וּמַיִם יוֹצְאִים בָּהֶן, וְשׁוֹקְעוֹת כָּל אַחַת וְאַחַת עַל הַתְּהוֹם, וּמְכַסּוֹת לִשְׁנֵי צְדָדִים.</p>\n<p>יוֹצְאִים הַמַּיִם בְּאוֹתָם נְקָבִים, וְנִכְנָס אוֹר וּמַכֶּה לְאַרְבַּעַת צִדְדֵי הַתְּהוֹם, מִתְגַּלְגֵּל אוֹר בַּחֲבֵרוֹ וְנִפְגָּשִׁים בְּאֶחָד, וּמְחַלְּקִים אֶת הַמַּיִם.</p>\n<p>וְאוֹחֲזִים כָּל אוֹתָם הַשִּׁבְעָה בְּשִׁבְעָה תְהוֹמוֹת, וְכוֹרִים בְּחָשְׁכֵי הַתְּהוֹמוֹת, וְהֶחֳשָׁכִים מִתְעָרְבִים בָּהֶם. עוֹלִים הַמַּיִם וְיוֹרְדִים וּמִתְגַּלְגְּלִים בְּאוֹתָם הַמְּאוֹרוֹת, וּמִתְעָרְבִים כְּאֶחָד - אוֹרוֹת וָחֳשָׁכִים וּמַיִם, וְנַעֲשִׂים מֵהֶם אוֹרוֹת שֶׁלֹּא נִרְאִים חֲשׁוּכִים.</p>\n<p>מַכֶּה כָּל אֶחָד בַּחֲבֵרוֹ, וְנֶחֱלָקִים לְשִׁבְעִים וַחֲמִשָּׁה צִנּוֹרוֹת שֶׁל הַתְּהוֹמוֹת, וּבָהֶם זוֹרְמִים מַיִם.</p>\n<p>כָּל צִנּוֹר וְצִנּוֹר עוֹלֶה בְקוֹלוֹ, וְהַתְּהוֹמוֹת מִזְדַּעְזְעִים. וּכְשֶׁאוֹתוֹ קוֹל נִשְׁמָע, כָּל תְּהוֹם קוֹרֵא לַחֲבֵרוֹ וְאוֹמֵר: חַלֵּק אֶת הַמַּיִם שֶׁלְּךְ וְאֶכָּנֵס בְּךְ. זֶהוּ שֶׁכָּתוּב (תהלים מב) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךְ.</p>\n<p>תַּחַת אֵלֶּה שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה גִידִים, מֵהֶם לְבָנִים, מֵהֶם שְׁחֹרִים, מֵהֶם אֲדֻמִּים, כְּלוּלִים זֶה בָּזֶה, וְנַעֲשׂוּ גָוֶן אֶחָד. אוֹתָם גִּידִים נִרְקְמוּ בִּשְׁבַע עֶשְׂרֵה רְשָׁתוֹת, וְכָל אַחַת נִקְרֵאת רֶשֶׁת גִּידִים. נִרְקְמוּ זֶה בָזֶה וְיוֹרְדִים לְשִׁפּוּלֵי הַתְּהוֹם. תַּחַת אֵלֶּה שְׁתֵּי רְשָׁתוֹת עוֹמְדוֹת בְּמַרְאֶה שֶׁל בַּרְזֶל, וּשְׁתֵּי רְשָׁתוֹת אֲחֵרוֹת בְּמַרְאֶה שֶׁל נְחֹשֶׁת.</p>\n<p>שְׁנֵי כִסְאוֹת עוֹמְדִים עֲלֵיהֶם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. כָּל אוֹתָן רְשָׁתוֹת מִתְחַבְּרוֹת כְּאַחַת, וְהַמַּיִם יוֹרְדִים מֵאוֹתָם צִנּוֹרוֹת וְנִכְנָסִים בָּרְשָׁתוֹת הַלָּלוּ. אוֹתָם שְׁנֵי כִסְאוֹת, אֶחָד כִּסֵּא הָרָקִיעַ הַשָּׁחֹר, וְאֶחָד כִּסֵּא הָרָקִיעַ הַצִּבְעוֹנִי.</p>\n<p>אֵלּוּ הַשְּׁנֵי כִסְאוֹת, כַּאֲשֶׁר אֵלּוּ עוֹלִים, עוֹלִים בַּכִּסֵּא הַהוּא שֶׁל הָרָקִיעַ הַשָּׁחֹר. וְכַאֲשֶׁר יוֹרְדִים, יוֹרְדִים בַּכִּסֵּא הַהוּא שֶׁל הָרָקִיעַ הַצִּבְעוֹנִי. שְׁנֵי הַכִּסְאוֹת הַלָּלוּ, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. אוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר מִיָּמִין, וְאוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַצִּבְעוֹנִי מִשְּׂמֹאל. כְּשֶׁעוֹלִים בַּכִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר, מֻנְמָךְ הַכִּסֵּא שֶׁל רָקִיעַ שְׂמֹאל וְיוֹרְדִים בּוֹ.</p>\n<p>מִתְגַּלְגְּלִים הַכִּסְאוֹת אֶחָד עִם אֶחָד. (לוקחים) יוֹרְדוֹת כָּל אוֹתָן רְשָׁתוֹת לְתוֹכָם וּמַכְנִיסִים אוֹתָן לְשִׁפּוּלֵי הַתְּהוֹם הַתַּחְתּוֹן.</p>\n<p>עוֹמֵד כִּסֵּא אֶחָד, וְעוֹלֶה מֵעַל לְכָל אוֹתָם הַתְּהוֹמוֹת, וְעוֹמֵד כִּסֵּא אַחֵר מִתַּחַת לְכָל הַתְּהוֹמוֹת. בֵּין שְׁנֵי הַכִּסְאוֹת הַלָּלוּ מִתְגַּלְגְּלִים כָּל אוֹתָם הַתְּהוֹמוֹת וְכָל אוֹתָם הַצִּנּוֹרוֹת, וְנִנְעֲצוּ בֵּין שְׁנֵי הַכִּסְאוֹת הַלָּלוּ.</p>\n<p>שִׁבְעִים וַחֲמִשָּׁה צִנּוֹרוֹת הֵם. שִׁבְעָה הֵם עֶלְיוֹנִים מֵהַכֹּל. וְכָל אוֹתָם אֲחֵרִים אֲחוּזִים בָּהֶם, וְכֻלָּם נְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא הַזֶּה בַּצַּד הַזֶּה, וּנְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא בַּצַּד הַזֶּה.</p>\n<p>בָּהֶם הַמַּיִם (בתהום) עוֹלִים וְיוֹרְדִים. אוֹתָם שֶׁיּוֹרְדִים כּוֹרִים בַּתְּהוֹמוֹת וּבוֹקְעִים אוֹתָם. אוֹתָם שֶׁעוֹלִים נִכְנָסִים לְאוֹתָם נִקְבֵי הָאֲבָנִים, וְעוֹלִים וּמְמַלְּאִים אֶת שִׁבְעַת הַיָּמִים. עַד כָּאן שִׁבְעַת גּוֹנֵי הָאוֹרוֹת בְּסוֹד עֶלְיוֹן.</p>"]]});
